WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[1051] = { title = "Vorrel's Revenge", description = "Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered.\n\nInterrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The monster!\n\nRevenge... I want revenge!\n\nThe pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill.\n\nHeed my last wishes....", objectives = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.", progress = "What do you want, stranger?", completion = "Vorrel led such a troubled existence. And what a good mate he was...\n\nDamn those filthy humans!\n\nVorrel is gone, never to enjoy undeath again. At least I can take solace in the revenge you took in his name. For that I thank you.\n\nNow let me be to mourn...." }
WordHunterWoW_QuestEN[1052] = { title = "Down the Scarlet Path", description = "We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron.\n\nYou have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron.\n\nTravel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery.", objectives = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.", progress = "Who goes there? What do you want from me?", completion = "Brother Anton still spreads the word of the Scarlet Crusade? Oh my...." }
WordHunterWoW_QuestEN[1053] = { title = "In the Name of the Light", description = "I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.\n\nBut as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued. \n\nThe Scarlet Crusade must be crushed in the name of the Light. You, <name>, must destroy the deranged regime.", objectives = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.", completion = "While disciples of the Light never revel in the loss of life, we must accept that on occasion, such sacrifices must happen for the greater good of the Kingdom and the planet.\n\nThrough your deeds in the Monastery you have spared many innocent lives, <name>. I salute your tenacity." }
WordHunterWoW_QuestEN[1054] = { title = "Culling the Threat", description = "Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly.\n\nKill as many of their kind as you can, but bring me their chieftain's skull as proof that their efforts have been stifled... for now.\n\nI shall remain here in Astranaar and await word from you. Elune be with you.", objectives = "Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.", progress = "The furbolgs' corruption has caused Ashenvale to become a fraction of its former glory.", completion = "Well done, <name>.\n\nWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer." }
WordHunterWoW_QuestEN[1055] = { title = "Raene's Cleansing", description = "The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success.", objectives = "Return to Shael'dryn at the moonwell.The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success.", completion = "You've done it, <name>! Well done!" }
WordHunterWoW_QuestEN[1056] = { title = "Journey to Stonetalon Peak", description = "The forest spirits tell me you are brave and willing to travel.\n\nTo the south, not far from Mystral Lake, there lies a tunnel named The Talondeep Path. Through this tunnel you will come to an area known as Windshear Crag in the Stonetalon Mountains. Once there, journey to the southwest past Cragpool Lake and then north, up the steep slope until you reach Stonetalon Peak.\n\nThere awaits Keeper Albagorm. Heed his bidding, <race>.\n\nThe journey will be perilous.", objectives = "Travel to Keeper Albagorm on Stonetalon Peak.The forest spirits tell me you are brave and willing to travel.\n\nTo the south, not far from Mystral Lake, there lies a tunnel named The Talondeep Path. Through this tunnel you will come to an area known as Windshear Crag in the Stonetalon Mountains. Once there, journey to the southwest past Cragpool Lake and then north, up the steep slope until you reach Stonetalon Peak.\n\nThere awaits Keeper Albagorm. Heed his bidding, <race>.\n\nThe journey will be perilous.", completion = "Finally, you arrive. I see Faldreas has listened to the forest spirits...." }
WordHunterWoW_QuestEN[1057] = { title = "Reclaiming the Charred Vale", description = "As a protector of the forest spirits you can undoubtedly guess why I am alarmed.\n\nYou have traveled through these mountains to reach this peak. Surely you have seen the travesty which has befallen the land. Greed has led to the destruction of these sacred hills.\n\nThe Charred Vale to the south was set afire by the greedy mechanized army of industrialists. Worse yet, the Bloodfuries that have encroached on the land refuse us passage in to begin regrowth.\n\nDrive the wretched harpies out, <name>!", objectives = "Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.", completion = "Now that the Bloodfuries have suffered such a great loss, perhaps the true work of restoring the land can begin...." }
WordHunterWoW_QuestEN[1058] = { title = "Jin'Zil's Forest Magic", description = "So excited I am!\n\nThree little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of... what do they call it... forest magic!\n\nI'll need a good mess of Stonetalon sap. From those horrid felines, bring me some twilight whiskers. This calls for plenty of courser eyes, of course -- can never have enough eyes. Oh, and lest we forget, a precious scale from a fey dragon.\n\nHurry to Stonetalon Peak, <name>, so I can brew some forest magic!", objectives = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.", progress = "Look at our poor little elf friends. All caged up with no forest to frolic in!\n\nNow were you able to find me some sap? How about the whiskers from the twilight runners? Don't suppose you have that fey dragon scale on you?\n\nAnd eyes! I'll need so many eyes! You just can't mix up a fierce forest magic brew without a good helping of eyes!", completion = "Oh how happy these little woodland nymphs shall be! We'll make them feel right at home with this special concoction!" }
WordHunterWoW_QuestEN[1059] = { title = "Reclaiming the Charred Vale", description = "The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.\n\nFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.\n\nThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.\n\nSend word of our need! Seek him out at once!", objectives = "Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.\n\nFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.\n\nThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.\n\nSend word of our need! Seek him out at once!", completion = "Keeper Albagorm was wise to send you with such urgency.\n\nLet us see if we cannot call forth aid from the great forest to travel to the Charred Vale before it is too late." }
WordHunterWoW_QuestEN[1060] = { title = "etter to Jin'Zil", description = "You've done so well for me, <name>. You're a regular lucky rabbit's foot and there's something I want you to see.\n\nThe harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil.\n\nHe'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place.", objectives = "Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.", progress = "You seem a shady character. You have something for me to see?", completion = "Ahh, a letter from Darsok. I have not heard from him in many years.\n\nSo the last of the Bloodfeathers are dead, eh? That is good news, I can remember when my friend Rokhan went with that crazy mok'nathal to kill her older sister. Ah, to be young again, like you." }
WordHunterWoW_QuestEN[1061] = { title = "The Spirits of Stonetalon", description = "The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.\n\nSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.\n\nMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.", objectives = "Speak with Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.", completion = "Ah, a <class>.  Very good.  We will need your skills to deal with these plunderers!" }
WordHunterWoW_QuestEN[1062] = { title = "Goblin Invaders", description = "The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!\n\nHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work--show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...\n\nViolence.", objectives = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.", completion = "Bravely done, <name>.\n\nWe may ultimately need the wisdom of tauren elders to calm the spirits of Stonetalon, but...\n\nRidding the Venture Company of its personnel is a good first move against them." }
WordHunterWoW_QuestEN[1063] = { title = "The Elder Crone", description = "To truly tend the spirits of Stonetalon we must consult the tauren elders.\n\nI do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she.\n\nMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains.", objectives = "Speak with Magatha in Thunder Bluff.To truly tend the spirits of Stonetalon we must consult the tauren elders.\n\nI do not know many of their leaders' names, but I do know of one: Magatha. I have heard that she is very old, and she knows much. If anyone can marshal spiritual aid from the tauren, it is she.\n\nMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff. Speak with Magatha, and tell her of the peril of Stonetalon Mountains.", completion = "I bid you greetings.  You are here seeking counsel?" }
WordHunterWoW_QuestEN[1064] = { title = "Forsaken Aid", description = "The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.\n\nIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.\n\nSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.", objectives = "Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.", completion = "Magatha sent word of your coming, <name>.  Although my heart beats no longer, I still feel sorrow for the spirits of Stonetalon.\n\nThe Forsaken are eager to offer what help we can." }
WordHunterWoW_QuestEN[1065] = { title = "Journey to Tarren Mill", description = "To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed.\n\nA colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron.\n\nTo reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad.\n\nSeek Lydon and bring him this note.  It details our needs to him.", objectives = "Bring Zamah's Note to Apothecary Lydon in Tarren Mill.", progress = "Ah, are you here with my new test subjects?", completion = "A note from Zamah?  Her needs must be great to send word from so far.  Let us see what she says...\n\nAh, splendid!  I know exactly what to do!" }
WordHunterWoW_QuestEN[1066] = { title = "Blood of Innocents", description = "I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?\n\nBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.\n\nFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.\n\nYou can find the Syndicate shadow mages in Durnholde Keep to the southeast.", objectives = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.", progress = "Did you find the Syndicate Shadow Mages, and collect from them the blood?", completion = "Very good!  I trust the Syndicate gave you little trouble?\n\nAs I mentioned, the blood of innocents is not an easy thing to obtain.  We are lucky the Syndicate shadow mages did the difficult work for us.\n\nNow hold a moment while I create my concoction..." }
WordHunterWoW_QuestEN[1067] = { title = "Return to Thunder Bluff", description = "Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!\n\nBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.", objectives = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.", progress = "You have returned, <name>.  Do you bring aid from Apothecary Lydon?", completion = "A toxin from Apothecary Lydon?  Very good.  If I know Lydon, then this toxin will be quite effective against the Venture Company..." }
WordHunterWoW_QuestEN[1068] = { title = "Shredding Machines", description = "There is a relation to the spiritual magic of shaman and the natural magic of druids.  This is why we shaman can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear...\n\nI saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped!\n\nIn my vision, the machines were marked with strange symbols:\n\nXT:4 and XT:9.", objectives = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.", completion = "The destruction of the machines XT:4 and XT:9 have soothed many of the spirits of Stonetalon, <name>.  With their loss, let us hope the Venture Company will remove itself from these mountains.\n\nFor if they do not, then I fear the atrocities this place has suffered will pale to what lies ahead." }
WordHunterWoW_QuestEN[1069] = { title = "Deepmoss Spider Eggs", description = "Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs.\n\nI smell an opportunity!\n\nIn Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle!\n\nIn Windshear Crag, the eggs will be clustered under what trees remain.\n\nIn Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...", objectives = "Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.", progress = "Did you get the eggs, <name>?  I already made a shipping deal with Wharfmaster Dizzywig!", completion = "You got them!  Thank you!\n\nI'll have these sent to Dizzywig and get them shipped to Booty Bay.  I can already taste the profits!\n\nHere is your cut, <name>.  I couldn't have made this deal without you." }
WordHunterWoW_QuestEN[1070] = { title = "On Guard in Stonetalon", description = "Hello, <name>.\n\nYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.\n\nRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.\n\nWould you find her and report back to me?", objectives = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.Hello, <name>.\n\nYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.\n\nRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.\n\nWould you find her and report back to me?", completion = "Ah, you've come from Ashenvale at the behest of Tara--how I miss her, my homeland and friends. She must be doing well with the Sentinels to be sequestering adventurers for other tasks. I'm proud of her.\n\nIt is a pleasure to meet you, <name>." }
WordHunterWoW_QuestEN[1071] = { title = "A Gnome's Respite", description = "You see, <name>, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.\n\nBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!\n\nI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east...", objectives = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.", completion = "Thanks so much for your help, <name>. You're actually back just in time.\n\nI think I've got a perfect plan... explosives. No, that's not the plan, but it's part of the plan.\n\nSee, I've been using high explosives--don't worry, they're not as dangerous as everyone thinks--to scare the goblins back a bit. I can herd 'em pretty good with a few key detonations along the mountains' edges, but I've been low on supplies now for a few days..." }
WordHunterWoW_QuestEN[1072] = { title = "An Old Colleague", description = "The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.\n\nAnd for that, we're going to need some potent explosives: Nitromirglyceronium.\n\nThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.\n\nYou talk him into making us some NG-5, I'll get to work on placement for my devices.", objectives = "Speak to Lomac Gearstrip in Ironforge.The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.\n\nAnd for that, we're going to need some potent explosives: Nitromirglyceronium.\n\nThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.\n\nYou talk him into making us some NG-5, I'll get to work on placement for my devices.", completion = "Ahhh.... Gaxim sent you, huh? How do I know you're not lying to me?! Hmm? Hmm...?" }
WordHunterWoW_QuestEN[1073] = { title = "Ineptitude + Chemicals = Fun", description = "Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!\n\nI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.\n\nThere's a problem though: I'm all out.\n\nBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.\n\nThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.", objectives = "Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge.", progress = "I can't make any Nitromirglyceronium if I don't have the potions... they're vital to its creation.", completion = "This'll do nicely.\n\nIf I didn't know better, stranger, I'd say you knew somethin' about alchemy. Good, good... the world's not all about swords and sorcery, you know?" }
WordHunterWoW_QuestEN[1074] = { title = "Ineptitude + Chemicals = Fun", description = "Here you go, stranger. Take heed with it though... it's volatile stuff.\n\nIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.", objectives = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.", progress = "Ah, goodie goodie, you're back.", completion = "Your task has been done flawlessly, <name>.\n\nNG-5 is the unequivocal component in the recipe to ignite the wagons of dynamite.\n\nWhat? Yes, dynamite... wagons of it. It's the perfect distraction, I tell you... just wait and see." }
WordHunterWoW_QuestEN[1075] = { title = "A Scroll from Mauren", description = "Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?\n\nOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.\n\nBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.", objectives = "Find Collin Mauren in Stormwind.Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?\n\nOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.\n\nBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.", completion = "Now, this spell you need; one that will allow you detonate explosives from a distance... hmmm." }
WordHunterWoW_QuestEN[1076] = { title = "Devils in Westfall", description = "Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.\n\nI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.\n\nWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.\n\nI'll be here when you return.", objectives = "Bring Dust Devil Debris to Collin Mauren in Stormwind.", progress = "Hello, <name>. Have you found the component I need?", completion = "Allow me just a few moments and I shall have your scroll ready for you." }
WordHunterWoW_QuestEN[1077] = { title = "Special Delivery for Gaxim", description = "Here you are, <name>. This should do nicely.\n\nPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.\n\nFare well.", objectives = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.", progress = "Haha! you're back! Do you have it? Do you have the spell?", completion = "This is perfect, <name>! Well done.\n\nThis spell, mixed with the NG-5, shall make the perfect remote explosive.\n\nWe'll be able to create the perfect distraction for you so you can sneak in and steal the Venture Co.'s letters and engineering plans.\n\nThat will surely slow down their deforestation acts." }
WordHunterWoW_QuestEN[1078] = { title = "Retrieval for Mauren", description = "Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co.\n\nWithin the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created.\n\nIf those basilisks still live, I would love to have a few of their scales.\n\nTake your time, it is no rush, but I can pay well.", objectives = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.", progress = "Hello again, <name>.\n\nHave you already returned from the Vale in Stonetalon with those scales?", completion = "This is perfect, <name>. Thank you greatly.\n\nPerhaps one day in the future I'll be able to help you as you have helped me." }
WordHunterWoW_QuestEN[1079] = { title = "Covert Ops - Alpha", description = "This is it, <name>. Pay close attention. The devices are done, and ready to be used.\n\nTake these pages--they'll explain more about the detonators and explosives, and where you should place them.\n\nRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.", objectives = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.", progress = "Did you get the plans, <name>?", completion = "Truly amazing! This is a huge blow to the Venture Co.\n\nWe'll be able to find weaknesses in their machines and also incorporate their designs into our own creations. This is a wonderful day, indeed." }
WordHunterWoW_QuestEN[1080] = { title = "Covert Ops - Beta", description = "Plan Beta's just like Plan Alpha, <name>.\n\nWe cause a distraction and then steal their precious letters.\n\nThe key is to get their letters... remember that.\n\nThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....", objectives = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.", progress = "How'd it go, <name>?", completion = "Incredible, <name>! Kaela and the Sentinels will be so happy. With your skill and my creations, we're unstoppable." }
WordHunterWoW_QuestEN[1081] = { title = "Reception from Tyrande", description = "<name>, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.\n\nIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.\n\nIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.", objectives = "Find Tyrande Whisperwind in Darnassus.<name>, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.\n\nIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.\n\nIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.", completion = "Hello, <name>. I have indeed heard your name before, and although you are still full of youth, I am pleased to see the path you have set for yourself.\n\nYou would do me a great honor if you would accept this as a gift of appreciation." }
WordHunterWoW_QuestEN[1082] = { title = "Update for Sentinel Thenysil", description = "<name>, you have done a great deed by lending a hand here.\n\nThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.\n\nFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.", objectives = "Return to Sentinel Thenysil in Ashenvale.<name>, you have done a great deed by lending a hand here.\n\nThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.\n\nFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.", completion = "Thank you, <name>. You have done a service to the Sentinels.\n\nI'm glad to see Kaela... and even Gaxim, are doing well.\n\nYou've earned our appreciation." }
WordHunterWoW_QuestEN[1083] = { title = "Enraged Spirits", description = "I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.\n\nThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.\n\nBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.\n\nThe land has no chance to see Elune's smile while these creatures roam free.\n\nBring me their smoldering embers to show you've reduced their numbers.", objectives = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.", progress = "The first time I saw the Charred Vale I almost wept, <name>.", completion = "The remains of our enemy... your strength serves us well, <name>. Thank you." }
WordHunterWoW_QuestEN[1084] = { title = "Wounded Ancients", description = "It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.\n\nGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.\n\nI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.\n\nBring me some of the shrapnel so the gnome can tell me more...", objectives = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.", progress = "I have a feeling Gaxim will find a use for the shrapnel regardless of how the Venture Co. has used it in the past.", completion = "Thank you, <name>.\n\nThis should be more than sufficient for Gaxim to figure out how the treants were corrupted. I shall give this to him right away." }
WordHunterWoW_QuestEN[1085] = { title = "On Guard in Stonetalon", description = "The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.\n\nThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.\n\nDo not judge Gaxim prematurely; he understands the need for us to work together.\n\nIf you wish to aid us, then start by speaking to Gaxim.\n\nI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.", objectives = "Speak to Gaxim in Stonetalon Mountains.The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.\n\nThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.\n\nDo not judge Gaxim prematurely; he understands the need for us to work together.\n\nIf you wish to aid us, then start by speaking to Gaxim.\n\nI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.", completion = "Treacherous... treacherous and dangerous, that's what this land is.\n\nBut I'm here to show the night elves that it's a little safer with the help of good ole engineering and a dash of magic.\n\nSee, swearing off magic completely won't help the night elves--they need it. The world needs it. And with engineering and alchemy to boot, you can't go wrong. The possibilities are endless." }
WordHunterWoW_QuestEN[1086] = { title = "The Flying Machine Airport", description = "The toxin is ready.  All that remains is its delivery.  You, <name>, must make that delivery.\n\nThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.\n\nPlace it, and run.", objectives = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.", completion = "You found the port?  Well done, <name>!  I am sure the goblins were quite surprised from your delivery!  Let us hope that toxin finds its way to their headquarters.\n\nYou have served your people well, and I advise you to ignore any guilt you might harbor for poisoning the Venture Company.  They are deserving of far worse.\n\nAnd if there is one mote of wisdom the Forsaken might teach its allies, it is this:\n\nDo not shy from dark paths... if those paths lead to victory." }
WordHunterWoW_QuestEN[1087] = { title = "Cenarius' Legacy", description = "You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests.\n\nWould that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done.\n\nI have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satisfied.", objectives = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.", completion = "Already I can feel it... yes... power so sweet... the rushing flood. The kaldorei are foolish to spurn the gifts of this world, to reject the coursing of magic as it flows singing through your veins.\n\nWhat a pale mockery life is without its burning embrace!" }
WordHunterWoW_QuestEN[1088] = { title = "Ordanus", description = "They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head!\n\nMagic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short.\n\nBring it to me and I will share with you a mighty gift.", objectives = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.", progress = "When my master bade me to the peak of Stonetalon, I expected that all I would need was to lay waste to the night elves that crawled the sacred ruins of our ancient temple of Azshara, their touch despoiling its sanctity... but Ordanus had slipped my grasp.", completion = "I knew Ordanus once, long ago. He had the arrogance of his kind, holding himself above even the Highborne.\n\nHis head does not rise so high now, does it, <name>?\n\nI promised you a reward, and you shall have it. Attend to me." }
WordHunterWoW_QuestEN[1089] = { title = "The Den", description = "The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items.\n\nThey devised a complex scheme to keep them from falling into the wrong hands.\n\nLuckily, I managed to... extract some details from one of them.\n\nHidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.", objectives = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard.", progress = "Three keyholes are carved into the stone.", completion = "As the three keys are slid into their matching openings, in the middle of the glowing light a number of items appear." }
WordHunterWoW_QuestEN[1090] = { title = "Gerenzo's Orders", description = "You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are.\n\nAnyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I get it.", objectives = "Get the mysterious ore from Piznik after he finishes mining it.", completion = "Thanks, <name>. It was looking a little dicey there for a second and we've probably drawn far too much attention to ourselves.\n\nThe important part is that we have the ore sample, though, and we should get it to Ziz as soon as possible." }
WordHunterWoW_QuestEN[1091] = { title = "Kaela's Update", description = "<name>, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.\n\nMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.", objectives = "Bring the Venture Co. Letters to Kaela Shadowspear in Stonetalon Mountains.", progress = "Yes, <name>? What can I do for you?", completion = "This is interesting indeed.\n\nYou and Gaxim have done very well, <name>. Thank you." }
WordHunterWoW_QuestEN[1092] = { title = "Gerenzo's Orders", description = "I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again.\n\nI'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job!\n\nI'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.", objectives = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.", progress = "Something I can help you with?", completion = "Ahhh, I knew that I did the right thing by telling Piznik to stay behind. I'm sure the engineers in Undermine will be most interested to look at this...\n\nOf course I'll want to keep a little piece for myself, but what they don't know won't hurt them, yes?" }
WordHunterWoW_QuestEN[1093] = { title = "Super Reaper 6000", description = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!\n\nLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!\n\nTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.", objectives = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.", progress = "Did you find those plans? I'm eager to impress the new boss. Hopefully, once he's convinced of my loyalty--well, as much as he can be convinced... goblin's honor, you know?--he'll feel comfortable making use of my rather impressive genius.", completion = "Hey, is that what I think it is? Great!\n\nNow, let's see. Ugh... how am I supposed to understand this stuff... can't figure out the way gnomes think. Lemme tell you, I'm surprised they could build the wheel, let alone those flying machines they like so much." }
WordHunterWoW_QuestEN[1094] = { title = "Further Instructions", description = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.\n\nSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.", objectives = "Deliver the Sealed Envelope to Sputtervalve at Ratchet in the Barrens.", progress = "Hello there! How can I help you?", completion = "Fizziks, eh? Can't say I trust him, but this information seems good enough. What I wouldn't give to have the Venture Company out of my hair.\n\nThey do come up with some good machines though... I can't deny that we've benefited from using some of the improvements they've devised." }
WordHunterWoW_QuestEN[1095] = { title = "Further Instructions", description = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.", objectives = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.", completion = "Eliminate Gerenzo? Now there is a prospect that I have no objections to.\n\nGnomes are bad enough as it is, but what I learned about Gerenzo only makes it worse. Apparently, he was one of the head engineers in Gnomeregan, where he was working on their secret project--we could never infiltrate Dun Morogh well enough to find out specific details. It was a failure. Our reports say that whatever it was literally exploded in their faces." }
WordHunterWoW_QuestEN[1096] = { title = "Gerenzo Wrenchwhistle", description = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.\n\nNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.\n\nIf you kill him for me, I'll make it worth your while!", objectives = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.", progress = "Sputtervalve will want some sort of proof that Gerenzo's dead. I think his mechanical arm will probably do.", completion = "Look at that thing... it'd take a gnome to come up with something like that. I can't understand why you'd cut off an arm, and replace it with that, when you could just keep both arms and add a third!\n\nGnomes, I tell you...\n\nAt least Gerenzo's out of commission. Hopefully that'll be enough proof, and Sputtervalve will assign me to one of the Tinkers' Union workshops in Gadgetzan or maybe even Undermine." }
WordHunterWoW_QuestEN[1097] = { title = "Elmore's Task", description = "There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north.\n\nYou have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves.\n\nYou can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.", objectives = "Speak with Grimand Elmore in Stormwind.", completion = "You're here to help with my delivery?  Very good!" }
WordHunterWoW_QuestEN[1098] = { title = "Deathstalkers in Shadowfang", description = "In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!\n\nSo here is your task, <name>.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.\n\nThis mission is as dangerous as is it critical, <name>.  Do not fail.", objectives = "Find the Deathstalker Adamant and Deathstalker Vincent.", completion = "Vincent's body lies broken, and still.\n\nAlthough Deathstalker Adamant will send his report to Hadrec... whatever additional details Vincent gained must remain with him.\n\nBut clutched in his hand is a small trinket..." }
WordHunterWoW_QuestEN[1099] = { title = "Goblins Win!", description = "", objectives = "" }
WordHunterWoW_QuestEN[1100] = { title = "Lonebrow's Journal", description = "You slowly open the weathered journal of Henrig Lonebrow....", objectives = "Read Henrig Lonebrow's Journal.", progress = "From your look of concern, I can tell that something is amiss....", completion = "You say you found this journal on a deceased dwarf? Give me but a moment to peruse the pages..." }
WordHunterWoW_QuestEN[1101] = { title = "The Crone of the Kraul", description = "Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.\n\nWe must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.\n\nSurely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. <name>, assemble a party to slay the crone.\n\nBring me Razorflank's Medallion as proof of demise.", objectives = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.", progress = "So long as Charlga Razorflank is mustering a force in Razorfen Kraul, these lands are in great danger.", completion = "The crone has been laid to rest. This is fantastic news, <name>.\n\nIn these times of peril, it is refreshing to see one as brave as yourself.\n\nWith Razorflank's minions taken care of, our studies in the area can continue. Perhaps now we can gain further knowledge of exactly what happened to corrupt the resting place of Agamaggan.\n\nHowever, I fear the answer to that question lies in treachery as well..." }
WordHunterWoW_QuestEN[1102] = { title = "A Vengeful Fate", description = "Cairne is a noble leader for uniting our people here on Thunder Bluff.\n\nBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.\n\nA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.\n\nBring me Razorflank's heart and I can die in peace, <name>.", objectives = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.", progress = "Once I know the foul beasts of Razorfen Kraul have been driven from their foul lair, I will be able to rest in peace, knowing that revenge has been served.\n\nHave you driven the quilboar from the Kraul? Do you bring to me good news in the form of Razorflank's heart?", completion = "I see the nasty tribe of Razorfen Kraul now knows the pain of my people. Serves the foul beasts right.\n\nTo drive one from a holy land is a sin worthy of the most severe revenge.\n\nThank you, <name>, for aiding me in my plight." }
WordHunterWoW_QuestEN[1103] = { title = "Call of Water", description = "Greetin's, <brotha/sista>! Have you too come to purify the waters here and prove your understandin' to Islen?\n\nI've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier.\n\nWhat's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again.\n\nBring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me parts.", objectives = "Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water." }
WordHunterWoW_QuestEN[1104] = { title = "Salt Flat Venom", description = "I have so many designs for our rocket car!  So many!  And I must try them all!!\n\nI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...\n\nThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!\n\nBring me venom and trust me -- our car will fly!!", objectives = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.", progress = "Hi hi hi!  Did you get that venom??", completion = "All right!  This venom is going to work great!  Thanks, <name>!\n\nNow I just need to boil it down, apply skipper-otomer, add a nega-catalyst, and... Drat!  Where are my notes!?" }
WordHunterWoW_QuestEN[1105] = { title = "Hardened Shells", description = "My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!\n\nI want to reinforce its fuel tanks before that happens.\n\nThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.\n\nYou look responsible enough.  Will you get me those shells?", objectives = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.", progress = "My brother is making progress with his new fuel design, and that has me worried.  I need to start work on a tortoise shell fuel tank as soon as possible!\n\n<name>, do you have those shells yet?", completion = "You got them!  Thanks, <name>!\n\nWow, these shells are harder than I thought!  Heh, when I work with them I'll probably bend a whole box full of tools!" }
WordHunterWoW_QuestEN[1106] = { title = "Martek the Exiled", description = "I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!\n\nBut there is someone who might know how.\n\nHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!\n\nBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!\n\nFind him!", objectives = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.", progress = "Well, you found me.  Good for you.\n\nAre you here about that axe I made for Gath'Ilzogg?  Or are you here to reclaim Duchess Pamay's honor?\n\nActually, I don't care which it is.  If you're here to fight, then let's get it over with...", completion = "Fizzle sent you?  Well that changes things!  Of course I'll help you.  Fizzle and his brother are two of the few people who don't want me dead!\n\nSo Fizzle wants to make pistons, eh?  Pistons strong enough to take whatever stresses he has planned, and if I know Fizzle, then this new car of his is a volcano on wheels!" }
WordHunterWoW_QuestEN[1107] = { title = "Encrusted Tail Fins", description = "Our rocket car is the fastest thing on the flats!  So fast that ... I'm afraid friction is going to tear it apart!\n\nTo prevent that I need to create a composite to coat the car's moving parts.  It must be hard but not brittle, and must be resistant to salt corrosion, or time spent on the Shimmering Flats will eat it away.\n\nHave you heard of the Vile Reef, <name>?  It's off the coast of Stranglethorn Vale.  Saltscale murlocs live there, and their tail fins are a crucial ingredient of my composite.", objectives = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.", progress = "Do you have the tail fins?  If I can't protect our car from its own speed, then it won't last long in these races.", completion = "Thank you, <name>!  After I grind these down and fuse them with a few other ingredients, the composite will be ready.  And after that, the car will be safe from its own speed.\n\nSafe, as long as it doesn't hit anything..." }
WordHunterWoW_QuestEN[1108] = { title = "Indurium", description = "I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, <name>, if you have the guts to get it.\n\nThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.\n\nBut let's make sure.  Get me samples of indurium and I'll test its properties.\n\nTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes.", objectives = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.", progress = "Did you find any indurium flakes, <name>.  I have my forge heated up and ready to test them.", completion = "Ah yes, these will do fine.  Now let's put them in some heat and see how they fare..." }
WordHunterWoW_QuestEN[1109] = { title = "Going, Going, Guano!", description = "As you can see, <name>, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a <class>. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...", objectives = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Splendid! This is just the start we needed, <name>." }
WordHunterWoW_QuestEN[1110] = { title = "Rocket Car Parts", description = "Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way.  If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!\n\nAnd those parts are worth money to the gnomes and goblins.  They're always looking for more contraptions to slap onto their cars.\n\nSo go out and get me parts.  Bring me a heap and I'll pay you well.", objectives = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way. If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!\n\nAnd those parts are worth money to the gnomes and goblins. They're always looking for more contraptions to slap onto their cars.\n\nSo go out and get me parts. Bring me a heap and I'll pay you well.", progress = "<name>, have you been out into the Flats?  Did you bring back that load of parts I wanted?", completion = "Whoa, look at all that!  There's some good stuff in that heap of junk.  I'm sure I can pawn it off for a hefty sum.\n\nAnd... is that an ear I see squashed between those two sheets of metal??  Ouch!  Heh, I sure wouldn't want to be that pilot!\n\nThanks, <name>.  Here's your pay.  And here's some advice, free of charge...\n\nIf you look hard enough, you can always find profit in someone else's tragedy." }
WordHunterWoW_QuestEN[1111] = { title = "Wharfmaster Dizzywig", description = "I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.\n\nSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.\n\nDo this for me, and I'll have more jobs for you.\n\nJobs, my friend, with serious profit potential...", objectives = "Bring Kravel's Parts Order to Wharfmaster Dizzywig at Ratchet in the Barrens.", progress = "Speak up!  Tell me, are you dropping off or picking up?", completion = "Oh yes.  Parts for Kravel.  I'm glad you're here.  These things have been sitting out here for days, and I was afraid they'd rust!" }
WordHunterWoW_QuestEN[1112] = { title = "Parts for Kravel", description = "Here's Kravel's package, <name>.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!", objectives = "Bring Kravel's Parts to Kravel Koalbeard on the Shimmering Flats in Thousand Needles.", progress = "Did you make it to Ratchet and get those parts?", completion = "Great, you got them!  Now we need to get them to the gnomes.  But first...\n\nLet's take out one small item..." }
WordHunterWoW_QuestEN[1113] = { title = "Hearts of Zeal", description = "Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.\n\nIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate, both inside and outside the halls. Which you slay matters not, any of them may have the heart I need.", objectives = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.", progress = "Have you returned from the Scarlet Monastery? I'll need many hearts for this delightful experiment!\n\nNo doubt, Varimathras and the Dark Lady will be pleased to be rid of the Scarlet Scum as well...", completion = "My what an abundance of gore you have brought me, <name>! Your efforts have been most excellent!" }
WordHunterWoW_QuestEN[1114] = { title = "Delivery to the Gnomes", description = "Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...\n\nAnd I wouldn't bother mentioning it to him.  It was small and worthless.\n\nTrust me.", objectives = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.", progress = "You have something for me?  That's great!  let's see it!", completion = "There they are!  My hydro ratchets and repeater bolts!  These will do just fine.  Thank you!" }
WordHunterWoW_QuestEN[1115] = { title = "The Rumormonger", description = "Now that we've done a service for the gnomes, it's time to do the goblins a favor!  \n\nI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.\n\nIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.\n\nIf you can get useful information from him, then we might just turn a profit from it.", objectives = "Talk to Krazek at Booty Bay in Stranglethorn Vale.", completion = "You want to know about Nazz Steamboil?  He's a racer pilot out in the Shimmering Flats, isn't he?\n\nYeah, I might be able to find something out about him... but it won't be easy.  Or fast.\n\nOr cheap." }
WordHunterWoW_QuestEN[1116] = { title = "Dream Dust in the Swamp", description = "Getting the information on Nazz is quite a favor, <name>.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?\n\nWhile I contact my sources, why don't you gather something for me, eh?\n\nHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!\n\nGet it for me, <name>, and I'll give you the information you seek.", objectives = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay. Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.", progress = "Back so soon?  Do you have my dream dust?", completion = "Well, look at that.  You found the dream dust!\n\nAnd how did you like the swamp, <name>?  It's not easy to get a hot meal there, is it?" }
WordHunterWoW_QuestEN[1117] = { title = "Rumors for Kravel", description = "I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.\n\nHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.\n\nJust don't tell anyone where you got it!", objectives = "Bring the Goblin Rumors to Kravel Koalbeard on the Shimmering Flats in Thousand Needles.", progress = "Did you get anything on Nazz Steamboil?  Anything he might want to keep a secret??", completion = "Well well!  This is interesting... very interesting.  Heh, perhaps I should bow to the goblin pilot the next time I see him.\n\nThis is worth plenty, <name>.  I'm sure Nazz will pay a small fortune to keep his secret... a secret." }
WordHunterWoW_QuestEN[1118] = { title = "Back to Booty Bay", description = "<name>, you're a <class> I can trust, both to get the job done and to keep your mouth shut while doing it.\n\nI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.\n\nTo start, you must go back to Booty Bay.  I apologize, good <name>.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.\n\nGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort.", objectives = "Bring Kravel's Scheme to Crank Fizzlebub at Booty Bay in Stranglethorn Vale.", progress = "Hello hello.  And what brings a noble <race> such as you down to Booty Bay?", completion = "I see.  Kravel has a big scheme planned.  He has a sinister mind -- I like that about him.\n\nSo you'll need something to addle wits, eh?  Something powerful...\n\nI wonder if the mixture Zanzil feeds his zombies could be used..." }
WordHunterWoW_QuestEN[1119] = { title = "Zanzil's Mixture and a Fool's Stout", description = "I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.\n\nAnd <name>, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.", objectives = "Bring the Fool's Stout back to Kravel on the Shimmering Flats in Thousand Needles.", progress = "Hello, <name>.  Was Fizzlebub able to help us?", completion = "Wonderful!  Fizzlebub came through!  I'll remember that next time I see him.\n\nAnd thank you, <name>.  You're doing a great job, and we both stand to make a lot of money from this..." }
WordHunterWoW_QuestEN[1120] = { title = "Get the Gnomes Drunk", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", objectives = "Bring the Fool's Stout to the Gnome Pit Boss at Mirage Raceway in Thousand Needles.", progress = "Hi!  You have something for me?", completion = "Stout?  How considerate!  Thank you!\n\nWe shouldn't be drinking with the race coming up, but... maybe my boys could do with just a little.  Besides, it can't be that strong, can it?" }
WordHunterWoW_QuestEN[1121] = { title = "Get the Goblins Drunk", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", objectives = "Bring the Fool's Stout to the Goblin Pit Boss at Mirage Raceway in Thousand Needles.", progress = "What are you looking at?", completion = "What do we have here?  Booze, eh?\n\nWell, I don't mind if we have just a little..." }
WordHunterWoW_QuestEN[1122] = { title = "Report Back to Fizzlebub", description = "That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!\n\nThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.\n\nAnd hopefully we can get more of that Fool's Stout for future races!", objectives = "Bring the Fool's Stout report to Crank Fizzlebub at Booty Bay in Stranglethorn Vale.", progress = "Hello <name>.  How'd that stout work out?  It's strong stuff, isn't it?", completion = "It says here that the fool's stout was a success.  That's good news!\n\nIf you ever want more of the stuff, then let me know and I'll have you gather more of Zanzil's Mixture." }
WordHunterWoW_QuestEN[1123] = { title = "Rabine Saturna", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.\n\nI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, <name>.  Good luck.", objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  The tauren have shown an incredible propensity to the tenets of Cenarius, and by their proxy the Horde is welcomed within the safety of this glade.  The preservation of Azeroth is a common goal we both share.\n\nYou are among friends here, <name>." }
WordHunterWoW_QuestEN[1124] = { title = "Wasteland", description = "West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.\n\nSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly.", objectives = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.", progress = "This is a dangerous land to be so casual, <class>.  What brings you to the wastes of Silithus?", completion = "Rabine sent you, did he?  Well, consider yourself welcomed here... as much as this desolate and forsaken land can welcome someone.\n\nI wasn't alive during the time of the great tribulations that took place here, but there are parts of this desert that might as well be eerie pictures of that forgotten past.  With your help, the Cenarion Circle might be able to bring finality to a threat that was supposed to have died generations ago." }
WordHunterWoW_QuestEN[1125] = { title = "The Spirits of Southwind", description = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, <name>.\n\nFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...\n\nThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed.", objectives = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.", completion = "I had thought that maybe the huge swirling hive near the ruins of the village had played a part in its demise.  It would seem that your work has proven this to be correct; the proximity of the hive poses a threat to any future work we may do here.\n\nI thank you for your benevolence in freeing the souls of the fallen; such work is never easy, I know.  When you're ready, however, I'd like to ask for your assistance once more..." }
WordHunterWoW_QuestEN[1126] = { title = "Hive in the Tower", description = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.\n\nThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.", objectives = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity. Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.", progress = "Well, did it work?  You're still in one piece, which is good news.  Did you find anything?", completion = "What the... what is it?\n\nIt has the shape of a... box, maybe?  It's encrusted over something fierce.  Wait, there's a portion here that's exposed... is that a book underneath all this gunk?\n\nI think you've stumbled across quite the find here, <name>... well, at least I hope it is.  Perhaps it is a journal or a log from ancient times, preserved in this shell.\n\nI think I know a way to find out what this is." }
WordHunterWoW_QuestEN[1127] = { title = "Fool's Stout", description = "So you want some Fool's Stout, eh?  Thinking of heading back to the races...?\n\nAll right, bring me more of Zanzil's mixture and I'll make some more stout for you.You will receive:", objectives = "Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay." }
WordHunterWoW_QuestEN[1130] = { title = "Melor Sends Word", description = "<name>, Melor Stonehoof has heard of your deeds, and has set a path before you.\n\nIf you wish to take it, then go to Thunder Bluff and speak with Melor.  You will find him on Hunter's Rise.", objectives = "Speak with Melor Stonehoof in Thunder Bluff.", completion = "So, <name>, you have come.  Now, are you prepared to journey through distant lands?\n\nIf so, young <class>, then listen on..." }
WordHunterWoW_QuestEN[1131] = { title = "Steelsnap", description = "At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings.\n\nBut the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing.\n\nThe hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts.\n\nFind Steelsnap, <name>.  Find him, and defeat him.", objectives = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.", progress = "Have you defeated the foul Steelsnap, <name>?", completion = "In defeating the creature Steelsnap, you have cleansed the Thousand Needles of a horrible taint.\n\nAnd that, <name>, is your lesson this day." }
WordHunterWoW_QuestEN[1132] = { title = "Fiora Longears", description = "Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!\n\nOh, I wish I had your fortune, good <class>, for I see the sea in your future!\n\nIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Auberdine.  Speak there with my partner, the elf, Fiora Longears.\n\nShe'll start you on your Kalimdor adventure!Upon completion of this quest you will gain:", objectives = "Speak with Fiora Longears on the docks at Auberdine in Darkshore.Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!\n\nOh, I wish I had your fortune, good <class>, for I see the sea in your future!\n\nIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Auberdine. Speak there with my partner, the elf, Fiora Longears.\n\nShe'll start you on your Kalimdor adventure!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1133] = { title = "Journey to Astranaar", description = "{name}, go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services.\n\nBut don't bother mentioning who sent you.  Shindrell does not know me...", objectives = "Speak with Shindrell Swiftfire in Astranaar.", completion = "You are here to offer your services to the Alliance, <name>?  We welcome the aid, for although its beauty remains... Ashenvale Forest is not the peaceful place it once was." }
WordHunterWoW_QuestEN[1134] = { title = "Pridewings of Stonetalon", description = "We are not in open war with the Horde, but our peace is fragile.  We often find their agents moving against us, but they do so covertly.\n\nOne such advance was revealed to us from hidden sources in Theramore, claiming that the orcs collect venom from the pridewings near Mirkfallon Lake, in the Stonetalon Mountains to the south.  Orc assassins then use the venom on their secret death raids against the Alliance!\n\nIf this is true, then we must stop them, <name>.  We must deny them their source of venom.", objectives = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.", progress = "Do you have the pridewing venom sacs, <name>?  We cannot allow the orcs to use the beasts' poisons against us!", completion = "Thank you, <name>.  It saddens me to order the slaughter of creatures who may not willingly aid our enemies, yet it is my duty to do so.\n\nYour heart might weep for the pridewings you slew, my friend, but may your heart then swell in knowing that your allies are safe from the pridewings' venom." }
WordHunterWoW_QuestEN[1135] = { title = "Highperch Venom", description = "As you may know, wyverns are often tamed by orcs for use as mounts.  But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself.  So if you're not afraid to do a little wyvern hunting, then... I have a job for you.\n\nThere is a place called Highperch in the land of a Thousand Needles, west of here.  The Highperch wyverns have a potent venom.  Potent, and valuable.You will receive:", objectives = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore." }
WordHunterWoW_QuestEN[1136] = { title = "Frostmaw", description = "<name>, it is now time for you to travel to far-off lands.  You are ready.\n\nYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.\n\nBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.\n\nNow go, <name>.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.", objectives = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.", progress = "Have you been to the Alterac Mountains, <name>?  Did you face the elusive Frostmaw?", completion = "Both strength and cunning were needed to find and defeat Frostmaw, <name>.  You have both.\n\nYour path has taken you to the valleys of Thousand Needles and to the high mountains of Alterac.  It will one day lead you through all the Earthmother's lands, for such is the way of the hunter." }
WordHunterWoW_QuestEN[1137] = { title = "News for Fizzle", description = "Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.\n\nTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.\n\nSend Fizzle Brassbolts my regards, and tell him what I told you.\n\nSafe travels, <name>.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!", objectives = "Speak with Fizzle Brassbolts on the Shimmering Flats in Thousand Needles.", completion = "<name>, you're back!  You found Martek?  You spoke with him?  What did he say?  Can he help??\n\nTell me, tell me, tell me!!" }
WordHunterWoW_QuestEN[1138] = { title = "Fruit of the Sea", description = "I love crab.  Crabs are the fruit of the sea!  You can bake it, barbecue it, boil it, and broil it.  They're pan fried, deep fried, and stir fried.  There's crab salad, crab soup, crab stew, pepper crab, lemon crab, whipper root crab, and Ironforge surprise crab.  That's... that's about it.\n\nI'm here fishing right now, so I can't get any fine crab chunks.  You can pick them out of reef crawlers and encrusted tide crawlers.  You can make a lot with it.  You can bake it, barbecue it, boil it...", objectives = "Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.", progress = "...lemon crab, whipper root crab, and Ironforge surprise crab.  That's about it.\n\nOh, hello there <name>.  Do you have them fine crab chunks I was telling you about?", completion = "Wow, these fine crab chunks are what I need.  Thanks <name>!  I found this while I was fishing a while ago, and I have no use for it.  Maybe you can do something with it.  It sure don't make any good crab dishes.\n\nI told you all about crabs, right?" }
WordHunterWoW_QuestEN[1139] = { title = "The Lost Tablets of Will", description = "We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.\n\nWe must still recover the Tablet before the Shadowforge clan finds it.\n\nReturn to Uldaman, find the tablet, and return here immediately.", objectives = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.", progress = "Hammertoe's quest must be actualized, <name>. I owe him that much.\n\nYour return to Uldaman is imperative not only to that goal, but also to the safety of all dwarven kind. With the tablet in the hands of the Dark Irons who knows how powerful their army of golems would become.", completion = "<Advisor Belgrum shakes his head in disbelief as you hand him the stone shard.>\n\n<name>, this is amazing. I shall have this brought to the king's mages as soon as possible. They will want to study it to find out if the legends are true. But that is a discussion for another time: you have aided our people more than I would have ever expected--thank you." }
WordHunterWoW_QuestEN[1140] = { title = "The Tower of Althalaxx", description = "The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies.\n\nFrom Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale.\n\nBe careful out there, <name>, the satyrs' blood-soaked temples can be unsettling even for a seasoned <class> such as yourself.", objectives = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.", completion = "Perhaps the satyrs have been allowed to persist in the forest for too long. I will speak with Elissa about it when next I travel to Auberdine.\n\nNonetheless, with the soulgems destroyed, Athrikus' power will be greatly diminished. We must seize on this opportunity to eliminate him and his cult." }
WordHunterWoW_QuestEN[1141] = { title = "The Family and the Fishing Pole", description = "I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish.\n\nThere's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too.\n\nSay, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.", objectives = "Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.", progress = "There's plenty of good dishes you use Darkshore groupers for.  They're good to eat, but I think it's more fun catching them.\n\nYou caught any Darkshore groupers yet?", completion = "Them's some real nice groupers, <name>!  Thanks for helping me out!\n\nYou're at least as good of a fisherman as my cousin, Graun Blump.  She also has a beard and she smells kinda funny, but that don't do nothing to stop her fishing.  I reckon you have what it takes to use a Blump Family Fishing Pole." }
WordHunterWoW_QuestEN[1142] = { title = "Mortality Wanes", description = "I have not long to live... so... so... weak.\n\n...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...\n\nBut before I... d-d-die...\n\n...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...\n\nFind it p-p-please... and return it to Treshala in Darnassus...\n\n...along with w-w-word of my lonely... death.", objectives = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.", progress = "What brings you to my home, <race>?", completion = "No!\n\n'Tis not fair. Oh, cruel and intolerable world!\n\nI must now carry this burden of grief and not let Heralath's work die with him.\n\nYou were brave to journey from such a dangerous place, <name>. But please leave me now.\n\nIn solitude I shall mourn." }
WordHunterWoW_QuestEN[1143] = { title = "The Tower of Althalaxx", description = "I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before.", objectives = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.", progress = "Athrikus Narassin is an ancient and powerful warlock. Perhaps we should wait for Delgren's assistance, but he obviously had much faith in you to send you alone.", completion = "With the death of Athrikus, I hope that the demonic forces in this area will be driven back. I have no doubt that they will regroup and return, but then we shall be even more prepared to meet their threat." }
WordHunterWoW_QuestEN[1144] = { title = "Willix the Importer", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Blueleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", objectives = "Escort Willix the Importer to the exit of Razorfen Kraul.", completion = "Thanks again, friend! I told you I'd make it worth your while." }
WordHunterWoW_QuestEN[1145] = { title = "The Swarm Grows", description = "Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.\n\nI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.\n\nBelgrom usually be found outside the warriors' guild house.", objectives = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.", progress = "I envy you, <class>. You have the look of someone who's been outside the walls of Orgrimmar for a while.\n\nI myself would travel in the name of the Warchief if Thrall didn't have need of my skills here in the city. But he leads us well, and I trust his judgement--I remain here for as long as he needs me.", completion = "Ah, a note from Korran. He has been a loyal servant for some time now. I was wondering how his duties were going in the Crossroads." }
WordHunterWoW_QuestEN[1146] = { title = "The Swarm Grows", description = "So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.\n\nA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.\n\nThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.", objectives = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.", progress = "War brings my group and I to the Shimmering Flats, <class>. What brings you here?", completion = "Don't mind the thundering echoes off the mountains' walls. The goblins and gnomes are out among the Flats racing one another in atrocities created by what they call science. There are bigger threats here in Thousand Needles, one of which killed more than half my war party.\n\nBut we remain here until we hear word from Belgrom in Orgrimmar. Until then, we hold our position here, and stay vigilant." }
WordHunterWoW_QuestEN[1147] = { title = "The Swarm Grows", description = "Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.\n\nI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?", objectives = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.", completion = "Ha! That ichor you're covered in actually makes you prettier, <name>! It certainly does make you reek at the same time though. Don't stand too close to the kodo; you'll either start a stampede or cause them to go into heat.\n\nI think my companions would agree that your smell alone is proof you've done your part to help us against those insect creatures. Thank you, <name>." }
WordHunterWoW_QuestEN[1148] = { title = "Parts of the Swarm", description = "You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.\n\nLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.", objectives = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.", progress = "Ah, it been a long time since you've come to see me, <name>. What can I do for you today? You be looking like you've seen the face of battle recently. Good... good for the Horde and good for you. The more battle you've seen, the more helpful you'll be; stronger, too.", completion = "Ahh, you've seen Moktar recently? He always be lookin' out for me. I'm sorry to hear he spends his time watching over his little war band instead of seeing battle, but I'm sure he be takin' great joy in killing members of the Explorers' League.\n\nYou be smart to bring me these specimens, <name>. Along with the eggs we be findin' in the Field of Giants, these should give me a good start in figuring out what these insects are, and what they be wantin'." }
WordHunterWoW_QuestEN[1149] = { title = "Test of Faith", description = "So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.\n\nMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.\n\nIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.\n\nThe first is a Test of Faith.", objectives = "If you have faith, leap from the planks overlooking Thousand Needles.So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.\n\nMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.\n\nIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.\n\nThe first is a Test of Faith.", completion = "It is not until faced with unforeseen adversity that we begin to see how strong our spirits are. You took the leap of faith even though you had no guarantees that you would survive. Your mind is open, and your spirit is prepared for what is to come.\n\nIf you are willing, then the next of your tests is ready." }
WordHunterWoW_QuestEN[1150] = { title = "Test of Endurance", description = "I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.\n\nFirst is a test of endurance. Go to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.", objectives = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", progress = "You must be prepared spiritually, physically and mentally for the challenges that lie ahead of you.\n\nToo often do we rush forward before we are ready. I consider it my duty to the youth, no matter which tribe they belong to, to prepare them for the dangers they may face after they leave the sanctity of their home.", completion = "Grenka was powerful, even by <race> standards. You should be proud of your accomplishment this day.\n\nDuring your test of faith you displayed strength of spirit, and now you have shown endurance in battle by taking on the Roguefeather harpies, but the time has come for a new test." }
WordHunterWoW_QuestEN[1151] = { title = "Test of Strength", description = "During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.\n\nThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.\n\nTo test your strength, find Rok'Alim in Thousand Needles and slay him.", objectives = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", progress = "Rok'Alim is also called the Pounder by the centaur tribes in Thousand Needles because of the thundering his fists make as he pummels the creatures brave, or stupid, enough to stand in his path.", completion = "The Test of Strength is done. You have shown strength and bravery, and you are now prepared for the final test before these rites are completed." }
WordHunterWoW_QuestEN[1152] = { title = "Test of Lore", description = "Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\n\nIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, <name>.\n\nWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, <name>, the night elves may wish to impede your test.", objectives = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\n\nIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, <name>.\n\nWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, <name>, the night elves may wish to impede your test.", completion = "The days and nights grow colder throughout the world as goblins rape the land, and the night elves point fingers at the younger races. The Forsaken and orcs are not the only ones to blame for the hardships found throughout Kalimdor and Lordaeron. Many of the intelligent races have contributed to the world's pain. Dorn knows this, and he has sent you to me because you have shown the attributes necessary to realize it also.\n\nNow you stand before Braug." }
WordHunterWoW_QuestEN[1153] = { title = "A New Ore Sample", description = "<class>, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.\n\nTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.", objectives = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.", progress = "I saw the travelers again--the ones that would not sell me a sample of the ore. I spit at them for not helping the warchief.\n\nMay they die in battle like cowards and not like warriors as should be the right of all people who ally themselves with the Horde.", completion = "A good sample, <name>. A good sample indeed.\n\nThose travelers can no longer lord over me the ore they found, now that you have been successful.\n\nI shall get to work on it immediately. If it proves strong enough, I will send a weapon crafted from the material back to the warchief to show him our success.\n\nI shall not forget your help, <class>." }
WordHunterWoW_QuestEN[1154] = { title = "Test of Lore", description = "You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.\n\nI shall explain it simply: find the book I name, study it, and answer my question about its contents.\n\nWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.", objectives = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", progress = "Bring me the book after you've studied it. I will not ask you your question until after you have given me the book.", completion = "This is the book I named. There is hope you will answer my question correctly then... unless you've forgotten to study its contents.\n\nWhen you are prepared, speak to me again and I shall ask a question of you." }
WordHunterWoW_QuestEN[1159] = { title = "Test of Lore", description = "Well done, <name>. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.\n\nSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.\n\nHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.", objectives = "Find Parqual Fintallas in Undercity.", completion = "Braug sent you? Impossible.\n\n<Parqual looks you up and down.>\n\nBraved Dor'Danil, took a leap of faith, fought and overpowered a powerful elemental? Bah! You're probably a farce; some adventurer that overheard talk in a tavern. And now you think you have what it takes to pass my test. So be it... <class>." }
WordHunterWoW_QuestEN[1160] = { title = "Test of Lore", description = "I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.\n\nGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.\n\nBring it to me.", objectives = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.", progress = "I hope you made the Scarlet Crusade suffer some before stealing the book from them.\n\nMy views of their kind are not unwarranted. The Crusade may have been followers of the Light at one time, but now, they seek to destroy any creatures that have not sided with their religion. They believe all undead, Forsaken or otherwise, must be cleansed, and those traveling in their lands must either be insane, or subject to the undead's powerful magics. Idiots. Idiots and fools; all of them.", completion = "This is the book I sent you to search for.\n\n<Parqual slowly caresses his hand over the top of the book as he stares down at it.>\n\nSo now you wish a question to prove your mind is as powerful as your body and spirit. If you have studied the book long enough, then I shall ask you your question and you can be done with these tests!" }
WordHunterWoW_QuestEN[1164] = { title = "To Steal From Thieves", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", objectives = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.", progress = "Kill them all and bring me their heads!", completion = "You stand before me as a figure of vengeance, and I bow down before you in thanks.\n\nWith that cow's death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off." }
WordHunterWoW_QuestEN[1166] = { title = "verlord Mok'Morokk's Concern", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny <race>, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", objectives = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.", progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good <race>. Me miss things very much. Me like you now." }
WordHunterWoW_QuestEN[1167] = { title = "The Tower of Althalaxx", description = "Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.", objectives = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.", completion = "Ah, it's good to see you again, <name>! The strangest things have been happening around here, I'm glad you showed up!\n\nIt was very strange, <name>. Everything seemed normal--well, as normal as things get around here--and then suddenly there was a blinding flash of light from the upper room of the tower. Then came the screams. The cries split the air, and lightning struck the ground from time to time. What's going on?" }
WordHunterWoW_QuestEN[1168] = { title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", objectives = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.", completion = "You kill many of the black dragon army. You brave <race>.\n\nMake Tharg happy." }
WordHunterWoW_QuestEN[1169] = { title = "dentifying the Brood", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, <name>? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", objectives = "Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.", progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home." }
WordHunterWoW_QuestEN[1170] = { title = "he Brood of Onyxia", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", objectives = "Speak with Overlord Mok'Morokk in Brackenwall Village.", completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here." }
WordHunterWoW_QuestEN[1171] = { title = "he Brood of Onyxia", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", objectives = "Speak with Draz'Zilb in Brackenwall Village.", completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done." }
WordHunterWoW_QuestEN[1172] = { title = "he Brood of Onyxia", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", objectives = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.", completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, <name>.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south." }
WordHunterWoW_QuestEN[1173] = { title = "hallenge Overlord Mok'Morokk", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny <race>!\n\nYou tell me when ready for good beating.", objectives = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, <name>.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all." }
WordHunterWoW_QuestEN[1174] = { title = "Gnomes Win!", description = "", objectives = "" }
WordHunterWoW_QuestEN[1175] = { title = "A Bump in the Road", description = "After the big crash with the goblins' Red Thunder racer and a basilisk, Kronkrider hired me on to take care of the track. I don't know what all the animals out on the flats are feeding on to grow so big, but we have to be careful to thin them out so they won't wander onto the track when a race is going on.\n\nTell you what. If you want to go out and make a little profit, go out and remove the basilisks from the area.", objectives = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.", completion = "I hope you didn't kill any of the basilisks on the tracks themselves! It takes a long time for the carcasses to decay in the sun, and I'd rather not have to take a shovel out to clean up." }
WordHunterWoW_QuestEN[1176] = { title = "Load Lightening", description = "When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.\n\nWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.\n\nBring me some and I'll give you a good price on them.", objectives = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.", progress = "Do you have those bones for me? I was just about to start working on lightening the steering rig, but I don't want to open her up without all the parts I need.", completion = "Great! I can get the crew working on this right away. Thanks, <name>!" }
WordHunterWoW_QuestEN[1177] = { title = "Hungry!", description = "Mud big ogre.\n\nMe hungry.\n\nGo bash fishy. Bring Mud food.\n\nYou feed Mud or Mud eat you.", objectives = "Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.", progress = "Gimme food or me eat you.", completion = "Me like fishy head!\n\nMe no eat you now." }
WordHunterWoW_QuestEN[1178] = { title = "Goblin Sponsorship", description = "Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.\n\nYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!\n\nA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!", objectives = "Speak to Gazlowe at Ratchet in The Barrens.", completion = "Pozzik sent you, huh? You know, Pozzik was one of the most respected tinkerers in Undermine before he retired to start working on the racers.\n\nThe first thing he did when he joined the team was develop the two engine model racers. Could be that the businesses will suffer without him working with the Tinkers' Union, but who cares, right? There's nothing like the races!" }
WordHunterWoW_QuestEN[1179] = { title = "The Brassbolts Brothers", description = "You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat!\n\nA couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions.\n\nSo they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip!\n\nCan you?", objectives = "Bring the crate of crash helmets to Wizzle Brassbolts at Mirage Raceway in Thousand Needles.", progress = "Watch where you're stepping!  Watch watch watch!!  This is delicate stuff you see here, and if we're to win then it must all work perfectly!", completion = "Ah!  Longbeard sent you with a load of helmets!  Hooray!\n\nNow maybe we can talk a pilot into driving our car..." }
WordHunterWoW_QuestEN[1180] = { title = "Goblin Sponsorship", description = "Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.\n\nIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.\n\nCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records.", objectives = "Speak with Wharfmaster Lozgil in Booty Bay.", completion = "Shipments to Ratchet? Let me just check the logbooks...\n\nNo, the most recent shipment I have on record of going out to Ratchet were boots from Drizzlik. Hasn't been much else, other than building supplies and tools. Definitely no race parts." }
WordHunterWoW_QuestEN[1181] = { title = "Goblin Sponsorship", description = "I'm afraid I can't be of much more help to you, <name>. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.\n\nYou'll find him at the tavern across the harbor, top floor.", objectives = "Speak with Baron Revilgaz in Booty Bay.", completion = "Oh, sure of course I know what you're talking about. Nope, can't help you though. Some of my men were supposed to go track down the blueprints for the fuel regulator, but they came back empty-handed." }
WordHunterWoW_QuestEN[1182] = { title = "Goblin Sponsorship", description = "See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.\n\nYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key.", objectives = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.", progress = "Much as I hate to admit it, that gnome team they have out there is pretty good. Our boys need every edge they can get.", completion = "Now, let me just get a copy of these blueprints for my own notes and you can bring these straight to Pozzik. Wouldn't want him to think that one of his sponsors was abandoning him." }
WordHunterWoW_QuestEN[1183] = { title = "Goblin Sponsorship", description = "You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!", objectives = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.", progress = "<name>! Did you manage to track down the fuel regulator?", completion = "I was hoping that it would be already assembled, but this does present the unique opportunity to improve on the design from the ground up. Thanks, <name>. I'll be able to sketch up some improved schematics, build the thing, and have it installed real soon." }
WordHunterWoW_QuestEN[1184] = { title = "Parts of the Swarm", description = "Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.", objectives = "Return to Belgrom Rockmaul in Orgrimmar.Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.", completion = "I'm appreciative of your efforts, <class>. The warchief will enjoy hearing how tenacious you have been in your duties.\n\nOh, of course I will mention your name to him. He speaks to me often and values my opinions greatly.\n\nGo now, I have much to do. And if you speak to Korran soon, and he has news of these creatures, then return to me--I would think they are a threat that must be taken seriously." }
WordHunterWoW_QuestEN[1185] = { title = "Under the Chitin Was...", description = "", objectives = "Hey, it's you again!  Well, I mean you - as in the you that is <name>!  Yes - that you!\n\nHey, let me start over!\n\nThat object you found in Silithus - it was in fact a book.  It was a journal written in a very ancient dialect of what we now call the Darnassian tongue.  It'll take a while, but I'm going to go over it very thoroughly.  I thought you should know that what you found was extremely valuable for the Circle.\n\nThe den mother's all excited and everything!" }
WordHunterWoW_QuestEN[1186] = { title = "The Eighteenth Pilot", description = "I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.\n\nHe's a little off his rocker, though, so try not to act too surprised.", objectives = "Speak with Razzeric on the Shimmering Flats in Thousand Needles.I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.\n\nHe's a little off his rocker, though, so try not to act too surprised.", completion = "You're the <race> that's been helping Pozzik out, right? I was like you once, running around the pit area, helping with whatever work the mechanics would let me do.\n\nNow look at me! The goblin racing team's pilot extraordinaire!" }
WordHunterWoW_QuestEN[1187] = { title = "Razzeric's Tweaking", description = "Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though.\n\nAfter Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice!\n\nI ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, <name>!", objectives = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.", progress = "How'm I supposed to show my face around the track without a little extra kick to get me going? It's a travesty, I tell you.", completion = "Just take a look at this beauty! Fifteen pounds of solid seaforium power! Once I get this strapped on to the side of my racer, I'll be around the track so fast I'll beat the gnomes twice!" }
WordHunterWoW_QuestEN[1188] = { title = "Safety First", description = "But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.\n\nYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this.", objectives = "Bring the Seaforium Booster to Shreev at Gadgetzan in Tanaris.", progress = "As I'm sure you know, the Gizmorium can service all of your tinkering needs! How can I help you?", completion = "Only Razzeric would take a look at this and say that I'd somehow put some sort of safety lock on it. This booster is almost completely seaforium explosives. I already modified it so that more of its payload would be delivered upon use, but Razzeric is never content unless he goes to eleven!" }
WordHunterWoW_QuestEN[1189] = { title = "Safety First", description = "There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.\n\nWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?", objectives = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats in Thousand Needles.", progress = "Can you believe Pozzik put a bucket of sand on the racer? How am I supposed to hit my maximum speed with a bucket of sand under the seat?", completion = "Now that's more like it! I wish I could see the look on the gnomes' eyes when they see me set this baby off.\n\nToo bad I'll be too busy pulling off a new course record!" }
WordHunterWoW_QuestEN[1190] = { title = "Keeping Pace", description = "The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.\n\nWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.\n\nZamek can create a diversion for you, so that you can steal those plans from them.", objectives = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats in Thousand Needles.", completion = "Scribbled in a hasty, hurried hand, a scroll of notes and designs for the refinement of some raw material." }
WordHunterWoW_QuestEN[1191] = { title = "Zamek's Distraction", description = "", objectives = "Let's go!" }
WordHunterWoW_QuestEN[1192] = { title = "Indurium Ore", description = "", objectives = "" }
WordHunterWoW_QuestEN[1193] = { title = "A Broken Trap", description = "", objectives = "" }
WordHunterWoW_QuestEN[1194] = { title = "Rizzle's Schematics", description = "Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.\n\nMuch of the other notes relate to the heat resistant properties.\n\nUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore.", objectives = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats in Thousand Needles.\n\nProvided item:", completion = "Indurium? Interesting... If it is capable of resisting heat to the degree that you say, it would explain the performance increase the gnomes have displayed of late.\n\nThis sample you've brought to me will be invaluable, also. I will be able to perform some tests on this, but I'll need more for this to actually be of any use to us." }
WordHunterWoW_QuestEN[1195] = { title = "The Sacred Flame", description = "The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.\n\nWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.\n\nTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.", objectives = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.", progress = "Once we have the filled phial, we can send it along to my associate, Rau, in the Thousand Needles. He was the one who requested the phial of water, so he'll better know how we can make use of it.", completion = "Very good. This should fill Rau's request just fine. Could you deliver this to him? You might enjoy spending some time out in the Needles." }
WordHunterWoW_QuestEN[1196] = { title = "The Sacred Flame", description = "Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens.\n\nI wouldn't be surprised if you can help us out further.", objectives = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.", progress = "I don't suppose you've been sent by Zangen, hm?", completion = "Hm, yes, this phial of water will serve our purposes perfectly. Because of the shared ancestry of the dryads and the centaurs, the water of the moonwells will enable us to breach the protection of the eternal flame surrounding the centaur relic." }
WordHunterWoW_QuestEN[1197] = { title = "The Sacred Flame", description = "Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.\n\nYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.\n\nBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.", objectives = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.", progress = "I am eager to put my hands upon the Cloven Hoof. Have you taken it yet?", completion = "I sense a strange energy emanating from the Hoof... I have no doubt that we will discover surprising new information about the centaur from its study.\n\nMy thanks, <name>. Now I must begin to decipher the mysteries you have brought to me." }
WordHunterWoW_QuestEN[1198] = { title = "In Search of Thaelrid", description = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps to the west.\n\nMy role here is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been days now since I sent a scout to check on the activity inside Blackfathom Deeps. Scout Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out Thaelrid for me, <name>.", objectives = "Seek out Scout Thaelrid inside Blackfathom Deeps.Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps to the west.\n\nMy role here is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been days now since I sent a scout to check on the activity inside Blackfathom Deeps. Scout Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out Thaelrid for me, <name>.", completion = "Dawnwatcher Shaedlass was good to send you. There is indeed a wicked plot underway in this corrupted place." }
WordHunterWoW_QuestEN[1199] = { title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps to the west.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", objectives = "Bring 10 Twilight Pendants to Sentinel Aluwyn at the Blackfathom Camp.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding their presence?", completion = "You are no doubt of brave and noble blood, <name>. The Argent Dawn commends you for your efforts against evil." }
WordHunterWoW_QuestEN[1200] = { title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, <name>, please.", objectives = "Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp.", progress = "Time is a precious commodity, <class>.\n\nMy role here in Darnassus is to ensure that the Argent Dawn thrives and that the evil forces encroaching upon Kalimdor are thwarted.\n\nState your business quickly or be on your way.", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nBy the light! To sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, <name>. I salute you on behalf of the Argent Dawn." }
WordHunterWoW_QuestEN[1201] = { title = "Theramore Spies", description = "The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top!\n\nNow is the chance to do just that.\n\nAlliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow.\n\nHunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' presence!", objectives = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.", completion = "Good work.  Their infiltrators are skilled, but they're not good enough to escape the watchful eye of the Horde!" }
WordHunterWoW_QuestEN[1202] = { title = "The Theramore Docks", description = "{name}, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.\n\nOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.\n\nThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, {name}, and bring them to me.", objectives = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.", progress = "Did you find the documents, <name>?  They hold information vital to the stability of the Alliance and, hence, vital to the security of the Horde.", completion = "I commend you, <name>.  This was not an easy mission.  But the documents you gained are valued greatly by our superiors." }
WordHunterWoW_QuestEN[1203] = { title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a sword.  I call it a swing blade.\n\nYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", objectives = "Bring Razorspine's Sword to \"Swamp Eye\" Jarl at Swamplight Manor.", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks." }
WordHunterWoW_QuestEN[1204] = { title = "Mudrock Soup and Bugs", description = "I'm working on a dish I call \"Mudrock Soup and Bugs.\"  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh!\n\nSo, {name}, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay.\n\nBut I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked...\n\nThey say the forked tongues have a distinct flavor, and I want that flavor in my dish...", objectives = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.", progress = "Did you get the forked tongues?", completion = "These will do fine!  Thank you, <name>!\n\nNow I'll try different cooking techniques on these tongues to find the best way to bring out their flavor.\n\nEventually I'll have a dish worthy of serving at the Blue Recluse in Stormwind!" }
WordHunterWoW_QuestEN[1205] = { title = "Deadmire", description = "Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.\n\nOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.\n\nYet now he lives in constant, maddening pain.  You must end the life of this noble creature, {name}.  You must lead Deadmire to peace.", objectives = "Bring Deadmire's Tooth to Melor in Thunder Bluff.", progress = "Do you have the tooth of Deadmire, <name>?  Have you ended the creature's suffering?", completion = "Very good, <name>.\n\nI am sure the hunt was not easy, but it is good to know the beast's pain has finally ended." }
WordHunterWoW_QuestEN[1206] = { title = "Jarl Needs Eyes", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", objectives = "Bring 20 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.", progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh." }
WordHunterWoW_QuestEN[1218] = { title = "Marsh Frog Legs", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.\n\nThen I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", objectives = "Bring 10 Marsh Frog Legs to \"Swamp Eye\" Jarl in Dustwallow Marsh.", progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew." }
WordHunterWoW_QuestEN[1219] = { title = "he Orc Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", objectives = "Bring the Spy's Report to Lieutenant Aden in Theramore.", progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!" }
WordHunterWoW_QuestEN[1220] = { title = "aptain Vimes", description = "Captain Vimes should see the orc report you found, <name>.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", objectives = "Bring the Spy's Report to Captain Garran Vimes.", progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says..." }
WordHunterWoW_QuestEN[1221] = { title = "Blueleaf Tubers", description = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.", objectives = "Grab a Crate with Holes.\nGrab a Snufflenose Command Stick.\nGrab and read the Snufflenose Owner's Manual.\n\nIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.", progress = "Do you have the tubers, <name>?", completion = "Great, you got them!  I can sell these to my contacts for a bundle!\n\nThanks for the delivery, <name>!  You are a great partner." }
WordHunterWoW_QuestEN[1222] = { title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!\n\nI need help handling the critters around here, and you fit the mold, buddy.\n\nThe cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty.\n\nAnyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?", objectives = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.", completion = "Mr. Ignatz was just here with the bogbean leaves, and he told me you helped him out of some real trouble.\n\nThank you, <name>.  I will ask my uncle to treat you to a feast the next time you visit the Blue Recluse in Stormwind." }
WordHunterWoW_QuestEN[1238] = { title = "The Lost Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", objectives = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", progress = "You have something for me?", completion = "Good work, <name>.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp..." }
WordHunterWoW_QuestEN[1239] = { title = "The Severed Head", description = "Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.", objectives = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.", progress = "You have another matter to report, <name>?", completion = "This is the head of Marg Nighteye!  As I feared, he is dead.\n\nLook at the wound on his neck!  Could a weapon have made that ragged cut, or did some beast slay our agent?\n\nThis is a mystery we must solve, <name>.  We must discover if Marg's death was at the hands of the Alliance!" }
WordHunterWoW_QuestEN[1240] = { title = "The Troll Witchdoctor", description = "We must know the events surrounding Marg's death!  And the only way to do that, <name>, is through the witch-magic of trolls.\n\nBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.\n\nKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.", objectives = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.", progress = "There is an angry spirit about you, brother.  What brings you to Kin'weelay?", completion = "Ah, I now see.  The spirit of this orc is bound in our world, boiling with rage from a task yet undone.\n\nWell, let us have words with this angry orc..." }
WordHunterWoW_QuestEN[1241] = { title = "The Missing Diplomat", description = "Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.\n\nI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.\n\nAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.\n\nIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions.", objectives = "Find Jorgen in Stormwind City.", progress = "Hmph, you better have good reason to interrupt a man and his fishin'. I don't take kindly to peddlers, let alone beggars.", completion = "Hmm... <Jorgen looks up at you through squinted eyes.>\n\nAll right. I'll help ya, but not because I want to, but because I'm obligated.\n\nAnd let's get one thing straight: you're knowin' far more than you should to begin with. Let's keep this our little secret, and don't go blabbin' at any taverns about anything you find out. Understand?" }
WordHunterWoW_QuestEN[1242] = { title = "The Missing Diplomat", description = "Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.\n\nI'm gonna only impress this on ya once more, <name>: treat this matter seriously, and keep your yapper shut.\n\nYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.", objectives = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.", progress = "Hello, <name>. Is there something I can do for you? Perhaps you'd like to try some of our special Trias cheddar? Or a block of Darnassian bleu?", completion = "I'm sorry, a letter for me? Well, I'll be... not often you get a delivery that's not a crate or barrel when all you do is work. Let's see what this is about.\n\n<Elling looks up at you while he opens the letter.>\n\nYou look a little tense, you okay, <name>?" }
WordHunterWoW_QuestEN[1243] = { title = "The Missing Diplomat", description = "Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?\n\nAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!\n\nHere's what's gonna happen, <name>. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.\n\nHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can.", objectives = "Give the Sealed Note to Watcher Backus in Duskwood.", progress = "Not too safe to be traveling about in the woods, <name>. Be careful, and if you see anything suspicious or dangerous, contact the Watchers immediately. Don't try and take anything on yourself. We're not responsible for anything terrible that might happen to you.\n\nBut we both know you're gonna ignore me and fight whatever comes out of the darkness anyway, don't we? Haha, yeah, you adventurer types... all the same.", completion = "Oh, Trias sent you, huh? That's a little different.\n\nFeel free to fight whatever monstrosities come at you from the darkness. I'm sure you'll be able to handle it pretty easily if you're the type to be hanging around with the likes of him.\n\nSo, what does my friend need of me on such a gloomy day as this?" }
WordHunterWoW_QuestEN[1244] = { title = "The Missing Diplomat", description = "Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat.\n\nBut now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down.\n\nWhy don't you check there first and bring me back anything you find?\n\nThe farmstead is south of the road from Westfall just as you enter Duskwood.", objectives = "Find the Defias Docket and return it to Watcher Backus in Duskwood.", progress = "Be careful out there, <name>. I know Trias was the one to send you here, but that doesn't mean there isn't anything lurking out in the woods that couldn't cause you some trouble... especially with you investigating the Defias.", completion = "You're back safe and sound. Couldn't ask for much more than that, could you?\n\nNow, let's see what we have here. This looks pretty official as far as any Defias documents I've seen. But it could be a dupe just to throw you off track of whatever it is you're looking for." }
WordHunterWoW_QuestEN[1245] = { title = "The Missing Diplomat", description = "Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see.\n\nAnd do me a favor, <name>, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me.", objectives = "Bring the Defias Docket to Elling Trias in Stormwind.", progress = "I see you're back, and in one piece. We both know you're not here for cheese, so let's cut out the pleasantries. Was Backus any help, or have you even left for Duskwood yet?", completion = "Yeah... this is an interesting read. Jorgen and DeLavey were smart to bring me in on this.\n\nSeems the Defias have been trying pretty hard to complete this plan of theirs. Hmm... what's this? \"Fist\"? That's a familiar name." }
WordHunterWoW_QuestEN[1246] = { title = "The Missing Diplomat", description = "Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls.\n\nYou can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willingly.", objectives = "Speak to Dashel Stonefist in Stormwind.", completion = "What?!\n\nYou come into me alley and ask questions about me personal business? Business which you obviously have nothing to do with." }
WordHunterWoW_QuestEN[1247] = { title = "The Missing Diplomat", description = "So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers.\n\nThe guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan.", objectives = "Speak to Elling Trias in Stormwind.", completion = "Good to see you're still alive, <name>. So, it went well with Dashel then, huh?\n\nI've been reading up more on this plan of theirs, and although it doesn't state the name of the diplomat they were after, it does talk about this plan B they enacted after failing on their first attempt to capture him.\n\nThis Slim that Dashel mentioned doesn't have any other name written here, but if you say he's in Menethil, then that's a start." }
WordHunterWoW_QuestEN[1248] = { title = "The Missing Diplomat", description = "A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago.\n\nSpeak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's captured.", objectives = "Speak to Mikhail in the Wetlands.", completion = "Welcome, welcome, welcome, <name>. Good of you to join us. Perhaps an ale today? Or some mutton?\n\nName your pleasure and I'll see to it that you're taken care of. My name is Mikhail, and I look forward to serving you.\n\nHmm? What's that? Trias? Keep your voice down, my friend. This isn't something for the whole tavern to hear about." }
WordHunterWoW_QuestEN[1249] = { title = "The Missing Diplomat", description = "You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you.\n\nHmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him.\n\nDon't look now, <name>, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door.", objectives = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.", completion = "Caught him, huh? Good for you. I'm surprised that was Slim.\n\nI'll be honest, I never thought I'd miss the excitement of some of the more devious underground activities. I guess old habits die hard. Don't mention that to Elling--he'd probably try and get me to come back to Stormwind if he heard I missed the action.\n\nI'm glad I could at least be of a little service to you while you were in Menethil. If you need anything else, just ask." }
WordHunterWoW_QuestEN[1250] = { title = "The Missing Diplomat", description = "The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them.\n\nMy part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know. I swear!", objectives = "Speak to Mikhail in the Wetlands.", completion = "THE KING?! I mean... the king? The real king? Are you joking? You didn't mention you were looking for the king's kidnappers. I didn't even hear he was missing--that would explain his son being crowned some.\n\nI'll send word to Elling right away. He'll want to know you're on the trail.\n\nI would never have guessed Jahn would sell out Stormwind for some lousy coin. Even a rogue's got to have honor when it comes to some things.\n\nThe key now is to find this Hendel. And I think I can help with that." }
WordHunterWoW_QuestEN[1251] = { title = "he Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", objectives = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", progress = "What's that you have there, <name>? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?" }
WordHunterWoW_QuestEN[1252] = { title = "ieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", objectives = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that." }
WordHunterWoW_QuestEN[1253] = { title = "he Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", objectives = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn." }
WordHunterWoW_QuestEN[1258] = { title = "... and Bugs", description = "Another component of my new recipe is the shelled leg of a giant crab.  And the crabs they have in Dustwallow -- spiny rock crawlers they call them -- will be perfect!\n\nThe shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs.  An adult crab might only have one or two such legs, and I need a lot in order to research my dish.\n\nHead on over to the rocks surrounding Theramore and get me those legs!", objectives = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.", progress = "My research with the Mudrock tongues is progressing nicely.  I trust your crab hunt goes well?", completion = "These are wonderful specimens, <name>!  The shells are in perfect condition, and the meat is pink and tender.  The blood of a chef is in your veins, I'm sure of it!" }
WordHunterWoW_QuestEN[1259] = { title = "ieutenant Paval Reethe", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", objectives = "Find out more about Reethe from Adjutant Tesoran in Theramore.", completion = "Hello, <name>. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book." }
WordHunterWoW_QuestEN[1260] = { title = "organ Stern", description = "I'm developing a new menu for the restaurant.  It will be filled with rural dishes with a \"bayou\" theme.  I think my clientele at the Blue Recluse will love them!\n\nI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh.  He's there gathering recipes from the locals, and I must know what he found so far.\n\nThe trip to Theramore is long.  Too long for me.  But I bet a young <class> like yourself would jump at the chance to travel, yes?", objectives = "Speak with Morgan Stern in Theramore.I'm developing a new menu for the restaurant. It will be filled with rural dishes with a \"bayou\" theme. I think my clientele at the Blue Recluse will love them!\n\nI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh. He's there gathering recipes from the locals, and I must know what he found so far.\n\nThe trip to Theramore is long. Too long for me. But I bet a young <class> like yourself would jump at the chance to travel, yes?", completion = "Oh, my uncle sent you, did he?\n\nWell I've been researching recipes and I have some leads, but I need help.\n\nHelp from someone willing to get his feet wet." }
WordHunterWoW_QuestEN[1261] = { title = "Marg Speaks", description = "Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...\n\nBut my mission!  My mission!  You, <name>, must complete it.\n\nWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!\n\nThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!\n\n<name>, you must find that muckshell and recover the pendant!", objectives = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.", progress = "<name>, did you discover Marg's fate?", completion = "This pendant was worn by a soldier of Stormwind??\n\nThank you, <name>.  You have revealed the secret of Marg's death.  But this pendant is a new mystery to solve, one that may have dire effects on the Alliance, and the Horde." }
WordHunterWoW_QuestEN[1262] = { title = "Report to Zor", description = "It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!\n\nRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.\n\nTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.", objectives = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.", progress = "You traveled from Brackenwall Village in Dustwallow?  How fares Nazeer, and how fare his efforts in the marsh?", completion = "This pendant was crafted with great skill and precision, <name>.  No orc would covet such a jewel...\n\nBut many humans would.\n\nI will have this pendant studied.  In time let us hope that its mysteries will be revealed to us." }
WordHunterWoW_QuestEN[1263] = { title = "The Burning Inn <CHANGE TO GOSSIP>", description = "", objectives = "" }
WordHunterWoW_QuestEN[1264] = { title = "The Missing Diplomat", description = "The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them.\n\nCommander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discreetly.", objectives = "Find Commander Samaul in Dustwallow Marsh.", completion = "A pleasure to meet you, <name>. I am Commander Samaul. I'm in charge of Miss Proudmoore's forces here in Theramore.\n\nAlthough I'm quite busy, if you have any questions, please feel free to speak up. I might have to keep it short, but there's no reason for me to be rude if you need my help.\n\nIf you plan on traveling out of the city, I'd suggest you be careful. Besides ogres, orcs and murlocs, the southern part of the swamp is filled with black dragons." }
WordHunterWoW_QuestEN[1265] = { title = "The Missing Diplomat", description = "Hendel? Yes, I know the man. But why would you need one of my soldiers?\n\nElling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can.\n\nI believe Hendel was stationed at the first tower outside of Theramore. Be cautious.", objectives = "Search Sentry Point for any sign of Private Hendel.", completion = "The man you seek, the one known as Hendel, is not here. Other sources have brought to the Lady Proudmoore information I believe you already know. She has asked me to find you, and give you aid in your venture. If you would allow it, I will tell you where to find Private Hendel so we can bring him to justice." }
WordHunterWoW_QuestEN[1266] = { title = "The Missing Diplomat", description = "Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders.\n\nYou should have no problem finding him; just look for the tents along the road.\n\nI have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems.", objectives = "Find Private Hendel in Dustwallow Marsh.", completion = "Hello, citizen. This is a dangerous place to be wandering about. I wouldn't hang around too long if you value your life.\n\nIf you keep your questions short, I'll see if I can help you. Just keep your eyes open for any of those filthy ogres. Rumor has it there's a Horde base somewhere in the swamps. The infiltrators are doing what they can to find it, but the process has been slow going and we've had little progress." }
WordHunterWoW_QuestEN[1267] = { title = "The Missing Diplomat", description = "", objectives = "Speak to Jaina Proudmore in Dustwallow Swamp.", completion = "Let me be first to thank you for all you've done, <name>. You have been an incredible blessing to my people and the people of Stormwind. I am sorry I couldn't make your acquaintance under better circumstances.\n\nUnderstand also that I cannot overtly thank you for your efforts, but I assure you again, it is appreciated.\n\nWhen you visit Theramore in the future, seek me out and I shall try to keep you appraised of the situation.\n\nThank you again, <name>." }
WordHunterWoW_QuestEN[1268] = { title = "uspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead." }
WordHunterWoW_QuestEN[1269] = { title = "ieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", objectives = "Bring Reethe's Badge to Krog in Brackenwall Village.", progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast." }
WordHunterWoW_QuestEN[1270] = { title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!!\n\nI need help handling the critters around here, and you fit the mold, buddy.\n\nA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.\n\nToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?", objectives = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.", completion = "Stinky was here with the herbs I ask of him, and he told me you helped him out of a bind.  Good work!  A friend of Stinky's is a friend of mine!\n\nHe asked me to give you this if I ever saw you, right before he walked back south toward the marsh." }
WordHunterWoW_QuestEN[1271] = { title = "Feast at the Blue Recluse", description = "", objectives = "My nephew said you aided him with his research in Dustwallow, and that you helped his associate out of a tight spot.  Well, we Sterns stick together and we don't ignore our friends!\n\nSo wash your hands, <name>, because we're about to throw a party in your honor!" }
WordHunterWoW_QuestEN[1272] = { title = "Finding Reethe <CHANGE INTO GOSSIP>", description = "", objectives = "" }
WordHunterWoW_QuestEN[1273] = { title = "uestioning Reethe", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", objectives = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.", completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere." }
WordHunterWoW_QuestEN[1274] = { title = "The Missing Diplomat", description = "Excuse me, <sir/madam>. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.\n\nIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.", objectives = "Find Bishop DeLavey in Stormwind Keep.", completion = "Hello, <name>. I am Bishop DeLavey.\n\nNo doubt if you're asking me about my business here in the keep then young Thomas has succeeded in requisitioning you to help our kingdom. He has always been adept at following my requests.\n\nI'm afraid I don't have time to elaborate much, so allow me to be blunt... and please, try to keep this from becoming common knowledge." }
WordHunterWoW_QuestEN[1275] = { title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the Sin'dorei are headed toward. In Blackfathom Deeps, just to the west, you will find both satyr and naga.", objectives = "Relwyn Shadestar at the Blackfathom Camp wants 8 Corrupt Brain stems.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have traveled far and undoubtedly faced great peril.\n\nYour actions have been selfless. 'Tis for the good of all Azeroth that you help me with my research. I thank you, <name>, for all that you have done.\n\nNow if you'll excuse me I have much work to do...." }
WordHunterWoW_QuestEN[1276] = { title = "he Black Shield", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", objectives = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", progress = "Hello there, <class>. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, <name>. I craft so many different shields and sets of armor, I can't keep track of them all." }
WordHunterWoW_QuestEN[1281] = { title = "Jim's Song <CHANGE TO GOSSIP>", description = "", objectives = "" }
WordHunterWoW_QuestEN[1282] = { title = "hey Call Him Smiling Jim", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.", objectives = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.", completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble." }
WordHunterWoW_QuestEN[1283] = { title = "Fire at the Shady Rest <CHANGE TO GOSSIP>", description = "", objectives = "" }
WordHunterWoW_QuestEN[1284] = { title = "uspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead." }
WordHunterWoW_QuestEN[1285] = { title = "aelin's Men", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", objectives = "Return the information about Reethe to Captain Garran Vimes in Theramore.", completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance." }
WordHunterWoW_QuestEN[1286] = { title = "he Deserters", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, <name>. He may be a tough nut to crack.", objectives = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", completion = "Did Vimes send you? Couldn't do his dirty work himself, could he..." }
WordHunterWoW_QuestEN[1287] = { title = "he Deserters", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", objectives = "Speak with Captain Garran Vimes in Theramore about Reethe.Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him." }
WordHunterWoW_QuestEN[1288] = { title = "Vimes's Report", description = "You've done some good work, <name>, best I've seen from an amateur.\n\nLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.\n\nI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.Upon completion of this quest you will gain:", objectives = "Bring Vimes's Report to Lady Jaina Proudmoore in Theramore." }
WordHunterWoW_QuestEN[1301] = { title = "ames Hyal", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?Upon completion of this quest you will gain:", objectives = "Speak with Vincent Hyal in Menethil Harbor.Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1302] = { title = "ames Hyal", description = "My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.\n\nI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him. Look for him on the top floor of that keep near the middle of the city. What's it called... Foothold Citadel, that's it.", objectives = "Speak with Clerk Lendry at Foothold Citadel in Theramore.My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.\n\nI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him. Look for him on the top floor of that keep near the middle of the city. What's it called... Foothold Citadel, that's it.", completion = "James Hyal, James Hyal... Why does that name sound so familiar?\n\nOf course! The Shady Rest Inn incident. If you have any information about what happened there, I would urge you to speak with Captain Vimes about it. He's handling the investigation." }
WordHunterWoW_QuestEN[1318] = { title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!Upon completion of this quest you will gain:", objectives = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings." }
WordHunterWoW_QuestEN[1319] = { title = "he Black Shield", description = "I'm sorry I can't be of much help, <name>, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", objectives = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work." }
WordHunterWoW_QuestEN[1320] = { title = "he Black Shield", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", objectives = "Speak with Captain Garran Vimes in Theramore.", completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened." }
WordHunterWoW_QuestEN[1321] = { title = "he Black Shield", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", objectives = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", progress = "Something for me, <class>?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, <name>.\n\nYou should know that." }
WordHunterWoW_QuestEN[1322] = { title = "he Black Shield", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.", objectives = "Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village.", progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, <name>. Now I rip them open and pour them onto the shield..." }
WordHunterWoW_QuestEN[1323] = { title = "he Black Shield", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", objectives = "Talk with Krog in Brackenwall Village.", completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything..." }
WordHunterWoW_QuestEN[1324] = { title = "The Missing Diplomat", description = "What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time.", objectives = "Defeat Private Hendel in Dustwallow Marsh.", completion = "I assure you, we're all quite upset about current events, but allow us to take him back to Theramore for some questioning, and we'll see about finding the King.\n\nI'm sure my lady Proudmore would like to thank you for your help. Speak to her when you have a moment." }
WordHunterWoW_QuestEN[1338] = { title = "Stormpike's Order", description = "There is a dwarven armorsmith whose work I admire greatly.  His name is Furen Longbeard, and his skill is unmatched.  I need a new shield, and I must have one of his!\n\nThe problem is... Furen is far to the south, in the dwarven district within Stormwind.  In human lands!  I can't imagine why he would live there, so far from Ironforge.  The humans must pay him a king's ransom to keep him there!\n\nSo, if you want to travel and don't mind making some money, then will you send Furen my request for a shield?", objectives = "Bring Stormpike's Request to Furen Longbeard in Stormwind.", progress = "A letter from the dwarven lands?  I wonder who would call from so far to the north...\n\nPlease, let me see the order.", completion = "Ah, a request from one of the Stormpikes.  That's a proud clan, full of quality dwarves.  Rich ones, too.\n\nThank you, <name>.  I'll get to work on Mountaineer Stormpike's shield by the end of the day." }
WordHunterWoW_QuestEN[1339] = { title = "Mountaineer Stormpike's Task", description = "I hear Mountaineer Stormpike is looking for a runner.  Someone to do a little traveling for him.  How about it?  Are you the <race> for the job?\n\nIf so, then you'll find Stormpike at the top of the northern guard tower.", objectives = "Speak with Mountaineer Stormpike.", completion = "That's right.  I have a task that I can't do while I'm guarding.  In fact, it'll take you far from Loch Modan.\n\nYour perfect chance for adventure!" }
WordHunterWoW_QuestEN[1358] = { title = "Sample for Helbrim", description = "A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me.\n\nHelbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.", objectives = "Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.", progress = "You have a package for me?", completion = "Ah, very good.  If initial reports are true, then the toxicity of these hearts could lead to further advances in our knowledge of poisons.\n\nThis is a welcome delivery, <name>.  Your reward is well earned." }
WordHunterWoW_QuestEN[1359] = { title = "Zinge's Delivery", description = "The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat!\n\nIt's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.", objectives = "Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.", progress = "You have something for me?", completion = "Ah yes, the heart samples of which Renferrel spoke.  I am eager to experiment with these... it is always of interest to the Royal Apothecary Society when new forms of toxins are discovered." }
WordHunterWoW_QuestEN[1360] = { title = "Reclaimed Treasures", description = "I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up.  I escaped with my hide barely intact, and nothing else.  In the chaos, I left my most treasured possession.  It's safe from the troggs in my chest, sure, but it's right in the thick of 'em.\n\nI'd be in your debt, both in honor and coin, if you could fetch it for me!  A chest with my name on it is at the end of the North Common Hall.  That's the one you need to get in.", objectives = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.", progress = "Well now, we're you able to get slap around those troggs long enough to get into my chest and nab my treasure?", completion = "Ah, I feel complete again - thank you kindly.\n\nSome dwarves may treasure the luster of metal, and some may treasure the glint of gems... but a Stoutarm without a treasured stein in hand is hardly a Stoutarm at all!" }
WordHunterWoW_QuestEN[1361] = { title = "Regthar Deathgate", description = "A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.\n\nAnd sharpen your weapons.  Desolace is a place torn by war.", objectives = "Speak with Regthar Deathgate.", completion = "Yes, I am recruiting.  This mission leads into Desolace, against the centaur there.  I will be brief so that you may quickly begin." }
WordHunterWoW_QuestEN[1362] = { title = "The Kolkar of Desolace", description = "The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.\n\nBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.\n\nSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.", objectives = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.", completion = "You are here on orders from Regthar?  Then you are here to deal with the centaur.  Good.\n\nI hope you're rested.  I don't know how our campaign against the centaur will end, but I know the struggle will be long.\n\nHave a seat, and listen." }
WordHunterWoW_QuestEN[1363] = { title = "Mazen's Behest", description = "As caretaker of the works here in the library of the Academy of Arcane Arts and Sciences, it is my responsibility to ensure all the magical tomes and scrolls are accounted for at all times. Who knows what folly would unfold if some of these enchanted texts were to fall into the wrong hands?\n\nWhich reminds me... my assistant, Dellis, made a horrible mistake last week. He's quite able in the library but incompetent when he leaves the gates of Stormwind. Be a hero, and help old Dellis out, would you?", objectives = "Speak with Acolyte Dellis in Stormwind.As caretaker of the works here in the library of the Academy of Arcane Arts and Sciences, it is my responsibility to ensure all the magical tomes and scrolls are accounted for at all times. Who knows what folly would unfold if some of these enchanted texts were to fall into the wrong hands?\n\nWhich reminds me... my assistant, Dellis, made a horrible mistake last week. He's quite able in the library but incompetent when he leaves the gates of Stormwind. Be a hero, and help old Dellis out, would you?", completion = "It wasn't my fault. Really it wasn't." }
WordHunterWoW_QuestEN[1364] = { title = "Mazen's Behest", description = "Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep.\n\nBut I had never been to the Blasted Lands before! The journey was frightening!\n\nWhen I got to the Swamp of Sorrows, I made a wrong turn and ended up surrounded by horrible plant-like swamp creatures. They lurched as if to attack me so I ran. But in my haste I dropped the essay. One of the beasts took it I am sure.\n\nCould you please try to retrieve it and deliver it to Mahar Ba?", objectives = "Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.", progress = "What brings you to Nethergarde Keep, <race>?", completion = "Ah, most splendid!\n\nFor some time I had feared my request for Khadgar's Essays on Dimensional Convergence had been overlooked by Master Mazen of the Academy of Arcane Arts and Sciences.\n\nHe must be bogged down with requests considering the many strange happenings going on.\n\nNow, if you'll excuse me, I need to begin my research at once. To finally glimpse the insight of one as great as Khadgar excites me to no end." }
WordHunterWoW_QuestEN[1365] = { title = "Khan Dez'hepah", description = "The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.\n\nWe must deal with them before they unite.\n\nYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.\n\nThe Kolkar Village is northeast of here.  Go, and may fortune go with you.", objectives = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.", progress = "<name>, have you defeated Khan Dez'hepah?", completion = "Well done.  This swift act against the Kolkar is an effective show of strength, and strength is what the centaur understand best.\n\nThe death of the Kolkar leader will not only disrupt that clan, but give pause to the others." }
WordHunterWoW_QuestEN[1366] = { title = "Centaur Bounty", description = "Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.\n\nBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.\n\nGood hunting, <name>.", objectives = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.", progress = "How is your collection of ears, <name>?  Large?", completion = "By now, the centaur must know your name.  I'm sure they know it, and respect it, and fear it.  And just as they know you, they know the banner under which you ride.\n\nThe banner of the Horde." }
WordHunterWoW_QuestEN[1367] = { title = "Magram Alliance", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.", objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.", completion = "The Gelkis cry when they hear your name, <name>.  They fear you and they hate you.  They hate you like they hate the Magram!\n\nMaybe you are strong like the Magram.  We will see..." }
WordHunterWoW_QuestEN[1368] = { title = "Gelkis Alliance", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.", objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", completion = "The earth speaks to me.  And it says you have killed many Magram.  This is good.\n\nIf you are a friend of the Gelkis, then listen.  I have more tasks for you." }
WordHunterWoW_QuestEN[1369] = { title = "Broken Tears", description = "The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest!\n\nShow the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!", objectives = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.", progress = "If you are not our enemy, then you will do what I ask!", completion = "You got the tears!  Now the Gelkis will know that Theradras will not help them.  She will not cry when we crush them!  The Magram will rule!\n\nYou are smart to help us, <name>.  We are the strongest." }
WordHunterWoW_QuestEN[1370] = { title = "Stealing Supplies", description = "When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones.\n\nIt is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.", objectives = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.", progress = "Return after you further prove your worth to the Gelkis!", completion = "Good.  I can hear the loud Magram bellies grumble from their village, far away!\n\nI will give this meat to the Gelkis.  And we will fight for many days without rest.\n\nWhat you did is good for the Gelkis, <name>." }
WordHunterWoW_QuestEN[1371] = { title = "Gizmo for Warug", description = "Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh.\n\nI kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it.\n\nI want a new one.  Get me a new one!", objectives = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.", progress = "If you are not our enemy, then you will do what I ask!", completion = "Yes, this is what I had!  I will make it move again.  It makes me laugh!" }
WordHunterWoW_QuestEN[1372] = { title = "Nothing But The Truth", description = "Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.\n\nWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.\n\nI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.\n\nWork with Faustin here to develop a... truth serum for our friend in Stonard.", objectives = "Speak with Apothecary Faustin at Beggar's Haunt.Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.\n\nWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.\n\nI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.\n\nWork with Faustin here to develop a... truth serum for our friend in Stonard.", completion = "Zraedus was just telling me about the nosey little Infiltrator before you arrived.\n\nQuite a problem, indeed. The last thing we need is a busybody sniffing around Beggar's Haunt.\n\nI am sure the orcs of Stonard would be quite anxious to hear what our friend has to say. Seeing that they are our allies, ahem, we must help them to get any information they can from the human.\n\nWork with me, <name>, and we will deliver a truth serum to Stonard.\n\nFor the Horde!\n\n...did I get that right?" }
WordHunterWoW_QuestEN[1373] = { title = "Ongeku", description = "You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you.\n\nThe earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule.\n\nBring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.", objectives = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.", progress = "Show me you are a friend of the Gelkis, <name>.", completion = "Yes, this is the shard of which the earth whispered.  I can feel strong magic in it!  I will use this magic against the enemies of the Gelkis.\n\nYou have done one more task for us, <name>.  Maybe soon, we will call you friend." }
WordHunterWoW_QuestEN[1374] = { title = "Khan Jehn", description = "The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan!\n\nBring me the head of the Magram Khan, Jehn!", objectives = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.", progress = "Show me you are a friend of the Gelkis, <name>.", completion = "Khan Jehn was strong, but stupid.  He thought his own strength was great.  He did not see that earth magic is stronger.  The Magram centaur will now fall without their leader, and the Gelkis will one day rule!" }
WordHunterWoW_QuestEN[1375] = { title = "Khan Shaka", description = "You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!", objectives = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.", progress = "Do tasks for the Magram, and I will help you.", completion = "Khan Shaka is dead!  I will place his head on a pike, and keep it with me so Shaka can see the strength of the Magram!" }
WordHunterWoW_QuestEN[1380] = { title = "Khan Hratha", description = "<name>, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha!\n\nTo face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears.\n\nBut to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur.\n\nAfter the horn is blown, centaur will come.  Kill them until Hratha appears.\n\nKhan Hratha holds the piece of... a key.  Bring it to me...", objectives = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.", progress = "Is Khan Hratha dead?  Do you have the key fragment?", completion = "He is dead!  Khan Hratha is dead!  And now the Maraudine will fall!  When the Gelkis rule this land, <name>, we will remember you.  And the spirits of the earth will sing your name for all time." }
WordHunterWoW_QuestEN[1381] = { title = "Khan Hratha", description = "The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha!\n\nTo face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn.\n\nDo this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...", objectives = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.", progress = "Do what I ask.  Prove to me that you are an ally of the Magram!", completion = "Khan Hratha is dead!  Now the Magram are the strongest of the centaur!  We will crush the others, and rule Desolace!\n\nWe will remember, you, <name>, and you will be spared our hooves when all others are trampled." }
WordHunterWoW_QuestEN[1382] = { title = "Strange Alliance", description = "We are fortunate the centaur clans fight among themselves, for if they joined into a single force then they would be unstoppable.  Yes, we are fortunate, and we should press our advantage.\n\nOne of the centaur clans, the Gelkis clan, is in brutal war with the Magram clan.  If we attack the Magram, then perhaps an alliance may be struck with the Gelkis.\n\nSpeak with Uthek the Wise, in the outskirts of the Gelkis camps in southwestern Desolace.  Through her we might strike an alliance with the Gelkis.", objectives = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", completion = "Your name is whispered among the Gelkis.  You have much Magram blood on your hands.  This is good.\n\nMaybe it is also good if we speak.  Speak of what you can do for the Gelkis, and what we can do for you." }
WordHunterWoW_QuestEN[1383] = { title = "Nothing But The Truth", description = "I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with.\n\nFor this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, <name>, can persuade him to part with some.\n\nThe last item I'll need for the serum is the blood of a dreaming whelp, like the ones that live outside Itharius' cave in the swamp.\n\nNow, off you go!", objectives = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and some Green Whelp Blood.", progress = "That Infiltrator in Stonard will surely.... open up... after he drinks my special serum. Haha!\n\nThe ingredients required are by no means easy to procure. Shadow Panthers are common in the Swamp but collecting enough hearts for our purpose can be daunting. And the Mire Lord can be such a fussy beast.", completion = "Splendid, <name>! And just in time too. From what Zraedus tells me, the Infiltrator has recovered from his wounds and is ready to be questioned by the orcs.\n\nGive me but a moment to prepare the pois-- I mean prepare the truth serum." }
WordHunterWoW_QuestEN[1384] = { title = "Raid on the Kolkar", description = "The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them!\n\nYou will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!", objectives = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.", progress = "You have the charms?  You showed the Kolkar they are weak?", completion = "You do a good thing for the Gelkis.  The Kolkar are weak and will die.  Their magic is pathetic and will not save them.  You showed them this, and their fear will make them even more feeble!\n\nAnd in our lands, the feeble soon die." }
WordHunterWoW_QuestEN[1385] = { title = "Brutal Politics", description = "Desolace is a land at war.  The centaurs wage war with each other, and we believe the victor among them will spill out and threaten our strongholds.  That, we cannot allow\n\nWe must learn how to beat the centaurs, and to do that... we must ally with one of the clans.  The Magram centaurs war with the Gelkis.  If you fight the Gelkis then the Magram might consider an alliance.\n\nEarn the favor of the Magrams then speak with Warug, in the Magram village in southeastern Desolace.", objectives = "Gain a Friendly reputation with the Magram, then speak with Warug.", completion = "Many Gelkis fall to you.  I like that.  Maybe you can do more things I like.  Maybe you and the Magram can be friends." }
WordHunterWoW_QuestEN[1386] = { title = "Assault on the Kolkar", description = "The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!", objectives = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.", completion = "The Kolkar fear you now!  I hope you laughed when you killed them.  It is better to laugh when you kill, so the enemy can see he is weak." }
WordHunterWoW_QuestEN[1387] = { title = "Centaur Bounty", description = "Many clans make up the centaur race.  Each has its own leader and agenda, but all the clans have one thing in common.  Cruelty.\n\nIf we are to ever find peace, then the centaurs must be removed.  And so I put you on the task to do just that.\n\nWhile wandering Desolace, hunt centaur and take their ears.  Bring me many, many ears.\n\nDo this in service of the Alliance, <name>, and we will be one step closer to war's end.", objectives = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.", progress = "Do you have a report, <name>?", completion = "Ah, the ears.  Well done.\n\nYour service to the Alliance is unquestioned, <name>.  The blood you spilled in Desolace will, no doubt, save countless lives." }
WordHunterWoW_QuestEN[1388] = { title = "Nothing But The Truth", description = "Everything is proceeding according to plan, <name>. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly.\n\nHaha!", objectives = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.", progress = "I hope you have proven yourself of use to our dear friend, Apothecary Faustin.", completion = "I knew old Faustin would come up with something good! You were a tremendous help, no doubt.\n\nNow let's get down to business, shall we?" }
WordHunterWoW_QuestEN[1389] = { title = "raenethyst Crystals", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the east, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", objectives = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.", progress = "Do you have the crystals?", completion = "Thank you, <name>.  We, are in your debt." }
WordHunterWoW_QuestEN[1391] = { title = "Nothing But The Truth", description = "We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right?\n\nBut if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew.\n\nMake haste to Stonard in the Swamp of Sorrows, <name>. And keep our little mission nice and quiet...", objectives = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.", progress = "Please have mercy on me! I have information that goes beyond alliance boundaries. While I am no sympathizer of the Horde, there is political treachery going on that must be revealed!", completion = "A drink for me? How kind. It's been days since they've allowed me to drink. Let me drink this down and then I'll tell you what I've learned...." }
WordHunterWoW_QuestEN[1392] = { title = "Noboru the Cudgel", description = "Noboru has plagued the Draenei of the Harborage for months, and his cudgel is a symbol of the brutality they have suffered at the hands of the lost ones.", objectives = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.", progress = "Greetings.  And welcome to the Harborage.", completion = "You have gained the weapon of the dreaded Noboru?  Is he then dead?\n\nThis is a joyous day for the Harborage.  Noboru and his gang were a terror to us, wandering the swamps and killing any Draenei who crossed his path.  He was a direct threat to our survival, and we did not have the strength to face him.\n\nWe are fortunate to have a friend in you, <name>." }
WordHunterWoW_QuestEN[1393] = { title = "Galen's Escape", description = "Please help!  These creatures are going to eat me!\n\nHelp me out of here, and I'll give you a great treasure!  It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know.\n\nIf you help me escape, then I'll teach it to you.", objectives = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.", completion = "The keyhole of this strongbox is filled with black resin.  It is impossible to open.\n\nBut Galen told you of a hidden latch on the box's bottom... \n\n...After a quick search the latch is found.  The latch is flipped, and the strongbox opens..." }
WordHunterWoW_QuestEN[1394] = { title = "Final Passage", description = "You have done well, <name>. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.\n\nStay true to the balance you've shown throughout these trials, <name>. Dorn will test you again in the future if you do.", objectives = "Speak to Dorn Plainstalker in Thousand Needles.You have done well, <name>. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.\n\nStay true to the balance you've shown throughout these trials, <name>. Dorn will test you again in the future if you do.", completion = "Ah, <name>. It has been a long time since you have last stepped into my home. It seems like many moons have passed since you took your first leap that set you upon your path.\n\nAnd now you return to me stronger than you once were... more enlightened. This pleases me. And you should be justly rewarded for seeing my tests to the end." }
WordHunterWoW_QuestEN[1395] = { title = "Supplies for Nethergarde", description = "This crate of powerstones needs to go to Nethergarde Keep, in the Blasted Lands.  They won't hold their power for long, so we can't ship them with the next caravan.\n\nYou must take them, and you must take them quickly.\n\nBring them to Quartermaster Lungertz in Nethergarde Keep.  To reach the keep, you must travel east through Deadwind Pass, then east through the Swamp of Sorrows, then south through the Blasted Lands.\n\nUse caution, <name>.  You will travel through dangerous lands, yet you must not fail.", objectives = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.", progress = "Hello!  Don't mind all the commotion, it's just business as usual at Nethergarde Keep.\n\nYou have something for me?", completion = "Ah, the powerstones!  The mages will be happy to see these!\n\nMany thanks, <name>.  I know your trip from Darkshire was not an easy one." }
WordHunterWoW_QuestEN[1396] = { title = "ncroaching Wildlife", description = "My caravan was destined for the eastern coast, but we did not reach our goal.  Lost Ones attacked us, killing guards and dashing supplies.\n\nI alone survived their assault.  I have sworn to protect what supplies remain, but wild creatures skulk near.  Please, help me defend my camp from the beasts!", objectives = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.", completion = "The sounds of animals are now faint, more distant.  Thank you, <name>.  Now let's hope they don't return!" }
WordHunterWoW_QuestEN[1398] = { title = "riftwood", description = "I owe you greatly, <name>.  An honorable heart beats within you.  And now I have another task for which I humbly ask your aid.\n\nIf I'm ever to reach Nethergarde, then I must fix this wagon.  And for that... I will need wood.  Strong, dry wood--not the spongy, tangled wood of the swamp's trees.\n\n<name>, go east to the coast and search for driftwood that has been dried by the sun.  Bring it to me.", objectives = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.", progress = "Did you find any driftwood, <name>?", completion = "This wood is light, but tough.  Thank you, <name>.  It will work nicely." }
WordHunterWoW_QuestEN[1418] = { title = "Neeka Bloodscar", description = "The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.\n\nProve yourself, <name>.  Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost.  Speak with her, and then send her report back to me.", objectives = "Speak with Neeka Bloodscar.The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.\n\nProve yourself, <name>. Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost. Speak with her, and then send her report back to me.", completion = "Helgrum wants a report, eh?  I sent an outrunner to Stonard not three days past.  Did he fail his mission?  If Stonard does not have my report, then it appears he did fail.\n\nLet's hope the next runner I send has more skill, or more luck." }
WordHunterWoW_QuestEN[1419] = { title = "Coyote Thieves", description = "Have you spent many days in the Badlands, <class>?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It's time you did.\n\nCrag coyotes are a tough breed.  Tough, and bold enough to creep into Kargath and steal from our food supplies.  Help rid the outpost of these thieves!\n\nHunt crag coyotes, <name>.  Hunt them and bring me their jawbones.  Bring me enough, and maybe I'll believe it when you say you know the Badlands.", objectives = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.", progress = "Do you have the jawbones?", completion = "That's a nice collection of jawbones, <name>.  Now those coyotes won't be tearing through our supplies for scraps.\n\nWell done.  The coyotes of the Badlands aren't easy prey.  Your deed shows me that you might just survive here." }
WordHunterWoW_QuestEN[1420] = { title = "Report to Helgrum", description = "I wrote a fresh report for Helgrum in Stonard.  Bring it to him.\n\nAnd if you consider yourself an outrunner, then don't lose your way.  Or fall to an enemy.", objectives = "Bring Neeka's Report to Helgrum the Swift in Stonard.", progress = "You returned.  You have a report?", completion = "Thank you, <name>.  From Neeka's report, I see the Alliance is not without its own problems.  And we may find that some enemies are shared between us." }
WordHunterWoW_QuestEN[1421] = { title = "he Lost Caravan", description = "I was stunned during the attack by the Lost Ones, but before my sight went black I spied one of our wagons being dragged to the Fallow Sanctuary, the lost one village to the north.\n\nA caravan chest with valuable reagents was in that wagon, reagents vital to the studies of the wizards of Nethergarde Keep.  Find the chest and get those reagents, <name>.  Get them and bring them to me.", objectives = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.", progress = "Do you have the wizard's reagents, <name>?", completion = "Ah, you found them!  With these, the wizards in Nethergarde may continue their work.  I do not know what it is that they do, but it is linked to the Dark Portal in the Blasted Lands, and is vital to the security of the Alliance." }
WordHunterWoW_QuestEN[1422] = { title = "hreat From the Sea", description = "While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.", objectives = "Speak to Katar in the Swamp of Sorrows.While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.", completion = "Be silent a moment, <class>. Even over the dull roar of the sea you can still hear those disgusting gurgles from the fish men." }
WordHunterWoW_QuestEN[1423] = { title = "The Lost Supplies", description = "This barrel is small yet sturdy.  Its seams are sealed with a yellow, pungent wax.  Stamped on the bottom of the barrel are the words:\n\nQUARTERMASTER LUNGERTZ\n\nNETHERGARDE KEEP", objectives = "Bring the Lost Supplies to Quartermaster Lungertz.", progress = "You have something for me?", completion = "Ah, thank you <name>!  So many supplies are lost from Darkshire to here.  It's good to see that some are recovered." }
WordHunterWoW_QuestEN[1424] = { title = "ool of Tears", description = "The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.\n\nThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.\n\nThe green dragons now guard the site, claiming to be protectors of Azeroth.\n\nWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.", objectives = "Fel'zerul in Stonard wants you to gather 5 Atal'ai Artifacts.", progress = "No one knows what dark practices went on inside The Temple of Atal'Hakkar. But we do know that great and powerful forces of magic were used.\n\nWe must learn as much as we can about such magic. Perhaps the spells of the Atal'ai will prove of use to the Horde.\n\nOnce you have gathered enough Atal'ai artifacts from around the Pool of Tears, I can begin to understand what the trolls were hoping to accomplish and what went so horribly wrong.", completion = "Your diligence in collecting the Atal'ai artifacts is worthy of praise, <class>." }
WordHunterWoW_QuestEN[1425] = { title = "eliver the Shipment", description = "While I fix this wagon, <name>, I have one last task for you.\n\nI have packed the most vital supplies saved from the ogre attacks.  Take them to Nethergarde Keep.  The keep is nestled in the northern hills of the Blasted Lands, keeping watch over the Dark Portal.\n\nTo reach Nethergard, follow the road east.  When it branches head south into the Blasted Lands, then turn left at the next fork.  Follow the road, <name>, and be wary.", objectives = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.", progress = "You have business with me?", completion = "What?  A package from Biggs' caravan?  We thought it, and he, were lost.\n\nThank you, <name>.  With luck, these supplies will carry the much needed reagent, Azoran Crystals.  Our stock is running low..." }
WordHunterWoW_QuestEN[1426] = { title = "hreat From the Sea", description = "I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will.\n\nWhich brings us to you, <class>. How many can you slay? Would you test yourself against their most powerful kind?", objectives = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.", completion = "The sea seems vast and relentless, but you have stained her with the blood of her own spawn. The fish men know pain. Their stupidity will force them to refortify their ranks from the devastation you've caused, and that is good.\n\nLet their gurgling screams overshadow the sea's roar long into the night. I shall smile every time I hear one of them silenced.\n\nReturn to me if you wish to slay more of the fish men. I will gladly reward you again." }
WordHunterWoW_QuestEN[1427] = { title = "hreat From the Sea", description = "Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.", objectives = "Speak with Tok'Kar in the Swamp of Sorrows.Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.", completion = "Ah, <name>, you've returned. Good. I've finished crafting more weapons for our fight against the murlocs. For bringing us the fresh sawtooth meat, and for bringing a small smile to Katar's face, I offer one of them to you." }
WordHunterWoW_QuestEN[1428] = { title = "ontinued Threat", description = "It pleases me to see your hatred for the fish men grows with mine.\n\nFind more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.", objectives = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.", completion = "Well done, <class>. I call for more of their blood. Let all the fish men perish." }
WordHunterWoW_QuestEN[1429] = { title = "he Atal'ai Exile", description = "While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.\n\nThis priest was sentenced to a fate worse than death amongst the Atal'ai.\n\nHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.\n\nI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.", objectives = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.", progress = "You are brave to come here. Brave or foolish...", completion = "You bring me the summoning artifacts of the Atal'ai?\n\nI see Jammal'an the Prophet is leading the disciples of the Chamber of Blood towards their chosen fate. Has Hakkar returned to the Temple I wonder? Has their fate been met?" }
WordHunterWoW_QuestEN[1430] = { title = "resh Meat", description = "There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers.\n\nIf you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar.\n\nThe coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.", objectives = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.", progress = "I have a cask of wine waiting for your success, <name>. It's only right I taste the goods before I have it shipped back to my customers.", completion = "Ah, this should be perfect. I can't wait to taste these after they are prepared perfectly over an open fire. You should take a sample of it with you on your travels. It truly is delicious." }
WordHunterWoW_QuestEN[1431] = { title = "Alliance Relations", description = "Be still, <class>, and allow me to share with you something important to our people, but far from obvious.\n\nWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.\n\nIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.", objectives = "Speak to Keldran in Orgrimmar.", completion = "Putanni, noble <class>. I am Keldran, student of magic... and other mystical arts.\n\nThe business Craven sent you here to speak to me about requires a touch more subtlety than you've previously needed, but that does not mean you can not still aid our cause.\n\nPlease, make yourself comfortable, and I shall tell you why the Warchief has need of my aid... and yours.\n\nIt starts with appearances, <name>. How the Horde sees itself. How our allies see us. And most importantly, how our enemies see us." }
WordHunterWoW_QuestEN[1432] = { title = "Alliance Relations", description = "As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.\n\nI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.", objectives = "Speak to Takata Steelblade in Desolace.", completion = "Greetings, <class>. You bring news from Orgrimmar; that is good.\n\nThe demon infestation overwhelms this area even more than the smell of centaur dung. The horse-men claim this land as their own, but clearly there are influences out of their control that will crush them if not kept in check.\n\nIt does not please me that we aid the centaur indirectly, but it is for the good of the Horde, so I do my duty for the Warchief, even if it means helping the warlocks within the Horde." }
WordHunterWoW_QuestEN[1433] = { title = "Alliance Relations", description = "The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.\n\nKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.\n\nHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.\n\nSpeak to him, and he will guide you in his designs.", objectives = "Speak to Maurin Bonesplitter in Desolace.The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.\n\nKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.\n\nHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.\n\nSpeak to him, and he will guide you in his designs.", completion = "Ah, yes. Aid from those loyal to the Warchief is always appreciated.\n\nMy name is Maurin. I am here at the behest of Keldran and the Warchief cub Thrall. It is my desire to aid the youngling leader against the evils that threaten his rule.\n\nCome, come closer, <class>. I shall explain to you my plan for removing the festering boil that is the Burning Blade." }
WordHunterWoW_QuestEN[1434] = { title = "Befouled by Satyr", description = "A demon infestation does not occur without other influences--something else allows evil to gain a foothold.\n\nIt may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr.\n\nTies have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back.", objectives = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.", completion = "You have done well, <class>. You have shown honor and dedication.\n\nWhen our campaign in Desolace is done, the Warchief will know that you aided us in our actions here, and that you helped make his will manifest.\n\nI thank you." }
WordHunterWoW_QuestEN[1435] = { title = "The Burning of Spirits", description = "Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness.\n\nTake this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind.\n\nBring me these infused gems so I may dispose of them properly.\n\nGo now, and may you elude death.", objectives = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.", progress = "I have tried to make the magics as simple as possible. Drawing the spirit of your victim out of its injured form should be child's play. Do not rely on the gem's power to slay your foe completely. You must only activate the gem when they are close to death, or it will be useless.", completion = "Ah, you've returned successful. That is good. Give me the gems and I shall put them someplace safe....\n\nMy tasks for you are complete, <class>. Speak to Takata when you are rested. He may have other tasks for you, or perhaps needs you to return to Orgrimmar to inform Keldran of our progress here in Desolace." }
WordHunterWoW_QuestEN[1436] = { title = "Alliance Relations", description = "The fight goes well, <name>. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings.\n\nReturn to Keldran and let him know what we have done. I am sure he will reward you for your efforts here. His cause is important to him, and he will take pride in knowing that the Warchief respects his concerns.", objectives = "Speak to Keldran in Orgrimmar.", completion = "You have returned from Desolace more than successful, <name>. Thank you.\n\nThank you for your efforts, your time, and your understanding to my plea. Thrall understands and desires peace between the Horde and Alliance, and by taking measures to insure our appearance is acceptable, we will not provoke any further threats of unnecessary violence.\n\nI am indebted to you." }
WordHunterWoW_QuestEN[1437] = { title = "Vahlarriel's Search", description = "I am Vahlarriel, <name>. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.\n\nLast word tells of them passing through the Stonetalon Mountains a few weeks ago.\n\nIf you find their wagon, please, come find me immediately.", objectives = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.I am Vahlarriel, <name>. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.\n\nLast word tells of them passing through the Stonetalon Mountains a few weeks ago.\n\nIf you find their wagon, please, come find me immediately.", completion = "As you rummage around the remains of the wagon, it becomes obvious that it was attacked by both spells and weapons. The battle seemed one-sided and quick; there's no blood to be found, and no remains of any bodies.\n\nWhoever attacked the wagon was efficient and swift." }
WordHunterWoW_QuestEN[1438] = { title = "Vahlarriel's Search", description = "Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.\n\n<name>, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.", objectives = "Find Dalinda Malem in Desolace.Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.\n\n<name>, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.", completion = "Thank Elune someone has finally come to help. Please, <class>, I need your help. My brother Tyranis and I were captured and brought here by the Burning Blade. I think they mean to sacrifice me to their demon masters!\n\n I knew coming to Desolace was a mistake, but Tyranis has recently begun craving knowledge of all things arcane--even against the wishes of our people. He decided to make this trek even after hearing tales of this land's demon infestation.\n\nI fear the worst for him." }
WordHunterWoW_QuestEN[1439] = { title = "Search for Tyranis", description = "We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans.\n\nTyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why.\n\nPlease, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known.", objectives = "Find Tyranis Malem in Desolace.", progress = "I fear Tyranis will attempt to learn the Burning Blade's secrets and count himself among their kind if they allow it--he has always adored the power magic brings to those who are seduced by it.\n\nI'm not sure I could endure returning home to my family with news of Tyranis' spirit flirting with such dangers. It's a terrible enough crime among my kind to pursue such things, but to become that which we attempt to protect ourselves from, well, that's apprehensible.", completion = "This is terrible! But I suppose it was necessary. If it wasn't by your hand, it would have surely been by that of my people's. I suppose I should thank you--please forgive me if it doesn't seem sincere. I mean no offense.\n\nWith the knowledge of my brother's fate in hand, it seems the time for my escape has come. If you are still willing, I will accept your aid in escaping this horrible place.\n\nWhen you are ready, we can make our way to safety." }
WordHunterWoW_QuestEN[1440] = { title = "Return to Vahlarriel", description = "So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right.", objectives = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.", completion = "Thank you, <name>. Dalinda made it safely back here to Nijel's Point, and in much better condition than I could have asked for. The fact that she arrived here under her own power was a good sign. I hope you're well?\n\nIt pains me to know that both Tyranis and Dalinda didn't return, but the embarrassment of Tyranis' decisions is hers to endure. It is something she will have to deal with when she returns to Darnassus." }
WordHunterWoW_QuestEN[1442] = { title = "Seeking the Kor Gem", description = "Greetings, <name>. What can I do for one who follows a holy path?\n\nAh, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time.\n\nHe never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble.\n\nIf you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, <class>.You will receive:", objectives = "Bring a Kor Gem to Thundris Windweaver in Darkshore." }
WordHunterWoW_QuestEN[1444] = { title = "Return to Fel'Zerul", description = "Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.\n\nHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.\n\nWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.\n\nThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....", objectives = "Return to Fel'Zerul in Stonard.Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.\n\nHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.\n\nWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.\n\nThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....", completion = "It has been quite some time since we spoke, <class>. I hope your journey was successful.\n\nWhat knowledge did you gain from the exiled Atal'ai in the Hinterlands?" }
WordHunterWoW_QuestEN[1445] = { title = "he Temple of Atal'Hakkar", description = "So he spoke of Jammal'an's prophecy?\n\nThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.\n\nFoolish trickery to bring about a premature doomsday if you ask me.\n\nBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.\n\nVenture into the Temple, and seize the fetishes!", objectives = "Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", progress = "If the Atal'ai fetishes hold the power to summon Hakkar and fulfill Jammal'an's prophecy they must be seized. Such powers must be understood by the Horde!", completion = "Brave <class>, you have proven yourself to be a great champion of the Horde.\n\nNow this collection of fetishes of Hakkar must be dealt with at once!" }
WordHunterWoW_QuestEN[1446] = { title = "Jammal'an the Prophet", description = "My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.", objectives = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", progress = "Once Jammal'an has been removed, I stand a chance of returning to my people.\n\nWith Jammal'an as their spiritual leader, the Atal'ai face certain destruction.", completion = "Jammal'an's reckless trust of false visions led my people to their eternal doom.\n\nI thank you, <class>, for avenging my exile. I mourn for my people. I have no home to return to." }
WordHunterWoW_QuestEN[1447] = { title = "The Missing Diplomat", description = "Yeah, you're obviously not the smartest <class> to come into Stormwind, but you're about to be one of the dumbest to never leave.\n\nHave you met me friends?", objectives = "Defeat Dashel Stonefist in Stormwind.", completion = "So, you came to me for a reason. What is it you need?" }
WordHunterWoW_QuestEN[1448] = { title = "In Search of The Temple", description = "There was a time when I was young and full of vigor like you, <class>.\n\nBut now I'm old and unable to explore the world like I once did. Ah, the things I saw!\n\nBut there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows.\n\nBecause of my frail state, I traveled the skies by gryphon in search of it but never found it.\n\nHelp an old dwarf out? Perhaps you will have better luck on foot.", objectives = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.", completion = "The Temple of Atal'Hakkar has been sunk beneath the Pool of Tears? And surrounded by the green dragonflight?\n\nAn amazing discovery, <class>. But obviously something has gone terribly wrong." }
WordHunterWoW_QuestEN[1449] = { title = "To The Hinterlands", description = "As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.\n\nI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...\n\nIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.\n\nJourney there and seek out Falstad Wildhammer.\n\nWe need to find out what happened to that pilot.", objectives = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.\n\nI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...\n\nIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.\n\nJourney there and seek out Falstad Wildhammer.\n\nWe need to find out what happened to that pilot.", completion = "What do you want, laddy? Can't you see I've got problems to take care of here? Who has time to stand around yapping with some <race> chatterbox?\n\nThere are trolls coming out of the woodwork! Make it snappy." }
WordHunterWoW_QuestEN[1450] = { title = "Gryphon Master Talonaxe", description = "So you're a glorified errand <boy/girl> for some old Explorers' League geezer, eh?\n\nWell you listen to me, <class>. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?\n\nIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.\n\nNow get a move on.", objectives = "Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary.So you're a glorified errand <boy/girl> for some old Explorers' League geezer, eh?\n\nWell you listen to me, <class>. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?\n\nIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.\n\nNow get a move on.", completion = "Ah, yes. Of course I remember sending one of my gryphon riders to lend a hand to Brohann Caskbelly.\n\nAlways had a soft spot in my heart for the Explorers' League. My father helped with the initial excavation team that discovered Uldaman as a matter of fact.\n\nI sent who I thought was my best gryphon rider at the time with Brohann. He was a chap by the name of Rhapsody Shindigger.\n\nAnd what a gryphon jockey he was! Well until..." }
WordHunterWoW_QuestEN[1451] = { title = "Rhapsody Shindigger", description = "Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.\n\nBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.\n\nFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.\n\nLast I heard, he's set up a brew camp to the east of here...", objectives = "Seek out Rhapsody Shindigger in The Hinterlands.Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.\n\nBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.\n\nFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.\n\nLast I heard, he's set up a brew camp to the east of here...", completion = "Hiccup!\n\nI'm a-lookin' right at you but you keep bobbing up and down. Makin' me dizzy. Hoho!\n\nHiccup!\n\nWhoa! Did ya feel that? Ground is a-shakin', my friend. I need a drink.\n\nHiccup!" }
WordHunterWoW_QuestEN[1452] = { title = "Rhapsody's Kalimdor Kocktail", description = "Hiccup!\n\nSo that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup!\n\nIf ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup!\n\nTell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it.\n\nGonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas...\n\nA nice stiff Kalimdor Kocktail... that'll get me talking!", objectives = "Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers.", progress = "Ya ever had a Rhapsody Malt? One of my finest brews, if I do say so myself. Hiccup!\n\nBut if I'm gonna relive the horrors of that fateful flight over... hiccup... the swamp, well I'm gonna need me something a wee bit stronger. Hiccup!\n\nDon't suppose you found me those gizzards and livers I need to add that extra kick to my Kalimdor Kocktail?\n\nHiccup!", completion = "I see ya had no trouble at all getting me what I need! Musta been quite a stint you had over there in far-off Kalimdor.\n\nIt won't take but a moment for me to extract what I need from these gizzards and livers. Hiccup!\n\nThen I can distill me a fierce ol' drink and finally tell ya what ya wanna know.\n\nHiccup!\n\nGetting shivers just thinking about that ol' swamp.\n\nHiccup!\n\nLemme whip up a drink real fast." }
WordHunterWoW_QuestEN[1453] = { title = "Reclaimers' Business in Desolace", description = "There's work to be done in Desolace, {name}. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha.\n\nYou can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.", objectives = "Speak to Kreldig Ungor in Desolace.", completion = "Glad to see the Reclaimers aren't in short supply of work, or adventurers willing to help out.\n\nI'm Kreldig, <name>. You've made a smart move helpin' out the Reclaimers. Everyone needs something these days: they've lost a family heirloom, a magic item, a loved one. You never can tell. But with the Reclaimers around, there's no reason, for the right price, everyone can't find what they've lost." }
WordHunterWoW_QuestEN[1454] = { title = "The Karnitol Shipwreck", description = "Greetings, friend. Have yerself a seat here...\n\nMy first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace. He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety.\n\nHe wants us to find the chest and its contents, and return it to him in Stormwind.", objectives = "Find Karnitol's Chest in Desolace.", completion = "You notice the chest does not seem to have any water damage.\n\nThe second thing you notice is that the top has been forced open, and whatever magical traps were set to safeguard it have long been triggered--this much is obvious from the burn marks around its edges." }
WordHunterWoW_QuestEN[1455] = { title = "The Karnitol Shipwreck", description = "You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword.\n\nAfter going through the chest you find it to be completely empty.\n\nNot having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.", objectives = "Return to Kreldig Ungor in Desolace.", completion = "Welcome back to Nijel's Point, <name>. So, tell me what you found.\n\nWhat!? Nothing? An empty chest ain't gonna get us paid, I'm afraid.\n\nTell me more about these marks you saw... these slashes." }
WordHunterWoW_QuestEN[1456] = { title = "The Karnitol Shipwreck", description = "Intriguing.\n\nWell, we might not be without hope quite yet.\n\nAlong that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet.\n\nIf a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.", objectives = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.", progress = "No offense to whoever Nijel is, but this camp ain't the most comfortable place I've spent a night, if you know what I mean, <name>.", completion = "This is great, <name>! You found Karnitol's belongings!\n\nThose blasted naga, always causing trouble. I think I'd rather spend my life at war with the Horde than have to go against their kind.\n\nYou've done a great service to the Reclaimers. Please, accept this with our thanks!" }
WordHunterWoW_QuestEN[1457] = { title = "The Karnitol Shipwreck", description = "Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done.\n\nHaha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time.\n\nAgain, great job, <name>.\n\nBe careful on your way back, and don't take too much time--Karnitol's not the most of patient of men, but he's very generous nonetheless.", objectives = "Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.", progress = "Business is booming, <name>, and I don't have a lot of time for questions. If you've got business with the Reclaimers, then let's hear it. If not, I'm gonna have to ask you to talk to one of me underlings--they're adept enough at taking care of things 'round here.", completion = "Ah, the Karnitol business in Desolace. Excellent!\n\nSo, the chest was destroyed, but the items are all here, huh? Well, I'll let him be the judge of that. One good part about this business I got going on here is that if they're not satisfied, I can tell 'em to shove it! They're relyin' on us to find their stuff... not make sure it's all pretty and in good shape when they get it back.\n\nGood work, <name>. Let's see about gettin' you paid." }
WordHunterWoW_QuestEN[1458] = { title = "Reagents for Reclaimers Inc.", description = "One of my tasks out here involves picking up some reagents for Leftwitch, a gnome mage in Kharanos . Roetten seems to think it's easy coin in the bank since we're out here already. He doesn't really care that we're short-handed as is.\n\nThe first few items on his list should be easy enough to get, and it'd be a good chunk of coin for anyone helping me out.\n\nI need some horns and claws from the Hatefury satyr to the east of here. Bring 'em back to me and we'll get started on the rest of the list.", objectives = "Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.", progress = "Despicable creatures, the satyr. Story says they're somehow tied to the night elves, but I'm not so sure I believe it.\n\nI think they get that on account of that one elf that brought them into the war few years back. World's never been the same since. Lot more dangerous, and a lot scarier.", completion = "Good good, <name>. Not sure if these are of any good quality, but if Leftwitch wanted a specific type, he should have specified before sending the Reclaimers out here to begin with.\n\nWhat say you to getting on with the next item on his list?" }
WordHunterWoW_QuestEN[1459] = { title = "Reagents for Reclaimers Inc.", description = "Next on Leftwitch's list is... let's see... hmm. Oh, here it is.\n\nSimple enough, but pretty explicit in his directions. He needs venom from the scorpashi, and hide from some kodo. The fine print says both are from specific creatures: the venom's got to come from any of the scorpashi, and the hide's got to come from an aged kodo, not the dying or ancient ones.\n\nMages, I tell ya, some of the stuff they want... it's just weird.", objectives = "Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.", progress = "Sorry I couldn't tell you where to find the kodo or the scorpashi. I'm not terribly familiar with the area, and I haven't had time to explore.", completion = "Your help here's a boon, <name>. You're cutting my time spent here in Desolace by half at least. I'll be back in Ironforge warming my feet in no time with your help.\n\nWhen we get this list taken care of, and I'm back home, look me up, I'll buy you an ale for sure.\n\nBut until then, let's get the rest of these reagents gathered." }
WordHunterWoW_QuestEN[1462] = { title = "Earth Sapta", description = "", objectives = "Speak to Seer Ravenfeather for another Earth Sapta.You will receive:" }
WordHunterWoW_QuestEN[1463] = { title = "Earth Sapta", description = "", objectives = "Speak to Canaga Earthcaller for another Earth Sapta.You will receive:" }
WordHunterWoW_QuestEN[1464] = { title = "Fire Sapta", description = "", objectives = "Speak to Telf Joolam for another Fire Sapta.You will receive:" }
WordHunterWoW_QuestEN[1465] = { title = "Vahlarriel's Search", description = "As you continue your search of the wagon you find not only a pendant, but also footprints leading off towards the south. In the distance you can see smoke rising from a large fort. The smoke is from a kept fire, not the burning of buildings, and your instincts tell you that the Malems, if still alive, were taken that direction.\n\nYou think Vahlarriel at Nijel's Point should not only see the pendant you've found, but also know about the signs of life to the south.", objectives = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.", completion = "Infuriating! This entire fiasco!\n\nThe two of them were warned about how dangerous coming here would be. Now they're both missing... or worse.\n\nYou said you saw tracks heading to a fort nearby? That may be our best bet.\n\nFrom what the locals have said, that fortress is infested with members of the Burning Blade--orcs who have dedicated themselves to demon causes. They may not represent the majority of the Horde's beliefs, but they are evil and will slay you on sight if you're caught spying." }
WordHunterWoW_QuestEN[1466] = { title = "Reagents for Reclaimers Inc.", description = "This is the last of the items, and I won't lie, it ain't pretty. I'm also expecting this to take you a little bit longer than the other items.\n\nSo, enough with the warning, let's get this started. Leftwitch says he needs: ten brains from either mana eaters, mage hunters, or ley hunters. Ten nether wings from a nether maiden, sister or sorceress. And... ten vials of doomwarder blood from a doomwarder captain, or lord.\n\nSimple enough, huh? Sheesh... if you wanna pass on this one, I'd understand.", objectives = "Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.", progress = "I didn't even realize these demon things were in Desolace. Last I read, centaur pretty much owned the land after the night elves picked up and left years ago.\n\nI wonder why they took up here, and how.", completion = "Honestly? I wouldn't have thought it. You're amazing, <name>. Taking on demons for a mage's experiments, and coming back in one piece to boot. Great job!\n\nI'm personally gonna tell Roetten about you when I get back to Ironforge." }
WordHunterWoW_QuestEN[1467] = { title = "Reagents for Reclaimers Inc.", description = "To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway. Just give him this and it should be enough to get your booty.\n\nAnd don't worry, I'm still going to put in a good word for you when I get back. I shouldn't be in Desolace much longer.", objectives = "Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.", progress = "Well met, <name>. Business is booming, the sounds of anvils being struck rings throughout Ironforge, the bellows blow the fires hot, and me wife's making me a pie for dessert after tonight's dinner. Could life be any grander?", completion = "Ah, the package for Leftwitch from Desolace. Excellent. I 'preciate the work, and your timeliness, <class>. Glad to have you aboard for at least this small bit of work.\n\nI got your payment right here. Let it be known that Reclaimers Inc. always pays well for a hard week's work." }
WordHunterWoW_QuestEN[1468] = { title = "Children's Week", description = "You're willing to help us here at the orphanage? Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle. You will only be able to use it for a short amount of time - typically not longer than Children's Week itself. When you use it, you will be able to talk with the child you've agreed to look after. Using it again will dismiss the child.\n\nBy all means {name} - use the whistle and meet your ward! I'm sure the child will be most eager to meet you.", objectives = "Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week.\n\nProvided item:", completion = "Um... hi.  My name is Randis, and I guess you're looking after me?  You're an adventurer, like my mom and dad were.  I'm happy to meet you.\n\nI hope we'll have a lot of fun together.  I have some things I'd like to do, and the matron says you'll be like a big brother to me during this week.  I'd like that a whole bunch, yes sir." }
WordHunterWoW_QuestEN[1469] = { title = "Rhapsody's Tale", description = "Before the flight, I drank me a whole keg of stout. Hiccup!\n\nAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!\n\nWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!", objectives = "Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.", progress = "At long last you have returned, <name>. It has been quite some time since we last spoke. I thought perhaps you had forgotten about my quest.\n\nDid you locate that wily gryphon rider? Did he have anything to report?", completion = "Rhapsody Shindigger! That's right... how could I forget such a name?\n\nSo he knew about the sinking of the temple all along? Well, that certainly would have saved you some leg work.\n\nBut this Atal'ai artifact! Why, it's quite a find!" }
WordHunterWoW_QuestEN[1470] = { title = "Piercing the Veil", description = "Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.\n\nAnd you will learn.\n\nThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.\n\nI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.You will learn:", objectives = "Bring Venya Marthand 3 Rattlecage Skulls." }
WordHunterWoW_QuestEN[1471] = { title = "The Binding", description = "Surely you have seen the circle of summoning below us? Only there will you be able to draw forth an unbound voidwalker.\n\nUsing these runes, you will be able to draw it forth, and then you must dominate it through strength of arms and magic.\n\nWhen it is subdued, it will be indentured to you. Come to me then, and I will elucidate the spell of summoning, so that it may serve you to whatever end you wish.You will learn:", objectives = "Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity." }
WordHunterWoW_QuestEN[1472] = { title = "Devourer of Souls", description = "A succubus is a devourer of souls, destroyer of hearts, tempter of men. A creature of profound evil and of singular mind.\n\nIt cannot be brought into our world without a stimulus.\n\nThus we use its own strength against it. With the hearts of good men, pure men, loving men, the succubus will be unable to resist, and will cross into our world. Then you can dominate it, and make it your own.\n\nSpeak with my assistant, Godrick Farsan, within the Temple. He will help you find your bait.Upon completion of this quest you will gain:", objectives = "Speak with Godrick Farsan in the Temple of the Damned.A succubus is a devourer of souls, destroyer of hearts, tempter of men. A creature of profound evil and of singular mind.\n\nIt cannot be brought into our world without a stimulus.\n\nThus we use its own strength against it. With the hearts of good men, pure men, loving men, the succubus will be unable to resist, and will cross into our world. Then you can dominate it, and make it your own.\n\nSpeak with my assistant, Godrick Farsan, within the Temple. He will help you find your bait.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1473] = { title = "Creature of the Void", description = "It seems the consensus that you are ready to learn to summon a voidwalker.\n\nA being created of the chaos that lies beyond, if you summon one but cannot control it, you will be torn asunder.\n\nThe first voidwalker was summoned by Egalin, and in his grimoire is the process explained.\n\nUnfortunately, it was stolen from us by an agent of the Scarlet Crusade who has it secreted away in his base at a tower to the west. Bring it to me, and I will impart the knowledge to you.Upon completion of this quest you will gain:", objectives = "Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned." }
WordHunterWoW_QuestEN[1474] = { title = "The Binding", description = "Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus. \n\nBeware its charms, <name>, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command.You will learn:", objectives = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity." }
WordHunterWoW_QuestEN[1475] = { title = "Into The Temple of Atal'Hakkar", description = "According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable.\n\nNow sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, <name>.\n\nAid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory.", objectives = "Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.", progress = "As dusk slowly descends upon my career I turn to you, <name>, to help me in my final quest for the Explorers' League. If my old bones could muster the strength to brave the Swamp of Sorrows and the sunken temple I would be fighting right alongside you.\n\nPride makes it hard for me to ask for your help in collecting the Atal'ai Tablets. But old age forces the necessity.\n\nPlease help me, <name>. I want to retire from the Explorers' League having completed their final bidding.", completion = "The Atal'ai Tablets! Thank you, <name>!\n\nOnce I deliver these to the Explorers' League our names shall go down in history together. You have helped an old dwarf fulfill his final obligation in life. For that I am eternally grateful." }
WordHunterWoW_QuestEN[1476] = { title = "Hearts of the Pure", description = "Men of honor and goodness? Does such a man exist?\n\nIt took much research, but through bits of overheard stories, I managed to find two men that should do.\n\nThe first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refugees, whom are refused by their kin at the Greymane Wall.\n\nThe other is Comar Villard, a man who remains faithful to his lost love, wandering the Wetlands for a sign of his wife.\n\nDeliver their hearts to Carendin. But first, let me show you your quarry.Upon completion of this quest you will gain:", objectives = "Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned." }
WordHunterWoW_QuestEN[1477] = { title = "Vital Supplies", description = "Our mages are conducting research at Nethergarde Keep in the Blasted Lands, research vital to our understanding of the Dark Portals. They require nearly constant supplies, but our supply line to Nethergarde is tenuous.\n\nYou must help ensure the supplies make it to Nethergard.  Report to Watchmaster Sorigal in Darkshire, and do as he asks.  This task will take you into hostile lands, <name>.  Prepare yourself.Upon completion of this quest you will gain:", objectives = "Speak with Watchmaster Sorigal at Darkshire in Duskwood.Our mages are conducting research at Nethergarde Keep in the Blasted Lands, research vital to our understanding of the Dark Portals. They require nearly constant supplies, but our supply line to Nethergarde is tenuous.\n\nYou must help ensure the supplies make it to Nethergard. Report to Watchmaster Sorigal in Darkshire, and do as he asks. This task will take you into hostile lands, <name>. Prepare yourself.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1478] = { title = "Halgar's Summons", description = "Ah, <name>! I just received word from Carendin Halgar that he would like to see you for further training.\n\nYou should be proud of yourself, <name>. It's not every day that Master Halgar personally sees fit to instruct a young warlock.\n\nYou'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Carendin Halgar in the Undercity.Ah, <name>! I just received word from Carendin Halgar that he would like to see you for further training.\n\nYou should be proud of yourself, <name>. It's not every day that Master Halgar personally sees fit to instruct a young warlock.\n\nYou'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1479] = { title = "The Bough of the Eternals", description = "I've heard stories about how the night elves have their bank in a tree - one that looks like a bear!  That's so cool!  Night elves are neat how they like nature and stuff, but bears are just totally awesome!\n\nWould you take me to see the bear-tree in Darnassus, please?  There's a boat that will take us close to there, and it shouldn't take very long.  Please, please, please!Upon completion of this quest you will gain:", objectives = "Take the orphan to the bank of Darnassus. The bank itself is hollowed out of a tree known as the Bough of the Eternals." }
WordHunterWoW_QuestEN[1480] = { title = "The Corrupter", description = "The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile.\n\nAs you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind.\n\nPerhaps it is something Maurin could tell you more about?", objectives = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.", progress = "The Burning Blade begin to realize how weak they truly are. Their magics are pathetic, their strength feeble.\n\nTheir only power comes from those they serve, and not from any understanding of true power and knowledge.", completion = "Hmm, these runes are indeed a language, <name>, an old language. They seem remotely similar to the Eredun language, but the differences are drastic. If I am not mistaken, this is a contract of some kind.... Here, yes, this symbol is the demon's signature: Lord Azrethoc." }
WordHunterWoW_QuestEN[1481] = { title = "The Corrupter", description = "I believe I can find this demon lord given the proper reagents.\n\nIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.\n\nFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.\n\nSearch for them among the ancient ruins in the northeast of Desolace.", objectives = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.", progress = "Do not bring me an incorrect scalp, <class>. Using the incorrect reagents could cause our deaths. The demon lord may have contingency spells on his person to slay those who would scry upon him.\n\nFate has already dealt me enough pain.", completion = "The shadowstalkers were unable to slay you, <class>. Impressive... most impressive.\n\nThis scalp will do nicely for my spell. While you were away, I was able to gather some of the other reagents needed for the spell.\n\nI am almost ready. I only need a focus for the spell--something to project an image of the demon lord and his whereabouts." }
WordHunterWoW_QuestEN[1482] = { title = "The Corrupter", description = "An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.\n\nNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.\n\nWhen you return, we shall see about finding this demon lord Azrethoc.", objectives = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.", progress = "I am ready for the oracle crystal, <class>. Finding and destroying this Lord Azrethoc would garner a great deal of favor with the Warchief for both of us. We would do well to work together and to do so swiftly so we may further our own ends and curry favor with the Warchief.", completion = "A precious oracle crystal... flawless... beautiful. Indeed.\n\nWe shall begin immediately. Finding this demon lord should be our primary concern, and its slaying demands our utmost attention.\n\nTake a step back, <class>, and let us see what this demon is, and where he may be found." }
WordHunterWoW_QuestEN[1483] = { title = "Ziz Fizziks", description = "The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.\n\nA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.\n\nMaybe you could look in on him for me? He's stationed at the western edge of Windshear Crag.", objectives = "Speak with Ziz Fizziks in Windshear Crag.", completion = "I thought those Venture Company higher-ups were slave drivers, but then I met Sputtervalve, the cruelest of them all!\n\nHa! Though it's better than being out of a job, I suppose... Or worse, working with that Gerenzo. If you're here to help, I've got something for you to do." }
WordHunterWoW_QuestEN[1484] = { title = "The Corrupter", description = "This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.\n\nSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.", objectives = "Speak to Takata Steelblade in Desolace.", completion = "I witnessed what just occurred with Maurin and the demon lord. That creature, even as an apparition, seems to have more power than my warlock companion. I wonder if he's up to the task of defeating the monster? It would serve the Warchief better if I go myself, but with my responsibilities here, I would disgrace my clan if I turned my back on my duties here to battle this evil for my own honor." }
WordHunterWoW_QuestEN[1485] = { title = "Vile Familiars", description = "Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.\n\nThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.\n\nBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.You will learn:", objectives = "Bring 6 Vile Familiar Heads to Ruzan." }
WordHunterWoW_QuestEN[1486] = { title = "Deviate Hides", description = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.\n\nIf you feel up to the task, venture into the caves below and retrieve some deviate hides.", objectives = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.", progress = "I am very interested in examining the hides from the deviate creatures who have infested these caves. Have you had any luck in collecting some, <class>?", completion = "Your efforts shall not go unnoticed in gathering these hides, <name>.\n\nThank you for your dedication." }
WordHunterWoW_QuestEN[1487] = { title = "Deviate Eradication", description = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.\n\nNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.\n\nWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.\n\nBrave the caverns, <name>, and eradicate the deviate spawn.", objectives = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.", completion = "As a Disciple of Naralex, I commend your bravery, <name>.\n\nYour aid in ridding the caverns is the first step in our long plight to see the Barrens restored.\n\nThank you and may you prosper." }
WordHunterWoW_QuestEN[1488] = { title = "The Corrupter", description = "Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.\n\nYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.\n\nWhen you are ready, head directly south,  and return to me when the threat has been ended.", objectives = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.", completion = "A mighty victory for us all, <name>. Let us rejoice in your success. I trust now that our future here is not as bleak as I once thought.\n\nThe demons will be slain, the Burning Blade will fail in their efforts, and we may one day have a place we can safely call home again." }
WordHunterWoW_QuestEN[1489] = { title = "Hamuul Runetotem", description = "The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake.\n\nThe Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel.\n\nYou will find him in Thunder Bluff, on the Elder Rise.", objectives = "Speak with Hamuul Runetotem.", completion = "I bid you greetings, <name>.  You are welcome here, and I suggest you gather all your strength.  For the task we now set before you ... is a dire one." }
WordHunterWoW_QuestEN[1490] = { title = "Nara Wildmane", description = "I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.\n\nI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.\n\nSpeak with Nara.  She is in the tent, over yonder.", objectives = "Speak with Nara Wildmane.", completion = "Yes, it is true.  I know of the druids in the Wailing Caverns.  I have seen their twisted, scaled faces.  I know their crimes, and I know their plans.\n\nYou must stop them, <name>." }
WordHunterWoW_QuestEN[1491] = { title = "Smart Drinks", description = "Ok, so raptor horns don't work so well.  But that's all right -- no one got rich on their first try!  And besides, I think I found something that'll work even better in my smart drinks!\n\nThere is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens.  Get me some and I'll try it in my drink!\n\nI heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west.  Hunt those creatures and gather the essence.", objectives = "Collect 6 portions of Wailing Essence.", progress = "Where is my wailing essence?", completion = "Great, you got it!  I can't wait to try it out.  This is going to make me a fortune, I just know it!\n\nThank you, <name>.  Take this, and after I'm rich I'll send you more, I promise!" }
WordHunterWoW_QuestEN[1498] = { title = "Path of Defense", description = "As a warrior, one of our most crucial tasks is... protection.  We are the shield of the Horde, and we keep our weaker brethren safe.  If you are to join in our ranks, then you must prove your mettle to me.\n\nGo to Thunder Ridge in Durotar, where live the lightning hides and thunder lizards.  Hunt the beasts!  Show me you are tougher than they!  Brave their assaults and bring me a stack of their singed scales as proof.\n\nDo this, and then I will teach you.Upon completion of this quest you will gain:", objectives = "Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens." }
WordHunterWoW_QuestEN[1499] = { title = "Vile Familiars", description = "Zureetha has been sending novices like yourself to help cull the numbers of the creatures in the cave near where you fought the vile familiars.\n\nI think it would be good for you to gain experience by assisting her. Be sure to tell her that you assisted with the imp problem, she'll probably have a reward for you.Upon completion of this quest you will gain:", objectives = "Speak with Zureetha Fargaze.Zureetha has been sending novices like yourself to help cull the numbers of the creatures in the cave near where you fought the vile familiars.\n\nI think it would be good for you to gain experience by assisting her. Be sure to tell her that you assisted with the imp problem, she'll probably have a reward for you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1500] = { title = "Waking Naralex", description = "", objectives = "" }
WordHunterWoW_QuestEN[1501] = { title = "Creature of the Void", description = "So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief.\n\nIt is time that you learned a new summoning spell.\n\nFirst, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker.Upon completion of this quest you will gain:", objectives = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar." }
WordHunterWoW_QuestEN[1502] = { title = "Thun'grim Firegaze", description = "It is vital that a warrior's weapon is one of quality.  And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze.  He is a hermit who dwells atop the hills east of the Crossroads.\n\nIf you seek a weapon, warrior, then you should seek Thun'grim.  To find him, first travel to the Crossroads to the west, then strike east into the hills.  His camp is high on a hilltop.Upon completion of this quest you will gain:", objectives = "Speak with Thun'grim Firegaze in the Barrens.It is vital that a warrior's weapon is one of quality. And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze. He is a hermit who dwells atop the hills east of the Crossroads.\n\nIf you seek a weapon, warrior, then you should seek Thun'grim. To find him, first travel to the Crossroads to the west, then strike east into the hills. His camp is high on a hilltop.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1503] = { title = "Forged Steel", description = "I will give you a weapon, <name>, but first you must aid me.  The Razormanes to the northwest came into my camp a few nights past.  They would not meet me in combat, but they know my eyes are bad--a few distracted me with snorts while others stole from me!  The cowards!\n\nThey took an iron chest, and within it were some forged steel bars.  If you can recover them then I will give you the weapon you seek.\n\nSearch for the iron box within the quilboar camps, and return with the forged steel bars.Upon completion of this quest you will gain:", objectives = "Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens." }
WordHunterWoW_QuestEN[1504] = { title = "The Binding", description = "Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker.\n\nYou must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will.You will learn:", objectives = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar." }
WordHunterWoW_QuestEN[1505] = { title = "Veteran Uzzek", description = "The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well.\n\nSeek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar.Upon completion of this quest you will gain:", objectives = "Speak with Uzzek at Far Watch Post." }
WordHunterWoW_QuestEN[1506] = { title = "Gan'rul's Summons", description = "You there. <name>, right?\n\nI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.\n\nBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.Upon completion of this quest you will gain:", objectives = "Speak with Gan'rul Bloodeye in Orgrimmar.You there. <name>, right?\n\nI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.\n\nBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1507] = { title = "Devourer of Souls", description = "The time has come for you to learn more of the summoning magics. You will learn to summon a succubus, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.\n\nA succubus can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.\n\nA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know.Upon completion of this quest you will gain:", objectives = "Speak with Cazul in the Cleft of Shadow.The time has come for you to learn more of the summoning magics. You will learn to summon a succubus, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.\n\nA succubus can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.\n\nA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1508] = { title = "Blind Cazul", description = "Hmm... But, of course, that is not why you have come to speak with me.\n\nIf Gan'rul has sent you to me, it must be that you are to summon a succubus, and need an object to use for enticement.\n\nHmm... If you trust a blind man to lead you, <name>, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate.\n\nGo to her.Upon completion of this quest you will gain:", objectives = "Speak with Zankaja in Orgrimmar.Hmm... But, of course, that is not why you have come to speak with me.\n\nIf Gan'rul has sent you to me, it must be that you are to summon a succubus, and need an object to use for enticement.\n\nHmm... If you trust a blind man to lead you, <name>, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate.\n\nGo to her.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1509] = { title = "News of Dogran", description = "My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.\n\nI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.\n\nNow it's been a week after he should have returned, and I have received no word from him...\n\nPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.Upon completion of this quest you will gain:", objectives = "Speak with Gazrog at the Crossroads.My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.\n\nI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.\n\nNow it's been a week after he should have returned, and I have received no word from him...\n\nPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1510] = { title = "News of Dogran", description = "He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.\n\nThey sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet.Upon completion of this quest you will gain:", objectives = "Speak with Ken'zigla at the Malaka'jin.He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.\n\nThey sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1511] = { title = "Ken'zigla's Draught", description = "I figured there might be another coming to get the draught, so I prepared it anyways.\n\nHere you go, <name>. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half.\n\nAnyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is.Upon completion of this quest you will gain:", objectives = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo." }
WordHunterWoW_QuestEN[1512] = { title = "Love's Gift", description = "Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice.\n\nLeave me, <name>. And thank you. I may end my life in glorious battle, instead of a lifeless husk.\n\nAnd please, I would ask you not to tell my mate of this... I do not want guilt on her conscience.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar." }
WordHunterWoW_QuestEN[1513] = { title = "The Binding", description = "Take this to the summoning circle in Neeru's tent, <name>. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock.\n\nWhen you have defeated it, return the pendant to me so that I might deliver the news to Zankaja.You will learn:", objectives = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar." }
WordHunterWoW_QuestEN[1514] = { title = "Corrupted Windblossom", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[1515] = { title = "Dogran's Captivity", description = "You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own.\n\nDogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds.\n\nGood luck.Upon completion of this quest you will gain:", objectives = "Bring Ken'zigla's Draught to Dogran in the Barrens." }
WordHunterWoW_QuestEN[1516] = { title = "Call of Earth", description = "The time is now, young <class>. You've grown strong and your spirit endures like the earth. Following the shaman's path shows you have wisdom before even proving yourself.\n\nThe element of earth will guide your destiny, becoming part of you if you are ready. But you must stand before the earth itself. If you are ready, then you will see things only shaman know of.\n\nSeek out the Felstalkers to the north, and take from them two of their hooves. Return to me then, and we shall speak more of your future.Upon completion of this quest you will gain:", objectives = "Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials." }
WordHunterWoW_QuestEN[1517] = { title = "Call of Earth", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a holy place, and never anywhere else--remember that.\n\nSeek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.Upon completion of this quest you will gain:", objectives = "Find Spirit Rock and drink the Earth Sapta.\n\nProvided item:" }
WordHunterWoW_QuestEN[1518] = { title = "Call of Earth", description = "Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, <name>. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.Upon completion of this quest you will gain:", objectives = "Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials." }
WordHunterWoW_QuestEN[1519] = { title = "Call of Earth", description = "The time has come, young <class>. Your body ages and grows strong, and your spirit endures like the earth. I see it within you-you have wisdom already.\n\nThe earth guides our people, and it speaks to us, as it will to you in time. But you must be tested. If you are ready, then you shall see things only our kind know of.\n\nSeek out the Bristleback shamans in their ravine to the east, and take from them a salve they use in their rituals. Return to me only when you have enough for your own potion.Upon completion of this quest you will gain:", objectives = "Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache." }
WordHunterWoW_QuestEN[1520] = { title = "Call of Earth", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the open minded to see the elements as no one has seen them before. Your spirit will forever be tied to the element the sapta was created for, and only a select few of our kind know the secrets of its creation.\n\nThe sapta is always imbibed in a holy place, and never anywhere else.\n\nSeek out the shaman shrine to the east of here and drink of the sapta.Upon completion of this quest you will gain:", objectives = "Find Kodo Rock and drink the Earth Sapta.\n\nProvided item:" }
WordHunterWoW_QuestEN[1521] = { title = "Call of Earth", description = "Take this rough quartz from me and bring it to Seer Ravenfeather as proof of our meeting. She will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast mountains.\n\nBe patient, <name>. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.You will also receive:", objectives = "Bring the Rough Quartz to Seer Ravenfeather in Camp Narache." }
WordHunterWoW_QuestEN[1522] = { title = "Call of Fire", description = "Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal.\n\nKranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready.\n\nHe be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.Upon completion of this quest you will gain:", objectives = "Find Kranal Fiss in the Barrens.Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal.\n\nKranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready.\n\nHe be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1523] = { title = "Call of Fire", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.", objectives = "Find Kranal Fiss in the Barrens.", completion = "Hmmm, Xanis sent you to me, did he?\n\nWell then, Xanis could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, <name>. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand." }
WordHunterWoW_QuestEN[1524] = { title = "Call of Fire", description = "You are powerful enough to wield the totem of fire, but that does not mean you are ready.\n\nAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.\n\nTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.", objectives = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.", progress = "Greetin's, <name>. You've found yourself at the Shrine of the Dormant Flame. Only those knowledgeable enough in the shamanistic arts will ever learn the secrets of this place and the power it holds. I'm sorry you made the trip all this way, only to be turned back now--the journey up here is far from safe after all--but I am the keeper of the shrine, and I cannot allow just anyone to wander around here.", completion = "Ah, my mistake, <name>. I apologize. I did not realize you possessed the Torch. I am pleased to make your acquaintance.\n\nMany adventurers find their way here while looking for lost treasure or the promise of mystical creatures to slay, only to be turned away from a seemingly empty shrine. But we know the truth, do we not, <name>?\n\nThis shrine holds a greater secret from the mundane members of the Horde. To us, it is sacred." }
WordHunterWoW_QuestEN[1525] = { title = "Call of Fire", description = "But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem.\n\nThe first step is to create a sapta and bind you to the flame.\n\nI can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens.\n\nThe second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor Hill.You will receive:", objectives = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar." }
WordHunterWoW_QuestEN[1526] = { title = "Call of Fire", description = "The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him.\n\nStrike him down swiftly, <name>, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch.You will receive:", objectives = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame." }
WordHunterWoW_QuestEN[1527] = { title = "Call of Fire", description = "Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.\n\nYou start off down the path back to the Barrens in search of Kranal Fiss.You will learn:", objectives = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens." }
WordHunterWoW_QuestEN[1528] = { title = "Call of Water", description = "Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen.\n\nIslen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready.\n\nShe be easy ta find, just don' go too far south--she be jus' beyond Ratchet.Upon completion of this quest you will gain:", objectives = "Find Islen Waterseer in the Barrens.Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen.\n\nIslen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready.\n\nShe be easy ta find, just don' go too far south--she be jus' beyond Ratchet.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1529] = { title = "Call of Water", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.Upon completion of this quest you will gain:", objectives = "Find Islen Waterseer in the Barrens.Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1530] = { title = "Call of Water", description = "If there is one lesson you must learn of water, it is this: water means rebirth.\n\nIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.\n\nWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.\n\nIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.Upon completion of this quest you will gain:", objectives = "Find Brine at Blackthorn Ridge in Southern Barrens.If there is one lesson you must learn of water, it is this: water means rebirth.\n\nIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.\n\nWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.\n\nIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1531] = { title = "Call of Air", description = "You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect.\n\nHead south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.Upon completion of this quest you will gain:", objectives = "Find Prate Cloudseer in Thousand Needles.You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect.\n\nHead south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1532] = { title = "Call of Air", description = "The winds of Kalimdor rush to meet you and you shall be counted among some of our most powerful <brothers/sisters>. I am proud to see you have come this far and have such a promising future.\n\nThe element of air is a difficult one to control, but I have faith that your skills will overcome any obstacles that are placed in front of you.\n\nHead to the very south of the Barrens, and enter Thousand Needles. It is there, far to the east, that you will find Prate Cloudseer. She will teach you more.", objectives = "Find Prate Cloudseer in Thousand Needles.", completion = "For the time being, I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more." }
WordHunterWoW_QuestEN[1534] = { title = "Call of Water", description = "Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens.\n\nOnce you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain.\n\nBring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen.Upon completion of this quest you will gain:", objectives = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens." }
WordHunterWoW_QuestEN[1535] = { title = "Call of Water", description = "To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives.\n\nWe shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me.Upon completion of this quest you will gain:", objectives = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens." }
WordHunterWoW_QuestEN[1536] = { title = "Call of Water", description = "Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill.\n\nIt was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea.\n\nBring me a sample of that water in this waterskin.Upon completion of this quest you will gain:", objectives = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens." }
WordHunterWoW_QuestEN[1558] = { title = "The Stonewrought Dam", description = "Ironforge is where all the dwarves and gnomes live.  Near there is a place called Loch Modan, and the dwarves built a HUGE dam there.  They say it's one of the biggest things anyone's ever made.  Wow!\n\nCould you take me to Loch Modan and see the dam there, please?  I think it is the Stone... um... Stonewrench Dam?  Stonewrought?  It's big - that's for sure.  I'd like to look out over the big waterfall.  I promise I won't lean over too far!Upon completion of this quest you will gain:", objectives = "Take the orphan to the Stonewrought Dam in Loch Modan. You should take him to the middle of the dam so he can see out over the giant waterfall." }
WordHunterWoW_QuestEN[1559] = { title = "Flash Bomb Recipe", description = "", objectives = "So you're an engineer, eh?  Well, for your help in getting me those pearls, here's the recipe for flash bombs.\n\nGood luck, and try not to blind yourself!You will receive:" }
WordHunterWoW_QuestEN[1560] = { title = "Tooga's Quest", description = "I am so lost!\n\nMy wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere.\n\nWould you be so kind as to lead me back to Torta? She's waiting for me just south of Steamwheedle Port.", objectives = "Show Tooga the way back to his wife, Torta.", completion = "So he couldn't find his way back on his own? Figures.\n\nWell, I guess you deserve something for your troubles...." }
WordHunterWoW_QuestEN[1578] = { title = "Supplying the Front", description = "The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs.\n\nThat's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you.\n\nThorvald is in Loch Modan's southern guard tower.", objectives = "Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan.", progress = "I have no time to chat.  Do you have business with me?", completion = "Ah, apologies!  I didn't realize you were here to help resupply our troops.  The stuff you made will be a big help!\n\nHere are plans for some armor.  I hope you find them useful." }
WordHunterWoW_QuestEN[1579] = { title = "Gaffer Jacks", description = "I came to Auberdine because of the quiet.  I want to invent my inventions where it's quiet, because after a night of drinking I don't like all the noise of Ironforge!\n\nSo I took a ship to Auberdine and had a little too much to drink on the way.  I dropped my box of gaffer jacks overboard!  I need my gaffer jacks!\n\nI don't know exactly where I dropped them, but if you fish for them in the ocean you might get lucky...", objectives = "Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.", progress = "Did you find my gaffer jacks, <name>?  Without my gaffer jacks I can't tune my stintle pegs!", completion = "I can't believe you found them!  You must be the luckiest <race> in Kalimdor!" }
WordHunterWoW_QuestEN[1580] = { title = "Electropellers", description = "We know you're lucky, but... just how lucky are you, <name>?\n\nOne night I was wandering the roads of Darkshore.  I was looking for a good river or lake to try my new self-propelled, exploding duck decoy and I think I was a little tipsy... because I passed out and awoke hours later in Auberdine.  My hair was singed and my bag of electropellers was gone!  I must have dropped them in the water!\n\nI need those electropellers!  Maybe you can fish them out of some lake or stream in Darkshore...", objectives = "Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.", progress = "Did you find any electropellers?  I'll need them if I'm to continue my research on duck decoys...", completion = "I can't believe it!  You found them!  You are the best fisherman I've ever seen!\n\nThank you, <name>.  And here, take these.  Although you're so good and you probably don't need them, they will help you with your fishing." }
WordHunterWoW_QuestEN[1581] = { title = "Elixirs for the Bladeleafs", description = "Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other.\n\nCan you help us?\n\nIf you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.", objectives = "Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.", progress = "Hello, <name>.  Do you have the elixirs to trade?", completion = "These are nicely mixed.  You take great care in your trade, <name>, and that is important for an alchemist.\n\nHere are your herbs, freshly gathered.  May you use them well." }
WordHunterWoW_QuestEN[1582] = { title = "Moonglow Vest", description = "We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.\n\nIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.", objectives = "Bring 1 Embossed Leather Gloves, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.", progress = "Greetings, <name>.", completion = "Yes, these are good pieces. You have a skilled hand and an eye for detail. Your future as a leatherworker is promising.\n\nHere, <name>. Let me show you the pattern to make the Moonglow Vest." }
WordHunterWoW_QuestEN[1598] = { title = "The Stolen Tome", description = "You there! <name>, right?\n\nI hope you're sure about becoming a warlock, because if you can't hold your own, you're likely to get pulled under.\n\nI'm to teach you, but I need to make sure you're strong enough first.\n\nThere was a novice studying at the Abbey who ran off to join the Defias Brotherhood. Why do I care? Well, he stole some important books.\n\nOne of those happens to be a book I've wanted for myself, the Powers of the Void. Steal it for me, they have it hidden at their tent in the Vineyards.You will learn:", objectives = "Retrieve the Powers of the Void for Drusilla La Salle." }
WordHunterWoW_QuestEN[1599] = { title = "Beginnings", description = "You must be the new warlock everyone's been whispering about. Must be someone's taken a liking to you if they've asked me to take time away from my research to start your training.\n\nDon't worry, I won't hold it against you.\n\nThe simplest of the summoning spells you will learn is that of the imp. Before I impart this to you, however, you must prove that you have the necessary magical and physical ability.\n\nBring me three feather charms from the frostmane novices from the cave to the southwest.You will learn:", objectives = "Bring 3 Feather Charms to Alamar Grimm in Anvilmar." }
WordHunterWoW_QuestEN[1618] = { title = "Gearing Redridge", description = "We dwarves aren't the only ones fighting.  Our human allies have their hands full too!\n\nRedridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.", objectives = "Tormus Deepforge wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.", progress = "I hope you're here with good news from Ironforge.  Because I'm at my wit's end!", completion = "Thank you, <name>.  This will help me out tremendously.  With the Blackrock orcs attacking from Stonewatch Keep and the Redridge gnolls lurking in the foothills to the north, I'm always fixing armor and making new weapons for our troops.\n\nThe supplies you brought will give me a moment's peace.  I will have enough time to teach you something..." }
WordHunterWoW_QuestEN[1638] = { title = "A Warrior's Training", description = "You've shown yourself to be a competent warrior, <name>.  But you're still young and have a lot to learn.\n\nSpeak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.Upon completion of this quest you will gain:", objectives = "Speak with Harry Burlguard in Stormwind.You've shown yourself to be a competent warrior, <name>. But you're still young and have a lot to learn.\n\nSpeak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind. Harry is an old veteran and a good teacher. He can show you a few moves that'll keep you breathing longer.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1639] = { title = "Bartleby the Drunk", description = "Yeah, I can teach you.  But first I wanna see what moves you have already.\n\nSee that drunk over there at the end of the bar?  Bartleby?  I want you to get his mug.\n\nHah, and if you know Bartleby then you know he won't just give it to you.", objectives = "Speak with Bartleby.", completion = "Hello, fancy boy!  What's a prissy thing like you doing in the Pig and Whistle?  Be careful, or you might break a nail..." }
WordHunterWoW_QuestEN[1640] = { title = "Beat Bartleby", description = "You want what??  You're crazy!\n\nThe only way you'll get this mug is if you pry it from my cold, dead fingers...", objectives = "Beat Bartleby, then talk to him.", completion = "You're a lot tougher than you look!" }
WordHunterWoW_QuestEN[1641] = { title = "The Tome of Divinity", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1642] = { title = "The Tome of Divinity", description = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.Upon completion of this quest you will gain:", objectives = "Speak to Duthorian Rall in Stormwind.In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1643] = { title = "The Tome of Divinity", description = "Your task then, <name>, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light.Upon completion of this quest you will gain:", objectives = "Search the Trade District of Stormwind for Stephanie Turner.Your task then, <name>, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1644] = { title = "The Tome of Divinity", description = "Bless their hearts, most of them have no families because of the Scourge attacks in the last decade.\n\nMy husband John collects the materials for me to make the shirts and pants for the children, but I haven't even had time to do that. I've been too focused on keeping food on their plates, and a roof over their heads.\n\nWhat's that? You'd be willing to help? Oh, thank the Light, and thank you, <name>.\n\nIf you could bring me some linen cloth so I can sew clothes for the kids, that would help me out so much.Upon completion of this quest you will gain:", objectives = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind." }
WordHunterWoW_QuestEN[1645] = { title = "The Tome of Divinity", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1646] = { title = "The Tome of Divinity", description = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.Upon completion of this quest you will gain:", objectives = "Speak to Tiza Battleforge in Ironforge.In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1647] = { title = "The Tome of Divinity", description = "Your task then, <name>, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Search the outer ring of Ironforge for John Turner.Your task then, <name>, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1648] = { title = "The Tome of Divinity", description = "My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help.\n\nThis trip's been agonizingly slow, and not very productive.\n\nIf I could just get some more linen for my wife to make some clothes, I could finally send a shipment home.Upon completion of this quest you will gain:", objectives = "Bring 10 Linen Cloth to John Turner in Ironforge." }
WordHunterWoW_QuestEN[1649] = { title = "The Tome of Valor", description = "Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.\n\nThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot.", objectives = "Speak to Duthorian Rall in Stormwind.", completion = "Ah, you wish to petition me for a test of valor. Splendid.\n\nThere are many tasks throughout the city and surrounding lands that hold much challenge, and they could use a woman with your skills.\n\nThis test should not be taken lightly, <name>. This, like many things along our path, could take our lives. The Church always wishes to bolster its ranks, but it understands the sacrifices needed to ensure the paladins serving it are worthy.\n\nAre you prepared?" }
WordHunterWoW_QuestEN[1650] = { title = "The Tome of Valor", description = "Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.\n\nAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.\n\nReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there.Upon completion of this quest you will gain:", objectives = "Find Daphne Stilwell in Westfall.Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.\n\nAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.\n\nReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1651] = { title = "The Tome of Valor", description = "Now, they'll be coming again soon, I'd wager, so get yourself ready.\n\nI've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own.\n\nI've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier.\n\nAsk the Light for whatever blessings you can because... did you hear that? I think they're coming.\n\nWe make our stand near the house!Upon completion of this quest you will gain:", objectives = "Defend Daphne Stilwell from the Defias attack.\n\nNeither of your spirits must be released from their mortal coils if you wish to succeed.\n\nAfter you are successful, speak to Daphne Stilwell again." }
WordHunterWoW_QuestEN[1652] = { title = "The Tome of Valor", description = "Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.\n\nHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.\n\nOh, how I miss my husband. I can't wait till he returns.You will learn:", objectives = "Speak to Duthorian Rall in Stormwind.Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.\n\nHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.\n\nOh, how I miss my husband. I can't wait till he returns.You will learn:" }
WordHunterWoW_QuestEN[1653] = { title = "The Test of Righteousness", description = "Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.\n\nJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.\n\nHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air.Upon completion of this quest you will gain:", objectives = "Speak to Jordan Stilwell in IronforgeActually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.\n\nJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.\n\nHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1654] = { title = "The Test of Righteousness", description = "I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance.\n\nI will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, <class>?Upon completion of this quest you will gain:", objectives = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge." }
WordHunterWoW_QuestEN[1655] = { title = "Bailor's Ore Shipment", description = "Ach, ya startled me, <man/woman>! Can't ya see I was lost in thought?\n\nWhat's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough.\n\nIf you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.", objectives = "Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan.", progress = "So, any luck yet? Haha, those ogres didn't get the best of ya yet, did they?", completion = "Yup yup, this is it. Ha! If I'd known you were really gonna head out there and fight some o' them ogres, I woulda given you a list of things to get instead of just this one thing. But, you're not here doin' business for me, are ya?.\n\nA deal's a deal; Jordan wanted a shipment of me alloy, that's what he's gonna get.\n\nTell 'em hello fer me, and be safe, <class>." }
WordHunterWoW_QuestEN[1656] = { title = "A Task Unfinished", description = "<name>, please, I beg of you, can you help me? I have not finished my tasks here on the Mesa--I'm in the middle of my Rite of Strength--and my father asked me to deliver these furs to the inn in Bloodhoof.\n\nI'm far from rested enough to complete both my rite and this task for my father. Would you mind going on for me?\n\nThe inn is pleasant and a perfect place to rest during your long travels. I'm sure you'll agree once you see it.", objectives = "Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.", progress = "Yes, young one? What can Kauth do for you?\n\nThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?", completion = "Ah, the furs I was expecting. Thank you.\n\nThese came faster than I had expected. They will make good blankets for anyone who wishes to stay here.\n\nPlease feel free to stay as long as you like. My inn is always open and all of our people are welcome here. And don't underestimate a good night's rest, it can make a great difference while you're out traveling." }
WordHunterWoW_QuestEN[1657] = { title = "Stinking Up Southshore", description = "Celebrate Hallow's End in style... by bringing grief to our enemies in Southshore!\n\nTake one of these specially crafted stink bombs.  It is filled with an odiferous funk that no human - or any weak-willed beast for that matter - can stand to smell.  You'll need to throw it right in the heart of Southshore for it to do its job, so be prepared for a fight against the Alliance!\n\nWhen you've completed this task... this tribute to our liberation, return to me!You will receive:", objectives = "Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade." }
WordHunterWoW_QuestEN[1658] = { title = "Crashing the Wickerman Festival", description = "I need brave individuals to head up to Tirisfal Glades and check out the Wickerman Festival.  I'm not going to lie - heading up there will be dangerous.  The guards at the festival will be exceptionally vicious.  Still, we need to know how big the festival is this year, and how much trouble the Forsaken are going to cause us during Hallow's End.\n\nIf you're up for it, head to Tirisfal and scout out the festival.  Return to me with the information, and I'll make sure you're well compensated.", objectives = "Locate the Forsaken's Wickerman Festival in Tirisfal Glades. Return to Sergeant Hartman in Southshore once you've done so.", completion = "Well done, <name>.  The Wickerman Festival will continue to be trouble so long as the abominable Forsaken are allowed to haunt the remnants of Lordaeron.  It is NOT a fitting tribute to that once proud kingdom, let me tell you...\n\nHere's some coin for any repairs you might need, and in the spirit of the season I've also included some treats you might like.  Happy Hallow's End - let's keep it as safe as possible here in Southshore." }
WordHunterWoW_QuestEN[1661] = { title = "The Tome of Nobility", description = "I greet you once again, <name>. I am more proud to call you <brother/sister> than ever before--your dedication is a tribute to us all.\n\nThe time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest.\n\nSpeak to me again and I shall grant you a great boon.You will learn:", objectives = "Speak to Duthorian Rall in Stormwind.I greet you once again, <name>. I am more proud to call you <brother/sister> than ever before--your dedication is a tribute to us all.\n\nThe time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest.\n\nSpeak to me again and I shall grant you a great boon.You will learn:" }
WordHunterWoW_QuestEN[1665] = { title = "Bartleby's Mug", description = "Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go.", objectives = "Bring Bartleby's Mug to Burlguard", progress = "I saw your fight with Bartleby.  Nicely done!  Did you get his mug?", completion = "There it is!  He sure didn't want to part with it, but you were persuasive.  Well done.\n\nNow for your lesson..." }
WordHunterWoW_QuestEN[1666] = { title = "Marshal Haggard", description = "You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you.\n\nMarshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career.\n\nLet him know I sent you, and with luck he'll have a spare weapon to offer.", objectives = "Speak with Marshal Haggard.", completion = "Who's that?  Burlguard, is that you?  You'll have to step a little closer.  My eyes aren't what they used to be.  Walking up like that, I thought you were a gnoll!" }
WordHunterWoW_QuestEN[1667] = { title = "Dead-tooth Jack", description = "Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you...\n\nA while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him!\n\nGet back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south.", objectives = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.", progress = "Do you have my badge? I don't want to think of the mischief Dead-tooth Jack could cause with it.", completion = "Great, you found it!  I feared it was gone forever, used by the Defias to impersonate a Stormwind official.  Well that won't happen now, thanks to you.\n\nHere are some weapons I used when I was a Marshal.  I kept them in great shape--take your pick!" }
WordHunterWoW_QuestEN[1678] = { title = "Vejrek", description = "If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes.\n\nVejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold.\n\nBring me Vejrek's head and I'll know you have mettle.Upon completion of this quest you will gain:", objectives = "Bring Vejrek's Head to Muren Stormpike in Ironforge." }
WordHunterWoW_QuestEN[1679] = { title = "Muren Stormpike", description = "Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.\n\nYou can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior.Upon completion of this quest you will gain:", objectives = "Speak with Muren Stormpike.Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.\n\nYou can find Muren at the Hall of Arms in the Military Ward of Ironforge. Talk to him when you're ready to learn what it is to be a warrior.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1680] = { title = "Tormus Deepforge", description = "Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like.\n\nYou'll find Tormus here in Ironforge, at the Great Forge.Upon completion of this quest you will gain:", objectives = "Speak with Tormus Deepforge.Now that you've learned some moves, it's time to get you a decent weapon. Speak with Tormus Deepforge. He can make you a weapon I'm sure you'll like.\n\nYou'll find Tormus here in Ironforge, at the Great Forge.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1681] = { title = "Ironband's Compound", description = "My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best.\n\nBut one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone!\n\nEnter Ironband's compound, <name>, and avenge my master's death.  And bring me the load of umbral ore that caused it.", objectives = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.", progress = "Have you entered Ironband's Compound?  Did you find the umbral ore?", completion = "You found it! Well done!\n\nI hope you killed a host of Dark Iron dwarves while searching.  I fear that Ironband's compound won't be the last place we see them.\n\nBut thank you for the ore, <name>.  I'm eager to work it and find its properties." }
WordHunterWoW_QuestEN[1682] = { title = "Grey Iron Weapons", description = "", objectives = "Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!\n\nPlease, <name>, take your pick!" }
WordHunterWoW_QuestEN[1683] = { title = "Vorlus Vilehoof", description = "Before I can teach you, you must show me your resolve.\n\nThe satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth.\n\nFind Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior.\n\nThe path to the moonwell is hidden well, <name>, but stay focused and alert and you will find it.Upon completion of this quest you will gain:", objectives = "Bring the Horn of Vorlus to Elanaria in Darnassus." }
WordHunterWoW_QuestEN[1684] = { title = "Elanaria", description = "Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher.\n\nThe warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.Upon completion of this quest you will gain:", objectives = "Speak with Elanaria.Greetings, warrior. Your skill grows, but there is more to your profession than you may believe. To further progress, you must soon find a teacher.\n\nThe warrior Elanaria dwells in Darnassus, at the Warrior's Terrace. She can instruct you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1685] = { title = "Gakin's Summons", description = "Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.\n\nI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.\n\nYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it.", objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.\n\nI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.\n\nYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it.", completion = "About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.\n\nNo matter.\n\nYou've gone too long without training, and a <class> without training isn't like to keep his head on his shoulders for long." }
WordHunterWoW_QuestEN[1686] = { title = "The Shade of Elura", description = "You have learned much, <name>.  Now we will craft you a weapon.  A warrior's weapon.\n\nTo do this, you must travel to Darkshore.\n\nLong ago a ship crashed upon the rocks near the Auberdine lighthouse, scattering many crates of elunite ore along the ocean floor.\n\nFirst, you must defeat the elunite's guardian, the Shade of Elura.  Once the ship's captain, she cursed herself to roam the deeps and protect her shipment for all time.  Defeat her, gain her medallion, and gather the crates of lost Elunite.Upon completion of this quest you will gain:", objectives = "Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus." }
WordHunterWoW_QuestEN[1687] = { title = "Spooky Lighthouse", description = "Sometimes late at night, our matrons at the orphanage will tell us spooky stories.  Those RULE!  There's one about a ghost that haunts a lighthouse in Westfall.  They say he was a pirate captain who had his ship taken from him by other pirates.  Wow!\n\nCould you please take me to the lighthouse in Westfall?  I wanna see if the ghost of that captain is there!  I promise to stay close to you; I won't run off or anything!Upon completion of this quest you will gain:", objectives = "Take the orphan to see the lighthouse off the coast of Westfall." }
WordHunterWoW_QuestEN[1688] = { title = "Surena Caledon", description = "I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!\n\nThe thieving wench ran off with a thug, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.\n\nHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.Upon completion of this quest you will gain:", objectives = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind." }
WordHunterWoW_QuestEN[1689] = { title = "The Binding", description = "By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was.\n\nWith that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that.\n\nI will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle below.You will learn:", objectives = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind." }
WordHunterWoW_QuestEN[1690] = { title = "Wastewander Justice", description = "You there!  It's time for you to be a big helper to the Gadgetzan Water Company.\n\nThe Wastewander nomads out in the Tanaris desert have seized almost all the water wells!  Without access to them, our water supply will dry up in no time.  If you want to get in our good graces, then you'll help us bring justice to those nomads!\n\nHead east of here and bring down ten Wastewander Bandits and Thieves, then report back to me on the double.  Justice waits for no man... goblin... bah, just get on it!", objectives = "Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle.", completion = "Now that's what I call efficiency!  You've helped thin out the nomad's numbers enough now that we can start to think about how we can win back those water wells.\n\nThe Gadgetzan Water Company thanks you for your help, but we're far from done in dealing with those foul nomads.  Listen close - here's what we need next..." }
WordHunterWoW_QuestEN[1691] = { title = "More Wastewander Justice", description = "We need you to take on the stronger ranks of the Wastewander nomads now.  You've done a good job thus far, but if we are to take back those water wells, then it only makes sense to do it against as few nomads as possible!\n\nThis time around we need you to take down their rogues, assassins, and shadow mages.  You'll find them east and southeast of here.\n\nI'm not going to lie to you - they're a nasty lot.  Do this for us though, and we'll be on our way to taking back what is rightfully ours!", objectives = "Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan.", completion = "Top notch work, <name>... top notch!  You've thinned down the nomad population to a point where we can actually take the fight to them!\n\nIf you haven't already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!" }
WordHunterWoW_QuestEN[1692] = { title = "Smith Mathiel", description = "I have placed the elunite you gathered into a case.  Take it to the blacksmith Mathiel, and he will craft for you an elunite weapon.\n\nMathiel is to the south, on the other side of this building.Upon completion of this quest you will gain:", objectives = "Bring the Case of Elunite to Smith Mathiel." }
WordHunterWoW_QuestEN[1693] = { title = "Weapons of Elunite", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1698] = { title = "Yorus Barleybrew", description = "Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.Upon completion of this quest you will gain:", objectives = "Speak with Yorus Barleybrew.Yorus Barleybrew has issued a challenge to all able warriors of the Alliance. He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1699] = { title = "The Rethban Gauntlet", description = "I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles...\n\nYou have to return within an hour.\n\nThere are whole heaps of Redridge Gnolls in the way.\n\nBefore you start, you have to take a swig of my family's signature drink: Barleybrew Scalder!\n\nSo what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?Upon completion of this quest you will gain:", objectives = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.\n\nYou must not die and release your spirit." }
WordHunterWoW_QuestEN[1700] = { title = "Grimand Elmore", description = "I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop.\n\nAnd duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring Furen's Notes to Grimand Elmore." }
WordHunterWoW_QuestEN[1701] = { title = "Fire Hardened Mail", description = "So I gave you a nice shield, but we don't have to stop there.  I know the secrets to make extremely hard mail armor.  It's not easy and it takes very rare materials, but if you're willing to do the legwork then I'll make a piece for you.\n\nWhat do you say, <name>?  If you're up for the challenge, then I'll give you a list of what to get and where to get them.Upon completion of this quest you will gain:", objectives = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind." }
WordHunterWoW_QuestEN[1702] = { title = "The Shieldsmith", description = "You really showed what you were made of when you ran the Rethban Gauntlet, <name>.  And I'm true to my word.  I'll get you the reward I promised...\n\nExcept it's in Stormwind.\n\nTalk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor.\n\nHere, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one.You will receive:", objectives = "Bring the Cask of Scalder to Furen Longbeard." }
WordHunterWoW_QuestEN[1703] = { title = "Mathiel", description = "I made a copy of my notes on the techniques I learned while making your armor, and need them sent to the blacksmith Mathiel.  He lives in Darnassus which is quite a long way off, but I'm sure he'll be very grateful to learn what I've learned.Upon completion of this quest you will gain:", objectives = "Bring Furen's Notes to Mathiel." }
WordHunterWoW_QuestEN[1704] = { title = "Klockmort Spannerspan", description = "I made a copy of my notes on the techniques I learned while making your armor, and need someone to take them to Klockmort Spannerspan.  He's a gnomish blacksmith in Ironforge and when he learns what I've learned... I bet he'll pull off his own beard in excitement.Upon completion of this quest you will gain:", objectives = "Bring Furen's Notes to Klockmort Spannerspan." }
WordHunterWoW_QuestEN[1705] = { title = "Burning Blood", description = "I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, <name>, then you can have the armor.\n\nTo make this armor, I need samples of burning blood and a burning rock.\n\nThe only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock.\n\nMay fortune grant you speed, <name>.Upon completion of this quest you will gain:", objectives = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind." }
WordHunterWoW_QuestEN[1706] = { title = "Grimand's Armor", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1707] = { title = "Water Pouch Bounty", description = "Greetings <name> - the name's Luglunket, and we've got an important job for you if you're up for it!  Huzzah!\n\nNothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert.  That's our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in.  Most importantly though, you're helping Gadgetzan help itself!", objectives = "Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan.", progress = "Got the five Wastewander water pouches we need?  If you do, then the Gadgetzan Water Company Care Package, Model 103-XB, will be yours!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me." }
WordHunterWoW_QuestEN[1708] = { title = "Iron Coral", description = "I want to try Furen Longbeard's new techniques on my own piece of armor.  And because you helped Furen and he helped me, you're welcome to the armor after I make it!\n\nTo finish the piece, I need a special coral, searing coral.  It grows in only one place--along the coast south of Menethil Harbor in the Wetlands.\n\nBring me enough searing coral and I'll get right to work on the armor.  And hurry, <name>.  I'm so eager to get started it's making my toes twist!Upon completion of this quest you will gain:", objectives = "Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge." }
WordHunterWoW_QuestEN[1709] = { title = "Klockmort's Creation", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1710] = { title = "Sunscorched Shells", description = "My colleague, Furen Longbeard, made a discovery which I am eager to test.  I wish to try it on a new armor that I am researching, for I believe Furen's techniques will produce superior results.\n\nWill you help me?  If you gather what I need to make the armor, then I will make an extra piece for you.\n\nI need the sunscorched egg shells of the Highperch Wyverns who dwell at Highperch, in Thousand Needles.  Search for the shells below their nests, and return to me when you have a sufficient amount.Upon completion of this quest you will gain:", objectives = "Bring 20 Sunscorched Shells to Mathiel in Darnassus." }
WordHunterWoW_QuestEN[1711] = { title = "Mathiel's Armor", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1712] = { title = "Cyclonian", description = "I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord.\n\nPerhaps you are that champion.\n\nProve it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart.\n\nIf so, then I will infuse the heart's power in a weapon, and I will give that weapon to you.\n\nHere is a parchment with the items I need.Upon completion of this quest you will gain:", objectives = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac." }
WordHunterWoW_QuestEN[1713] = { title = "The Summoning", description = "I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power.\n\n<name>, are you ready to face the wind lord?Upon completion of this quest you will gain:", objectives = "Bring the Whirlwind Heart to Bath'rah Windwatcher." }
WordHunterWoW_QuestEN[1714] = { title = "Essence of the Exile", description = "", objectives = "" }
WordHunterWoW_QuestEN[1715] = { title = "The Slaughtered Lamb", description = "Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training.\n\nLuckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood!\n\nAnyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.Upon completion of this quest you will gain:", objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training.\n\nLuckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood!\n\nAnyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1716] = { title = "Devourer of Souls", description = "A succubus is a devourer of souls, destroyer of hearts, and dominator of minds. It knows nothing but evil.\n\nThis will be the creature you will learn to summon and control, but it cannot be brought into our world without a stimulus.\n\nWith a symbol of love as bait, it will surely answer your call. Then you can defeat it, and make it your tool.\n\nIt will be hard to find something of this nature, though. You should speak with Takar the Seer. You will find him in the Barrens of Kalimdor near Camp Taurajo.Upon completion of this quest you will gain:", objectives = "Speak with Takar the Seer in the Barrens.A succubus is a devourer of souls, destroyer of hearts, and dominator of minds. It knows nothing but evil.\n\nThis will be the creature you will learn to summon and control, but it cannot be brought into our world without a stimulus.\n\nWith a symbol of love as bait, it will surely answer your call. Then you can defeat it, and make it your tool.\n\nIt will be hard to find something of this nature, though. You should speak with Takar the Seer. You will find him in the Barrens of Kalimdor near Camp Taurajo.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1717] = { title = "Gakin's Summons", description = "<name>! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you.\n\nIt's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.Upon completion of this quest you will gain:", objectives = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.<name>! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you.\n\nIt's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1718] = { title = "The Islander", description = "Your renown as a warrior grows, <name>.  Now it is time to pit yourself against your peers and see where you stand.\n\nThere is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet.\n\nMeet, and fight.\n\nSpeak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path.\n\nTo reach Fray Island, search for the sand bar shallows along the Merchant Coast.Upon completion of this quest you will gain:", objectives = "Speak with Klannoc Macleod.Your renown as a warrior grows, <name>. Now it is time to pit yourself against your peers and see where you stand.\n\nThere is an island off the coast of the Barrens, south of Ratchet. It is called Fray Island and it is a place where warriors meet.\n\nMeet, and fight.\n\nSpeak with the chief warrior of Fray Island, Klannoc Macleod. If he finds you worthy, then Klannoc will lead you further down the warrior's path.\n\nTo reach Fray Island, search for the sand bar shallows along the Merchant Coast.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1719] = { title = "The Affray", description = "If you want to learn from me, then you must first pass The Affray.  It is a challenge we on Fray Island like to offer rising warriors who think they're tough, and if you can pass this test then I'll know you are.\n\nTo begin, walk into the middle of that crowd yonder and step on the grate.  That'll tell Twiggy Flathead you're ready, and he'll send challengers against you.\n\nBeat all the challengers and he'll call out Big Will.  Kill Big Will, and return to me in the time we allow.Upon completion of this quest you will gain:", objectives = "Kill Big Will, then speak to Klannoc Macleod on Fray Island." }
WordHunterWoW_QuestEN[1738] = { title = "Heartswood", description = "In preparation for your coming, I used my sight to look over the world and through the mists of time. I have found what it is you seek.\n\nIn the War of the Ancients, two lovers fell together in battle. Where they took their last breaths, a tree known as the heartswood grew, a symbol of their undying love.\n\nThat should be enough to tempt a succubus. You will find it in the ruins of Ordil'Aran in the northwestern part of the forest of Ashenvale.Upon completion of this quest you will gain:", objectives = "Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind." }
WordHunterWoW_QuestEN[1739] = { title = "The Binding", description = "Using the heartswood core, you will be able to cast a spell at the summoning circle in the crypt below to open a portal for the succubus to pass through.\n\nBe careful, <name>, succubi have overrun even the strongest of minds.\n\nOnce you have bested and returned it to the void, return to me and I will show you how to call and control it.You will learn:", objectives = "Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb." }
WordHunterWoW_QuestEN[1740] = { title = "The Orb of Soran'ruk", description = "When demons of the Legion fall out of favor, their spirits are imprisoned within orbs and distributed to their mages and warlocks.\n\nMany were carried by their servants in Azeroth. Even fragmented, they still possess the powers of the demons trapped inside.\n\nThe orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps. The other, larger piece, was possessed by a wizard in Shadowfang Keep. Find them and I can reform it.Upon completion of this quest you will gain:", objectives = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens." }
WordHunterWoW_QuestEN[1758] = { title = "Tome of the Cabal", description = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge.Upon completion of this quest you will gain:", objectives = "Speak with Krom Stoutarm in Ironforge.It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1778] = { title = "The Tome of Divinity", description = "I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, <class>.Upon completion of this quest you will gain:", objectives = "Speak to Tiza Battleforge in Ironforge.I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, <class>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1779] = { title = "The Tome of Divinity", description = "I want you to take this, <name>. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now I want you to prove just how adept you've become in both combat, and power.\n\nMy husband Muiredon returned recently from an encounter with some Dark Iron dwarves, and he barely escaped with his life--he's over there having his wounds healed by one of our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May the Light shine upon you.", objectives = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.\n\nProvided item:" }
WordHunterWoW_QuestEN[1780] = { title = "The Tome of Divinity", description = "I'll take these to the children this very day. Please be safe, good <class>. It is not often <men/women> of your character show their faces in the city, but you've proven that the paladins here in Stormwind shall never turn their backs on those in need.\n\nFarewell.Upon completion of this quest you will gain:", objectives = "Speak to Duthorian Rall in Stormwind.I'll take these to the children this very day. Please be safe, good <class>. It is not often <men/women> of your character show their faces in the city, but you've proven that the paladins here in Stormwind shall never turn their backs on those in need.\n\nFarewell.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1781] = { title = "The Tome of Divinity", description = "Take this, <name>. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now the time has come to see if you're powerful enough to focus one of the Light's greatest gifts.\n\nMy friend Gazin returned recently from an encounter with some Defias in Elwynn near Heroes' Vigil--he barely escaped with his life. He's near the altar having his wounds healed by our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May you bask in the Light's glory.", objectives = "Take the Symbol of Life to Gazin Tenorm in Stormwind.\n\nProvided item:" }
WordHunterWoW_QuestEN[1782] = { title = "Furen's Armor", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1783] = { title = "The Tome of Divinity", description = "We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.\n\nNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.\n\nNarm needs help, an' I'll not rest till he gets it.\n\nC'n ya help, <name>?Upon completion of this quest you will gain:", objectives = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.\n\nNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.\n\nNarm needs help, an' I'll not rest till he gets it.\n\nC'n ya help, <name>?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1784] = { title = "The Tome of Divinity", description = "Before I fell in battle, Muiredon and I had almost defeated one of the Dark Iron spies near that small house. We witnessed their captain passing orders to them, and sought to kill him and take the orders.\n\nSome of the council in Ironforge do not yet believe the presence of Dark Iron dwarves exists in Dun Morogh. By attaining one of those scripts, we'll not only have proof of their movements, but possibly an idea of what they're planning.\n\nGet one of those scripts and take it back to Muiredon, <name>.Upon completion of this quest you will gain:", objectives = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge." }
WordHunterWoW_QuestEN[1785] = { title = "The Tome of Divinity", description = "I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.\n\nLight be witcha, mighty <class>. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes.You will learn:", objectives = "Speak to Tiza Battleforge in Ironforge.I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.\n\nLight be witcha, mighty <class>. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes.You will learn:" }
WordHunterWoW_QuestEN[1786] = { title = "The Tome of Divinity", description = "Henze and I had made it to Heroes' Vigil, an island in the middle of Stone Cairn Lake in northeastern Elwynn. We'd heard the Defias had infiltrated our borders and we wanted proof to take to the king's advisors.\n\nWe caught sight of a couple of the scum going over some documents, and we attacked. Unfortunately, we were quickly overwhelmed by more of the mages.\n\nHenze held them off for me while I escaped... the daft fool, going and being brave.\n\nHe's out there now, Henze is. Can you help us, <name>?Upon completion of this quest you will gain:", objectives = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.Henze and I had made it to Heroes' Vigil, an island in the middle of Stone Cairn Lake in northeastern Elwynn. We'd heard the Defias had infiltrated our borders and we wanted proof to take to the king's advisors.\n\nWe caught sight of a couple of the scum going over some documents, and we attacked. Unfortunately, we were quickly overwhelmed by more of the mages.\n\nHenze held them off for me while I escaped... the daft fool, going and being brave.\n\nHe's out there now, Henze is. Can you help us, <name>?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1787] = { title = "The Tome of Divinity", description = "We'll have time to talk more about the Symbol at a later time. What's important now is to get those papers we saw the Defias going over. If we can get our hands on them, we'll be able to prove the Defias have infiltrated Elwynn and hopefully gain some insight into what their plans are.\n\nI'm in no shape for battle as of now, <name>. Do you think you're strong enough to get those papers from the Defias here on the island?\n\nIf you're able to get them, bring them back to Gazin and let him know I'm all right.Upon completion of this quest you will gain:", objectives = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind." }
WordHunterWoW_QuestEN[1788] = { title = "The Tome of Divinity", description = "I'll take the script to the King's advisors after Duthorian's taken a look at them, but in the meantime, you should go speak to Duthorian now. He'll be wanting to pat you on the back for sure!\n\nThank you again, <name>. I hope we meet again. You're surely an ally I'm proud to call friend.You will learn:", objectives = "Speak to Duthorian Rall in Stormwind.I'll take the script to the King's advisors after Duthorian's taken a look at them, but in the meantime, you should go speak to Duthorian now. He'll be wanting to pat you on the back for sure!\n\nThank you again, <name>. I hope we meet again. You're surely an ally I'm proud to call friend.You will learn:" }
WordHunterWoW_QuestEN[1789] = { title = "The Symbol of Life", description = "", objectives = "If you fail to help Narm after you've used the Symbol of Life, <name>, then return to me and I shall give you another.\n\nIt is important to both my husband and I that you return successful. Please, make haste." }
WordHunterWoW_QuestEN[1790] = { title = "The Symbol of Life", description = "", objectives = "Make haste, <name>, more than one life hangs in the balance if you fail.\n\nIf for some reason you fail to help Gazin and Henze, then return to me and I will give you another Symbol of Life for your travels.\n\nDon't mistake my aid as simple charity, you must prove yourself worthy like any other <class> and continual failure may reflect upon you later." }
WordHunterWoW_QuestEN[1791] = { title = "The Windwatcher", description = "Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.\n\nTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands.  He is a skilled weapon maker and a powerful shaman.\n\nTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank.  Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank.Upon completion of this quest you will gain:", objectives = "Speak with Bath'rah the Windwatcher.Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.\n\nTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands. He is a skilled weapon maker and a powerful shaman.\n\nTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank. Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1792] = { title = "Whirlwind Weapon", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1793] = { title = "The Tome of Valor", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1794] = { title = "The Tome of Valor", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1795] = { title = "The Binding", description = "If you are sufficiently prepared, then we should begin. Let me explain the process to you.\n\nI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.\n\nOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, <name>. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders.You will learn:", objectives = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet." }
WordHunterWoW_QuestEN[1796] = { title = "Components for the Enchanted Gold Bloodrobe", description = "The first item I will aid you in creating is a robe. You will gather the items for me, and we will put them together. Afterwards, assuming you succeed, you will have the first of many items that will make you more powerful and aid you in your struggles.\n\nTo start, you must have crafted Robes of Arcana. A tailor can make this for you, or perhaps you can purchase one from someone else--I'd be most impressed if you could make it yourself--but regardless, bring me the robes, and we shall go from there.Upon completion of this quest you will gain:", objectives = "Bring Robes of the Arcana to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[1798] = { title = "Seeking Strahad", description = "It is time you learned the felhunter summoning, <name>. I do not have the reagents and items necessary to teach you here, so you will have to seek out another, Strahad Farsan, another of our inner circle.\n\nHe makes his residence in the goblin port of Ratchet. I will send word ahead of you to inform him of your coming.Upon completion of this quest you will gain:", objectives = "Speak with Strahad Farsan in the Barrens.It is time you learned the felhunter summoning, <name>. I do not have the reagents and items necessary to teach you here, so you will have to seek out another, Strahad Farsan, another of our inner circle.\n\nHe makes his residence in the goblin port of Ratchet. I will send word ahead of you to inform him of your coming.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1799] = { title = "Fragments of the Orb of Orahil", description = "Good, then we shall begin.\n\nThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.\n\nSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.\n\nAgain, do not come back until you have done both things I've asked.Upon completion of this quest you will gain:", objectives = "Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.\n\nAfterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh." }
WordHunterWoW_QuestEN[1800] = { title = "Lordaeron Throne Room", description = "The orphan matrons at my home tell mighty stories of battle and lore at night if we are good and do our chores.  One story was about how Lordaeron fell, and about how the evil Arthas took his own father's life to become ruler.\n\nHe had no honor, <name>!  When I grow up and become a mighty Horde warrior, my blade will be guided by honor - never evil!\n\nWould you take me to see the throne room, please?  It is just before where you would go down into the Undercity.Upon completion of this quest you will gain:", objectives = "Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity." }
WordHunterWoW_QuestEN[1801] = { title = "Tome of the Cabal", description = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know.Upon completion of this quest you will gain:", objectives = "Speak with Jorah Annison in the Undercity.It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1802] = { title = "Tome of the Cabal", description = "It was lost, but there's some idea as to where it might be found.\n\nThere was only one copy ever made and it was vandalized at some point, a large portion of it ripped from the binding. Rumor has it that it somehow passed into the hands of the centaur of Thousand Needles.\n\nThe rest was lost off the coast west of Southshore, where it was to be transported to Menethil Harbor by boat. It never arrived.\n\nIn exchange for this knowledge, all I ask is that if you find it, bring it to me to see.Upon completion of this quest you will gain:", objectives = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge." }
WordHunterWoW_QuestEN[1803] = { title = "Tome of the Cabal", description = "Ah! I see that you are a warlock of similar tastes to mine. Indeed, acquiring the Tome of the Cabal is a worthy aspiration. Did you know that it was once held within the walls of Lordaeron? It was vandalized though, almost half its pages removed. Who would commit such a heinous act?\n\nThat half is lost, though rumor says that it fell into the hands of the centaur of the Thousand Needles.\n\nThe rest of the text was to be transferred to Ironforge, but was lost in transit on the coast west of Southshore.Upon completion of this quest you will gain:", objectives = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity." }
WordHunterWoW_QuestEN[1804] = { title = "Tome of the Cabal", description = "Well, ah, it's hard to let it go. But you found it, and you have more important things to do with it, of course. Just, please, be sure to mention to Strahad that I wanted a copy.\n\nWhile you were out, he sent a message for you. He wanted me to tell you that for his acolytes to assist with the summoning, you'll have to acquire three rods of channeling.\n\nHe might not know where to find them, but I do! They were last used by the orcs of the Dragonmaw clan in the Wetlands. I'd check their spellcasters!Upon completion of this quest you will gain:", objectives = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet." }
WordHunterWoW_QuestEN[1805] = { title = "Tome of the Cabal", description = "This is one of the most interesting texts I have perused in the last few years. The selection here is sparse--mostly books on geography--and I have already read them all. I should hope that Strahad would send me a copy of this tome when he has the chance.\n\nSpeaking of him, he sent word to me while you were away. For your task, you must obtain three rods of channeling.\n\nFor allowing me to look at this text, I will share a secret: You can find the rods on orcs of the Dragonmaw Clan in the Wetlands.Upon completion of this quest you will gain:", objectives = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet." }
WordHunterWoW_QuestEN[1806] = { title = "The Test of Righteousness", description = "Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.\n\nWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.\n\nI'll be somewhat honest, <name>, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy.You will receive:", objectives = "Wait for Jordan Stilwell to finish forging a weapon for you.Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.\n\nWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.\n\nI'll be somewhat honest, <name>, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy.You will receive:" }
WordHunterWoW_QuestEN[1818] = { title = "Speak with Dillinger", description = "I was told Deathguard Dillinger has a job for someone like you.  If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.\n\nDeathguard Dillinger's post is on the west end of Brill, near the graveyard.Upon completion of this quest you will gain:", objectives = "Speak with Deathguard Dillinger in Brill.I was told Deathguard Dillinger has a job for someone like you. If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.\n\nDeathguard Dillinger's post is on the west end of Brill, near the graveyard.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1819] = { title = "Ulag the Cleaver", description = "When the Scourge swept through Tirisfal Glades, we captured one to study.  He had a free mind, and called himself Ulag the Cleaver.  But, although his will was free, he was still enthralled by the Lich King.\n\nWe hoped to find a way to break the king's control over Ulag, but we failed.  Now, finally, it is time to free him.  \n\nFree him, and kill him.\n\nActivate the skull stone trigger near the mausoleum to the north.  This will lift the magical seal that binds him.\n\nThen... be ready, <name>.", objectives = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.", completion = "Well done, <name>.  Ulag was no minor agent of the Scourge.  You have shown the Deathguards, and hence the Dark Lady, that you are a <class> of skill and resolve, and are worthy of further instruction." }
WordHunterWoW_QuestEN[1820] = { title = "Speak with Coleman", description = "You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.\n\nColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.\n\nYou will find him in the Gallow's End Tavern in eastern Brill.", objectives = "Speak with Coleman Farthing.You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.\n\nColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.\n\nYou will find him in the Gallow's End Tavern in eastern Brill.", completion = "Yes, it is true.  I have need for your skills in combat.  My means are small, but my task aids both me and the Forsaken's cause.  Do it, and your reward will be twofold." }
WordHunterWoW_QuestEN[1821] = { title = "Agamand Heirlooms", description = "The Agamand family were my employers in life, and they were the cause of my death!  It is fitting that the Agamands are now mindless minions of the Lich King.\n\nNow I would have their last vestiges of honor.  Go into their family crypt and rob them of their family heirlooms: a sword, an axe, a dagger and a mace.  Bring them to me!\n\nThe Agamand family crypt is at the north end of the Agamand mills, protected by lurking Scourge and dead Agamands.", objectives = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.", progress = "Do you have the heirlooms, <name>?", completion = "Ah!  You retrieved them!  Now the last semblance of honor and memory is stripped from the cursed Agamand lands.  The family truly is no more!" }
WordHunterWoW_QuestEN[1822] = { title = "Heirloom Weapon", description = "", objectives = "I will keep three of the weapons you returned to me, as mementos of my pain and loss.  But please, <name>, choose your favorite of the heirlooms and keep it for yourself.\n\nMay it serve you greater than it served its cursed, former owners." }
WordHunterWoW_QuestEN[1823] = { title = "Speak with Ruga", description = "You are a warrior of skill and growing renown.  Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.\n\nHe awaits those warriors who answer his call.Upon completion of this quest you will gain:", objectives = "Speak with Ruga Ragetotem.You are a warrior of skill and growing renown. Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.\n\nHe awaits those warriors who answer his call.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1824] = { title = "Trial at the Field of Giants", description = "To pass this trial, you must travel south to the Field of Giants.  There you will find a host of crawling, insect creatures.  They are new to the Barrens and I do not like what they herald.\n\nBring me their still-twitching antennae, and waste no time, <name>, for harvested antennae will not twitch for long.  Bring me the antennae in the time allowed, and you will pass the trial.You will receive:", objectives = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo" }
WordHunterWoW_QuestEN[1825] = { title = "Speak with Thun'grim", description = "Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde.  He would like to fashion for you a suit of armor, and bids you speak with him immediately.\n\nThun'grim is camped east of the Crossroads in the Barrens.Upon completion of this quest you will gain:", objectives = "Speak with Thun'grim Firegaze in the Barrens.Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde. He would like to fashion for you a suit of armor, and bids you speak with him immediately.\n\nThun'grim is camped east of the Crossroads in the Barrens.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1838] = { title = "Brutal Armor", description = "I have heard tales of your strength and valor, and wish to make for you a suit of armor, a companion to aid you as tales of your great deeds grow.\n\nBut the fashioning of this armor will be a quest unto itself, <name>.  I will need your help, and the help of other smiths of the Horde.\n\nHere, take this scroll.  I spent many nights, struggling with near-blind eyes, writing that which I need for the armor.  Bring me the items on this scroll and I will create for you the first piece of the suit.Upon completion of this quest you will gain:", objectives = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston." }
WordHunterWoW_QuestEN[1839] = { title = "Ula'elek and the Brutal Gauntlets", description = "The troll smith Ula'elek will craft for you the brutal gauntlets.  He dwells in Durotar, in Sen'jin Village with his Darkspear brethren, and he awaits your coming.Upon completion of this quest you will gain:", objectives = "Speak with Ula'elek in Durotar.The troll smith Ula'elek will craft for you the brutal gauntlets. He dwells in Durotar, in Sen'jin Village with his Darkspear brethren, and he awaits your coming.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1840] = { title = "Orm Stonehoof and the Brutal Helm", description = "Orm Stonehoof is respected greatly for his skill.  He will make for you the brutal helm.\n\nSeek him out in Thunder Bluff, near the pool by the city's great, central totem.Upon completion of this quest you will gain:", objectives = "Speak with Orm Stonehoof in Thunder Bluff.Orm Stonehoof is respected greatly for his skill. He will make for you the brutal helm.\n\nSeek him out in Thunder Bluff, near the pool by the city's great, central totem.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1841] = { title = "Velora Nitely and the Brutal Legguards", description = "It is said that, before her death, Velora Nitely was one of the finest armorsmiths in Lordaeron.  Death, it seems, has not decreased her talents.  Speak with Velora--she will make your brutal legguards.\n\nVelora plies her trade in the Undercity of Lordaeron, in the trade quarter.Upon completion of this quest you will gain:", objectives = "Speak with Velora Nitely in the Undercity.It is said that, before her death, Velora Nitely was one of the finest armorsmiths in Lordaeron. Death, it seems, has not decreased her talents. Speak with Velora--she will make your brutal legguards.\n\nVelora plies her trade in the Undercity of Lordaeron, in the trade quarter.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1842] = { title = "Satyr Hooves", description = "I can make you a pair of brutal gauntlets, and great magic will they hold.  But first, you must collect this magic and bring it to me.\n\nThe satyrs dwell in northeastern Ashenvale because of the forest's power.  They feed off its purity, leeching and corrupting.  You can tell which satyrs have drawn the most of Ashenvale's magic by their swollen, uncloven hooves.\n\nThese hooves hold great power.  I will need them for your gauntlets' crafting.Upon completion of this quest you will gain:", objectives = "Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar." }
WordHunterWoW_QuestEN[1843] = { title = "Brutal Gauntlets", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1844] = { title = "Chimaeric Horn", description = "I will make you the helm, but you must show me you are worthy of it.\n\nNestled in the southwestern reaches of the Stonetalon Mountains lies the Charred Vale.  It was once a verdant place, but is now defiled and ashen, and what creatures remain there are mad with pain and despair.\n\nThat place is where I send you, <name>.\n\nYou must go to the Charred Vale and find a chimaera matriarch.  Slay her, free her of her misery.  Bring me her galvanized horn as proof, and I shall make for you the helm.Upon completion of this quest you will gain:", objectives = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff." }
WordHunterWoW_QuestEN[1845] = { title = "Brutal Helm", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1846] = { title = "Dragonmaw Shinbones", description = "To make the brutal leg guards, I need a brace of sturdy shinbones.  The Dragonmaw orcs of the Wetlands have nice, thick shinbones.  I'll need theirs.\n\nBut they must be sturdy.  Be sure to test the shinbones as you collect them.  If you can break them with your bare hands, then they won't be sturdy enough to work with.Upon completion of this quest you will gain:", objectives = "Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity." }
WordHunterWoW_QuestEN[1847] = { title = "Brutal Legguards", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1848] = { title = "Brutal Hauberk", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1858] = { title = "The Shattered Hand", description = "I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key.\n\nAs you didn't find it on Tazan's body, I can only assume that he left the key in the care of another... Ah, yes, that's right. He had an assistant named Gamon. A drunkard, you'll most likely find him at the tavern. Perhaps you could quietly relieve him of the key.You will receive:", objectives = "Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar." }
WordHunterWoW_QuestEN[1859] = { title = "Therzok", description = "Lower your voice, <name>. Yeah, I know your name. Was told to keep an eye out for an orc by your description.\n\nFrom what we've heard about you, you can handle yourself in combat, and aren't opposed to a little sneakery from time to time.\n\nAm I right?\n\nAnyways, you should go see Therzok in Orgrimmar. He's got an offer for you to hear.Upon completion of this quest you will gain:", objectives = "Speak with Therzok in the Cleft of Shadow in Orgrimmar.Lower your voice, <name>. Yeah, I know your name. Was told to keep an eye out for an orc by your description.\n\nFrom what we've heard about you, you can handle yourself in combat, and aren't opposed to a little sneakery from time to time.\n\nAm I right?\n\nAnyways, you should go see Therzok in Orgrimmar. He's got an offer for you to hear.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1860] = { title = "Speak with Jennea", description = "We mages have a task that needs doing.  One that is vital to the safety of Stormwind and Elwynn forest.\n\nJennea Cannon has the details.  She studies in the wizard's sanctum, in the mage district of Stormwind.  You should make your way to her with haste.Upon completion of this quest you will gain:", objectives = "Speak with Jennea Cannon in Stormwind.We mages have a task that needs doing. One that is vital to the safety of Stormwind and Elwynn forest.\n\nJennea Cannon has the details. She studies in the wizard's sanctum, in the mage district of Stormwind. You should make your way to her with haste.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1861] = { title = "Mirror Lake", description = "This world has been victim to massive mystic struggles, which tore magic currents from once stable channels.  We struggle to determine the effects these changes have caused, and some of us fear the worst!\n\nBut I will reveal more of this later.  Right now, we need you to gather information.\n\nHere, take this flask.  Go to the base of the waterfall at Mirror Lake, southwest of the Stormwind gates, and retrieve a sample of the water there.  Return it to me so that I might test it for magical taints.Upon completion of this quest you will gain:", objectives = "Bring a Mirror Lake sample to Jennea Cannon in Stormwind." }
WordHunterWoW_QuestEN[1878] = { title = "Water Pouch Bounty", description = "", objectives = "Back again, <name>?  If you have five more Wastewander water pouches, then I have a care package with your name on it!", progress = "Back again, <name>?  If you have five more Wastewander water pouches, then I have a care package with your name on it!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me." }
WordHunterWoW_QuestEN[1879] = { title = "Speak with Bink", description = "<name>!  Bink, my gnome colleague in Ironforge, sends word.  She has a task that needs doing and won't rely on anyone but a mage to do it!  Are you that mage, <name>?\n\nIf so, then speak with Bink.  She spends her time in the Hall of Mysteries in the Mystic Ward of Ironforge.Upon completion of this quest you will gain:", objectives = "Speak with Bink in Ironforge.<name>!  Bink, my gnome colleague in Ironforge, sends word. She has a task that needs doing and won't rely on anyone but a mage to do it!  Are you that mage, <name>?\n\nIf so, then speak with Bink. She spends her time in the Hall of Mysteries in the Mystic Ward of Ironforge.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1880] = { title = "Mage-tastic Gizmonitor", description = "We mages do more than just waggle our fingers and make pretty sparks!  We control magic, the base fabric of our world!  And that takes great care, and resolve.  And knowledge... so much knowledge!\n\nOne of my devices, the mage-tastic gizmonitor, collects and stores that knowledge in huge amounts!  But it's lost!  When we fled our home of Gnomeregan, I left it in a chest in one of our huts outside the city, and now the place is crawling with leper gnomes!\n\nPlease, <name>, retrieve my gizmonitor!Upon completion of this quest you will gain:", objectives = "Bring Bink her Mage-tastic Gizmonitor." }
WordHunterWoW_QuestEN[1881] = { title = "Speak with Anastasia", description = "<name>, Anastasia Hartwell has a task for someone of your talents.  Speak with her in the Magic Quarter of the Undercity, and prepare yourself for your first task for the mages of the Forsaken.Upon completion of this quest you will gain:", objectives = "Speak with Anastasia Hartwell.<name>, Anastasia Hartwell has a task for someone of your talents. Speak with her in the Magic Quarter of the Undercity, and prepare yourself for your first task for the mages of the Forsaken.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1882] = { title = "The Balnir Farmstead", description = "The Plaguelands to the east are an aberration.  Devised by the Lich King, they spread their magic into the soil, corrupting and killing all that live.  Although there is a certain charm to the destructive forces of the plague, we, the mages of the Forsaken, believe it is unruly and must be curtailed.\n\nBut first, we must measure how far it has spread into Tirisfal.  Go to the Balnir Farmstead in eastern Tirisfal.  In the garden are flowers--snapdragons.  Gather these and return.Upon completion of this quest you will gain:", objectives = "Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity." }
WordHunterWoW_QuestEN[1883] = { title = "Speak with Un'thuwa", description = "Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid.  Speak with Un'thuwa and do what you can to help him.\n\nDo this, and in time further secrets will be revealed to you.Upon completion of this quest you will gain:", objectives = "Speak with Un'thuwa.Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid. Speak with Un'thuwa and do what you can to help him.\n\nDo this, and in time further secrets will be revealed to you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1884] = { title = "Ju-Ju Heaps", description = "The warlock Zalazane of the Echo Isles has disrupted the normal flow of magic in Durotar.  He does this through tainted fetishes, ju-ju heaps, which he has placed among his huts on the main Echo Isle.\n\nThese heaps corrupt our wildlife and give power to the warlocks and infernal creatures that lurk in the land's dark corners.\n\nYou must destroy the ju-ju heaps, <name>, before the flow of magic is forever altered.Upon completion of this quest you will gain:", objectives = "Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village." }
WordHunterWoW_QuestEN[1885] = { title = "Mennet Carkad", description = "<name>? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?\n\nEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.<name>? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?\n\nEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1886] = { title = "The Deathstalkers", description = "If you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.\n\nI will not lie to you, <name>, this task could mean your death.\n\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.\n\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.Upon completion of this quest you will gain:", objectives = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter." }
WordHunterWoW_QuestEN[1898] = { title = "The Deathstalkers", description = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.\n\nLord Varimathras suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.\n\nI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.Upon completion of this quest you will gain:", objectives = "Speak with Andron Gant in the Undercity." }
WordHunterWoW_QuestEN[1899] = { title = "The Deathstalkers", description = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.Upon completion of this quest you will gain:", objectives = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity." }
WordHunterWoW_QuestEN[1918] = { title = "The Befouled Element", description = "The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.\n\nIt's not exactly common knowledge who might be interested in such a find; perhaps Mastok Wrilehiss at Splintertree Post, might have an idea.", objectives = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.", progress = "Yeah, what do you need?", completion = "You find a nasty ball of water and decide to bring it to me?  Who am I, the Earthen Ring or something?\n\nActually, that does give me an idea... perhaps you do need the Earthen Ring for this.  I mean, if it helps clear up the situation at the lake for good, then I'm all for it.\n\nYou know who the Earthen Ring are, <name>?" }
WordHunterWoW_QuestEN[1919] = { title = "Report to Jennea", description = "Your knowledge of the craft grows, young <name>.  Are you now ready to begin your true lessons?  Are you ready to take your place in the secret war we wage?\n\nIf so, then speak with Jennea Cannon, in the wizard's sanctum in the mage district of Stormwind.  She has a task for you which will open your first window into the invisible world.Upon completion of this quest you will gain:", objectives = "Speak with Jennea Cannon in Stormwind.Your knowledge of the craft grows, young <name>. Are you now ready to begin your true lessons?  Are you ready to take your place in the secret war we wage?\n\nIf so, then speak with Jennea Cannon, in the wizard's sanctum in the mage district of Stormwind. She has a task for you which will open your first window into the invisible world.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1920] = { title = "Investigate the Blue Recluse", description = "A disturbance has been reported at the Blue Recluse tavern in the Mage Quarter.  Strange, invisible creatures now wander the tavern, and I fear a mana rift has formed there.\n\nI want you to investigate the tavern and capture those creatures.  Use the cantation of manifestation in the tavern to make the creatures visible, subdue them then use a containment coffer to capture them.  When you have enough, return to me with your filled coffers, your empty coffers and the cantation.Upon completion of this quest you will gain:", objectives = "Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon. Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum." }
WordHunterWoW_QuestEN[1921] = { title = "Gathering Materials", description = "You have served your fellow mages well, and now it is time to don your wizard's robe.  Wynne Larson can make your robe, but you must bring her the needed materials  \n\nThe robe will be made of linen which is easy to find, but you must also gain charged rift gems, and the only known location of the gems is in the Silver Stream Mine of Loch Modan, left in crates by the dwarven miners' league.\n\nGather the linen and the gems and bring them to Wynne Larson at the Larson Clothiers in the Mage District.Upon completion of this quest you will gain:", objectives = "Bring 10 Linen Cloth and the 6 Charged Rift Gems to Wynne Larson in Stormwind." }
WordHunterWoW_QuestEN[1938] = { title = "Ur's Treatise on Shadow Magic", description = "Long ago, three mages studied in this tower until one fell to the dark arts.  He was urged to turn away from that evil magic, but he could not resist.  And so he was banished.\n\nThe fallen mage's new domain is the tower of Ilgalar in Redridge, and he took with him a powerful book--Ur's Treatise on Shadow Magic.\n\nWe, the mages of Stormwind, would have that book returned.  Enter the tower of Ilgalar, find the tome in his library, and bring it to me.", objectives = "Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind.", progress = "Do you have the book, <name>?  Its secrets are not meant for the untrained, and plumbing its depths can lead to doom and ruin.", completion = "I feared that Morganth had hidden the book elsewhere, or that he had found a way to open it and read its contents.\n\nIt is good to see that he did not, and that the seals we placed on Ur's Treatise on Shadow Magic still hold." }
WordHunterWoW_QuestEN[1939] = { title = "High Sorcerer Andromath", description = "High Sorcerer Andromath wishes to speak with you, <name>.  He is at the top of the wizard's sanctum, in the mage's district of Stormwind.\n\nIt would be wise to speak with him, for Andromath is one of the most powerful mages not locked away in Dalaran.  Council with him is high council indeed.Upon completion of this quest you will gain:", objectives = "Speak with High Sorcerer Andromath.High Sorcerer Andromath wishes to speak with you, <name>. He is at the top of the wizard's sanctum, in the mage's district of Stormwind.\n\nIt would be wise to speak with him, for Andromath is one of the most powerful mages not locked away in Dalaran. Council with him is high council indeed.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1940] = { title = "Pristine Spider Silk", description = "Your service has been unwavering, <name>.  I think, perhaps, it is time you had a finer garment, one more suiting your station as an adept mage.  If you gather the needed materials, then we will arrange the robe made.\n\nYou must enter Duskwood and hunt carrion recluse spiders.  Extract their silk, but only the finest, most pristine silk will do.  When you have enough, take it to Wynne Larson, here in the mage district at the Larson Clothiers.  She will craft your robe.Upon completion of this quest you will gain:", objectives = "Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind." }
WordHunterWoW_QuestEN[1941] = { title = "Manaweave Robe", description = "", objectives = "Here is your robe.  It's one of my best made yet!  Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!" }
WordHunterWoW_QuestEN[1942] = { title = "Astral Knot Garment", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1943] = { title = "Speak with Deino", description = "The troll mage Deino has need of your assistance, <name>.  She resides in Orgrimmar, in the Darkbriar Lodge.Upon completion of this quest you will gain:", objectives = "Speak with Deino.The troll mage Deino has need of your assistance, <name>. She resides in Orgrimmar, in the Darkbriar Lodge.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1944] = { title = "Waters of Xavian", description = "The fabled city of Xavian lies nestled deep within eastern Ashenvale, and tales of its ancient knowledge are well known among the learned.  It is said that the waters of Xavian hold vast magical powers.\n\nI would have a sample of those waters, from their source.\n\nTake this flask and go to Xavian.  Gather water from the bottom of its highest waterfall, and return to me.  And use care as you move through that ancient city--satyrs now hold the ruins and do not like mages prying into their affairs.Upon completion of this quest you will gain:", objectives = "Bring the Xavian Water Sample to Deino in Orgrimmar." }
WordHunterWoW_QuestEN[1945] = { title = "Laughing Sisters", description = "For your services, I have arranged for the creation of your new robes, provided you can gather the needed materials...\n\nFor these robes, you must return to Ashenvale for the locks of hair from laughing sisters--dryads who gather near the Raynewood Retreat.\n\nWhen you have their hair, bring it to Kil'hala, a troll tailor at the Crossroads in the Barrens.  He will be expecting you, and will fashion your robes.Upon completion of this quest you will gain:", objectives = "Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads." }
WordHunterWoW_QuestEN[1946] = { title = "Nether-lace Garment", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1947] = { title = "Journey to the Marsh", description = "Now it is time for you to earn your mage's wand.  To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh.  You will find her shack deep in the marsh, west of Theramore.\n\nSpeak with her, for her knowledge is vast.  You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins.Upon completion of this quest you will gain:", objectives = "Speak with Tabetha.Now it is time for you to earn your mage's wand. To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh. You will find her shack deep in the marsh, west of Theramore.\n\nSpeak with her, for her knowledge is vast. You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1948] = { title = "Items of Power", description = "The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.\n\nI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly.Upon completion of this quest you will gain:", objectives = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh." }
WordHunterWoW_QuestEN[1949] = { title = "Hidden Secrets", description = "To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.\n\nI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.\n\nGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.Upon completion of this quest you will gain:", objectives = "Speak with Magus Tirth in the Shimmering Flats.To make your wand, there are key passages in a certain book that I must read. The book is called Rituals of Power, written by the Magus Tirth.\n\nI do not have a copy of his book, and none of the world's great libraries possess it. So you must speak with Tirth and gain it from him.\n\nGood luck. Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1950] = { title = "Get the Scoop", description = "I can help you with the book, but first you have to help me!\n\nThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.\n\nIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!", objectives = "Find the phrase to Tirth's strongbox, then return to Tirth.", progress = "What are you waiting for? I need my magic phrase!" }
WordHunterWoW_QuestEN[1951] = { title = "Rituals of Power", description = "Hm... now that I think about it, I don't have my book!  You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....\n\nA member of the Scarlet Brotherhood.  He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!\n\nIf you want that book, then you'll have to go to the monastery to find it.  And sorry about all the trouble.  I'm not myself these days...Upon completion of this quest you will gain:", objectives = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh." }
WordHunterWoW_QuestEN[1952] = { title = "Mage's Wand", description = "I'll go make the wands now.Upon completion of this quest you will gain:", objectives = "Speak with Tabetha after her ritual.I'll go make the wands now.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1953] = { title = "Return to the Marsh", description = "It is time, <name>, for you to speak with Tabetha... the hermit of Dustwallow Marsh.  She will instruct you on the creation of a powerful mage's implement.\n\nTabetha's shack lies deep in Dustwallow Marsh, west of Theramore.Upon completion of this quest you will gain:", objectives = "Speak with Tabetha." }
WordHunterWoW_QuestEN[1954] = { title = "The Infernal Orb", description = "The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.\n\nGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.\n\nWhen you have the orb, return to me.Upon completion of this quest you will gain:", objectives = "Bring an Infernal Orb to Tabetha in Dustwallow Marsh." }
WordHunterWoW_QuestEN[1955] = { title = "The Exorcism", description = "Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.\n\nYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.\n\nAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!\n\nSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.Upon completion of this quest you will gain:", objectives = "Kill the Demon of the Orb, then speak with Tabetha." }
WordHunterWoW_QuestEN[1956] = { title = "Power in Uldaman", description = "Now that the demon has been removed, we must gain a power source.  Unfortunately, the best power sources are usually the oldest and the hardest to get.  It's neat how fate likes to take a bite out of you sometimes, isn't it?\n\nSo you're going to need to go to Uldaman and defeat the obsidian sentinel there.  He's big, he's tough, and his power source packs a punch!\n\nI wish you the best of luck, <name>.  And if you don't get lucky then, well... it was nice knowing you.Upon completion of this quest you will gain:", objectives = "Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh." }
WordHunterWoW_QuestEN[1957] = { title = "Mana Surges", description = "We are almost finished, but this last step is the most perilous, <name>.\n\nI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.\n\nKill enough mana surges before the rift closes and I will place all their collected energy in your orb.Upon completion of this quest you will gain:", objectives = "Kill 12 Mana Surges in the allowed time limit." }
WordHunterWoW_QuestEN[1958] = { title = "Celestial Power", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1959] = { title = "Report to Anastasia", description = "The mages of the Undercity have noted a magical disturbance within the city, and have sent word for mages of the Horde to investigate.\n\nAnastasia Hartwell can tell you more.  Speak with her in the Magic Quarter in the Undercity.Upon completion of this quest you will gain:", objectives = "Speak with Anastasia Hartwell.The mages of the Undercity have noted a magical disturbance within the city, and have sent word for mages of the Horde to investigate.\n\nAnastasia Hartwell can tell you more. Speak with her in the Magic Quarter in the Undercity.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[1960] = { title = "Investigate the Alchemist Shop", description = "Algernon's alchemist shop in the Apothecarium is the locus of a strange disturbance.  Invisible creatures, made solely of magic, wander the shop--there must be a reason, and we must find it!\n\nInvestigate the disturbance and capture those creatures.  Take a chest of coffers and a scroll from behind me.  Use the scroll at the shop to make the creatures visible, subdue them with your spells, then throw down a coffer to capture them.  Return with the filled coffers, the empty coffers and the cantation.Upon completion of this quest you will gain:", objectives = "Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell. Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity." }
WordHunterWoW_QuestEN[1961] = { title = "Gathering Materials", description = "It is time for you to don your first mage's robes, <name>.  They are a sign of your station, and a testament to your worth.\n\nTo gain the robes, you must gather the mana gems from the Dalaran mages of Silverpine.  Their beliefs are similar to ours and so killing them is somewhat distasteful, but if they lack the strength to resist us, then they do not deserve their lives.\n\nBring the gems and a supply of linen to Josef Gregorian at the Magic Quarter's tailor shop.Upon completion of this quest you will gain:", objectives = "Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian." }
WordHunterWoW_QuestEN[1962] = { title = "Spellfire Robes", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[1963] = { title = "The Shattered Hand", description = "The Warchief is too subtle in his methods. He is cautious to unleash the might of the Horde. Once we were stronger, mighty conquerors all. That pride we must regain, and the Shattered Hand will do so.\n\nWe build strength from the shadows and strike at the exposed, secretly laying our enemies low. A task you must complete for me, to prove your worth.\n\nThe troll Tazan trades with the pirates near Ratchet. He has information I must have. Kill him and bring me his satchel.Upon completion of this quest you will gain:", objectives = "Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar." }
WordHunterWoW_QuestEN[1978] = { title = "The Deathstalkers", description = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.You will receive:", objectives = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity." }
WordHunterWoW_QuestEN[1998] = { title = "Fenwick Thatros", description = "Lord Varimathras has just sent me a missive about a threat to the Forsaken that must be immediately removed. His name is Fenwick Thatros, one whom Lord Varimathras believes is a leader of the undead that have taken root in Silverpine Forest.\n\nYour name came to mind immediately, <name>. I have faith enough in your abilities that you will carry out this mission flawlessly.\n\nThe latest reports from the Deathstalkers in Silverpine indicate that Thatros can be found near the decrepit dock on Lordamere.Upon completion of this quest you will gain:", objectives = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity." }
WordHunterWoW_QuestEN[1999] = { title = "Tools of the Trade", description = "The wizards of the Kirin Tor at Ambermill have stored away important documents pertaining to the current state of Dalaran. This we know from the admissions of one of our prisoners. Lord Varimathras has placed the duty of recovering them in the hands of the Deathstalkers.\n\nThis task falls to you, <name>. You will need some equipment, however, and the knowledge of lockpicking. Speak with Estelle Gendry, our outfitter, and ask her for a set of tools before you set out.Upon completion of this quest you will gain:", objectives = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity." }
WordHunterWoW_QuestEN[2000] = { title = "Rokar Bladeshadow", description = "Too much idle time for you, <name>. It's time that you learned more of our trade. Just last night, five of our number were found dead in one of the cracks in Orgrimmar, with few leads. There are those that oppose us, using our own methods against us.\n\nSo it is I've decided you should learn the art of lockpicking.\n\nUnfortunately, it is a skill that my hands are not well suited to. You should seek out Rokar, who lives in the hills near Durotar. Even in his old age, I suspect he still has the touch for it.You will receive:", objectives = "Speak with Rokar Bladeshadow in Durotar.Too much idle time for you, <name>. It's time that you learned more of our trade. Just last night, five of our number were found dead in one of the cracks in Orgrimmar, with few leads. There are those that oppose us, using our own methods against us.\n\nSo it is I've decided you should learn the art of lockpicking.\n\nUnfortunately, it is a skill that my hands are not well suited to. You should seek out Rokar, who lives in the hills near Durotar. Even in his old age, I suspect he still has the touch for it.You will receive:" }
WordHunterWoW_QuestEN[2018] = { title = "Rokar's Test", description = "Ah, so now Therzok sends me his budding students, hm? Well, I suppose I can teach you a thing or two. Not that I care much of your business, but I'd not want it on my conscious that I sent you to your death.\n\nBut you must first prove yourself worthy.\n\nI will tell you, <name>. I do not much like this Venture Company. This land reminds me of Draenor, and I do not like the thought of those goblins destroying it. Perhaps if their overseer at the Sludge Fen is killed, their operation will be hamstrung.You will receive:", objectives = "Kill Overseer Glibby and return his Whistle to Rokar Bladeshadow in Durotar." }
WordHunterWoW_QuestEN[2019] = { title = "Tools of the Trade", description = "Here you go, <name>. These should serve you well. Crafted by my own hand, I swear you'll find none better.\n\nDo not bother to tell me your business, however. I have no interest in Therzok's schemes, I wish only to live out my retirement in peace.\n\nIf you should ever need another set of tools, come back to me, and I will furnish you with a new set. But have a care with them!You will receive:", objectives = "Return to Therzok in the Cleft of Shadow in Orgrimmar.\n\nProvided item:" }
WordHunterWoW_QuestEN[2038] = { title = "Bingles' Missing Supplies", description = "As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives. With no gyrocopter and no explosives, the movement has no chance!\n\nGet my tools back and find my Blastencapper explosives, <name>. For Gnomeregan!", objectives = "Find and return Bingles' supplies:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.", progress = "<name>! Where are my things?!", completion = "You've done the movement a great service, <name>. The troggs and leper gnomes infesting Gnomeregan will soon feel the brunt of a gnomish air assault!" }
WordHunterWoW_QuestEN[2039] = { title = "Find Bingles", description = "We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.\n\nHe was last seen flying over the Loch. Perhaps you can investigate, {name}.", objectives = "Find Bingles Blastenheimer in Loch Modan.", completion = "So Gnoarn doesn't trust my reconnaissance abilities? I wonder why...\n\nNevermind that, I need your assistance! Nay! The movement needs your assistance!" }
WordHunterWoW_QuestEN[2040] = { title = "Underground Assault", description = "Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, <name>.\n\nDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!", objectives = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.", progress = "Have you found the Gnoam Sprecklesprocket, <name>?", completion = "Well done, <name>. Thanks to you, Gnomeregan is one step closer to its day of liberation!" }
WordHunterWoW_QuestEN[2041] = { title = "Speak with Shoni", description = "Perhaps... Perhaps you can help us in the battle for Gnomeregan.\n\nIn Stormwind you will find the commander of our underground assault crew, Shoni the Shilent. Shoni needs assistance with her gyrodrillmatic excavationators.\n\nYou will probably find her amongst the dwarves in Stormwind.\n\nGood luck, <name>.", objectives = "Speak with Shoni the Shilent at the Dwarven District in Stormwind.Perhaps... Perhaps you can help us in the battle for Gnomeregan.\n\nIn Stormwind you will find the commander of our underground assault crew, Shoni the Shilent. Shoni needs assistance with her gyrodrillmatic excavationators.\n\nYou will probably find her amongst the dwarves in Stormwind.\n\nGood luck, <name>.", completion = "Do you bring word from central command?" }
WordHunterWoW_QuestEN[2078] = { title = "Gyromast's Revenge", description = "Landlubber, ye needs to find me first mate.\n\nTake this'n key, puts it in his gulliver an' bring him back here to serve the Cap'n.\n\nThem murlocs an' their chief ain't gonna be too happy once me first mate gets a hold of em!", objectives = "Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.", completion = "Yarrr... Ye be provin' yerself to be more than a yella sea dog, landlubber.\n\nThe Cap'n may promote ye to poop deck swabby if ye be keepin' this up..." }
WordHunterWoW_QuestEN[2098] = { title = "Gyromast's Retrieval", description = "A pirate's life ain't an easy one, landlubber. It ain't all about plunderin' and booze! Alas, me ship be sunk just off shore thanks to them pesky Threshadons.\n\nWhat I be needin' is me first mate back in workin' order!\n\nWhen I washed up'n shore, the key for me first mate broke on the rocks and was pilfered by the beasties of Darkshore. Out of the corner of me eyes I saw some of them Ragin' Crawlers, Ferocious Foreststrider, and murloc rummaging through the wreckage....", objectives = "Find and return the three pieces of Gelkak's Key to Gelkak Gyromast.", progress = "Have ye found me broke down key, landlubber?", completion = "Avast ye scurvy sea dog! Ye did it! Soon me first mate be back in workin' order and them beasties won't know what hit em!\n\nHrm, have ye seen me first mate?" }
WordHunterWoW_QuestEN[2118] = { title = "Plagued Lands", description = "A sickness spreads across the Darkshore, gripping the minds and bodies of all it touches.\n\nThe Thistle Bears have been hit the hardest by this plague. The once noble beasts are now an instrument of destruction - rabid and frenzied. I may have a cure for this ailment.\n\nTake this trap to the forest and lay it on the ground. Any Rabid Thistle Bear that crosses the light shall become docile for a short time. Once the bear is docile, it shall follow you. Lead it back here, <name>.", objectives = "Capture a living Rabid Thistle Bear and bring it back to Tharnariun.\n\nShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap.", completion = "Our work has only just begun, <name>. Are you prepared for your next task?" }
WordHunterWoW_QuestEN[2138] = { title = "Cleansing of the Infected", description = "As I had feared, the cure does not work.\n\nIt saddens me greatly to order the death of any of nature's beasts, but the sick and tainted thistle bears must be put down.\n\nReturn to the forest and destroy 20 rabid thistle bears, <name>. It will most certainly not put a stop to the plague but it will slow down the damage the animals are doing to our forest and its inhabitants for a short time.", objectives = "Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.", completion = "You have done Auberdine a great service, <name>, but your task is not yet complete.\n\nReturn to me once you have rested.\n\n...and <name>, prepare your mind and soul for more bloodshed." }
WordHunterWoW_QuestEN[2139] = { title = "Tharnariun's Hope", description = "The survival of our people and lands comes at unfortunate costs, <name>.\n\nYou have spilled the blood of nature's servants; many sick animals you have felled. The people of Auberdine are indebted to you, for the forest's pain is eased - even if only for a moment.\n\nI have one final task for you, but be warned, you will have to kill again. It is my hope that this will be the last time I call upon you, <name>.\n\nIn a cave to the northeast, near Bashal'Aran, resides the Den Mother. Slay her.", objectives = "Find and kill the Den Mother.", completion = "You have fought for Auberdine with bravery and honor, <name>. In our war torn lands, death and despair are common. Many will not rise to meet the challenge of life in our new home, choosing instead to hide in their homes or escape to the more fortified lands of the Alliance.\n\nThank you, <name>. Perhaps someday soon we shall fight along side as comrades versus another foe." }
WordHunterWoW_QuestEN[2158] = { title = "Rest and Relaxation", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", objectives = "Speak with Innkeeper Farley at the Lion's Pride Inn.", completion = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.\n\nWould you like to try a sampling of some of our fine food and drink?" }
WordHunterWoW_QuestEN[2159] = { title = "Dolanaar Delivery", description = "Greetings, young {class}.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.\n\nCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.", objectives = "Bring the Dolanaar Delivery to Innkeeper Keldamyr.", progress = "How might I be of service to you, young one?  Are you here to rest in the inn?  Do you require a hearthstone?", completion = "Ah yes, the delivery of herbs from Shadowglen.  It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I.  But I am glad to get the herbs nonetheless, and I am glad you came.\n\nWhile you are here, please, rest yourself.  Heroes must keep their strength and spirits high, and must find rest and solace whenever they may.  For to neglect one's peace of body and mind is a sure path to failure.\n\nSo... rest." }
WordHunterWoW_QuestEN[2160] = { title = "Supplies to Tannok", description = "Hey! You look like a hearty adventurer. If you're planning on braving the pass, do you suppose you could bring a package to the inn in Kharanos?\n\nYou were planning on stopping at the inn, right? If you make it through the pass, you'll definitely want to take a breather there.\n\nAnyways, bring this to Tannok Frosthammer, the innkeeper's assistant. I can't get through the pass myself, and it'll be days until a Mountaineer escort comes through!", objectives = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.", progress = "Hi there! Come in, take a seat by the fire and warm yourself with a flagon of ale.", completion = "Ah, at last, the supplies from Hands! I was beginning to worry, we've had scarce word from Anvilmar ever since the troggs overran the pass.\n\nThanks for bringing this to me, <name>. And please, make yourself comfortable. You must be tired after your journey." }
WordHunterWoW_QuestEN[2161] = { title = "A Peon's Burden", description = "Excuse me?  Can you help me?\n\nI have a load of food here.  I walked along the road and braved scorpids and spiders and worse!  I brought the food to the Valley of Trials because I thought they needed it and I like to help out.  But they don't need any food!  Now I have to take it back to Razor Hill and I'm afraid of all the beasts along the way...\n\nCan you take it for me?  I'm just a peon, but you're a hero.  You fear nothing!\n\nTake it to Innkeeper Grosk at the Razor Hill inn.  Thank you!", objectives = "Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.", progress = "Welcome to Razor Hill!", completion = "Ah, this is the food Ukor brought to the Valley of Trials.  Did they not need it?  Well, I guess they like to starve you heroes in training.  Builds spirit, they say!\n\nThank you for returning the food.  I'll stick it back on the shelves... but here, let me offer you some refreshment first!\n\nAnd don't forget to rest here in the inn.  You may be a brave <class> ready to take on the world, but if your energy is sapped you won't be doing yourself, or the Horde, much good." }
WordHunterWoW_QuestEN[2178] = { title = "Easy Strider Living", description = "Do you smell that delicious aroma? It's my secret recipe, <name>--fresh strider stew. Delicious!\n\nPerhaps you would be interested in learning the recipe?\n\nBefore I teach you the recipe, you will need to prove that you can handle the beasts.\n\nNow, I don't expect you to go out and tame one and ride it back to me, but if you can kill a few and bring back some of their succulent meat, I may be persuaded to show you the ways of strider stew.", objectives = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.", progress = "The pot is empty and I'm hungry! What's taking you so long?", completion = "Fantastic! Try it and tell me what you think, <name>!" }
WordHunterWoW_QuestEN[2198] = { title = "The Shattered Necklace", description = "You have found a tarnished necklace, though the tarnish belies intricate and magical craftsmanship.  The necklace has been shattered, as its setting appears to be missing three gems.  On the underside of the necklace is the faint imprint of the city seal for Ironforge.  Below the seal are three tiny, engraved letters: \"TdK\".\n\nIf there is anything to be gleaned from the necklace, you will need to learn about its origins.  Perhaps the seal and the initials are a start...", objectives = "Search for the original creator of the shattered necklace to learn of its potential value.", progress = "You've got the wrong gnome, pal!  I was never there!  You can't prove anything!\n\nWait a second... who are you?  What the... where did you find this necklace at?", completion = "Yes... I am the jeweler who made this necklace.  I also am not in the business of handing out information as though it were free.  Information is never free, friend.  If I am going to help you out, you need to help ME out first." }
WordHunterWoW_QuestEN[2199] = { title = "Lore for a Price", description = "I am a jeweler of great renown here in Ironforge!  Well, former renown anyway... I have fallen onto hard times due to the chicanery of a competitor!  A bad reputation in this business spells financial disaster.  As a result, I find myself without a copper to my good-though-currently-sullied name.\n\nI want you to get me five silver bars to finish an order I received - the first in what seems like an eternity.\n\nYou get me those five silver bars, and I'll answer your questions on the necklace.", objectives = "Bring five silver bars to Talvash del Kissel in Ironforge.", progress = "Have you got the five silver bars I asked for?  I will share my sad tale of woe with you concerning the necklace you now possess... but only after I get those bars!  Please, help a gnome out, won't ya?", completion = "You're all right in my book; I don't care what everyone else has been saying... I kid, I kid!  Seriously, thank you my friend.\n\nNow, the necklace you have is one of my finest creations, but it is missing three gems that help bind magic power to it.  I crafted it for a paladin some time ago.  He was on a self-appointed quest to clear out the \"evil taint\" present at an excavation site in the Badlands called Uldaman.\n\nWell... that paladin died in Uldaman, and that was just the beginning of my woes." }
WordHunterWoW_QuestEN[2200] = { title = "Back to Uldaman", description = "A competitor of mine started a rumor that my necklace cursed the paladin.  Needless to say, no one wants to buy cursed items from a jeweler.\n\n<name>, I'll make you a deal - find the gems and I'll reassemble the necklace, so long as you'll advertise that I do NOT make cursed items!\n\nTry looking for clues in Uldaman; maybe see if the paladin's body is down there, since he's the one who we know had it last!  When you find the gems you should use this; it'll allow you to contact me here in Ironforge.", objectives = "Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who had it last.\n\nProvided item:", completion = "Reading the journal reveals that after much effort, the paladin had identified the location of all three missing gems:\n\nThe Shadowforge dwarves hid the ruby in their barricaded area as they battled the Troggs for control of Uldaman.\n\nThe troggs stashed the topaz in an urn located near some unusual inhabitants of Uldaman - Alliance dwarves!\n\nFinally, the trogg elder himself took the sapphire as his own." }
WordHunterWoW_QuestEN[2201] = { title = "Find the Gems", description = "The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.\n\nArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions.", objectives = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n\n* The sapphire has been claimed by Grimlok, the trogg leader.", progress = "Talvash's image comes into focus from the waters of the scrying bowl.\n\n\"Wow, you're still alive!  Did you manage to find the gems?  Are you truly the savior of my reputation I have hoped for?  Please tell me you didn't waste a charge on the phial just to chat; those things are NOT cheap, and I'm already in dire financial straits.\"", completion = "Yep, those indeed are the three gems.  Good job!  Unfortunately, your work isn't quite over just yet.\n\nNo, I'm not trying to pull a fast one here, silly <class>.  This is about making magic jewelry - Talvash del Kissel quality-level jewelry!  You need a strong power source to give it some oomph.  Well, that necklace has no more oomph to give." }
WordHunterWoW_QuestEN[2202] = { title = "Uldaman Reagent Run", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", objectives = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.", progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done <name>, you've proven your worth once again!  The caps will be an interesting study, you betcha.\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!" }
WordHunterWoW_QuestEN[2203] = { title = "Badlands Reagent Run II", description = "You have been most helpful to me, <class>.  I would reward you with the very recipe for the brew I gave you earlier... but I would ask of you a task that is quite dangerous.  Hear my request.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be warned.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.Upon completion of this quest you will gain:", objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Jarkal Mossmeld in Kargath." }
WordHunterWoW_QuestEN[2204] = { title = "Restoring the Necklace", description = "You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.\n\nWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!", objectives = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.", progress = "You didn't even stop to tidy yourself up after leaving Uldaman, did you.  You just came straight here, lingering dungeon odors be damned.  Well, let's hope this visit is merely an odiferous one, and not a useless one to boot.\n\nDo you have the power source for the necklace?", completion = "Well I'll be - I sure am glad to see you and this power source in one piece.  It will take me a moment to magically fuse the power source with the necklace now that the gems have been reunited with it.  Once it is done, however, the necklace will be yours!\n\nYou're excited, aren't you?  All tingly with anticipation?  Now where did I put that spell focus at..." }
WordHunterWoW_QuestEN[2205] = { title = "Seek out SI: 7", description = "The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery <boy/girl> instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.\n\nSpeaking of which, deliver this package to Mathias and he may give you a small task or two.\n\nGet cracking.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks." }
WordHunterWoW_QuestEN[2206] = { title = "Snatch and Grab", description = "Our operatives in the field are reporting heavy bandit activity south of Goldshire. The reports indicate that bandits have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.\n\nI need you to infiltrate the dock house and get me that shipping schedule, {name}. You will probably find it buried deep in the pockets of the Dockmaster.\n\n...and {name}, should you be discovered, SI:7 will disavow all knowledge of your existence.", objectives = "Find the Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.", progress = "Your mortality wanes with every moment you waste loitering in the barracks, <class>.", completion = "I am astonished... Astonished that Keryn finally found a recruit that could possibly have the makings of a proper <class>. Take this blade, <name>. A day will come when you will be called upon again to serve the SI:7. Hone your skills, keep your eyes open and that blade sharp.\n\nYou won't see us coming but you'll feel it when we get there..." }
WordHunterWoW_QuestEN[2218] = { title = "Road to Salvation", description = "Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.\n\nWell, today's your lucky day, friend. Hogral's got the cure for your ailment.\n\nHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Hulfdan Blackbeard in Ironforge.Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.\n\nWell, today's your lucky day, friend. Hogral's got the cure for your ailment.\n\nHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2238] = { title = "Simple Subterfugin'", description = "Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.\n\nThe Hidden Circle has values, <name>. We value valuables. Can ye understand?\n\nNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.\n\nWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.Upon completion of this quest you will gain:", objectives = "Find Onin MacHammar by Gnomeregan.Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.\n\nThe Hidden Circle has values, <name>. We value valuables. Can ye understand?\n\nNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.\n\nWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2239] = { title = "Onin's Report", description = "The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.\n\nMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.\n\nIt's all in the report, <race>. Take it back to Hulfdan so he can plan the next step.You will receive:", objectives = "Take Onin's Report back to Hulfdan in Ironforge." }
WordHunterWoW_QuestEN[2240] = { title = "The Hidden Chamber", description = "Now for the task at hand.\n\nThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.\n\nI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, <name>, must find the chamber of Khaz'mul for us!\n\nRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.", objectives = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.", completion = "You have seen the Chamber of Khaz'mul?  Amazing!  Baelog was sure it existed, but I must admit that I had my doubts.\n\nThank you, <name>.  With luck your finding will incite our leaders to renew their efforts to retake Uldaman.  And if it is ever again under Ironforge control, then the secrets of the Chamber of Khaz'mul will be ours!" }
WordHunterWoW_QuestEN[2241] = { title = "The Apple Falls", description = "They say I'm 'lovestruck,' whatever that means.\n\nSure, I spend my every waking moment thinking about Syurna. Sure, my home is full of paintings and drawings of Syurna. Sure, I often go days without eating, sleeping, or drinking, while I lament about the love we could have had. Is that so wrong?\n\nNow she won't see me! ME! I've tried sending her messages but she won't even talk to another person unless they are a rogue.\n\nCould you deliver this flower to her? Don't forget to tell her it's from Jannok.Upon completion of this quest you will gain:", objectives = "Take Jannok's Rose to Syurna in Darnassus." }
WordHunterWoW_QuestEN[2242] = { title = "Destiny Calls", description = "We believe there is one being that may be able to help us understand what is happening to the forests of Teldrassil. Unfortunately, getting the creature to cooperate has proven disastrous.\n\nHe hides on a branch at the outskirts of the Oracle Glade. All who have so far approached the satyr, whether through force or diplomacy, have met with doom. Perhaps stealth is the answer, <name>.\n\nFind what Sethir the Ancient carries in his packs and report back to me.You will receive:", objectives = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna." }
WordHunterWoW_QuestEN[2258] = { title = "Badlands Reagent Run", description = "<name>, I could use your aid if you're up for it.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.  Watcha wanna do?", objectives = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.", progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done!  These should last me for a little while, at least.  Here is your pay as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?" }
WordHunterWoW_QuestEN[2259] = { title = "Erion Shadewhisper", description = "Do not worry, <name>, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Contact Erion Shadewhisper in Darnassus.Do not worry, <name>, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2260] = { title = "Erion's Behest", description = "Word of your deeds has spread far and wide, <name>. So far, in fact, that Stormwind Intelligence has asked for you by name.\n\nThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.\n\nA new world awaits you, <name>. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.Upon completion of this quest you will gain:", objectives = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"Word of your deeds has spread far and wide, <name>. So far, in fact, that Stormwind Intelligence has asked for you by name.\n\nThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.\n\nA new world awaits you, <name>. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2278] = { title = "The Platinum Discs", description = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!", objectives = "Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon.", progress = "The voice of the stone watcher seems to resonate within your very inner being:\n\n\"You must first satisfy the data assimilation prerequisite of Discs of Norgannon; once you fulfill this requirement, you will then be permitted to obtain a portable version of the stored data.  Please be sure you have fully explored the information within this repository first.\"", completion = "Following the instructions of the stone watcher, you once again access the Discs of Norgannon now that you have learned about the history of the Earthen, the troggs, and the dwarves.  A faint, brief hum is heard from within the discs.  The stone watcher then speaks:\n\n\"The discs have now been synthesized.  Access the Discs of Norgannon once more to receive your personal copy.\"" }
WordHunterWoW_QuestEN[2279] = { title = "The Platinum Discs", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.", objectives = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.", progress = "Yes, may I help you with something?  I assure you I am a very busy right now.  If it is grave importance to the Explorers' League, however, then I am all ears!", completion = "What do you have there... oh my.  You found this where?\n\nNo, really?\n\nYou spoke to whom about what?\n\nNO, REALLY?!\n\nMy fine <class>, you may have just made the archaeological find of the year!  By the Gods who am I kidding, the find of the century!  If these discs are what I think them to be, then this could be the very key we have been looking for!  This may well prove outright once and for all the legitimacy of the Dwarves' enchanted creation!" }
WordHunterWoW_QuestEN[2280] = { title = "The Platinum Discs", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  Someone would sure be interested in this!", objectives = "Take the miniature version of the Discs of Norgannon to someone very interested in them.", progress = "What is that you have there? What did you learn from the discs?", completion = "These discs will change everything. Their secrets are ours now." }
WordHunterWoW_QuestEN[2281] = { title = "Redridge Rendezvous", description = "Sending you out in the field now would be suicide. Renzik doesn't need another dead rogue on his hands. Don't fret, though, <name> - Renzik is going to get you up to speed.\n\nMake your way to the Redridge Mountains and speak with an associate of SI:7 named Lucius. You will find him hanging around the docks of Lakeshire with the other shady good-for-nothings.", objectives = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.", completion = "Ah, so your fingers are a little fat, eh? Don't worry, <name>, I've turned more useless thieves than you into accomplished rogues." }
WordHunterWoW_QuestEN[2282] = { title = "Alther's Mill", description = "We've been training thieves here for years! After all, not every rapscallion is born with the grace and finesse of old Lucius.\n\nUp off the road here you'll find Alther's Mill. I got a chest up there with something important inside. Go get it for me! Bring back that token and you'll receive your Certificate of Thievery!You will receive:", objectives = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire." }
WordHunterWoW_QuestEN[2283] = { title = "Necklace Recovery", description = "We've got work for you, that is if you've got the guts to do it!\n\nDeep in the Badlands is the Uldaman dig site.  We've heard a tale about some idiot paladin who died there recently.  Why we even care is that he had a very valuable necklace on him.  It's supposedly got three large gems: a ruby, a sapphire, and a topaz.\n\nThe shot: we want it, and we're payin' TOP SILVER to get it.  It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it.", objectives = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged.", progress = "Well, do you have the necklace?  You won't see a copper from us if you don't have that necklace!", completion = "Mmmm salvage!  I can smell the necklace from here.  Now let's look at that beauty...\n\nHey, what do you think you're trying to do here?  This necklace is missing the gems!  You think we wouldn't notice?  Even Malton could see that the gems are gone.\n\nWell, maybe you didn't steal them... but this necklace is worthless without those gems!  Your job isn't done here yet, not by a long shot!" }
WordHunterWoW_QuestEN[2284] = { title = "Necklace Recovery, Take 2", description = "As sure as Malton is a dummy, those gems are still in Uldaman somewhere.  You're going to have to go back there and look for them.\n\nLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace.  Find them and put them in the necklace.\n\nAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin.  If he's not been stripped clean already, then maybe he's got them on him still.", objectives = "Find a clue as to the gems' whereabouts in the depths of Uldaman.As sure as Malton is a dummy, those gems are still in Uldaman somewhere. You're going to have to go back there and look for them.\n\nLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace. Find them and put them in the necklace.\n\nAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin. If he's not been stripped clean already, then maybe he's got them on him still.", completion = "You seem to have found the remains of the paladin that Dran had mentioned from before.  Searching the remains uncovers what would appear to be his journal.  The book is in poor condition, as dried blood has stained most of the text in the book.  What you can read, however, is gibberish; it is written in the native tongue of the humans, to the best of your knowledge.\n\nYou will need the book translated if you are to glean any knowledge from it." }
WordHunterWoW_QuestEN[2298] = { title = "Kingly Shakedown", description = "So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.\n\nWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!\n\nMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"Upon completion of this quest you will gain:", objectives = "Travel to Stormwind and seek out Renzik \"The Shiv.\"So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.\n\nWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!\n\nMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2299] = { title = "To Hulfdan!", description = "Where have you been, <name>? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.\n\nGet to Ironforge as soon as possible and speak with Hulfdan!Upon completion of this quest you will gain:", objectives = "Travel to Ironforge and speak with Hulfdan Blackbeard.Where have you been, <name>? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.\n\nGet to Ironforge as soon as possible and speak with Hulfdan!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2300] = { title = "SI:7", description = "Renzik was looking for you, fish.\n\nI wouldn't keep Mathias's second in command waiting if I were you.Upon completion of this quest you will gain:", objectives = "Travel to Stormwind and seek out Renzik \"The Shiv.\"Renzik was looking for you, fish.\n\nI wouldn't keep Mathias's second in command waiting if I were you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2318] = { title = "Translating the Journal", description = "At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start.", objectives = "Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands.\n\nProvided item:", completion = "Mighty <class>, I know what you are doing out here in the Badlands.  I know you seek my gift of tongues.  You're after the parts to that necklace you found in Uldaman.\n\nSurprised?  Don't be - it's my job to know such things.  Instead, let's discuss what you're going to do for a translated journal.  Trust me - I'm the only one you'll find that can translate it.\n\nBetter still, let me make you a better offer than Dran Droffers is, and it'll let you still complete your deal with them.  Interested now, yes?" }
WordHunterWoW_QuestEN[2338] = { title = "Translating the Journal", description = "Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.\n\nIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?", objectives = "Let Jarkal borrow the necklace. In exchange, he will translate the journal for you.", progress = "You've thought about it, yes?  You're a smart <class> if you take this deal - you and I will get what we both want, and Droffers and Son Salvage will think they're getting what they want.", completion = "You know a good deal when you see one - I knew I could count on you.\n\nIt will be just a moment while I cast a spell to quickly translate the human tongue into a form you will understand.  I am a troll of my word; ask anyone in the Horde about Jarkal Mossmeld.  Now, let's get this started..." }
WordHunterWoW_QuestEN[2339] = { title = "Find the Gems and Power Source", description = "Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.\n\nLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.\n\nWhen you have everything collected, come back here!", objectives = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.", progress = "You've got another trip into the depths of Uldaman in store for yourself if you don't have the gems and a power source capable of channeling magical power back into the necklace.\n\nYou'll be getting the gems back to deliver to the goons in Orgrimmar; I will be keeping the power source, since it will be the thing that will make the necklace work in the first place...", completion = "Very well done, <class>.  Now the fruits of our redirection will pay themselves out handsomely.  I'm finished with the necklace itself, and I am confident I can duplicate the construction process consistently.\n\nBut first, I will use a specially prepared incantation to quickly analyze those gems before you take them and the necklace back to Orgrimmar.  This will take just a brief moment to do." }
WordHunterWoW_QuestEN[2340] = { title = "Deliver the Gems", description = "Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.\n\nI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.\n\nHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you.", objectives = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.", progress = "Well, look who it is!  Took your sweet time getting here, I see.  Let's hope this isn't a waste of my time!  You'll not get paid unless you have everything I asked for.  And trust me on this - we'll be double and triple checking everything!", completion = "Yep, it's all here.  Say, mind if we keep the bag too?  No?  Thanks, appreciate it!  Har!\n\nThis necklace will be our greatest haul yet!  Don't feel too bad though; I'm sure the necklace wouldn't fit you anyway.  Har again!\n\nA deal is a deal, so here's your fee for the salvage.  Our business is done here for now; check back later to see if we have more work.  Until then, beat it!" }
WordHunterWoW_QuestEN[2341] = { title = "Necklace Recovery, Take 3", description = "As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.", objectives = "Visit Jarkal Mossmeld in Kargath to see if he was successful.As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete. A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.", completion = "The power source you gave me exceeded every expectation I had for it.  I was able to make both you and me a necklace, and I have enough left over to make at least three more.  They will fetch quite the fee, with Droffers and Son Salvage none the wiser.\n\nHere you go, my friend.  I give you my thanks on a splendid job... and something quite special for your trouble." }
WordHunterWoW_QuestEN[2342] = { title = "Reclaimed Treasures", description = "Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.\n\nThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.\n\nReclaim my family's treasure and bring it to me!  Help me restore my birthright!", objectives = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.", progress = "The sweeping never ends... these bats are prolific in their mockery of me and my broom.  Please tell me you've reclaimed my family's treasure!  I've offered you my silver - is that not enough?!", completion = "At last - a broom worthy of a Garrett.  You're bloody well worth every silver I spent on you, I say!\n\nDo you hear me, foul bats?  I now wield the Garrett family weapon of choice!  Tremble, bats, tremble!!" }
WordHunterWoW_QuestEN[2358] = { title = "Horns of Nez'ra", description = "Many years ago, the Horns of Nez'ra were stolen from Ravenholdt manor. Across continents and oceans I have searched, only to discover that these insignificant beasts have had it in their possession all along.\n\nSlay every Blackrock orc you cross until the Horns of Nez'ra are recovered. Should you recover the horns, find me in Lakeshire.\n\nDo this for me and your name shall be known to Ravenholdt, <name>.", objectives = "Return the Horns of Nez'ra to Arantir in Lakeshire.", progress = "Do you have the demon prince's horns?", completion = "To deny Ravenholdt the artifact, would be to deny one's own existence. Well done, <class>. You may yet walk among the assassins of Ravenholdt.\n\nAs a young <class> adventuring in Darkshore, I discovered a tea that replenishes energy in combat. It has served me well throughout the years and now I pass on a taste of the thistle tea to you. Drink of it when you tire, <name>, and fight with vigor once more!" }
WordHunterWoW_QuestEN[2359] = { title = "Klaven's Tower", description = "I've been staking out this tower for weeks, <name>. Recently a major shipment came through from Duskwood, and along with it came those guards.\n\nWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.\n\nAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.\n\nGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias.You will receive:", objectives = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower." }
WordHunterWoW_QuestEN[2360] = { title = "Mathias and the Defias", description = "Not a moment too soon, <name>. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.\n\nIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.\n\nGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.\n\n...and <name>, should you be discovered, SI:7 will disavow all knowledge of your existence.Upon completion of this quest you will gain:", objectives = "Travel to Westfall and find Agent Kearnen for your debriefing.Not a moment too soon, <name>. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.\n\nIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.\n\nGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.\n\n...and <name>, should you be discovered, SI:7 will disavow all knowledge of your existence.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2361] = { title = "Restoring the Necklace", description = "", objectives = "I gladly give you this necklace, mighty <class>.  You have done me an invaluable service, and for that I thank you.  Wear it with pride, and make sure you mention loudly and repeatedly who made it for you!\n\nAlso, if you could toss in the fact that it really isn't cursed, that would be great.You will receive:" }
WordHunterWoW_QuestEN[2378] = { title = "Find the Shattered Hand", description = "You have served the Deathstalkers well, <name>, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.\n\nThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.Upon completion of this quest you will gain:", objectives = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.You have served the Deathstalkers well, <name>, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.\n\nThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2379] = { title = "Zando'zan", description = "Your determination alone is not enough to overcome the obstacles that lay ahead of us.\n\nSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.\n\nIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny.", objectives = "Speak with Zando'zan at the Cleft of Shadow.Your determination alone is not enough to overcome the obstacles that lay ahead of us.\n\nSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.\n\nIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny." }
WordHunterWoW_QuestEN[2380] = { title = "To Orgrimmar!", description = "A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.\n\nTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.Upon completion of this quest you will gain:", objectives = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.\n\nTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2381] = { title = "Plundering the Plunderers", description = "I don't mean to scare you, <name>, but the last five thieves I sent to steal the southsea treasure came back to me in pieces.\n\nSouth along the coast you'll find Tide Razor, the southsea freebooter's ship. Nestled in the hold is the payoff - the southsea treasure. On the second level of that ship is the pirate's den, a place where they train all of their thieves.\n\nBoard that ship, steal the treasure, and bring it back to me. Use the pirate's den if you need to practice your thievery, but be careful!You will receive:", objectives = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\n\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!" }
WordHunterWoW_QuestEN[2382] = { title = "Wrenix of Ratchet", description = "Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.\n\n<name>! Zando'zan has a task for <name>! <name> must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!Upon completion of this quest you will gain:", objectives = "Travel to Ratchet in the Barrens and speak with Wrenix the Wretched.Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.\n\n<name>! Zando'zan has a task for <name>! <name> must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2383] = { title = "Simple Parchment", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", objectives = "Read the Simple Parchment and speak to Frang in the Valley of Trials.", progress = "What's that you have there?  A parchment?  You're not a scholar, I hope...", completion = "Ah, that's my parchment.  I heard you'd be coming to the Valley, <name>.  I'm glad to see you made it--let's hope you survive the trials ahead." }
WordHunterWoW_QuestEN[2398] = { title = "The Lost Dwarves", description = "The dig site at Uldaman wasn't always overrun.  We Ironforge dwarves used to control the area, but... that was before the troggs came.  They came so fast and in such numbers that not even dwarven might could stop them!\n\nIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.\n\nMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up.  If he and his company live, then I want you to find them.", objectives = "Find Baelog in Uldaman.", completion = "It's about time you showed up!  I was in danger of losing a bet with Olaf!\n\nHe wagered that his beard would grow to his knees before he saw another living <race>.  Well here you are, and as you can see Olaf's beard has a few more inches to go.\n\nThanks, <name>.  I'll split the winnings with you." }
WordHunterWoW_QuestEN[2399] = { title = "The Sprouted Fronds", description = "", objectives = "The fronds Denalan planted within his garden have sprouted and grown.  They tremble, eager to be picked...." }
WordHunterWoW_QuestEN[2418] = { title = "Power Stones", description = "A while ago, I had an incident with the Shadowforge Dwarves.  They brought me to Angor Fortress to study two types of strange stones from Uldaman.  I discovered that the stones were sustained, stable power sources if treated correctly.  It's amazing the things one can find in that old dig site!\n\nAnyway, after I told them the secret of the stones they kicked me out of Angor Fortress and began digging for more in Uldaman.\n\nI want those stones for myself!  Bring me both types and I'll pay you plenty!", objectives = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.", progress = "Do you have the power stones, <name>?  I have a robotic rodent that needs a power supply...", completion = "That's great, you found some!  Thanks a lot, <name>.  You're the most dependable <race> I've met!\n\nI can't wait to try these on some devices I've been tinkering with.  I bet that, under the right circumstances, devices powered with these stones will keep going, and going, and going..." }
WordHunterWoW_QuestEN[2438] = { title = "The Emerald Dreamcatcher", description = "I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it.\n\nSadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there.\n\nPerhaps you would be willing to recover my dreamcatcher, {class}? ", objectives = "Retrieve the Emerald Dreamcatcher.", progress = "Please move swiftly. I can only hope that my emerald dreamcatcher has been unharmed by the furbolg.\n\nHave you recovered it yet, <name>?", completion = "My emerald dreamcatcher is of great importance to me. It is a gift only given to few. Thank you for returning it, <name>." }
WordHunterWoW_QuestEN[2439] = { title = "The Platinum Discs", description = "This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.\n\nAs for you, heroic <class>, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!\n\nReturn to me directly when you are ready; there is much more to do for the Explorers' League!", objectives = "Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.", progress = "Welcome to the Vault of Ironforge, <name>.  What may I do for you today?", completion = "As yes, a voucher from the Explorers' League... and quite the valuable one, might I add.\n\nThe Explorers' League lends me the authority to offer you a choice in your compensation directly from their vault.  You are to receive this item, and you may choose between five superior healing potions or five greater mana potions as your reward." }
WordHunterWoW_QuestEN[2440] = { title = "The Platinum Discs", description = "I shall focus my energies on these discs; they will reveal their true workings to me in due time.\n\nAs for you <name>, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.\n\nReturn to me soon, as I sense there is much more at hand for us to do regarding this find.", objectives = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.", progress = "Greetings, <class>!  Are you here for alchemy training, or perhaps something else?", completion = "Well <name>, you must have pleased Sage Truthseeker greatly for him to give you this item.  You are also to be granted a gift from his cache of potions; you may choose between 5 superior healing potions or 5 greater mana potions as your reward." }
WordHunterWoW_QuestEN[2458] = { title = "Deep Cover", description = "The Venture Company... Perhaps you have heard of them?\n\nFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.\n\nRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.\n\nWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand.You will receive:", objectives = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.\n\nProvided item:" }
WordHunterWoW_QuestEN[2459] = { title = "Ferocitas the Dream Eater", description = "The emerald... It is missing! My dreamcatcher has been damaged!\n\nThere is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater, has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him.\n\nFind this missing jewel, {name}. And, while you're there, clear out some of the corrupted mystics as well.", objectives = "Kill 7 Gnarlpine Mystics and find the missing jewel.", progress = "Ferocitas and the Gnarlpine mystics must return what is mine.  Please retrieve the emerald so that I may repair my emerald dreamcatcher.", completion = "Now I can repair my dreamcatcher.  Thank you, <name>." }
WordHunterWoW_QuestEN[2460] = { title = "The Shattered Salute", description = "As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.\n\nWatch, learn, repeat.Upon completion of this quest you will gain:", objectives = "Perform the Shattered Salute on Shenthul." }
WordHunterWoW_QuestEN[2478] = { title = "Mission: Possible But Not Probable", description = "You will need to steal the tower key from Foreman Silixiz, <name>. Once you've got the key in your possession, hold on to it - I may need it later.\n\nRemember, the poison has weakened everything in this tower. Use your abilities to bring chaos and destruction to its inhabitants. Slay them all -- show no mercy!\n\nOnce everything inside lays in a bloodied heap, pick Gallywix's lockbox and steal the cache of Zanzil's mixture held inside. Take both the head of Gallywix and the mixture to Shenthul in Orgrimmar.You will receive:", objectives = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\n\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction." }
WordHunterWoW_QuestEN[2479] = { title = "Hinott's Assistance", description = "Take a sample of the mixture to Serge Hinott in Tarren Mill.\n\nIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use.Upon completion of this quest you will gain:", objectives = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!" }
WordHunterWoW_QuestEN[2480] = { title = "Hinott's Assistance", description = "I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.\n\nSo, I am to cure you of this and then teach you how to make use of the poison?\n\nGive me a few moments to examine the toxin, <name>.You will receive:", objectives = "Wait for Serge Hinott to complete the cure." }
WordHunterWoW_QuestEN[2498] = { title = "Return to Denalan", description = "I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.\n\nMake haste, <name>; he needs our help.", objectives = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.\n\nMake haste, <name>; he needs our help.", completion = "Ah, so Rellian sent you to aid me. I am glad you arrived here so soon.\n\nI have discovered something quite disturbing!" }
WordHunterWoW_QuestEN[2499] = { title = "Oakenscowl", description = "I figured it out! I had to rush here to find you! It's so simple really... the corruption has spread from timberling to timberling, but there's but one that is the source.\n\nOakenscowl, he's being poisoned by the largest tumor I have ever seen... I would call it gargantuan, even.\n\nOakenscowl used to reside in a cave near my lake, but has since found his way to a nook to the northeast of here. {name}, Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home.", objectives = "Collect the Gargantuan Tumor from Oakenscowl.", progress = "Have you located Oakenscowl yet, <race>?", completion = "I knew you were more than capable of ridding the lake of that horrible beast.\n\nIt is a distressing situation; Oakenscowl was once a grand leader amongst his kind... but corruption does not discriminate between the lowly and the noble.\n\nThe size of this tumor is quite disturbing, but I must study it to learn more about the disease that upsets the timberling population.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[2500] = { title = "Badlands Reagent Run", description = "<class>, I would make use of your services.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.\n\nWell, what say ye?", objectives = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.", progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done <name>.  These should last me for a little while at least.  Here is your pay, as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?" }
WordHunterWoW_QuestEN[2501] = { title = "Badlands Reagent Run II", description = "You have been most helpful to me, <name>.  I would like to reward you with the very recipe for the brew I gave you earlier, but I must ask of you a favor that is quite dangerous.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be careful.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.", objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Ghak Healtouch in Thelsamar.", progress = "Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...", completion = "From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years!" }
WordHunterWoW_QuestEN[2518] = { title = "Tears of the Moon", description = "Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept at the nearby temple.\n\nBut of late, Sathrah has descended into madness. Her future generations are now threatened as well.\n\nFind Lady Sathrah, {name}, and end her suffering. She dwells northeast of here, near the river. Gather her silvery spinnerets and bring them back to me.", objectives = "Recover Lady Sathrah's Silvery Spinnerets.", progress = "I regret the task that I have asked you to carry out; but Lady Sathrah is beyond hope.\n\nIt is our hope to offer the sacrifice of the spinnerets to Elune. With this sacrifice, Elune will bless Sathrah so that she might be reborn, and at peace.", completion = "The forest mourns for Lady Sathrah, but it was something that had to be done. I hope now that she can rest in peace.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[2519] = { title = "The Temple of the Moon", description = "A once great creature of the forest is in need of help, <race>.\n\nThere is a difficult task that must be done.\n\nPlease seek out Priestess A'moora; she will explain things to you. Find her to the southeast of here, inside the Temple of the Moon.", objectives = "Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon.A once great creature of the forest is in need of help, <race>.\n\nThere is a difficult task that must be done.\n\nPlease seek out Priestess A'moora; she will explain things to you. Find her to the southeast of here, inside the Temple of the Moon.", completion = "So, Sister Aquinne sent you?" }
WordHunterWoW_QuestEN[2520] = { title = "Sathrah's Sacrifice", description = "Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest.\n\nInside this temple, find the central fountain. There is where you may leave the sacrifice.  The holy waters will purify and cleanse the corruption that drove Sathrah mad.\n\nWhen you have completed this, return to me.", objectives = "Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.", completion = "The loss of Lady Sathrah is distressing, but in this way only may she be reborn with a renewed spirit.\n\nMay Elune willingly accept the sacrifice that you have offered her." }
WordHunterWoW_QuestEN[2521] = { title = "To Serve Kum'isha", description = "<race>, can your miniscule brain comprehend the rarity of a flawless sphere of draenethyst? Draenei have spent lifetimes in search of just one of these crystals, only to meet horrible fates, their purpose unfulfilled.\n\nSo you stand before Kum'isha, knowing what Kum'isha has requested and still wish to assist? Very well, <race>... At any time during your travels across these lands, should you find a flawless sphere of draenethyst, return it to me and I shall reward you with riches beyond your wildest dreams.", objectives = "In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\n\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\n\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.", progress = "I have dedicated my life to the search of flawless draenethyst spheres. A lifetime, <race>!", completion = "Do my eyes deceive me? Impossible! Where did you... How...\n\nPerhaps now a rift can be opened, returning us to our homeland." }
WordHunterWoW_QuestEN[2522] = { title = "Kum'isha's Endeavors", description = "Even though the portal conjuration was a failure, I remain hopeful that my next attempt will be successful.\n\nThe hope of the Draenei is as fervent as your greed for trinkets, <race>. Go back out into these cursed lands and recover another flawless draenethyst sphere.\n\nOf course, the choice to take on this task is completely left to you *grin*.", objectives = "Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.", progress = "Have you found another flawless draenethyst sphere?", completion = "Simply amazing. I had doubted that you could find another sphere, yet here it is, pulsating in my hands.\n\nWell done, <name>!\n\nShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again." }
WordHunterWoW_QuestEN[2523] = { title = "Corrupted Songflower", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[2541] = { title = "The Sleeping Druid", description = "The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this.\n\nYou must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, {name}, bring one to me.", objectives = "Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den.", progress = "If I can examine the charm, I may be able to figure out how to break the enchantment. Have you found one?", completion = "Thank you, <name>.\n\nWhat an odd trinket this is... I can sense the vile aura emanating from it; this is a very powerful enchantment." }
WordHunterWoW_QuestEN[2561] = { title = "Druid of the Claw", description = "After examining this charm, {name}, I see now what must be done. Please take it, and do as I ask.\n\nYou are to approach the door to the nearby chamber. Inside, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.\n\nIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.", objectives = "Kill the soulless body of Oben Rageclaw, and then use the Voodoo Charm.", progress = "<name>, be wary when approaching my physical form; the enchantment it is under is quite powerful.", completion = "I am finally free of the control of the Gnarlpine. Thank you, <name>.\n\nMy spirit may now rest peacefully forever in the Emerald Dream.\n\nPerhaps one day we may meet again, young <class>. But, for now, please accept this reward as a symbol of my gratitude." }
WordHunterWoW_QuestEN[2581] = { title = "Snickerfang Jowls", description = "It is a well known fact that hyenas possess tremendous strength in their jowls, but the strength to snap through three inches of thorium steel? Impossible, improbable, and yet I have seen this demonstrated with my own eyes.\n\nVenture forth, into the Blasted Lands, and bring me three snickerfang jowls. As you search for the snickerfang, be on the lookout for boars and scorpoks: The initial assay also requires two blasted boar lungs and one scorpok pincer to complete.", objectives = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", progress = "You smell foul, <name>. Have you been traipsing in sulfur fields? And where are my components?!", completion = "How do you feel, <name>? You radiate with the aura of the snickerfang--your strength, unmatched by mortals!\n\nUnfortunately, with the components you brought to me, I could only make enough of the assay for one tablet. I will require more components, should you require another tablet." }
WordHunterWoW_QuestEN[2582] = { title = "Rage of Ages", description = "Ah, <name>, welcome back. It seems you enjoyed the effect of the robust, operational imbue, derived from snickerfang. Be warned, while the immediate effect is a titanic burst of strength, the long term effects on your spirit and intelligence could be hazardous.\n\nWith that said, do you require more? If so, bring me another three snickerfang jowls, two blasted boar lungs, and one scorpok pincer.", objectives = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", progress = "Do you have the beast organs?", completion = "There you go! Remember, use it sparingly. If you require another, come see me after you finish the one you currently have in your possession." }
WordHunterWoW_QuestEN[2583] = { title = "A Boar's Vitality", description = "Within these blasted lands exists two species of boar: the ash-mane boar and the helboar.\n\nIt would appear that the stamina of these beasts renders them nearly immune to harm, as the other animals find them too difficult to kill and consequently, not worth the effort.\n\nWe need to perform further analysis, <name>. Should you bring me three blasted boar lungs, two scorpok pincers, and one basilisk brain, I shall create a divine elixir from the residue of the assay. You will be my first test subject!", objectives = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", progress = "Where are the organs, <name>!?", completion = "The spirit of the boar illuminates your being, <name>! I wonder, do you believe yourself to be as invulnerable as these beasts?" }
WordHunterWoW_QuestEN[2584] = { title = "Spirit of the Boar", description = "When I first administered the elixir, <name>, I could tell that one or two applications would not satiate your appetite. Even now, I can see the hunger in your eyes. The concoction has addictive properties of which, seemingly, the most strong of will cannot resist.\n\nSo be it! Should you require more of the lung juice cocktail, venture back into the wasteland and find for me three blasted boar lungs, two scorpok pincers, and one basilisk brain.", objectives = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", progress = "Where are the organs, <name>!?", completion = "I must warn you, <name>, do not attempt to mix the formulas I have created. The chemical properties of the formula you most recently ingested will always take precedence over former enchantments; thus, rendering the other formulation null." }
WordHunterWoW_QuestEN[2585] = { title = "The Decisive Striker", description = "Have you ever watched them in battle, <name>? The scorpoks, I mean. Have you ever seen the grace and agility with which they move? The decisiveness of their strikes?\n\nIf only we could somehow isolate that agility and encapsulate it, we would be wealthy beyond our... I mean... it would be a boon for the scientific community.\n\nAssist me, <name>, and I shall allow you a sampling of the assay.\n\nIn order to create a stable sample, I will need three scorpok pincers, two vulture gizzards, and one blasted boar lung.", objectives = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", progress = "Where are the organs, <name>!?", completion = "Fascinating. This has been the most difficult of all assays to analyze.\n\nTake a pinch of this residual salt and place it under your tongue. You should experience a slight feeling of euphoria followed by a state of unprecedented agility and quickness." }
WordHunterWoW_QuestEN[2586] = { title = "Salt of the Scorpok", description = "You live! This is good news, indeed. I assume you are back for more of the scorpok assay?\n\nVery well, <name>, back to the wasteland with you and do not return until you have collected three scorpok pincers, two vulture gizzards, and one blasted boar lung.", objectives = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", progress = "Where are the organs, <name>!?", completion = "Fine work, <name>. Here is one sample of the assay for you and the remaining nine will be used in my research.\n\nAnytime you require more of the ground scorpok assay, return to me and we shall work out a deal." }
WordHunterWoW_QuestEN[2601] = { title = "The Basilisk's Bite", description = "These wastelands are riddled with redstone basilisk, <name>. These basilisk have adapted and flourished, more so than any of the other wildlife within the region.\n\nI have watched from afar as they hunt and go about their daily activities - the beasts exhibit a thought process more complex than even some humanoids.\n\nI must study their brains!\n\nRetrieve ten of their brains for me, <name>. The compound cannot be complete, however, without two vulture gizzards to form the base of the solution.", objectives = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", progress = "Have you returned with the requested organs?", completion = "This is wondrous, <name>! My offering to you is a taste of the inner workings of the redstone basilisk.\n\nShould the compound be to your liking, more can always be made... for a price." }
WordHunterWoW_QuestEN[2602] = { title = "Infallible Mind", description = "Your focused concentration has dwindled so soon? More research must be done!\n\nOh yes, the price remains the same, <name>. Venture forth into the blasted lands and return to me with ten brains from the redstone and two vulture gizzards.", objectives = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", progress = "Have you returned with the requested organs?", completion = "Yes, yes, give me a moment and more of the compound will be ready for your consumption, <name>.\n\nTake it... and <name>, do not attempt to consume these experimental concoctions in rapid succession. The results could be disastrous." }
WordHunterWoW_QuestEN[2603] = { title = "Vulture's Vigor", description = "Death does indeed have wings in these blasted lands, <race>. I have witnessed the black slayers and bonepickers feasting upon the corpse of many a fallen explorer - sometimes feeding upon the most vile and disease ridden of carcasses. It is a wonder, then, how their internal systems overcome the pestilence that claims these lands.\n\nAssist me in my studies, <name>! Gizzards I need! Two snickerfang jowls will also be required for the base of the concoction.\n\nYou shall be rewarded two-fold for your efforts.", objectives = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", progress = "Do not waste my time, <name>. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Most excellent! I shall get to work immediately. Perhaps a cure for many of the ailments of the world is to be found!\n\nAh yes, your reward - of course, should you require more of the gum, return to me and another task you shall be given." }
WordHunterWoW_QuestEN[2604] = { title = "Spiritual Domination", description = "I see that the inner fire has dwindled. Would you say the spiritual euphoria lasted an hour?\n\nIf it's more of the gizzard gum you desire, then more of the gizzards I require. Back to the wastelands, <name>. Do not return until you have recovered ten gizzards and two jowls.", objectives = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", progress = "Do not waste my time, <name>. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Perhaps one day I shall be able to isolate the active enzymes of this assay and produce a much more efficient resultant. Unfortunately, you will have to settle for what I am currently able to produce. Return to me should you require more gizzard gum." }
WordHunterWoW_QuestEN[2605] = { title = "The Thirsty Goblin", description = "I've got an idea, see. I've heard of some strange creatures called dew collectors that live to the southwest... and that they are able to store water in special glands.\n\nI think that if I could get one of these glands, I could create a drink that would quench my terrible thirst! Do you think you could help me, <name>?\n\nLook for the cactus garden, <name>; that's where you'll find the dew collectors.", objectives = "Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.", progress = "Please, tell me you found the dew collectors?", completion = "Oh, wonderful! Give it here -- let me drink it!" }
WordHunterWoW_QuestEN[2606] = { title = "In Good Taste", description = "Blech! This stuff tastes terrible! So much for that idea...\n\nWait, what's that? Oh, I know, I know, you think I shouldn't give up on this stuff. Well, okay then.\n\nUhhhh, I have an idea! Brilliant! Take this dew to my friend Sprinkle -- she's an excellent chef. Tell her what we're up to here and that we want to make it go down a little easier.\n\nI mean, if it's going to taste that bad, it at least should have some kick to it... And I'm just not feeling it...", objectives = "Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan.", progress = "So old Marin's up to it again, eh? What's this concoction made from?", completion = "Marin's a good guy, don't get me wrong -- just a little... eccentric, I'd say.\n\nAnd of course he needs my help, yet again." }
WordHunterWoW_QuestEN[2607] = { title = "The Touch of Zanzil", description = "It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, <name>.\n\nA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help.", objectives = "Speak with Doc Mixilpixil in the cellar of the Barracks.It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, <name>.\n\nA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help." }
WordHunterWoW_QuestEN[2608] = { title = "The Touch of Zanzil", description = "Oh my, you look like death. Correction - I've seen death, you look worse than death. You, <sir/miss>, would be what death coughed up at his last physical.\n\nHah! You hear that Noarm? Write that one down!\n\n*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, <name>.Upon completion of this quest you will gain:", objectives = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?" }
WordHunterWoW_QuestEN[2609] = { title = "The Touch of Zanzil", description = "It's unanimous, <name>. You've got the 'itis.'\n\nLuckily, I have a cure for the 'itis.'\n\nHere's what I need: One bundle of simple wildflowers, one leaded vial, one bronze tube, and last but certainly not least, one spool of light chartreuse silk thread. Ol' Emma left a spool of it for me at 'The Finest Thread.' You can find the shop along the canals.\n\nHurry along now, <name>, and try not to touch anyone until you're cured. Oh, and Dr. Montgomery says you need a shower -- his words, not mine.You will receive:", objectives = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young <fella/lady>." }
WordHunterWoW_QuestEN[2621] = { title = "The Disgraced One", description = "Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault.\n\nSo here I stand, awaiting orders. I must know. I must have those orders.\n\nDispatch Commander Ruag resides in Stonard. Find him and find out what became of the orders.", objectives = "Speak to Dispatch Commander Ruag at Stonard in Swamp of Sorrows.", completion = "Thrall's Grasp... The story is still fresh in my mind.\n\n<Commander Ruag shakes his head.>\n\nTerrible thing that happened to that regiment. The horde lost some of its best soldiers when that battalion was destroyed." }
WordHunterWoW_QuestEN[2622] = { title = "The Missing Orders", description = "The orders? What could you possibly want with the orders?\n\nWhat are you implying, <name>? Of course I relayed those orders! The soldiers I sent the orders with were ambushed and brutally beaten by murlocs. Only one survived, if you can call that surviving. He can hardly speak, cannot walk, and must be fed through a tube. If you want to know what happened to those orders, speak with Bengor. I'm sure he is around here somewhere... and, <name>, be mindful of what you stick your nose into - it may get bitten off.", objectives = "Speak to Bengor at Stonard in Swamp of Sorrows.", completion = "Swamp tal... talk.. talker..." }
WordHunterWoW_QuestEN[2623] = { title = "The Swamp Talker", description = "Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.\n\nMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....\n\n<Bengor passes out.>", objectives = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.", progress = "Awaiting orders.", completion = "It is worse than I imagined. Nineteen of my men could have been spared from the agony which they faced. If only I had not acted so irrationally.\n\nYou must help them, <name>! I am powerless to act." }
WordHunterWoW_QuestEN[2641] = { title = "Sprinkle's Secret Ingredient", description = "When I was a kid, my sister used to do all the cooking. It was horrible! I could barely stomach some of her concoctions -- until I found what I like to call my \"secret\" ingredient! Add it to anything, and... WOW! It tastes great!\n\nWhat is it, you ask? It's a mushroom called the Violet Tragan. If you want me to help you turn this horrid-tasting brew into something edible, head to the Hinterlands, and look for a small lake there.\n\nOh, and remember, the Violet Tragan can only be found underwater.", objectives = "Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.", progress = "Under the waters of that lake -- it's the only place where the Violet Tragan can be found.  Hope you're good at holding your breath!", completion = "That's the stuff, <name>!\n\nIt looks so good, I might just...  Haha, gotcha!" }
WordHunterWoW_QuestEN[2661] = { title = "Delivery for Marin", description = "Here's the Violet Powder, <name>. Take it to Marin and tell him he owes me a favor!", objectives = "Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan.", progress = "Oh, <name>, you're finally back.  What have you brought?", completion = "Violet Powder, eh? Let's give it a try -- it sure couldn't make it any worse, that's for sure!" }
WordHunterWoW_QuestEN[2662] = { title = "Noggenfogger Elixir", description = "Now, to mix this powder in with the dew.\n\nCome back and talk to me in a minute... after I have perfected the fabulous Noggenfogger Elixir!", objectives = "Marin Noggenfogger wants you to speak to him again after he creates his elixir.Now, to mix this powder in with the dew.\n\nCome back and talk to me in a minute... after I have perfected the fabulous Noggenfogger Elixir!", completion = "Drink this! It's absolutely wonderful!!!\n\nI knew I had it in me... Oh thanks again, <name> for your help, but please, stand a little to the side, will you? You're blocking my business! I'm going to make millions on the fabulous Noggenfogger Elixir, millions!\n\nWhat's that? Sprinkle says I owe her a favor? Oh, that Sprinkle, such a kidder!" }
WordHunterWoW_QuestEN[2681] = { title = "The Stones That Bind Us", description = "It will take more than you alone to overcome the forces of Razelikh and his subordinates.\n\nGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.\n\nFight hard and die with honor, <name>.", objectives = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.", completion = "You have done it, <name>! The poor, tortured souls can finally rest.\n\nOur work is not yet over, <name>. We have much to discuss and much more to accomplish." }
WordHunterWoW_QuestEN[2701] = { title = "Heroes of Old", description = "Please, take from this a relic of old. We no longer have a use for the item.\n\nMay it serve you well in your fight against the legion.", objectives = "Open the chest and claim your reward.", completion = "You are temporarily blinded by the sparkle and gleam." }
WordHunterWoW_QuestEN[2702] = { title = "Heroes of Old", description = "You have honored me with your nobility and heroism, <name>.\n\nYou have also honored them...", objectives = "Speak to Corporal Thund Splithoof.", completion = "Indeed, you have honored us all. Our thanks alone are not sufficient." }
WordHunterWoW_QuestEN[2721] = { title = "Kirith", description = "As one chapter of your adventure closes, another one begins, <name>.\n\nOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.\n\nAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.", objectives = "Find out what became of Lieutenant Kirith.As one chapter of your adventure closes, another one begins, <name>.\n\nOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.\n\nAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.", completion = "Trebor? Trebor sent you?" }
WordHunterWoW_QuestEN[2741] = { title = "The Super Egg-O-Matic", description = "", objectives = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", progress = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", completion = "You place the hippogryph egg into the machine. A series of beeps follows along with some strange mechanical sounds.\n\nIt appears that the Eggometer has weighed, measured, and packaged your egg. Now that's speedy service!" }
WordHunterWoW_QuestEN[2742] = { title = "Rin'ji is Trapped!", description = "Hey <race>!\n\nRin'ji lost axe and was captured! Please, help Rin'ji escape. Me know that <race> like you don't like Rin'ji's kind, but Rin'ji begs! Must get out of here!\n\nGot something for nice <race> if <he helps Rin'ji out of here/she helps Rin'ji out of here>...\n\nRin'ji is hiding something secret at the Overlook Cliffs.", objectives = "Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east.", completion = "This troll tablet must be the \"secret\" that Rin'ji was talking about.\n\nCovered with strange markings, you can not decipher what the tablet says." }
WordHunterWoW_QuestEN[2743] = { title = "The Cover of Darkness", description = "Let us not mince words, <race>; my time here is limited.\n\nYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.\n\n<Kirith grins.>\n\nYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.\n\nReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.", objectives = "Return to the Fallen Hero of the Horde with your findings.", completion = "The demon lord displays a cunning almost as calculated as his brutality, <name>." }
WordHunterWoW_QuestEN[2744] = { title = "The Demon Hunter", description = "The triad is protected by Razelikh.\n\nIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.\n\nThere is one who may be able to assist you further, <name>. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands.", objectives = "Speak with Loramus Thalipedes in Azshara.", completion = "I will help you. Although, I do not think you fully understand what you are up against." }
WordHunterWoW_QuestEN[2745] = { title = "Infiltrating the Castle", description = "Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.\n\nLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?\n\nYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this.", objectives = "Speak to Tyrion in Stormwind Castle.", completion = "What the...?! Don't sneak up on me like that! And keep your voice down! What in the name of the Shadow are you doing sneakin' up on me for? Can't you see I'm busy, you daft fool?\n\nWhat do you mean, what am I doing? I'm waiting for the next Dark Portal to open, what the heck do you think I'm doing? Speak your peace and be off with you... 'fore the guards notice the two of us hiding in the bushes together. I have a reputation to maintain." }
WordHunterWoW_QuestEN[2746] = { title = "Items of Some Consequence", description = "Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get <his/her> hands dirty, understand? Good.\n\nOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.\n\nBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples.", objectives = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.", progress = "I've been watching Lescovar for a couple weeks now. Trias has never trusted him, but we didn't suspect he was involved in anything to do with the Defias Brotherhood. We were following leads that tied him to the Twilight's Hammer. Either way, he's become more dangerous than this city can deal with, and that's where we come in.\n\nGet me those items and we can put my plan into effect.", completion = "These will do nicely, <name>. Great job.\n\nI have the rest of the gear I'll need in my pack... thank the Light I just got a tailor friend of mine to make me a silk bag. I was running out of room carrying all my gear around.\n\nBefore Spybot heads in, let's get the details set so you know what you have to do." }
WordHunterWoW_QuestEN[2747] = { title = "An Extraordinary Egg", description = "", objectives = "" }
WordHunterWoW_QuestEN[2748] = { title = "A Fine Egg", description = "", objectives = "A fine egg is one that will, in ideal conditions, hatch free of the evil effects of the Gordunni ogres' incantations.", progress = "A fine egg is one that will, in ideal conditions, hatch free of the evil effects of the Gordunni ogres' incantations.", completion = "Very good, <name>. I will be sending this egg to Darnassus where I hope it will soon hatch!\n\nPlease accept this as a symbol of my gratitude." }
WordHunterWoW_QuestEN[2749] = { title = "An Ordinary Egg", description = "", objectives = "Ordinary hippogryph eggs hatch about half the time. We do our best to nurture them and with a little luck, they will hatch.", progress = "Ordinary hippogryph eggs hatch about half the time. We do our best to nurture them and with a little luck, they will hatch.", completion = "So, you have found an ordinary egg, <name>? Please give it to me... And we can only hope for the best.\n\nI don't have much, but please accept this reward. If you ever find yourself in Feralas again, know that I am always here to take the eggs you find there." }
WordHunterWoW_QuestEN[2750] = { title = "A Bad Egg", description = "", objectives = "" }
WordHunterWoW_QuestEN[2751] = { title = "Barbaric Battlements", description = "Twenty generations of Omosh have held this hammer, {name}. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.\n\nI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!\n\nProve to Orokk you are capable, {name}. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.", objectives = "Bring two Patterned Bronze Bracers, two Bronze Greatswords, and two Sharp Claws to Orokk Omosh in Orgrimmar.", progress = "Bronze, <name>! More bronze!!", completion = "The bloodline will fade but perhaps the legend of Omosh will continue!\n\nYou have proven that you are a blacksmith, <name>. For the blacksmith the reward is the satisfaction of seeing their weapons and armors coated in the blood of their enemies!\n\nMay the breastplates you create for the generations ahead be drenched in the blood of your enemies!" }
WordHunterWoW_QuestEN[2752] = { title = "On Iron Pauldrons", description = "Orokk sees the eagerness in your eyes, {name}. Like a sponge you soak in the wisdom of the Omosh.\n\nThree lessons I shall teach!\n\nReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.", objectives = "Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar.", progress = "Show me your dedication, <race>.", completion = "You do Orokk proud, <name>. Read, learn of iron shoulders!" }
WordHunterWoW_QuestEN[2753] = { title = "Trampled Under Foot", description = "Only two more lessons Orokk will teach, {name}. Your muscles ache, I know, but continue on for the Omosh!\n\nBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!", objectives = "Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar.", progress = "Their skulls will crack under the pressure of your boots!", completion = "You remind Orokk of his grandfather, Chief Gorokk of Omosh! Read, learn of the iron boot." }
WordHunterWoW_QuestEN[2754] = { title = "Horns of Frenzy", description = "The final lesson Orokk teaches you, {name}. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.\n\nSee the fear in their eyes as you approach!\n", objectives = "Bring two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar.", progress = "Show the iron who is in charge, <name>!", completion = "Astounding! You have learned the way of the Omosh, <name>!" }
WordHunterWoW_QuestEN[2755] = { title = "Joys of Omosh", description = "Orokk is not crying, {name}. Soot is in eye.\n\n<Orokk wipes a tear away.>\n\nThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to {name}.\n\nLearn Omosh dance of joy and then you learn fist of iron!\n", objectives = "Watch and learn the Omosh Dance of Joy.", completion = "<Orokk pants.>\n\nIt has been a very long time since Orokk has done the Omosh dance of joy. Learn now, <name>!" }
WordHunterWoW_QuestEN[2756] = { title = "The Old Ways", description = "In the time of legends, Aturk would crush the skulls of his enemies and grind the bone into a fine powder for use in filament. Long gone are those days, <race>. The Warchief calls for peace among the clans. Old enemies are now only watched with weary eyes!\n\nUnbelievable, I know, but such is the will of Thrall.\n\nEnough lamenting! You are here to learn, and learn you will! Bring me four steel breastplates and four steel helms and you will gain a taste of war!", objectives = "Bring four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil in Orgrimmar.", progress = "Aturk, like time, waits for no one! Hurry up fool!", completion = "It seems you are but another complacent lemming of the Warchief, <name>. How disappointing.\n\nHow I long for a glorious death upon the battlefield. Instead, I am stuck here, by order of Thrall, to teach infants how to craft! Watch and learn, child!" }
WordHunterWoW_QuestEN[2757] = { title = "Booty Bay or Bust!", description = "Listen, kid, you're not gonna learn anything hanging around here.\n\nI know a guy who knows a guy. He hangs around the smithy in Booty Bay. If you show him this insignia, he'll tell you all about mithril.\n\nSo whadd'ya say? Leave this kid stuff to the babies in diapers, <name> -- it's time to move on.\n\nIf you're interested, his name's McGavan. Show him this trinket and he'll recognize your commitment.Upon completion of this quest you will gain:", objectives = "Speak with McGavan in Booty Bay." }
WordHunterWoW_QuestEN[2758] = { title = "The Origins of Smithing", description = "When I was about your age, a dwarf by the name of Galvan took me under his wing and trained me in the ways of the armorsmith. Before he left for Booty Bay, he made me promise to train all those with the desire and determination to advance in the craft of blacksmithing -- so here I am -- all these years later.\n\nSo, now it's time for you to learn a little something. Make me six golden scale bracers and you will learn where smithing comes from, <name>.You will receive:", objectives = "Bring six Golden Scale Bracers to Hank the Hammer in Stormwind." }
WordHunterWoW_QuestEN[2759] = { title = "In Search of Galvan", description = "Although Galvan left Booty Bay many years ago, members of the order still remain in town, hoping to one day find another worthy of Galvan's tutelage.\n\nTake this insignia and present it to McGavan in Booty Bay.\n\nIf you actually make it that far, he'll know that you are worthy. I have faith, <name>!Upon completion of this quest you will gain:", objectives = "Speak with McGavan in Booty Bay." }
WordHunterWoW_QuestEN[2760] = { title = "The Mithril Order", description = "Most of our recruits never make it to Booty Bay, <name>. The shine of the insignia is enough to trigger the loot lust in even the staunchest of blacksmiths. Fools they be, as the insignia is a drop in the bucket compared to the wealth of items you'll see!\n\nFind Galvan the Ancient and show him this pin. His residence is far to the north, between Zul Gurub and the Mosh'Ogg ogre mound.", objectives = "Speak with Galvan the Ancient in Stranglethorn Vale.", progress = "Hail! Come closer; show Galvan what you have.", completion = "Ah, many years it has been since one has been worthy of the Mithril Order's initiation. We will start now!" }
WordHunterWoW_QuestEN[2761] = { title = "Smelt On, Smelt Off", description = "Many blacksmiths believe that mining and smithing are separate, independent jobs; but can there be blacksmithing without mining? Ah ha -- it is an impossibility! The accomplished blacksmith must also be an accomplished miner.\n\nShow Galvan that you are capable, <name>. Bring me forty bars of iron and forty bars of mithril. For this, Galvan will teach you the ways of the ornate mithril pants!You will receive:", objectives = "Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn." }
WordHunterWoW_QuestEN[2762] = { title = "The Great Silver Deceiver", description = "It is said that truesilver is stronger and more durable than mithril. Galvan does not disagree with this assessment of the minerals, but contrary to its name, truesilver is not true! Mithril is a far nobler mineral! HAH! Regardless, for this lesson you will need to find the great silver deceiver, <name>.\n\nBring me forty bars of mithril and five bars of truesilver. In exchange, you will be taught the secret of ornate mithril gloves and more importantly, learn that truesilver is a liar!", objectives = "Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn.", progress = "After such mining, your muscles bulge and your body aches!", completion = "She's a cruel mistress, is she not, <name>? I'm speaking of truesilver, naturally. Aye, Galvan spent over a decade in the mountains of Alterac learning this lesson. Take this and learn from it all that you can!" }
WordHunterWoW_QuestEN[2763] = { title = "The Art of the Imbue", description = "The harvesting of precious gems is of utmost importance to our craft, <name>. Few gems are more precious than the citrine. The magical properties we imbue into our goods are amplified greatly by the presence of citrine.\n\nFor this lesson, we will fortify forty bars of mithril with four citrines. The result will be a better understanding of magical gemology and the knowledge to create ornate mithril shoulders.You will receive:", objectives = "Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn." }
WordHunterWoW_QuestEN[2764] = { title = "Galvan's Finest Pupil", description = "If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.\n\nThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!\n\nOh, Gadgetzan is in Tanaris, of course!", objectives = "Speak with Trenton Lighthammer in Gadgetzan.If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.\n\nThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!\n\nOh, Gadgetzan is in Tanaris, of course!", completion = "Galvan the Ancient sent you??\n\n<Trenton bows.>\n\nIt is a great honor to meet another of the master's pupils!" }
WordHunterWoW_QuestEN[2765] = { title = "Expert Blacksmith!", description = "When you first came to me, I knew that you would turn out to be one of my finest pupils! It was without hesitancy that you gave up a trinket of some power to McGavan. You did this only so that you could meet me. Such blind faith and devotion to the craft should be rewarded.\n\nYou have attained expertise over blacksmithing, <name>. Reap the rewards!You will receive:", objectives = "Claim your reward from Galvan the Ancient!" }
WordHunterWoW_QuestEN[2766] = { title = "Find OOX-22/FE!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", objectives = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-22/FE is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"" }
WordHunterWoW_QuestEN[2767] = { title = "Rescue OOX-22/FE!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the main road!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "Escort OOX-22/FE to safety, then report to Oglethorpe Obnoticus in Booty Bay.", completion = "Oh, YOU'RE the great savior of OOX-22/FE!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance <name>, my robots and I are in your debt!" }
WordHunterWoW_QuestEN[2768] = { title = "Divino-matic Rod", description = "Sergeant Bly stole from me!  He said he'd only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??\n\nFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west.  I bet you'll find him there.\n\nLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight.", objectives = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", progress = "Did you find Sergeant Bly?  Did you get my divino-matic rod?", completion = "You found it!  Well done, <name>!  Did you have to fight Bly for it?  I hope you knocked him and his band down good and hard!" }
WordHunterWoW_QuestEN[2769] = { title = "The Brassbolts Brothers", description = "Have you met the Brassbolts brothers?  They're over in the Shimmering Flats, in Kalimdor, racing their rocket car against the goblins.  They usually win which is no surprise--the goblin car blows up so much it barely ever crosses the finish line!\n\nBut even then, the Brassbolts brothers are always looking for new ways to make their car go faster, and Wizzle told me he needs a very rare component for his next experiment.\n\nHe probably needs help getting that part.  Speak to him and find out.", objectives = "Speak with Wizzle Brassbolts in the Shimmering Flats.", completion = "Ah, you want to help me?  Great!\n\nThere's a part I want for an experiment I'm working on, and I need a brave <class> like you to help me get it!" }
WordHunterWoW_QuestEN[2770] = { title = "Gahz'rilla", description = "Deep in Zul'Farrak, the sand troll city in Tanaris, there is a sacred pool.  From that pool the trolls summon a huge beast!  Gahz'rilla!  He's so fierce that even his scales crackle with energy.  It's that energy I want to harness for my car!\n\nBring me the electrified scale of Gahz'rilla!\n\nBut the summoning of Gahz'rilla is a well-kept secret of the trolls.  To face him, you must first wrest the secret from them.", objectives = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", progress = "Do you have the scale?  I can't wait to try different ways to harness its energy!", completion = "Wow, you got the scale!  Thanks, <name>.  I can't wait to get to work on this thing!\n\nSo you saw Gahz'rilla?  Was he as big as they say??" }
WordHunterWoW_QuestEN[2771] = { title = "A Good Head On Your Shoulders", description = "It seems as if master had this planned from the start. I was not taught to create the items which you learned to create and you were not taught the items which I learned to create.\n\nThe master is wise, <name>. We shall teach each other!\n\nShow me how to make a mithril coif and ornate mithril shoulders and I shall show you how to create an ornate mithril helm.Upon completion of this quest you will gain:", objectives = "Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer." }
WordHunterWoW_QuestEN[2772] = { title = "The World At Your Feet", description = "At last year's All-Valley Blacksmithing Championship, all those who watched saw my leg get swept from under me by a cowardly dog from the Venture Co. Foundry. What they didn't know, however, was the reason I was able to continue and ultimately win the tournament: That's right, ornate mithril boots!\n\nI will need to learn how to craft ornate mithril pants for this year's tournament, however, as a Venture Co. shredder is an entrant! Teach me the way of the pants and learn the way of the boot!Upon completion of this quest you will gain:", objectives = "Bring two Heavy Mithril Boots and one Ornate Mithril Pants to Trenton Lighthammer." }
WordHunterWoW_QuestEN[2773] = { title = "The Mithril Kid", description = "Around these parts I am known as the Mithril Kid. I supply ornate mithril to adventurers from around the world.\n\n<Trenton whispers.>\n\nLittle do they know that I do not know the technique to fashion ornate mithril gloves. Shhhh! This will be our little secret.\n\nTeach me the technique to create ornate mithril gloves, <name>, and in exchange, I will show you the resultant of the culmination of my training under Galvan: the ornate mithril breastplate.Upon completion of this quest you will gain:", objectives = "Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer." }
WordHunterWoW_QuestEN[2781] = { title = "WANTED: Caliph Scorpidsting", description = "WANTED: Caliph Scorpidsting!\n\nThe Gadgetzan Water Company of Gadgetzan, Tanaris will pay a high bounty for the head of Caliph Scorpidsting, leader of the Wastewander outlaws.  His crimes include:\n\n1.  Murdering Gadgetzan Water Co. employees!\n2.Stealing Gadgetzan Water Co. resources!\n3.Seizing Gadgetzan Water Co. property!\n\nBring proof of Caliph Scorpidsting's demise to Chief Engineer Bilgewhizzle for an immediate reward!", objectives = "Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.", progress = "Yes <class>, I am an official of the Gadgetzan Water Company.  What can I assist you with?", completion = "Finally - justice is served!  You have struck a mighty blow against those vile nomads!  With Scorpidsting's demise, this might be just the thing to finally push those squatters off of Gadgetzan's water wells!\n\nBy the authority of the Gadgetzan Water Company, I gladly award you with this bounty.  You've done a great service for us all." }
WordHunterWoW_QuestEN[2782] = { title = "Rin'ji's Secret", description = "The tablet is covered with Witherbark troll markings. Rin'ji's secret truly is a mystery... \n\nIt's possible that you might have something quite valuable on your hands here. On the other hand, quite the opposite is also possible. A Witherbark troll in distress would probably do anything to find his way out of trouble...", objectives = "Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity.", progress = "Well, now, what is this?", completion = "This tablet... Quite unusual... Where did you find this, <name>?" }
WordHunterWoW_QuestEN[2783] = { title = "Petty Squabbles", description = "We fight the wrong enemy, <name>.\n\nThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.\n\nDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.\n\nPut your differences aside, <name>, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands.", objectives = "Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp.We fight the wrong enemy, <name>.\n\nThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.\n\nDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.\n\nPut your differences aside, <name>, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands.", completion = "The Alliance wishes to assist?\n\nI thought to never see this day again. A day in which the Alliance fights side by side with the Horde against a common enemy.\n\nIt shall be... we will unite." }
WordHunterWoW_QuestEN[2784] = { title = "Fall From Grace", description = "Hear my story, <race>.", objectives = "Listen to the Fallen Hero of the Horde tell his story.", completion = "As a spirit, I am powerless, <name>. Assist me. Allow me to regain my honor." }
WordHunterWoW_QuestEN[2801] = { title = "A Tale of Sorrow", description = "Before we may continue, you must hear my story.", objectives = "Listen to the Fallen Hero of the Horde tell his story.", completion = "The time to act is now, <name>." }
WordHunterWoW_QuestEN[2821] = { title = "The Mark of Quality", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises.  Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides.  The Yeti are native to Feralas, with many found in Feral Scar Vale.  I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair to you, then we're in business.", objectives = "Bring 10 Thick Yeti Hides to Pratt McGrubben in Feathermoon Stronghold.", progress = "A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you'll get a good item!\n\nIf you can't seem to find yetis, I know where some might be.  Try looking just inland of the Forgotten Coast, around Feral Scar Vale.", completion = "Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!\n\nAnd now, please choose from what I am able to offer you for your service!" }
WordHunterWoW_QuestEN[2822] = { title = "The Mark of Quality", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found west of here in Feral Scar Vale.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", objectives = "Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.", progress = "Were you able to get a stack of ten thick yeti hides?  My leather goods are second to none, and I'll share a sampling with you should you have the hides.\n\nIf you can't seem to find yetis, I know where some might be.  Try looking west of here, just inland of the Forgotten Coast around the Feral Scar Vale.", completion = "Ah, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, <name>... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted." }
WordHunterWoW_QuestEN[2841] = { title = "Rig Wars", description = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, <name>!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, <name>. Then crack open that safe and bring back those blueprints!", objectives = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", progress = "I don't see any blueprints. Did you hide them somewhere on your body or are you just standing around here to irritate me?", completion = "I knew you could do it, <name>! Sovik on the other hand, he had his doubts.\n\n\n\nNow that we have the blueprints in our possession, it is only a matter of time before we figure out all of the gnomish innovations that went into the creation of the rig and make them goblin innovations for our new shredder models." }
WordHunterWoW_QuestEN[2842] = { title = "Chief Engineer Scooty", description = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, <name>. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!", objectives = "Speak with Scooty in Booty Bay.As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, <name>. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!", completion = "She's a beauty, isn't she? Pinnacle of goblin transport technology -- only exploded a dozen or so times.\n\nDon't worry, <name>, I've got her all fixed up. She won't blow up on you - and if she does, it'll be quick and painless." }
WordHunterWoW_QuestEN[2843] = { title = "Gnomer-gooooone!", description = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.", objectives = "Wait for Scooty to calibrate the Goblin Transponder.", completion = "All done! When you're ready, just step on the pad." }
WordHunterWoW_QuestEN[2844] = { title = "The Giant Guardian", description = "I am no good, <name>. I was 'spose to be watchin' over my little friend, Shay, and somehow, she got away from me. I'm not all that sure what happened, really, but last time I saw her, we was walkin' through the ruins just north of here.\n\nEverythin' was goin' fine, but then I turned around, and... she was gone.\n\nNow I jus can't quite figure out what I should do here. Got any ideas, <name>? I'm awful worried.\n\nHey, how 'bout you go look fer Shay? Yer legs can travel much faster 'n mine.", objectives = "Locate the lost night elf girl.I am no good, <name>. I was 'spose to be watchin' over my little friend, Shay, and somehow, she got away from me. I'm not all that sure what happened, really, but last time I saw her, we was walkin' through the ruins just north of here.\n\nEverythin' was goin' fine, but then I turned around, and... she was gone.\n\nNow I jus can't quite figure out what I should do here. Got any ideas, <name>? I'm awful worried.\n\nHey, how 'bout you go look fer Shay? Yer legs can travel much faster 'n mine.", completion = "Oh, I am so glad you found me! I must admit, I am a bit lost... But isn't this a beautiful place?" }
WordHunterWoW_QuestEN[2845] = { title = "Wandering Shay", description = "Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.\n\nThere is one thing that will always work to get my attention, though.\n\nInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back.", objectives = "Pick up Shay's Bell from the chest.\n\nEscort Shay Leafrunner to Rockbiter's camp.", progress = "I was gettin' worried 'bout ya! Thank you so much for bringin' Shay home, <name>.", completion = "What? You say dis bell will work when Shay runs off? Well, how 'bout that!\n\nSince you did so much fer me, here ya go, <name>." }
WordHunterWoW_QuestEN[2846] = { title = "Tiara of the Deep", description = "Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep.  And not only was it pretty--it held great power for those with the knowledge to use it.\n\nSo when word of the tiara reached the Hydromancer Velratha, she had to have it.  She sent agents to my home and they stole it while I was away.  The thieves!\n\nI want my tiara back!  Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her.  Return it to me and you'll earn my favor.", objectives = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", progress = "Do you have the tiara, <name>?  Has Velratha learned the price of crossing me?", completion = "Wonderful!  You found it!  And what's just as important--Velratha no longer has it!  Thank you, <name>.  I am forever in your debt!\n\nAnd if I sounded a little... mean before, pay it no mind.  You'll find me a much nicer person to those who haven't stolen from me." }
WordHunterWoW_QuestEN[2847] = { title = "Wild Leather Armor", description = "<name>, you're becoming quite skilled as a leatherworker!  I know some patterns you might be interested in... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  The armor made using it is second to none for people of your skill, guaranteed.\n\nI'll teach this to you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.Upon completion of this quest you will gain:", objectives = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold." }
WordHunterWoW_QuestEN[2848] = { title = "Wild Leather Shoulders", description = "Wild Leather shoulders support the wearer's frame extremely well, offering top notch protection of the upper arms and the shoulders themselves.  As with all Wild Leather armor, a potent but random benefit is applied to the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.You will receive:", objectives = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold." }
WordHunterWoW_QuestEN[2849] = { title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.You will receive:", objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold." }
WordHunterWoW_QuestEN[2850] = { title = "Wild Leather Helmet", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random enhancement to the frame of the helm.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, two Nightscape headbands, and a wildvine.  Complete this order and the pattern will be yours!You will receive:", objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold." }
WordHunterWoW_QuestEN[2851] = { title = "Wild Leather Boots", description = "You've learned quite a bit now, <name>; still, there is more for you to learn.  Next are Wild Leather boots, the cornerstone of any set.\n\nThese boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need an order of two Nightscape pants and two Nightscape boots filled.  I also will require two wildvines... not just one.  When you have all this, let me know.You will receive:", objectives = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold." }
WordHunterWoW_QuestEN[2852] = { title = "Wild Leather Leggings", description = "With the basics down, you are ready to master more complex fare, <name>.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor this pattern, I need an order of two Turtle Scale helms, two Turtle Scale bracers, and two wildvines filled.You will receive:", objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold." }
WordHunterWoW_QuestEN[2853] = { title = "Master of the Wild Leather", description = "Well <name>, you are the definition of diligence.  There is one pattern left for Wild Leather armor; you've mastered the others.  I won't require you to toil needlessly for the pattern.  You've earned it outright, and then some... but I cannot give it to you myself.  My teacher, the one who brought me into the craft, is the one who must reward you.\n\nTake this letter to Telonis; he teaches leatherworking in Darnassus.  Show him the letter, and let him acknowledge you as an equal, as I do.You will receive:", objectives = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus." }
WordHunterWoW_QuestEN[2854] = { title = "Wild Leather Armor", description = "<name>, your skill as a leatherworker precedes you.  I possess leatherworking lore you would be wise to acquire... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  Armor made using it is second to none for a crafter of your skill, guaranteed.\n\nI'll teach you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.", objectives = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.", progress = "We must be clear; you shall be apprenticed to me while you learn the art of Wild Leather armor.  Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making.  This knowledge, however, was not easy for me to acquire.\n\nThe initial cost to begin this process is ten pieces of thick leather.\n\nOnce that is done, we'll get to the work you need to do in order to obtain the patterns.", completion = "Well <name>, I'm glad to have you on board as my apprentice.  You've made a wise decision as a leatherworker; those who make use of leather armor will be clamoring to you once you learn how to master the art of Wild Leather.\n\nLet's get to work - where do you want to start?" }
WordHunterWoW_QuestEN[2855] = { title = "Wild Leather Shoulders", description = "Wild Leather shoulders support a wearer's frame extremely well, offering superior protection of the upper arms as well as the shoulders.  As with all Wild Leather armor, a random yet very potent enhancement is imbued within the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.You will receive:", objectives = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache." }
WordHunterWoW_QuestEN[2856] = { title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.You will receive:", objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache." }
WordHunterWoW_QuestEN[2857] = { title = "Wild Leather Helmet", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random magic imbuement to the helm's frame.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, 2 Nightscape headbands, and a wildvine.  Complete this lesson and the pattern will be yours!You will receive:", objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache." }
WordHunterWoW_QuestEN[2858] = { title = "Wild Leather Boots", description = "Your knowledge of Wild Leather armor grows, <name>; still, there is more for you to learn.\n\nWild Leather boots are the cornerstone of any set.  Such boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need two Nightscape pants and two Nightscape boots crafted.  I also will require two wildvines... not just one.  When you have these items, we will proceed.You will receive:", objectives = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache." }
WordHunterWoW_QuestEN[2859] = { title = "Wild Leather Leggings", description = "You are ready to master more complex lessons, <name>.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor you to gain this pattern, I need two Turtle Scale helms, two Turtle Scale bracers, and two wildvines.You will receive:", objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache." }
WordHunterWoW_QuestEN[2860] = { title = "Master of the Wild Leather", description = "<name>, you have learned all I am able to teach you.  There is, however, one remaining pattern for Wild Leather armor.  I will not require you to toil needlessly for this; you've earned it outright, and then some.  This pattern, however, is one that I cannot freely share with you.\n\nMy teacher, the one who brought me into the craft, is the one who must reward you.  Take this note to Una; she teaches leatherworking in Thunder Bluff.  Show her the letter, and let her acknowledge you as an equal, as I do.You will receive:", objectives = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff." }
WordHunterWoW_QuestEN[2861] = { title = "Tabetha's Task", description = "Rumor is that Tabetha, a mage colleague who lives deep in Dustwallow Marsh, has a bone to pick with a certain sand troll in Zul'Farrak.  If you speak with Tabetha she can tell you more.\n\nAnd bring some friends with you, <name>.  If Tabetha has you go to Zul'Farrak then you're not going to want to go alone.\n\nYou will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruin.", objectives = "Speak with Tabetha in Dustwallow Marsh.", completion = "That's right.  I do have a bone to pick with a troll.  A few bones.  All her bones!\n\nWant to help me?" }
WordHunterWoW_QuestEN[2862] = { title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", objectives = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh <name>?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, <name>.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past, our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, <name>, that might settle things once and for all against them..." }
WordHunterWoW_QuestEN[2863] = { title = "Alpha Strike", description = "The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!\n\nI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work <name>, or we'll remain at this impasse!", objectives = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.", completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, <name>.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup though, I want to find out what is causing it." }
WordHunterWoW_QuestEN[2864] = { title = "Tran'rek", description = "My cousin Tran'rek is in a tight spot.  He promised me a load of scarab shells weeks ago and he hasn't delivered.  He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.\n\nCan you speak to Tran'rek for me?  Let him know he needs to get that delivery together before I do something rash?\n\nGadgetzan is in northern Tanaris, in Kalimdor.", objectives = "Speak with Tran'rek in Gadgetzan.", completion = "Hello!\n\nOh, you spoke to my cousin Krazek?  How is he?  I hope Booty Bay is treating him well...\n\nScarab shells, you say?  Well... let me tell you a story..." }
WordHunterWoW_QuestEN[2865] = { title = "Scarab Shells", description = "The scarabs of Tanaris have very hard shells!  Hard enough to use as a building material for lots of things.  So many things!\n\nIn fact, those shells are so useful... the scarabs were hunted all to near extinction!\n\nI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are.  Promise?\n\nOk, the scarabs have a colony in Zul'Farrak.  I guess the trolls don't hunt them for their shells.\n\nBut you can!  Go to Zul'Farrak and get me uncracked shells!", objectives = "Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", progress = "Do you have the shells?  My cousin in Booty Bay is waiting for a load of them, and he's getting impatient!", completion = "Oh, great!  You got them!\n\nThanks, <name>.  You're a real lifesaver!" }
WordHunterWoW_QuestEN[2866] = { title = "The Ruins of Solarsal", description = "To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.\n\nVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.\n\nGo there, explore the ruins, and look for anything that stands out to you. Good luck, <name>.", objectives = "Explore the Ruins of Solarsal and investigate the presence of the naga there.", completion = "Examining the gazebo reveals some interesting and unusual things in contrast to the surrounding ruins.\n\nFirst, the gazebo is clearly a more recent construction than the other objects in the ruins.  Second, the gazebo has a small series of glyphs engraved into the sides of it; the glyphs repeat in their pattern, but it otherwise is unknown in origin and meaning.  Third, the stone of the gazebo itself is warm to the touch.\n\nThis certainly quantifies as \"standing out\" in the search of the ruins!" }
WordHunterWoW_QuestEN[2867] = { title = "Return to Feathermoon Stronghold", description = "With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here.", objectives = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.", completion = "Welcome back, <name>.  Your report on this gazebo is most... disturbing.  It would seem that even if the naga there were not planning on an attack, their continued presence bodes ill for our push into Feralas.  At any rate, here is compensation for your investigation.\n\nIt would seem that Feathermoon Stronghold is in dire need of additional assistance concerning the Hatecrest naga.  I'd like to offer you the task, if you are so inclined.  There is much to do." }
WordHunterWoW_QuestEN[2869] = { title = "Against the Hatecrest", description = "The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.\n\nBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our advantage.", objectives = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.", progress = "<name>, if you're here to verify the task given to you, then excellent - it is ten Hatecrest scales I seek.  If you are here for chit-chat, then I am currently unavailable for such trivialities.\n\nKnow this - we night elves are not warmongers.  Our race is dedicated to the preservation of peace and harmony.  This does not mean, however, that we will not proactively protect our own interests.  This is my duty to General Feathermoon, and to the stronghold.", completion = "Yes, yes, these scales are more than satisfactory.  Actually, I think I will send these down to Pratt for him to take a look at.  Maybe he can craft something useful out of them.\n\nAs for you, I have another mission I want to send you on.  But first, here is your bounty for the scales.  Your continued service to the General and Feathermoon Stronghold at large is a blessing in the face of adversity." }
WordHunterWoW_QuestEN[2870] = { title = "Against Lord Shalzaru", description = "<name>, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.\n\nSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.\n\nPut a stop to it by putting a stop to him, and bring me his relic so we can study it.", objectives = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.", progress = "Bringing down Lord Shalzaru would certainly set their plans back weeks, if not months.  On top of that, the relic he uncovered is of definite interest to us.\n\nHave you performed the mission given to you, <name>?", completion = "Well played, <name>! Lord Shalzaru's demise will throw the naga into disarray for some time, if not permanently.  The threat they pose is now under more of our control than it has ever been, and we have you to thank for it.\n\nHere is more bounty money from the stronghold treasury - you've earned every copper.  You and yours are welcome in Feathermoon Stronghold anytime, my friend.\n\nOne more thing before you depart, <name>... if you could..." }
WordHunterWoW_QuestEN[2871] = { title = "Delivering the Relic", description = "If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!\n\nShe's just around the bend, no doubt studying.  Thanks, <name>.", objectives = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.", progress = "Yes, may I assist you?\n\nHold on, you're the <class> that has been helping General Feathermoon and Latro out with the naga threat, yes?  I'm Vestia, Latro's - erm, rather, Latronicus' wife.  It is a pleasure to meet you!\n\nI'm sorry, you're here on business, of course.  Do you have something for me - from him, perchance?", completion = "Interesting... this came from the Ruins of Solarsal, you say?  Well, Latro's right that I need to look at this.  At first glance, it seems non-indigenous to the ruins.  Then again, this isn't of naga design... not something as alien as this.\n\nIt is going to take some time to research this item.  Once my research on it is done, maybe I will make use of your talents, should you be around.\n\nHere, take one of these extra items we have; I hope you'll find some use for it!" }
WordHunterWoW_QuestEN[2872] = { title = "Stoley's Debt", description = "My old buddy Stoley owes me a very special bottle of rum.  He tends the bar at Steamwheedle Port in Tanaris, Kalimdor,  and he promised me that the rum there is stronger than anything we can find in Booty Bay.  He's so confident that he says if I try that rum and don't agree with him, then he'll double the money he owes me!\n\nWell, I think he's not as confident as he was when last we spoke, and now he's afraid to give me that rum.  But I don't back down from wagers, so why don't you talk to him for me...", objectives = "Speak with Stoley in Steamwheedle Port.", completion = "Ah, so you've been speaking with MacKinley, have you?\n\nIt's not what he thinks!  I'm not afraid to give him some Steamwheedle Bilge Rum...\n\nI just don't have any rum to give him!" }
WordHunterWoW_QuestEN[2873] = { title = "Stoley's Shipment", description = "I owe \"Sea Wolf\" MacKinley in Booty Bay some rum, to settle a bet, but I'm all out of rum!  Captain Cuergo stole my last shipment, and he has it stowed in that walled pirate town to the south.\n\nIf you can find my shipment of rum and return it to me, then I can prove to MacKinley that Kalimdor's booze beats the dirt out of Booty Bay!", objectives = "Bring Stoley's Shipment to Stoley in Steamwheedle Port.", progress = "Did you find my shipment of rum, <name>?", completion = "Great, thanks for the shipment!  Now MacKinley and I can finally settle our wager." }
WordHunterWoW_QuestEN[2874] = { title = "Deliver to MacKinley", description = "Thanks again for your help, <name>.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze.", objectives = "Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay.", progress = "Did Stoley cough up my booze?", completion = "Hm, let's try this...\n\nI can't believe it!  This stuff is... terrible!  That's great!\n\nWell I guess Stoley can keep the money he owes me.  He's true to his word about Steamwheedle bilge rum.  That stuff is as thick as gravel and burns like lava!" }
WordHunterWoW_QuestEN[2875] = { title = "WANTED: Andre Firebeard", description = "The vile pirate Andre Firebeard is wanted for crimes against Steamwheedle and Gadgetzan.\n\nBy decree of governing counsel, any who read this are hereby authorized to use lethal force during the apprehension of Andre and his abettors.\n\nBy further decree, should Andre be deceased, or otherwise indisposed, during the time of his hearing, his head may act as proxy, and deliverance of such head to Security Chief Bilgewhizzle constitutes a binding, and tenderable, contract.", objectives = "Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port.", progress = "You look a little dazed.  Have you been reading our legal documents?", completion = "Ah, Andre's head.  So I guess he'll make his trial after all!\n\nMuch appreciated, <name>.  Now if you'll just sign here, I can issue you payment for services rendered.\n\nDon't worry about the small print.  It's harmless, and... I don't think there's a magnifying glass small enough to read it anyway." }
WordHunterWoW_QuestEN[2876] = { title = "Ship Schedules", description = "This scroll contains the schedules of shipments between Steamwheedle Port and Booty Bay. Both past and future shipments are included, along with ship names, with large 'X's next to some ships' journeys, and annotations like \"GREAT LOOT\" and \"HARD FIGHT\" next to others.\n\nSomeone at Steamwheedle Port would want to see this document.", objectives = "Report the Ship Schedules to an authority in Steamwheedle Port.", progress = "You look out of breath.  You have something to tell me?", completion = "Oh my, this looks to be a list of ship departures and arrivals, with accurate dates and times and everything!  If the captain of a pirate ship got his hands on this, he could have himself a field day!\n\nYou say you got this from a pirate?  Well that's disturbing news...\n\nThank you, <name>.  I'm glad you took it from him, and I'm glad that pirate's eating dirt right now!" }
WordHunterWoW_QuestEN[2877] = { title = "Skulk Rock Clean-up", description = "We Wildhammers remember the past, more than our brothers in Ironforge.  If you want to make friends here, then you get your hands dirty for us!\n\nThe Horde abandoned their positions in the Hinterlands around Skulk Rock; it's now overrun with nasty sludges and oozes.  We've got plans on that area, but first we need a clean-up crew to make a hole for us.\n\nThat's where you come in, Sunshine!  Head down there and take out ten green sludges and ten jade oozes, then report back to me here.  Move out!", objectives = "Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak.", completion = "Well look at you, helping out the Wildhammers!  You're a <class> of action, and action is what we respect around here.\n\nYour little clean-up mission is a lot more important than you might think it is.  With folks thinning out the oozes and sludges, we'll be able to extend our sphere of influence in no time. Here - have a little something in addition to just making new friends here in Aerie Peak!" }
WordHunterWoW_QuestEN[2878] = { title = "Corrupted Songflower", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[2879] = { title = "The Stave of Equinex", description = "This stave might be the Stave of Equinex! The Stave of Equinex is actually a key, used to unlock the Equinex Monolith in the Ruins of Ravenwind, on the mainland west of the Dream Bough.\n\nFind the four flames that still burn in those ruins: Samha, Imbel, Byltan, and Lahassa. Retrieve their essence and then while standing by the Equinex Monolith, use the essences to energize the stave. If this is truly is the Stave of Equinex, you will be able to unlock the Monolith and gather a sacred artifact from it.", objectives = "Energize Troyas' Stave and find the Equinex Monolith.", progress = "The Equinex Monolith stands silently among the ruins. What could it be holding?", completion = "Holding the energized stave is almost impossible. Its power rumbles through your body.\n\nYou reach out to the cold surface of the Equinex Monolith...\n\nA small door opens, allowing you to reach in and take the artifact inside.\n\nBeams of light fill the area around the Equinex Monolith." }
WordHunterWoW_QuestEN[2880] = { title = "Troll Necklace Bounty", description = "Get this straight, <race> - we are NOT part of the Alliance!  The Wildhammers are independent, relying on deeds and actions to prove one's worth, rather than the blather of those who use jibber-jabber to bolster their do-nothing attitudes!\n\nIf you're looking for friends here, then prove your worth to us first!  The foul trolls that choke the hillsides of the Hinterlands sometimes carry tribal necklaces.  Bring five of them to me, and we'll mark it down as a step in the right direction for you.", objectives = "Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak.", progress = "I want five of those tribal necklaces the trolls carry on them.  If you need it spelled out further, then killing one of them stands you a good chance of getting one!\n\nProve your worth to the Wildhammers!", completion = "Now that's what I am talking about!  See - these necklaces prove that you're willing to get your hands dirty.  We Wildhammers value that in those we associate with.\n\nYou keep this up, and you'll be in our good graces yet." }
WordHunterWoW_QuestEN[2881] = { title = "Troll Necklace Bounty", description = "", objectives = "" }
WordHunterWoW_QuestEN[2882] = { title = "Cuergo's Gold", description = "This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...\n\n\nSouth of Wheedle\nSouth of home\nFind a mast and flag and bones\nDig you there, if you be bold\nDig and claim Cuergo's gold!\nA key you'll need and a key you'll see\nThe men you face take blood as fee.", objectives = "Find Cuergo's gold!", progress = "This chest is locked!", completion = "Captain Cuergo's hidden treasure awaits!" }
WordHunterWoW_QuestEN[2902] = { title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.", objectives = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs..." }
WordHunterWoW_QuestEN[2903] = { title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", objectives = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", progress = "Welcome back <name> - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is." }
WordHunterWoW_QuestEN[2904] = { title = "A Fine Mess", description = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, <name>!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!", objectives = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", completion = "I suppose you should be rewarded for bringing Kernobee back to us in one piece, <name>. If you go back to Gnomeregan, these might give you the edge you'll need in defeating that good-for-nothing backstabber, Mekgineer Thermaplugg." }
WordHunterWoW_QuestEN[2922] = { title = "Save Techbot's Brain!", description = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!\n\nBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.", objectives = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.", progress = "Did you find Techbot?  Did you retrieve its memory core??", completion = "Oh, this is wonderful!  Thank you, <name>!  I'll get to work immediately!!\n\nPoor, poor Techbot... Don't feel bad.  We'll get you fixed.\n\nNow, where did I put that plug for my hydro-jack swivel spanner..." }
WordHunterWoW_QuestEN[2923] = { title = "Tinkmaster Overspark", description = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad.  But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help.", objectives = "Speak with Tinkmaster Overspark in Ironforge.Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot. I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad. But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge. He would welcome your help.", completion = "Yes it's true.  Techbot has gone rogue!  Please, can you help me?" }
WordHunterWoW_QuestEN[2924] = { title = "Essential Artificials", description = "A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan.  But during the frantic exodus from our city, no one remembered to take any of these devices with them!  And I need a large supply of them for work I will soon undertake.\n\nPlease, go into Gnomeregan and get me some essential artificials.  You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.\n\nThank you, <name>, and please hurry!", objectives = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.", progress = "Do you have the essential artificials?", completion = "You got them!  Now I can begin my new experiments!\n\nI can't thank you enough, <name>!  Your bravery has advanced gnomish research by a leap and a bound!" }
WordHunterWoW_QuestEN[2925] = { title = "Klockmort's Essentials", description = "A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.", objectives = "Speak with Klockmort Spannerspan in Ironforge.A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge. He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend. If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.", completion = "I do!  I do need help with a mission into Gnomeregan.  And you're just the <class> to do it!" }
WordHunterWoW_QuestEN[2926] = { title = "Gnogaine", description = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, <name>.\n\nLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!", objectives = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", progress = "Can't you see we're trying to cure an entire species of gnomes here??! We need more of the green glow!", completion = "Excellent work! The time has come to test the new formula. If this works, not only should that captured leper gnome be cured, but I should have a full head of hair! Stand back!" }
WordHunterWoW_QuestEN[2927] = { title = "The Day After", description = "You don't think I was always bald, do you? No <sir/ma'am>! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.\n\n<Gnoarn shakes his fist in the air.>\n\nDamn those damned dirty troggs - damn them all!!\n\nPerhaps it's not too late, <name>. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution.", objectives = "Speak with Ozzie Togglevolt at Kharanos in Dun Morogh.You don't think I was always bald, do you? No <sir/ma'am>! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.\n\n<Gnoarn shakes his fist in the air.>\n\nDamn those damned dirty troggs - damn them all!!\n\nPerhaps it's not too late, <name>. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution.", completion = "I thought the loss of that outstanding head of hair would have been the end of him for sure, but he survived!\n\nI was standing right next to him when he was hit by the radiation bolt. Those delightful brown locks of hair hit the floor in clumps! Clusters! The horror of it all was only compounded when Gnoarn completely freaked out! Oh yes, freaked out I say! Gnoarn touched his bald head in disbelief, the look in his eyes screamed revenge, <name>! Then he turned his anger towards the troggs!" }
WordHunterWoW_QuestEN[2928] = { title = "Gyrodrillmatic Excavationators", description = "It's terrible, <name>. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.\n\nWhat we need are spare parts, <name>. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.\n\nWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.", objectives = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.", progress = "If this were a race, you would have lost by now.", completion = "This will do nicely, <name>. One gyrodrillmatic excavationator fixed; 398 left to go." }
WordHunterWoW_QuestEN[2929] = { title = "The Grand Betrayal", description = "I trusted Thermaplugg, <race>. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....\n\nWe will retake Gnomeregan, <name>. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.", objectives = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.", completion = "I like to think that the last thing that went through his head as he collapsed to the ground was your foot, <race>. With Thermaplugg dead, our plans to retake Gnomeregan are one step closer to becoming a reality." }
WordHunterWoW_QuestEN[2930] = { title = "Data Rescue", description = "When we fled Gnomeregan, we left so much data behind!  Vitally important data!\n\nI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan.  You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C.  And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.\n\nIt's a catastrophe!  Can you help?", objectives = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.", progress = "Do you have the prismatic punch card??", completion = "You did it!  You found the prismatic punch card and recovered the lost data!  Vitally, critically, immeasurably important data that we could not live another moment without!\n\nYour service to the gnomes will be long remembered, <name>." }
WordHunterWoW_QuestEN[2931] = { title = "Castpipe's Task", description = "Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.\n\nCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!\n\nThose are good odds!", objectives = "Speak with Master Mechanic Castpipe in Ironforge.Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.\n\nCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!\n\nThose are good odds!", completion = "I'm organizing data extraction missions into Gnomeregan.  If you're here for that, then listen up!" }
WordHunterWoW_QuestEN[2932] = { title = "Grim Message", description = "The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!\n\nHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.\n\nWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.\n\nShow them their vile actions are of consequence!", objectives = "Gather Witherbark Skulls and place on Nimboya's Pike. Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn.", completion = "Word reached me of your deed.  A grim deed, but one of honor.  Let us hope the Witherbarks heed your message." }
WordHunterWoW_QuestEN[2933] = { title = "Venom Bottles", description = "These bottles hold a vile, green venom.\n\nConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample.", objectives = "Bring a Venom Bottle to an apothecary in Tarren Mill.", progress = "Hello, gentle <class>.  The day has been long and not a single experiment successful...I hope you bring good news to me.", completion = "Ah, and what is this?  It appears to be venom... from some arachnoid creature I deem.  And where did you get it?" }
WordHunterWoW_QuestEN[2934] = { title = "Undamaged Venom Sac", description = "I must have a fresh sample of the venom you brought me.  The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me.  You will find many spiders near the troll city of Shadra'Alor.\n\nDo not tarry, <name>, for the venom sac must be fresh when you deliver it.", objectives = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill.", progress = "Do you have the undamaged venom sac, <name>?  I yearn to run experiments with its fresh venom, and have ordered a collection of small, terribly cute animals on which to test it!", completion = "Oh, splendid!  The venom is quite fresh and I'm sure very deadly.  Thank you!" }
WordHunterWoW_QuestEN[2935] = { title = "Consult Master Gadrin", description = "The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.\n\nI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom.", objectives = "Speak with Master Gadrin in Sen'jin Village.The venom from the broodguards wasn't as potent as the venom you brought originally. It must have come from a different spider.\n\nI want a fresh sample of that venom. To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village. Travel to Durotar and speak with Gadrin. With luck, he'll know where the Witherbarks get their venom.", completion = "Ah, so you want fresh venom from the spider of the witherbarks, yes?  Well, sit down... you're not going to like what I have to tell you." }
WordHunterWoW_QuestEN[2936] = { title = "The Spider God", description = "The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!\n\nTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.\n\nDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me.", objectives = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.", completion = "Ah, Elortha no Shadra... speak this name only in whispers, for its utterance carries much weight in the realms of the spirit.\n\nI will put it to parchment and create for you a spell of summoning..." }
WordHunterWoW_QuestEN[2937] = { title = "Summoning Shadra", description = "Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god.", objectives = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill.", progress = "Did you get the venom?", completion = "Sweet, you got it!" }
WordHunterWoW_QuestEN[2938] = { title = "Venom to the Undercity", description = "The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!\n\nI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himself.", objectives = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.", progress = "Word was sent of your coming, <name>.  You have a parcel for me?", completion = "Ah, very good.  Lydon mentioned the poison in this parcel is the most potent he has come in contact with, and is busy working on new applications with it.\n\nWith luck, we will find many.\n\nThank you, <name>.  Your service to the Royal Apothecary Society is undeniable." }
WordHunterWoW_QuestEN[2939] = { title = "In Search of Knowledge", description = "While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.\n\nSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.\n\nI have a colleague in Darnassus that may be able to tell us what this is, <name>. Why don't you go talk to her and see if she can help us?", objectives = "Talk to Daryn Lightwind in Rut'theran Village.While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.\n\nSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.\n\nI have a colleague in Darnassus that may be able to tell us what this is, <name>. Why don't you go talk to her and see if she can help us?", completion = "Oh, so Troyas Moonbreeze sent you?\n\n<mutters>...always bothering me with his wild notions that he found something important...\n\nLook, <name>, I'll be blunt. Troyas always thinks he has found something important in those ruins. The truth is, anything that was truly valuable was probably hoarded away long ago by the ogres or the harpies that now reside there.\n\nYou're welcome to take a look around, but I don't know if you'll find any books here that will help you." }
WordHunterWoW_QuestEN[2940] = { title = "Feralas: A History", description = "This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.\n\nYou pick it up, but realize you should probably ask before borrowing it.", objectives = "Ask Daryn Lightwind if you may borrow her book.This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.\n\nYou pick it up, but realize you should probably ask before borrowing it.", completion = "So, you'd like to borrow Feralas: A History?\n\nLet me think...\n\nI will allow you to borrow this book, <name>, but only if you do something for me first." }
WordHunterWoW_QuestEN[2941] = { title = "The Borrower", description = "I have studied many subjects in my time, and my latest fascination is with the snapjaw that occupy the beach in the Hinterlands. There's one in particular I'd like to see, a giant snapjaw named Gammerita. I'd like to go myself, but my research keeps me here. I think a picture of her would be the next best thing.\n\nTake this letter to Curgle Cranklehop in Tanaris. She has created an invention for me that can capture a picture. She called it a \"snapshot,\" I think...", objectives = "Take the letter to Curgle Cranklehop in Tanaris.", progress = "A letter -- for me?", completion = "Are you another one of Daryn's interns? She's quite a knowledgeable historian, <name>. You should be grateful to be studying under her leadership.\n\nNow, let me get the Super Snapper FX. You're gonna love it!" }
WordHunterWoW_QuestEN[2942] = { title = "The Morrow Stone", description = "The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade.", objectives = "Return the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze in Feathermoon Stronghold.", progress = "I am glad you have returned, <name>. I am eager to hear of your findings.", completion = "I have been reading since you left, <name>. This stone you have found is called the Morrow Stone. While I am not entirely sure what its purpose is yet, you can be sure that it is something of great significance to be hidden away inside the Equinex Monolith the way it was.\n\nI will continue my studies, and I hope I will be able to count on you in the future, <name>. Thank you for all your help." }
WordHunterWoW_QuestEN[2943] = { title = "Return to Troyas", description = "Here it is, <name>. Please, take care of my book.\n\nNow, hurry along. I'm sure Troyas is eager for your return.", objectives = "Deliver the book to Troyas Moonbreeze in Feathermoon Stronghold.", progress = "Hello, <name>. Have you been to Darnassus?", completion = "You have brought a book along. Excellent!" }
WordHunterWoW_QuestEN[2944] = { title = "The Super Snapper FX", description = "Have the first look at my new invention, <name>. All you need to do is target whatever it is you'd like to take a picture of, and push the button.\n\nWhat was that creature from the Hinterlands that you mentioned? Gammerita? Well, good luck finding her. I'm sure Daryn will be quite pleased with the snapshot you return to her.\n\nIn any case, here's the Super Snapper. Have fun!", objectives = "Use the Super Snapper FX to take a snapshot of Gammerita, then return to Daryn Lightwind in Rut'theran Village.", progress = "So, you have finally returned, <name>. And you've brought the contraption that Curgle built for me -- perfect.", completion = "Well! Curgle's invention lived up to its expectations.\n\nDon't get too excited, but do know that I am pleased with your work, <name>.\n\nNow, where did I leave that book..." }
WordHunterWoW_QuestEN[2945] = { title = "Grime-Encrusted Ring", description = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.", objectives = "Figure out a way to remove the grime from the Grime-Encrusted Ring.", progress = "The gnomish contraption before you bears a plaque calling it \"The Sparklematic 5200\".  The gist of the machine, from reading the instructions below the plaque, is to scrub away dirt that an item might have.  The machine has a coin slot, accepting three silver coins to start the process once the item is placed inside it.\n\nIt would seem as though the grime-encrusted ring you found earlier is just the thing to try in this machine!", completion = "You place the ring inside the Sparklematic 5200 and deposit a silver coin into the slot.\n\nPainful grinding noises emanate from the machine as it begins to jerk around violently.  One can only guess what is happening with the ring inside the machine...\n\nThe machine suddenly stops, trumpeting its cessation with a simple \"Ding!\"  The item receptacle opens up to reveal a small box that is neatly wrapped with a red bow.  It would appear that the Sparklematic 5200 also gift wraps!" }
WordHunterWoW_QuestEN[2946] = { title = "Seeing What Happens", description = "We want you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nWhen you've found out what happens, return to Ironforge.  We'll have a lot to analyze when you're done!", objectives = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"" }
WordHunterWoW_QuestEN[2947] = { title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...", objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", progress = "Hey, easy there partner - I'm a very important businessman!  I am sure that the courier is just simply late with the delivery of the rent... wait... you're not my landlord.\n\nWell, of course you aren't - silly me!  You've come to me seeking the finest jeweler in all of Ironforge, one who does NOT make CURSED items!  Yes!\n\nUm... what do you need?", completion = "A ring, you say?  Let's see... yep, I made that ring by golly.\n\nBefore Gnomeregan went up, I had a small shop there.  Perhaps it's one I left behind when I ran for the hills; it's a simple design, and I made several like it.  Maybe it's from someone who didn't make it out.\n\nDark Iron dwarves had this?  Well, that puts a new layer of conspiracy on the nine different layers already floating about.  Maybe the authorities would like to know; it's wasted on the likes of me.\n\nNow, back to the ring..." }
WordHunterWoW_QuestEN[2948] = { title = "Gnome Improvement", description = "Listen {name}, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...\n\nI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!\n\nTrust me!", objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.", progress = "Do you have the materials I need?  I wouldn't ask you for them if I wasn't down on my luck...", completion = "Ah, exactly what I needed!  Someday, when I find myself out of this hole that I am unjustly in, I will make for you, for EVERYONE the finest trinkets in all of Azeroth!  Until then, thanks for being a sport about the reagents.  I'd normally charge ten times what I have charged you for a ring of this quality...\n\nSpeaking of rings, here's your new one!" }
WordHunterWoW_QuestEN[2949] = { title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...", objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", progress = "You'd think that we would find a way on our own to outdo those filthy little gnomes.  I would even wager that they stole that rig from us to begin with!  Bah, those greasy, grimy... erm, yes?  You need something?", completion = "A ring from Gnomeregan?  Let's see... not mine, but interesting.\n\nThe Gnomeregan thing - couldn't have happened to a nicer bunch of numbskulls.  For years they're a joke, and now almost overnight they're making better rigs than us?\n\nDark Iron dwarves had the ring?  That's even more interesting!  You know, maybe the gnomes stole their crazy golem plans and modified them.  Those Dark Irons, they'd definitely want some major payback.  It's certainly worth investigating.\n\nYou know, about that ring..." }
WordHunterWoW_QuestEN[2950] = { title = "Nogg's Ring Redo", description = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?", objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.", progress = "Do you have the materials I need?  I can't improve on this design without everything I asked for.", completion = "Here's your ring, better than before.  Thanks again for the information about those Dark Iron dwarves.  This seems like a reasonable lead as to how those gnomes suddenly were struck with goblin-like inspiration." }
WordHunterWoW_QuestEN[2951] = { title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", objectives = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in an almost frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side..." }
WordHunterWoW_QuestEN[2952] = { title = "The Sparklematic 5200!", description = "", objectives = "As quickly as it started, the Sparklematic 5200 comes to an abrupt halt.  A simple \"ding\" is heard from the machine, and the mouth of the machine spirals upward.  Inside the Sparklematic 5200 is a small box wrapped in a little bow.  The machine would appear to wrap an object up after eliminating its grime-encrusted status.  Even if the machine didn't work, at least the item is now wrapped in a pretty box.\n\nWell, there is one way to find out if it cleaned the item or not..." }
WordHunterWoW_QuestEN[2953] = { title = "More Sparklematic Action", description = "", objectives = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", progress = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", completion = "The Sparklematic 5200 comes to life, lurching to and fro.  Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine's gnomish cleaning agent.\n\nThe Sparklematic 5200 comes to a halt, heralded by a familiar \"ding!\"  The item receptacle of the machine spirals open, revealing a neatly wrapped box." }
WordHunterWoW_QuestEN[2954] = { title = "The Stone Watcher", description = "\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"\n\nThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on.", objectives = "Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert.", completion = "The stone watcher's voice resonates with power and authority:\n\n\"Your discs will be returned to you once you access the pedestal.  When you have obtained the Plates of Uldum and incorporated them into your existing disc set, you may then enter the complex.\"" }
WordHunterWoW_QuestEN[2962] = { title = "The Only Cure is More Green Glow", description = "Not only was your sample insufficient in quantity, it was also impure.\n\nWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered.", objectives = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.\n\nOzzie will also require your Heavy Leaden Collection Phial when the task is complete.", progress = "Hrm, you're not glowing. That's a good sign.", completion = "<Ozzie examines you.> Impressive, you still have all of your limbs. Now it's time to see what this stuff can do!" }
WordHunterWoW_QuestEN[2963] = { title = "Portents of Uldum", description = "Greetings once again, <name>!  Your discovery inside Uldaman has set the Explorers' League abuzz with excitement.  The League has been working to unlock the secrets of the miniature platinum discs you found.  Your fortuitous arrival here in the Hall allows me to share with you that we are quite possibly on to something!\n\nHistorian Karnik has uncovered some important clues as to the true origins of the Valley of the Watchers in the Tanaris desert.  He would like to speak with you as soon as possible!", objectives = "Speak with Historian Karnik in the Hall of Explorers within Ironforge.", completion = "I am glad you're maintaining your interest in exploration, <name>!  With your natural talent and moxie, we could crack open secrets that we never thought were possible!\n\nThe Discs of Norgannon in Uldaman were a repository of vast information; you were only permitted to access the top layers, as it were, of the information stored there.  The Creators were rumored to have more repositories located throughout Azeroth.  This now brings us to Uldum..." }
WordHunterWoW_QuestEN[2964] = { title = "A Future Task", description = "Well <name>... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.\n\nThe High Explorer needs to be informed on this, <name>; no doubt, he also wants to thank you personally for once again aiding the League.", objectives = "Speak with High Explorer Magellas in Ironforge.Well <name>... we seem to be at a temporary dead end here. We know what we need - the Plates of Uldum - but we have no idea where they might be. We'll need to do quite a bit of research on this to come up with a solid plan of attack. I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.\n\nThe High Explorer needs to be informed on this, <name>; no doubt, he also wants to thank you personally for once again aiding the League.", completion = "We're all in agreement then - the best plan of attack is putting this on hold until we can narrow down the areas where these plates might lie hidden.  You've brought us this far <name>, and I hope you will be the one to head back in to the field to unlock Uldum for us all!\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons!" }
WordHunterWoW_QuestEN[2965] = { title = "Portents of Uldum", description = "Ah, <name>, it is fortuitous that you have come to me again.  Your revelations at the Uldaman dig site have certainly given us sages much discuss.  I was doing just that with one of the druids, Nara Wildmane, when it dawned on me that her past adventuring experiences may have some great importance as to the next step we need to take.\n\nI would like for you to speak with her concerning her travels to the Valley of the Watchers in the Tanaris desert.  She waits for you on the Elder Rise.", objectives = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.", completion = "There is a place deep in the Tanaris desert called the Valley of the Watchers.  The discs that you recovered... their translated glyphs make mention of a place called Uldum.  Most think this place to be a myth.\n\nI know this to be false; Uldum exists.  I've been there.  Well... outside, at any rate.\n\nThe crux is this, <name>: we think there is a connection between the discs and Uldum, and we want you to go there." }
WordHunterWoW_QuestEN[2966] = { title = "Seeing What Happens", description = "Sage Truthseeker and I would like you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nLearn what you can, then return to me. We will have much to discuss.", objectives = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"" }
WordHunterWoW_QuestEN[2967] = { title = "Return to Thunder Bluff", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Thunder Bluff and inform the Nara Wildmane of your discovery.", objectives = "Speak with Nara Wildmane in Thunder Bluff.", progress = "Welcome back <name>.  Were you able to use the discs to your advantage, or was it for naught?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself.  I don't know whether to be excited by that prospect, or be terrified.\n\nWe may need to risk everything to ensure that those secrets the earth keeps which would destroy us all remain just that - secrets." }
WordHunterWoW_QuestEN[2968] = { title = "A Future Task", description = "Well <name>... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.\n\nSage Truthseeker needs to be informed on this, <name>; no doubt, he also wants to thank you personally for once again heeding the call.", objectives = "Speak with Sage Truthseeker in Thunder Bluff.Well <name>... we seem to be at an unfortunate impasse. We know what we need - the Plates of Uldum - but we have no idea where they might be. We will research this, and then devise a solid plan of attack. I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.\n\nSage Truthseeker needs to be informed on this, <name>; no doubt, he also wants to thank you personally for once again heeding the call.", completion = "We're all in agreement then - the best course of action is to wait until we can narrow down the areas where these plates might lie hidden.  You've brought us this far <name>, and I hope you will be the one to head back in to the field to confront the secrets of Uldum.\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons us all, young one." }
WordHunterWoW_QuestEN[2969] = { title = "Freedom for All Creatures", description = "The filthy Grimtotem clan are capturing faerie dragons, <name>. Jer'kai and I have no idea what they plan on doing with them, but they're obviously up to no good.\n\nWe're not powerful enough to fight our way into the camp and free the captured dragons, but perhaps with your help...\n\nIf you're willing, and you have some strong friends, release the creatures from their cage with this key and make sure they escape with their lives. I'll be by your side the entire time. Jer'kai will remain here.", objectives = "Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.\n\nYou have 6 minutes before Kindal decides it is time to retreat and you fail the quest.", completion = "Thank Elune, <name>! You are a great blessing to us and to the darters you saved. Jer'kai and I would never have been able to help the dragons ourselves--your intervention in the Grimtotem's affairs will be remembered.\n\nSpeak to Jer'kai now... I have to prepare for our retribution. Just because the faerie dragons are free, it doesn't mean they will remain so. Jer'kai and I will now go on the offensive." }
WordHunterWoW_QuestEN[2970] = { title = "Doling Justice", description = "As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.\n\nYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons.", objectives = "Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas.", completion = "Kindal was right about you, <name>--you do have a knack for this. You are a more seasoned adventurer than the both of us, and for that we thank you.\n\nThe Grimtotem clan is much more hostile than most tauren... I wonder if their own kind frowns upon their actions. I wouldn't be surprised. As you are probably aware, many races on Azeroth have ties to less kindly counterparts.\n\nBut that is a discussion for another day." }
WordHunterWoW_QuestEN[2972] = { title = "Doling Justice", description = "Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.\n\nWe both thank you, <name>.", objectives = "Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus.", progress = "Hello, child. It pleases us to have more powerful adventurers here in the temple. If you have the time, will you share a tale or two with the younger adventurers? I know many of them would benefit from your wisdom.\n\nI'm sorry, look how rude of me. You've come to the Temple seeking our aid, and I impose on you. Please, forgive me. Tell me what the servants of the Light can do for you.", completion = "That's an amazing story, <name>. It pleases us that you've not only helped dragonkind, but also one of our own priestess. Jer'kai was right to send you to me. I will make sure she has her ring returned to her--I have scouts heading the direction of Feralas soon. This will be one more thing for them to investigate while on their mission.\n\nThank you again, and please, make yourself at home while you're here." }
WordHunterWoW_QuestEN[2973] = { title = "A New Cloak's Sheen", description = "Well met, <class>. I've traveled with my companions down to the Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with gorgeous wings I want are west of Camp Mojache.", objectives = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, <class>. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, <class>! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, <class>." }
WordHunterWoW_QuestEN[2974] = { title = "A Grim Discovery", description = "What!? You came across tauren in the area? You're joking! What did they look like!?\n\nThe Grimtotem clan! You found some of them? Belgrom, one of our masters, has an interest in their kind... he's even put a bounty on them.\n\nYou have to go back, <class>. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", objectives = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", progress = "Take my words seriously, <class>, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "These are good horns, <class>. Well done. I'll take these from you and be sure to tell Belgrom as soon as we return to Orgrimmar. You've helped me twice now, and for that, you have my mark. Perhaps in the future I can help you! Good luck to you." }
WordHunterWoW_QuestEN[2975] = { title = "The Ogres of Feralas", description = "The effects of the Gordunni Ogre tribe can hardly go unnoticed in this area. Look around, <name>; their very presence scars this land. We must push them back before they expand even further into Feralas.\n\nFollow the river north, and you will find their outpost. Decrease their numbers, <name>. We must show them that their kind is not wanted here.", objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.", completion = "Excellent, <name>. In time, the land will heal. We must not give up." }
WordHunterWoW_QuestEN[2976] = { title = "A Grim Discovery", description = "What?!\n\nAh, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it?\n\nYou did the work, so I suppose it is only right you reap the greatest reward from it. Take the horns, I'll have them put in a crate for you. Find Belgrom Rockmaul in the Valley of Honor, he'll want to know what you saw and he'll reward you for your hard work.\n\nBe well, <class>, and thank you again for everything you've done.", objectives = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.", progress = "Be quick, <class>, I have much to complete today.", completion = "The Grimtotem!? This is interesting. You say you came across them while hunting in Feralas? Truly?\n\nMy peers will want to hear your news, <class>. Tell me more and I'll count out your coin while you do so.\n\nAnd before you go, know that I give you thanks for the information you've passed on to me this day." }
WordHunterWoW_QuestEN[2977] = { title = "Return to Ironforge", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Ironforge and inform the Explorers' League of your discovery.", objectives = "Speak with Historian Karnik in Ironforge.", progress = "Welcome back <name>.  Were you able to use the discs to your advantage, or did it end up being a wild goose chase?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself!  Imagine actually exploring the place where the Creators worked without having to bring a huge shovel!\n\nNot that there's anything wrong with shovels... or digging..." }
WordHunterWoW_QuestEN[2978] = { title = "The Gordunni Scroll", description = "Picking up the soiled scroll, you notice that it seems to be depicting some sort of meeting or ceremony. Rok Orhan would be interested in this scroll, and what it might mean to the Gordunni.", objectives = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.", progress = "What is this?", completion = "This scroll... You found this in the Gordunni Outpost?" }
WordHunterWoW_QuestEN[2979] = { title = "Dark Ceremony", description = "These seem to be plans for some sort of dark ceremony, <name>. From what I can make out, this ritual is conducted by the Gordunni mage-lords.\n\nFind one of these mage-lords, and from him, gather an orb.\n\nThe orb of a mage contains great power, and will help us discover more about this ceremony and the magic that the Gordunni wield.", objectives = "Rok Orhan in Camp Mojache wants you to find a Gordunni Orb.", progress = "We must discover more about why the Gordunni are here, <name>.", completion = "This orb will provide us with more information about the Gordunni... which we will then use in planning their downfall, <name>." }
WordHunterWoW_QuestEN[2980] = { title = "The Ogres of Feralas", description = "Now that you have proven that you are a true fighter, I trust that you possess the courage to continue with the task at hand.\n\nTravel to the High Wilderness, southwest of here. There lie some abandoned and destroyed structures, on land that once belonged to the night elves. Look for these ruins, and when you see the withered trees and desecrated terrain, you will find the Gordunni. Push them back.\n\nThese ogres are much stronger than the ones you faced previously, <name>. Be aware.", objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.", completion = "You have proven yourself to be a trustworthy and dependable ally, <name>." }
WordHunterWoW_QuestEN[2981] = { title = "A Threat in Feralas", description = "Feralas is an ideal location for an accomplished <class> to prove <himself/herself>. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.\n\nA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.", objectives = "Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache.", completion = "So, Belgrom sent you. You are just in time, <race>.\n\nLet me explain the situation, and then you can decide if you are up to the challenge... But if Belgrom sent you, I am sure your courage is unquestionable." }
WordHunterWoW_QuestEN[2982] = { title = "The High Wilderness", description = "Although it is dangerous, Troyas and I have been investigating the ruins that cover the forests of Feralas.\n\nLately, though, Troyas has been going on his own to the High Wilderness, and I really worry about him. The Gordunni Ogres have taken over that area, and they don't take kindly to anyone that enters their territory.\n\nI was hoping you might be willing to travel to the ruins to the southeast and clear out some of the ogres. Make it a little safer for my Troyas, and I will be extremely grateful.", objectives = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.", completion = "I am very grateful you were able to do this for me.\n\nNow, please, don't mention a word to Troyas about this..." }
WordHunterWoW_QuestEN[2983] = { title = "Call of Fire", description = "It's been some time since you were tested last, <name>. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.Upon completion of this quest you will gain:", objectives = "Find Kranal Fiss in the Barrens.It's been some time since you were tested last, <name>. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2984] = { title = "Call of Fire", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.", objectives = "Find Kranal Fiss in the Barrens.", completion = "Hmmm, Narm sent you to me, did he?\n\nWell then, Narm could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, <name>. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand." }
WordHunterWoW_QuestEN[2985] = { title = "Call of Water", description = "You look ready for your next test, <name>. You've been patient in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.Upon completion of this quest you will gain:", objectives = "Find Islen Waterseer in the Barrens.You look ready for your next test, <name>. You've been patient in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2986] = { title = "Call of Water", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.", objectives = "Find Islen Waterseer in the Barrens.", completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take." }
WordHunterWoW_QuestEN[2987] = { title = "Gordunni Cobalt", description = "I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.\n\nIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!", objectives = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.", progress = "Get on up there and start digging!\n\nI've got places to go and people to see -- time is money!", completion = "Perfect! I will take these along as I continue my travels, <name>. I'm sure I can find someone that will pay a pretty penny for this cobalt.\n\nHere, take this for your trouble." }
WordHunterWoW_QuestEN[2988] = { title = "Witherbark Cages", description = "The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.\n\nYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there.", objectives = "Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe.", completion = "Sharpbeak wasn't at the villages?  Hm... this is grim news.  That gryphon is destined to lead the next generation of gryphons.  If he is lost then the strength and spirit of our fleet will suffer immensely." }
WordHunterWoW_QuestEN[2989] = { title = "The Altar of Zul", description = "Sharpbeak was not with the Witherbark trolls.  Perhaps the Vilebranch trolls took him.  Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child.", objectives = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe.", completion = "Sharpbeak wasn't there?  That is bad news, but it is good news too...\n\nIt is good that he was not at the Altar of Zul for the Vilebranch trolls are known for performing sacrifices.\n\nI thank you for all of your aid, but I'm afraid I have an even greater task ahead." }
WordHunterWoW_QuestEN[2990] = { title = "Thadius Grimshade", description = "Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!\n\nAnd perhaps his talents can help us find Sharpbeak.\n\nThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.\n\nGood luck, <name>.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep.", objectives = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.", progress = "<name>, you come bearing a gift?", completion = "Ah, yes.  This feather belongs to a fine gryphon.  One destined for great things... if he can survive into adulthood undamaged.\n\nYou wish to find him?  Then listen close, brave <class>..." }
WordHunterWoW_QuestEN[2991] = { title = "Nekrum's Medallion", description = "I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.\n\nZul'Farrak is across the ocean to the west, in the desert of Tanaris.", objectives = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.", progress = "Do you have Nekrum's Medallion, <name>?  There are powers hidden within it that I am eager to discover.", completion = "Ah, the medallion of Nekrum.  It is rumored to have given the troll an unnatural long life, but at a cost.  I hope to discover a way to reap the medallion's power while avoiding its... unpleasant side effects.\n\nYou have done me a service, <name>.  I shall now uphold my end of our bargain." }
WordHunterWoW_QuestEN[2992] = { title = "The Divination", description = "Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.\n\nThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes.", objectives = "Wait until Grimshade performs the ritual of divination.", completion = "The ritual was a success.  I have seen Sharpbeak and can tell you how to find him." }
WordHunterWoW_QuestEN[2993] = { title = "Return to the Hinterlands", description = "Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.\n\nThere.  I have done my part.  I bid you fortune on your quest, <name>.", objectives = "Speak with Gryphon Master Talonaxe.", completion = "You've spoken with Grimshade?  What did he say?\n\n...What?  The Vilebranch trolls have Sharpbeak?  That's unbearable!  We must organize a force to get him back!" }
WordHunterWoW_QuestEN[2994] = { title = "Saving Sharpbeak", description = "We must save Sharpbeak!\n\nFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!", objectives = "Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.", completion = "Swiftwind and Keenclaw returned with their child moments ago, and are fussing over him like new parents.  Seeing them together again is enough to give even this old dwarf mist in the eyes...\n\nWe cannot repay you enough for what you have done, <name>.  The gryphons of Aerie peak, and their riders, will sing your name for a long, long time." }
WordHunterWoW_QuestEN[2995] = { title = "Lines of Communication", description = "The Quel'Danil Lodge is a center of communication for the high elves of the Hinterlands. Their ambassadors are working to establish relationships with other races, with whom they share their knowledge of the Witherbark trolls that inhabit the area in the southern Hinterlands. All of the documents regarding the communications are kept at the lodge.\n\nWe don't need the Highvale building alliances with others, <name>.\n\nDestroy the Highvale documents.  We need to burn their lines of communication... literally.", objectives = "Burn the Highvale Records, Highvale Report, and Highvale Notes.", completion = "Perfect, <name>. While the Highvale work to recover their lost information, we will be able to seal off the lines even further..." }
WordHunterWoW_QuestEN[2996] = { title = "Seeking Strahad", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.Upon completion of this quest you will gain:", objectives = "Speak to Strahad Farsan in Ratchet.I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2997] = { title = "Tome of Divinity", description = "Hello, <name>. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.\n\nYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, <name>.Upon completion of this quest you will gain:", objectives = "Speak to Tiza Battleforge in Ironforge.Hello, <name>. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.\n\nYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2998] = { title = "Tome of Divinity", description = "Greetings, <brother/sister>. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.\n\nIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time.Upon completion of this quest you will gain:", objectives = "Speak to Duthorian Rall in Stormwind.Greetings, <brother/sister>. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.\n\nIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[2999] = { title = "Tome of Divinity", description = "Hello, <name>. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.Upon completion of this quest you will gain:", objectives = "Speak to Tiza Battleforge in IronforgeHello, <name>. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[3000] = { title = "Tome of Divinity", description = "Hello, <name>. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.\n\nYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.Upon completion of this quest you will gain:", objectives = "Speak to Tiza Battleforge in Ironforge.Hello, <name>. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.\n\nYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[3001] = { title = "Seeking Strahad", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.\n\nYou can find him in Ratchet... above the port town next to the tower there.Upon completion of this quest you will gain:", objectives = "Find Strahad Farsan in Ratchet.I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.\n\nYou can find him in Ratchet... above the port town next to the tower there.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[3002] = { title = "The Gordunni Orb", description = "Although I know my enemy well, I am a warrior, <name>. I cannot begin to tell you what this orb is capable of.\n\nI know of a mage in Orgrimmar that will be able to tell us more about the orb. Take it to him.", objectives = "Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar.", progress = "What have you brought me, <race>?", completion = "Fascinating, <name>...\n\nThis orb is very powerful, but also very dangerous." }
WordHunterWoW_QuestEN[3022] = { title = "Handle With Care", description = "<name>, I can see you yearn to be dedicated to my worthwhile cause. Yes, of course, you can do something for me!\n\nTake this crate of eggs to Erelas Ambersky. He is a druid that cares for these eggs, helping them to hatch and then training the young hippogryphs. You will find him in Teldrassil, in a small village to the south called Rut'theran.", objectives = "Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village.", progress = "Another shipment from Curgle, I assume?", completion = "Thank you for your help, <name>. The hippogryph population simply wouldn't flourish if it weren't for us. Ah, but I am sure you understand all too well, having traveled to Feralas yourself, and seen the devastation of the Gordunni there.\n\nWell, as you can see, I am hard at work here, so you'd best be on your way.\n\nThanks again, <name>." }
WordHunterWoW_QuestEN[3042] = { title = "Troll Temper", description = "The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft.  It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.\n\nZul'Farrak is northwest of Gadgetzan.  Good luck.", objectives = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", progress = "Did you bring me the temper, <name>?", completion = "Ah, this is very nice temper indeed!  And so much of it!  I'll be at work for days before I use it all!\n\nThank you, <name>.  Please, take this as payment." }
WordHunterWoW_QuestEN[3062] = { title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", objectives = "Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.", progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart; I will keep it in memory of what did here for me, <name>. Thank you." }
WordHunterWoW_QuestEN[3063] = { title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. <name>, get my revenge.", objectives = "Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers.", completion = "Thank you, <name>. You have put an old tauren's mind at peace." }
WordHunterWoW_QuestEN[3064] = { title = "<NYI> <TXT> Pirate Hats", description = "I need pirate hats for my shop.  Get me lots!", objectives = "" }
WordHunterWoW_QuestEN[3065] = { title = "Simple Tablet", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", objectives = "Read the Simple Tablet and speak to Frang in the Valley of Trials.", progress = "Another <race> to bolster the ranks. Good enough for me.\n\nYou'll probably have a hard time hefting a good weapon like an axe, but a spear's just as good as anything else.\n\nWelcome to the Valley of Trials.", completion = "You'll find this place fitting as you continue to train in the <class> ways. If you have any questions, feel free to ask anyone around, and when you feel you're ready, come back to me for training. I've mastered as much as any <class> here in the Valley and can pass that knowledge on to you... for a price." }
WordHunterWoW_QuestEN[3082] = { title = "Etched Tablet", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.Upon completion of this quest you will gain:", objectives = "Speak to Jen'shan in the Valley of Trials." }
WordHunterWoW_QuestEN[3083] = { title = "Encrypted Tablet", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", objectives = "Read the Encrypted Tablet and speak to Rwag in the Valley of Trials.", progress = "Welcome to the Valley of Trials, <name>. You wouldn't be here if you hadn't gotten my tablet, so I will get to the point.\n\nI am Rwag and I am responsible for training the rogues, thieves, and cutpurses here in the Valley. I'm the one the Hand will turn to if you're not ready for what's to come. But don't worry, the Hand won't be controlling everything you do, but it would be wise to work with them if they have need of your talents.", completion = "Until such time comes, you'll be under my tutelage. I will show you the ropes as some folks say. Whenever you feel prepared, come to me and I will see about training you further. Until then, practice your skills and keep them honed to a razor's edge. You'll never know when you'll need even the most insignificant ability." }
WordHunterWoW_QuestEN[3084] = { title = "Rune-Inscribed Tablet", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", objectives = "Speak to Shikrik in the Valley of Trials.", progress = "Ah, welcome, <name>. I'm pleased you have arrived. My days have become long and even busy what with so many students to teach, but the coming of one of your ilk brings me a great sense of accomplishment--I remember the days when I was taught by one of your shamans.", completion = "As you probably know, the elements give us our power. Fire, earth, water and air--these are our tools.\n\nOur strength comes from the spirits of our ancestors. We are the leaders of our people. Like Thrall is to the Horde, so shall we be to the villages and towns we visit. They will look to us for wisdom and protection. To be better prepared, you must train often. When you feel you've gained more power, come to me and I shall teach you what I can." }
WordHunterWoW_QuestEN[3085] = { title = "Hallowed Tablet", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the priest trainer Ken'jai. He would have words with you when you're ready.", objectives = "Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials.", progress = "So ya made it... good good! Da spirits tol' me you be comin' to see Ken'jai soon enough. Let me be one o' da first to welcome ya to da Valley of Trials. Dis place not be your home fer long, but while it is, why dontcha make da best o' it.", completion = "As ya test yeself, ya'll find ya have better an' better control o'er da spirits--ya'll be callin' on dem fer greata an' greata tings...  dat's where ol' Ken'jai come in. You come talk to ole Ken'jai when ya feel yer ready. If da spirits agree, den we see 'bout teachin' ya more powerful abilities... but only if da spirits agree.\n\nGo now, talk to da rest of da Valley's people. Speak to me again later." }
WordHunterWoW_QuestEN[3086] = { title = "Glyphic Tablet", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Mai'ah. She would have words with you when you're ready.", objectives = "Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials.", progress = "Ya look to please Mai'ah already, <name>. Dat be good. You give Mai'ah respect, and Mai'ah maybe give you respect back. But enough o' dat, you be here to learn 'bout magic, not hear Mai'ah talk.\n\nThere be only one ting Mai'ah can no teach you 'bout magic, <name>, and dat's how to stop da corruptin'.", completion = "You be among da most powerful beings on da planet, <name>... there no arguin' dat. And everyone know it... know it good, too!\n\nBut ya must be weary! 'cause it not orc, or elf, or dwarf dat you should be scared of... it be da tings you can'na see. Magic be powerful. Make you do tings you may not want to do. Make ya tink you more powerful then you really be. Be patient. Be smart.\n\nWhen ya tink you be ready for trainin', come back to Mai'ah. She teach you what you ready to learn, no problem." }
WordHunterWoW_QuestEN[3087] = { title = "Etched Parchment", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Karranisha. He would have words with you when you're ready.", objectives = "Read the Etched Parchment and speak to Karranisha in the Valley of Trials.", progress = "Many come to me with the desire to be a <class>, but few follow through.  It's easy to underestimate our job.  Being a <class> is far more than just aiming and shooting.", completion = "As a <class>, my skill rivals the arcane powers of the mages, the martial prowess of the warriors, or even the blessed acts of our beloved shaman.  To be a <class> requires focus and dedication.  Let us continue." }
WordHunterWoW_QuestEN[3088] = { title = "Encrypted Parchment", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", objectives = "Read the Encrypted Parchment and speak to Rwag in the Valley of Trials.", progress = "Shhh, not so loud.  The enemy has ears everywhere.", completion = "Now that you know where I'm holding up, I should let you know: the Shattered Hand's asked me to look out for you. They want me to train you and keep you informed of anything they might need. Even if you're not interested in helping them yet--which you'd be a fool not to be--I'll do what I can to train you... for a small fee." }
WordHunterWoW_QuestEN[3089] = { title = "Rune-Inscribed Parchment", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", objectives = "Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.", progress = "So, you've arrived. I was beginning to wonder when you would show yourself. I sent the parchment some time ago--I wasn't sure if it had arrived.\n\nBut enough chatter... you're here because you have been chosen: chosen to lead the spiritual lives of our people.", completion = "You will be the conduit in which our ancestors communicate.  You will have the power of the elements at your beck and call.  Sundering your enemies will be child's play; healing your allies as easy as breathing.\n\nBut not yet.  First, you train." }
WordHunterWoW_QuestEN[3090] = { title = "Tainted Parchment", description = "Ah, while you were gone a parchment came for you, <name>.\n\nI usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer Nartok. He would have words with you when you're ready.", objectives = "Read the Tainted Parchment and speak to Nartok in the Valley of Trials.", progress = "Finally, you've arrived... and discretely also. Good.\n\nOur world is full of fools, <name>. Even the mighty Thrall has greater flaws than most can see. He turns his back on the power needed to make this land ours completely! We're not the same people who were manipulated and used by creatures from the Nether. We are our own people. We are proud... and we are strong.", completion = "And now you've joined our ranks also. Don't misunderstand, <name>. Just because you have access to power that many will be jealous of, it does not mean you will be accepted easily.  Hellscream allows our kind into Orgrimmar because we are still his fellow kin--he cannot turn his back on us, or we would become as pathetic as the humans who enslaved him. My point is: be careful. You can be powerful, but if you are foolish, then you are as good as dead." }
WordHunterWoW_QuestEN[3091] = { title = "Simple Note", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the warrior trainer Harutt. If this note is from Harutt, I wouldn't take long in reading its contents.", objectives = "Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.", progress = "Ah, at last, you've arrived, <class>. I did not lie in my note, <name>. We are a special breed also, not unlike the druids or shamans of our tribe. You are just as important. We are the ones called upon to defend our borders, to hunt the centaur, and to go to war.", completion = "Each of us plays a role in our tribe. Each of us must also go through all the same rites. Do not ever let your pride tell you otherwise.\n\nI remain here to train new warriors that seek the glory of battle and who follow the ways of our oldest ancestors. When you feel ready, come back to me and I will do what I can to train you further. Go with the tribe's blessing, <name>." }
WordHunterWoW_QuestEN[3092] = { title = "Etched Note", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the hunter trainer Lanka. If this note is from Lanka, I wouldn't take long in reading its contents.", objectives = "Read the Etched Note and speak to Lanka Farshot in Camp Narache.", progress = "Welcome to Camp Narache, <name>. I hear good things about you. Your bloodline is strong, and many of the elders consider you skilled already. But that we will test.\n\nThe plains of Mulgore will be your home for sometime--you should do your best to learn it very well. One day you will travel to unfamiliar lands to master greater skills. You must be ready.", completion = "And it is my job to make sure you are prepared by teaching you the basics of our profession--how to tame your pet, how to fire your rifle, and many other skills that will become necessary.\n\nHunters are a strong part of our tradition and history, <name>. You would do well to remember how important you are to the tribe. You will be respected and revered if you serve our people well." }
WordHunterWoW_QuestEN[3093] = { title = "Rune-Inscribed Note", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the shaman trainer Meela. If this note is from Meela, I wouldn't take long in reading its contents.", objectives = "Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.", progress = "As quickly as water falls from the sky, here you are before me. I am pleased by your haste. It means you realize both the importance of our meeting and you being here. I am no leader, but I do understand the elements, and I can speak to the spirits of our people. I will teach you to do the same.", completion = "We will meet many times in the days to come. Each time you will hopefully leave my company a little more powerful... a little more prepared. Like the Eternal Flame, your spirit will burn bright and hot.\n\nGo now, <name>. Go and test yourself. I will be here for you when you need." }
WordHunterWoW_QuestEN[3094] = { title = "Verdant Note", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the druid trainer Gart. If this note is from Gart, I wouldn't take long in reading its contents.", objectives = "Read the Verdant Note and speak to Gart Mistrunner in Camp Narache.", progress = "You have arrived. This is good. Our ancestors' spirits have become restless throughout Mulgore and beyond, but I cannot tell why. It will forever be your duty to learn to listen to nature's spirits, and act as their avatar. Be mindful of that.", completion = "Though we share a common bond, do not expect much welcome from the night elves. Their pride still limits their sight, but that is none of our concern. The teachings of the Earthmother are all you must concern yourself with, and I will teach you what I know as you grow in wisdom.\n\nReturn to me often, <name>. You will find that the Earthmother grants incredible abilities to those who are most dedicated." }
WordHunterWoW_QuestEN[3095] = { title = "Simple Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warrior trainer Dannal. I would take some time to read it before heading out again.", objectives = "Read the Simple Scroll and speak to Dannal Stern in Deathknell.", progress = "Ah, so you've arrived. Good. I overheard that a few others were able to escape \"death\" and were heading into town. Perhaps that resilience will pay off in the future also.\n\nYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.", completion = "I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you'll find everything I can teach you to be worthwhile.\n\nGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need warriors with your type of strength in the future. You will be the backbone of our salvation. Do not forget it." }
WordHunterWoW_QuestEN[3096] = { title = "Encrypted Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the rogue trainer David Trias. I would take some time to read it before heading out again.", objectives = "Read the Encrypted Scroll and speak to David Trias in Deathknell.", progress = "So you've made it? Good, we'll have need of more rogues as time goes on. The Shadowstalkers will probably wind up finding you when they think the time's right, so don't go and slip up or do anything you might regret. They need talented agents... not pickpockets and fools.", completion = "I spend most of my time here in the inn keeping an eye out for new faces and just keeping tabs on up-and-coming prospects. Keep your nose clean and I'll do what I can to teach you a few things. Just come back to me whenever you want, and we'll see if you're ready for a new skill or two." }
WordHunterWoW_QuestEN[3097] = { title = "Hallowed Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the priest trainer Duesten. I would take some time to read it before heading out again.", objectives = "Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell.", progress = "Ah, so between fire, plague, rioting, and much worse, one more of the \"faithful\" comes to my door. Well, let me bid you welcome, <class>. And allow me a moment to explain a thing or two before you decide it's time for you to seek whatever drives you forward: the Holy Light no longer concerns you, the spirits of your forefathers are fairy tales, and creatures from the Nether don't want you.\n\nDo you understand me so far?", completion = "There is only one thing you must know: we have survived through will alone. It is faith in ourselves that separates us from others, and with our powers, we will cause great change in all of Azeroth. The weak will come to lean on you. The lepers will call you Lord. And the ignorant will look to you for guidance. It is my duty to make sure you have the necessary tools so when the time comes, you are prepared. As you grow in experience, seek me out. I will teach you greater powers if you are ready." }
WordHunterWoW_QuestEN[3098] = { title = "Glyphic Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the mage trainer Isabella. I would take some time to read it before heading out again.", objectives = "Read the Glyphic Scroll and speak to Isabella in the church in Deathknell.", progress = "I knew you would come to me, <name>. Not because you do not have the will to follow your own path, but because we are kindred spirits. We both have felt pain. We have both suffered. And now we want the power to take back what we know is ours: this land, our lives, our destinies. But there is much for you to learn still.", completion = "You must return to me often if you are to become powerful enough to destroy those who would oppose us. The rules of magic still apply to you, <name>. You will still find corruption follows you like hungry wolves in the night. You will find its caress is not unlike an addiction, an old lover still wanting to be by your side. But these things can be staved off. These things will only control you if you allow them to.\n\nGo now, return to me when you've grown more powerful." }
WordHunterWoW_QuestEN[3099] = { title = "Tainted Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warlock trainer Maximillion. I would take some time to read it before heading out again.", objectives = "Read the Tainted Scroll and speak to Maximillion in Deathknell.", progress = "I bid you welcome, brother. I knew you would come. It was only a matter of time.\n\nWhat I said interested you, didn't it? I hit a chord... something inside you knew what I claimed was truth. Good.\n\nKnow this though: I am no traitor to Sylvanas. If anything, she would appreciate my claims considering it was her own beliefs that has put the Forsaken in the position it is now.", completion = "I mentioned a slave still being a slave, no matter the master. Do you remember? We both know that it is that type of control--that type of power--that now drives us. We seek to have creatures serve us. We know we are more powerful and deserve more respect than others give us ... and so now we look to take it.\n\nI will be your ally in this struggle--the struggle for our own freedom. Freedom to seek our own allegiances. When you feel ready, return to me and I will teach you all I know." }
WordHunterWoW_QuestEN[3100] = { title = "Simple Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.", progress = "Ah, you got my letter, <name>... good.\n\nThere's been an influx of warriors in Elwynn recently--which is good for Stormwind, but bad for the orcs in the area.", completion = "Get yourself squared away, learn the layout of the land, and come back to me whenever you need training. I'll be here night or day.\n\nThe Knights of the Silver Hand have done well in making this place fairly safe, but as you meet the other citizens, I think you'll find they all have problems they could use some help with--help a <class> can give them. Good luck." }
WordHunterWoW_QuestEN[3101] = { title = "Consecrated Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Brother Sammuel, our local paladin trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.", progress = "Finally! We meet face to face, brother to brother. I welcome you to Northshire. This will be your home for a short time while you learn the ins and outs of how things are done, but know that Stormwind is not far off, and sooner or later, your path will take you there. But until then, be patient... Knight of the Silver Hand.", completion = "In the meantime, you should know one or two other things. You are a symbol to many here in this land--act accordingly. The Holy Light shines within you, and it will be obvious to both your allies and your enemies.\n\nAlso, as you gain in wisdom and power, you will need to train to learn new abilities. That's where I come in. When you feel you've gained some experience here in Northshire, come back to me and I will teach you what I feel you are ready to learn. Good luck... <class>!" }
WordHunterWoW_QuestEN[3102] = { title = "Encrypted Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.", progress = "You made it here in one piece, and it doesn't look like too many people saw you. Good enough for me. I don't like to have much attention drawn to me back here... nice and quiet. I'm sure you can understand.\n\nHave any trouble yet? I'm glad to hear not. That'll change soon enough.", completion = "You're gonna find a number of outfits that covet our skills, <name>. Adventurers, SI:7... heck, even the disorganized rabble wouldn't mind a spy or two inside Stormwind. But you remember this: You're your own man. Don't let nobody bully you into doing something you don't wanna do! Besides, we hold all the cards... at least, we do before the game's done. Know what I mean?\n\nAnyway, just wanted to introduce myself and let you know that I'm here if you need any training. Come by anytime." }
WordHunterWoW_QuestEN[3103] = { title = "Hallowed Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Priestess Anetta, our local priest trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.", progress = "Ah, at last you've come. I knew you would find your way to me. The Holy Light shines upon you, and the path you've chosen. These times are harsh--the Burning Legion still has a presence upon Azeroth, the entirety of Kalimdor seeks new ways to defend itself from its own tribulations, and it is up to you to aid as many as you can.", completion = "As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so." }
WordHunterWoW_QuestEN[3104] = { title = "Glyphic Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Khelden, our local mage trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.", progress = "Hello, <name>. I am Khelden. Is there something I can do for you?", completion = "Haha, I knew my note would not dissuade you from your path. So, you're prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?\n\nI will not lie, <name>, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful." }
WordHunterWoW_QuestEN[3105] = { title = "Tainted Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Drusilla, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.", progress = "Ah, so you've arrived, and not a moment too soon, <name>. Some of the guards were over here a moment ago and were giving me curious looks... pathetic mundanes.", completion = "As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.\n\nAs you grow more powerful, return to me and I will teach you more about our ways." }
WordHunterWoW_QuestEN[3106] = { title = "Simple Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar.", objectives = "Read the Simple Rune and speak to Thran Khorman in Coldridge Valley.", progress = "Blast it's cold today, ain't it? It's like the snow never goes away, <name>.", completion = "If you look around, you'll see a few interesting things: dwarves using magic in a fight instead of a rifle. Some of us have taken to worshipping the Holy Light like some of the humans, and, last but not least, troggs. You'll learn more about them later, but what you need to know now is that I'm here to help you." }
WordHunterWoW_QuestEN[3107] = { title = "Consecrated Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the paladin trainer Bromos. Take a gander at it and go find him inside Anvilmar.", objectives = "Read the Consecrated Rune and speak to Bromos Grummner in Anvilmar.", progress = "So, you've made it! And not a second too soon. There's much to be done in Coldridge Valley and beyond. I'm gonna need your help as much as you're gonna need mine!\n\nYou're a Knight of the Silver Hand now, be ready to play the part.", completion = "The humans have taught us a great deal about the Holy Light and how important their order is to them... and to protecting all of Azeroth. We have a great respect for how it is steeped in tradition, and how just one figure, one sacrifice, can make the difference between pain and salvation.\n\nThe two of us are gonna be working together for a bit." }
WordHunterWoW_QuestEN[3108] = { title = "Etched Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the hunter trainer Thorgas. Take a gander at it and go find him inside Anvilmar.", objectives = "Read the Etched Rune and speak to Thorgas Grimson at Anvilmar.", progress = "Ya made it! Good to hear! Betcha didn't have to track me to find the place either. Haha!", completion = "One thing you should always remember is that you gotta respect the world you're livin' in. The beasts that choose to fight along side you; the shine of your weapon; the weight of your ammo; the bite of a bitter wind; all these things you need to know intimately." }
WordHunterWoW_QuestEN[3109] = { title = "Encrypted Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar.", objectives = "Read the Encrypted Rune and speak to Solm Hargrin in Anvilmar.", progress = "You made it! Great!\n\nWe've got an influx of activity lately, so I'm glad to count another of the Ironforge clan among our numbers. Nothin' like a cold blade in your hand and a shadow to keep you one step ahead, and if you're here, you know exactly what I mean!", completion = "Anyway, as you start peekin' around Coldridge you'll probably have need of training at some point. You just come back to me whenever you feel you need it and I'll teach you what I know--a trick here, a maneuver there. You know, the stuff that keeps you alive and makin' a little extra coin." }
WordHunterWoW_QuestEN[3110] = { title = "Hallowed Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar.", objectives = "Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar.", progress = "Ach! Ya made it, <name>! Wonderful!\n\nI was gonna say, I was about to lose faith that ye'd arrive at all... get it, lose faith? It's a joke, lad... aww, nevermind. Ya didn't come here for me bad jokes anyway.", completion = "I'm the one who can train ya as you start to find your way around Coldridge Valley. When ya feel yer ready, come back to me and we'll see about maybe teaching you a new spell or two to fend off the valley from them blasted troggs.\n\nYa got the Light on yer side, along with all of Ironforge, <name>... no pressure on ya to become somethin' special." }
WordHunterWoW_QuestEN[3112] = { title = "Simple Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.Upon completion of this quest you will gain:", objectives = "Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley." }
WordHunterWoW_QuestEN[3113] = { title = "Encrypted Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley.", progress = "Glad to see you got my note and came over. Sorry about pretendin' it was a memorandum from your higher-ups... no offense intended. I just knew the two of us, along with others of our kind, gotta stick together.\n\nNot many think it's the best thing in the world to have your kind and my kind holed up in the same city, but I think we can work things out just fine. What do you think?", completion = "I pretty much keep to myself around here so we don't get a bad rap for things gone missing, but if you need anything, some training or somethin', just come back anytime.\n\nYou and me got an understandin'. We know when it comes down to it you can only trust family... and that's just what we got going on here, isn't it? Regardless of Gnomeregan being... overrun, and whatever else is thrown our way, we got one another to back each other up. Right?" }
WordHunterWoW_QuestEN[3114] = { title = "Glyphic Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the mage trainer Marryk. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley.", progress = "Yeah, what's that, <race>? Speak up, if you don't mind. I don't hear so good after a few ales.", completion = "Oh, yeah! Arcane Arts... of course.\n\nHere's what you need to know, <name>: Don't get into too much trouble. Save some coin to buy me an ale... or any spells ya might want. And stay the heck away from Gnomeregan. Other than that, have a good day! I'll be here if you need me or want to train... or whatever." }
WordHunterWoW_QuestEN[3115] = { title = "Tainted Rune", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warlock trainer Saripal. Take a gander at it and go find her inside Anvilmar when you've a chance.\n\nAnd watch yerself, <name>, your kind ain't too trusted 'round these parts.", objectives = "Read the Tainted Rune and speak to Saripal Smolderbrew inside Anvilmar above Coldridge Valley.", progress = "Wonderful! You obviously got my rune.\n\nIgnore the fools around you, <name>. The Holy Light?! The sword and shield?! These aren't paths for ones as open minded as us.", completion = "But none of that matters. What matters is that you've seen your own Holy Light! You know where power truly comes from. You realize that having our own allies is much more... prudent. Special allies. Allies that, no matter the task, will obey till their last breath.\n\nAnd that's where I come in, <name>. I can train you in the beginnings of those special powers. Seek me out often and I will do what I can to teach you more spells." }
WordHunterWoW_QuestEN[3116] = { title = "Simple Sigil", description = "This sigil was given to me by a messenger from our warrior trainer, Alyissia. It seems Alyissia would have words with you when you have a moment. Read it and bring it to her afterwards.", objectives = "Speak to Alyissia inside Aldrassil in Shadowglen.", progress = "You made it. I'm so glad.\n\nMuch has happened over the last few years, <name>: the creation of Teldrassil, the corruption of many of the forest creatures here and abroad, discovery of lands we thought lost to us like Feralas... so much, in so little time. But those are just some of the reasons we are here, the most important being to protect our kind from further evil.", completion = "Soon you will see others from different races in the boughs of our home--do not let it cause any prejudice within you. They are welcome. They will aid us when they can. Not all of them will be altruistic, but they should be granted some amount of trust.\n\nBut none of this matters now. Now we must focus on you, and how you can aid our people. I am here for that very purpose. I will train you in the ways of a <class> as you become stronger. Return to me whenever you wish and I will do what I can to aid you." }
WordHunterWoW_QuestEN[3117] = { title = "Etched Sigil", description = "This sigil was given to me by a messenger from our hunter trainer, Ayanna. It seems Ayanna would have words with you when you have a moment. Read it and bring it to her afterwards.", objectives = "Speak to Ayanna Everstride inside Aldrassil in Shadowglen.", progress = "You've arrived, and none too soon, <name>. Welcome to Shadowglen.\n\nI trust my sigil found you in good spirits and health?\n\nAs I said previously, I am here to train you as a <class>; to tame beasts to aid you in battle; to use a bow with unerring accuracy; to respect the lands which we call home and also the lands beyond.", completion = "As you experience what Shadowglen has to teach you, come see me--I will be able to help you understand more about your role as a <class> and what you are capable of.\n\nThese are dangerous times, <name>, do not take for granted the skill of your pets--there are things in this world more dangerous than you can imagine. Go with Elune and return to me again." }
WordHunterWoW_QuestEN[3118] = { title = "Encrypted Sigil", description = "This sigil was given to me by a messenger from our rogue trainer, Frahun. It seems Frahun would have words with you when you have a moment. Read it and bring it to him afterwards.", objectives = "Speak to Frahun Shadewhisper inside Aldrassil in Shadowglen.", progress = "Hello, <name>. I'm glad you found me. I was thinking that perhaps you got lost on the way here.\n\nNothing really new has happened in Shadowglen since I sent you my sigil, but I'll leave all the information gathering to you. Speak to the rest of the people around Aldrassil if you'd like.", completion = "Until then, know that our kind are needed more than ever in this tenuous time. Peace with the other races can fail at any moment, and there is much talk about members of the Horde looking to sow even greater seeds of distrust. Remember that.\n\nAs you gain in power and feel more prepared, come back to me here and I will see about getting you some training. It's important that you know how to handle your weapon of choice, among other things." }
WordHunterWoW_QuestEN[3119] = { title = "Hallowed Sigil", description = "This sigil was given to me by a messenger from our priest trainer, Shanda. It seems Shanda would have words with you when you have a moment. Read it and bring it to her afterwards.", objectives = "Speak to Shanda inside Aldrassil in Shadowglen.", progress = "It pleases me to see you've arrived so quickly, <name>. Welcome.\n\nAs you've probably heard, all of Teldrassil is stirring with the comings and goings of travelers. Even members of the Alliance have been allowed access onto Teldrassil's boughs in order to meet with other Kaldorei who prepare for the adventures ahead.", completion = "Do not concern yourself with the world below Teldrassil for now. There will be time for that later. Go now and speak to the others in Shadowglen--they can tell you more about what events have transpired. Help them in any way you can, and anytime you feel you need more training, come back to me and I will teach you what I can." }
WordHunterWoW_QuestEN[3120] = { title = "Verdant Sigil", description = "This sigil was given to me by a messenger from our druid trainer, Mardant. It seems Mardant would have words with you when you have a moment. Read it and bring it to him afterwards.", objectives = "Speak to Mardant Strongoak inside Aldrassil in Shadowglen.", progress = "Ah, young <class>. I see you're eager to continue your studies. Good.\n\nI wonder, have you spent much time in the Emerald Dream already? Perhaps you're not prepared for that yet... In time, I'm sure.\n\nBut until then, we should discuss other matters.", completion = "I will be your mentor and guide for now. It is my duty to teach you how to interpret not only what the spirits communicate to us, but also the complexities and secrets of the Emerald Dream.\n\nAs you learn and grow in power, you will learn more of our sleeping trance. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind." }
WordHunterWoW_QuestEN[3121] = { title = "A Strange Request", description = "Xerash Fireblade, located at the Lariss Pavilion, north of Camp Mojache,  has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.\n\nOff with you now -- to Xerash. Here, take this with you. It's a shrunken head that I promised Xerash in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure he will be pleased.", objectives = "Take the Shrunken Head to Xerash Fireblade at the Lariss Pavilion in Feralas.", progress = "Yes?", completion = "I have been waiting for Uzer'i to deliver this...\n\nLet me give you the herb mixture I prepared for his... well, experiments..." }
WordHunterWoW_QuestEN[3122] = { title = "Return to Witch Doctor Uzer'i", description = "Here are the herbs, <name>. Take them to Witch Doctor Uzer'i.\n\nPlease let him know that I am satisfied with the shrunken head.", objectives = "Deliver Xerash's Herb Pouch to Witch Doctor Uzer'i in Feralas.", progress = "Have you spoken to Xerash?", completion = "This is just what I need to prepare the muisek vessel, <name>.  Soon we will see if my latest incantations prove to be as powerful as I had hoped.\n\nPlease, a moment. I must perform the ritual and apply the herbs." }
WordHunterWoW_QuestEN[3123] = { title = "Testing the Vessel", description = "This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, <name>. With it, you will have the power to shrink and capture a creature inside of it.\n\nTravel to the wilderness east of here and look for beasts. The vicious, ironfur bears and longtooth runners are your targets, <name>. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.", objectives = "Kill 10 Ironfur Bears or Longtooth Runners, and use the Beast Muisek Vessel to shrink and capture the fallen beasts.\n\nBring 10 Beast Muiseks and the Beast Muisek Vessel to Witch Doctor Uzer'i in Feralas.", progress = "Were you able to capture the beasts?", completion = "Upon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, <name>, prevents the muisek from escaping. Now we may use it as we please!" }
WordHunterWoW_QuestEN[3124] = { title = "Hippogryph Muisek", description = "Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.\n\nHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.\n\nYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here.", objectives = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", progress = "Were you able to capture the hippogryphs?", completion = "After killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature. We would never be safe from its vengeance.\n\nThis is a dangerous job I have given you, <name>. Again, you have completed it well." }
WordHunterWoW_QuestEN[3125] = { title = "Faerie Dragon Muisek", description = "<name>, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, <name>. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", objectives = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, <name>. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me." }
WordHunterWoW_QuestEN[3126] = { title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, <name>. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", objectives = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, <name>. Our muisek collection is almost complete." }
WordHunterWoW_QuestEN[3127] = { title = "Mountain Giant Muisek", description = "The last task I will require of you is to travel to the northwest and find the final enemy.\n\nThe mountain giants left the mountains to aid the night elves when the burning legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", objectives = "Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, <name>. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish." }
WordHunterWoW_QuestEN[3128] = { title = "Natural Materials", description = "I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.\n\nI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned.", objectives = "Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", progress = "Were you able to collect the materials I need?", completion = "Excellent! These materials, combined with the muisek, should yield just the results we've been wanting." }
WordHunterWoW_QuestEN[3129] = { title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", objectives = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", completion = "As promised, you have your choice, <name>. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well." }
WordHunterWoW_QuestEN[3130] = { title = "Against the Hatecrest", description = "At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.\n\nAnyway, Latronicus awaits.  Good work thus far, <name>.  Keep it up.\n\nYou're dismissed.", objectives = "Report to Latronicus Moonspear in Feathermoon Stronghold.", completion = "Excellent, <name> - I value a \"can do\" attitude in those who I work with.\n\nI've been tasked by General Feathermoon to address the naga in a direct manner.  My plans are two fold: one, we will weaken their forces both in number and in command, and two, we will uncover what they are up to in the ruins.  With your help, we'll counter the naga presence without sacrificing the general security of the stronghold." }
WordHunterWoW_QuestEN[3141] = { title = "Loramus", description = "So you wish to battle demons? You would do well to listen to my tale.", objectives = "Listen to Loramus Thalipedes tell his story.", completion = "So be it..." }
WordHunterWoW_QuestEN[3161] = { title = "Gahz'ridian", description = "<name>, I'm a scientist, but also a treasure hunter at heart!\n\nLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian,\" after the hydra god.\n\nI did find some myself, but I'd like to have some more to study -- maybe you can find some?\n\nI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search begins!", objectives = "Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.", progress = "Are you having any trouble?\n\nYou can find Gahz'ridian just about anywhere in Tanaris, <name>, so keep looking!", completion = "Perfect; these ornaments are perfect for my studies. Thanks so much for the help, <name>.\n\nOh, can I get my helmet back?" }
WordHunterWoW_QuestEN[3181] = { title = "The Horn of the Beast", description = "The gigantic horn has numerous scratches and cracks. An unusual metal object is lodged into the rough surface.\n\nUpon further examination, you notice that the metal is actually a broken axe head. On the metal, the following words are etched:\n\nProperty of Mountaineer Pebblebitty.\n\nWhen you try and dislodge the broken axe head, it shatters into a million pieces.\n\nWoops!", objectives = "Take Margol's Gigantic Horn to Mountaineer Pebblebitty.", progress = "No, I will not open the gate.", completion = "What have you got there? A fake obviously!\n\nI've been face to face with Margol and I know for a fact that her horn is at least eight times larger than the one you've got in your hands, <name>. You probably got that off of a stormsnout in the Barrens. No sir, you can't fool Pebblebitty!" }
WordHunterWoW_QuestEN[3182] = { title = "Proof of Deed", description = "You expect me to believe a story like that? The real horn would have had my broken axe head still lodged into its surface.\n\nListen, take that obvious fake to Curator Thorius in Ironforge. If he can validate your claim, you will receive a proof of deed. Bring that proof back to me and I'll give you the key to the Searing Gorge.\n\nGet going!", objectives = "Take Margol's Gigantic Horn to Curator Thorius in Ironforge.", progress = "Why hello there young man. Would you like a tour of the museum?", completion = "What's this?\n\nOh my, I don't believe it! Do you realize what you've got here, <race>? This is the horn of Margol the Rager! Margol, the bane of every archaeologist that ever set foot in the Searing Gorge.\n\nMay I keep it?" }
WordHunterWoW_QuestEN[3201] = { title = "At Last!", description = "I can't believe Pebblebitty doubted the authenticity of the horn. Between you and me, I think she's just jealous. I know she really wanted to kill that beast herself, what with the 'incident' and all.\n\nSo you need a proof of deed? After the contribution you just made to the museum, it won't be a problem.\n\n<Curator Thorius begins to fill out a large document.>\n\nThere we go! You can take that back to Pebblebitty.", objectives = "Take the Proof of Deed back to Mountaineer Pebblebitty.", progress = "I don't believe it.", completion = "I don't know how someone as weak as you overcame Margol, but a deal is a deal. Here is the key.\n\nIf anything happens to you after this, it will be your own fault." }
WordHunterWoW_QuestEN[3221] = { title = "Speak with Renferrel", description = "While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons.  He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.", objectives = "Speak with Apothecary Renferrel at the Sepulcher.While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons. He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.", completion = "Ah, very good.  There is a matter regarding the wolf hearts you brought to me earlier that demands our attention." }
WordHunterWoW_QuestEN[3281] = { title = "Stolen Silver", description = "You may have killed the raptors, but the silver they stole must be recovered!  I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds.  It is likely that they brought our stolen silver there.\n\nGo to this raptor haven and search for the stolen silver.  When you find it, return it to me.", objectives = "Bring the Stolen Silver to Gazrog in the Crossroads.", progress = "Do you have the silver?", completion = "Aha!  So the raptors did hide the silver at their lair.  It's hard to believe these beasts would have the desire for silver.  Perhaps the stories of their intelligence are not as far from the mark as I thought!\n\nThank you, <name>.  Take this as a reward for your service to us, and know that the guards of the crossroads owe their next month's pay to you." }
WordHunterWoW_QuestEN[3301] = { title = "Mura Runetotem", description = "My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies.  Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life.  Perhaps the strange life found here in the Barrens can help her work in Silverpine.\n\nTake a sample of the shells you gathered, and bring it to Mura in Silverpine.  She is staying at the Sepulcher.  With luck, studying the shell will give her the insight she needs to heal that dying place.", objectives = "Speak with Mura Runetotem at the Sepulcher in Silverpine Forest.", progress = "I can smell the dust of the Barrens on you, <class>.  You have traveled far.", completion = "Ah, what is this?  This shell has an inner glow, as if it still pulses with life.  Amazing!  I must study it further.\n\nThank you, <name>.  With luck, this shell will hold a secret I can use to aid the poor land of Silverpine." }
WordHunterWoW_QuestEN[3321] = { title = "Did You Lose This?", description = "You have done much for the Order, <name>. The sheer dedication it takes to get this far would have turned away any ordinary person. There is no doubt in my mind, or in the mind of Galvan, that you are one of us.\n\nWhich is why I think you deserve a little reward. It is nothing really, just a trinket. You may be familiar with its properties, as I do believe it is what brought you to us in the first place.", objectives = "Wait for Trenton to finish his work.", completion = "Rise and be recognized, <name>, blacksmith of the Mithril Order." }
WordHunterWoW_QuestEN[3341] = { title = "Bring the End", description = "In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...\n\nThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.\n\nAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, <name>. An end must come to the Coldbringer.", objectives = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.", progress = "This matter is of utmost importance, <name>. We must stop any attempt by the Scourge to bolster their ranks.", completion = "The loyalty of a Lich is unswerving, <name>. Let them know that such loyalty will only bring them destruction." }
WordHunterWoW_QuestEN[3361] = { title = "A Refugee's Quandary", description = "I was on my way to join my fellow gnomes at Gnomeregan, but then it all went so horribly wrong!\n\nI left Anvilmar, bags packed and wading through waist-deep snow.  Then we had this ridiculous earthquake, and I got all turned around.  I ended up here, and what's worse: the trolls stole all my stuff!\n\n{name}, I've obviously proven myself to be quite incompetent over the last day and a half.  Would you mind infiltrating the troll camps southwest of here and returning my stuff to me?", objectives = "Obtain Felix's Box, Felix's Chest and Felix's Bucket of Bolts.", progress = "Once I get my tools, I'm outta here.", completion = "Huzzah, you've found them!  Get ready, women of Gnomeregan: here comes Felix!\n\nNow, which road takes me out of here..." }
WordHunterWoW_QuestEN[3362] = { title = "Thistleshrub Valley", description = "Have you ever seen Thistleshrub Valley? It's a mighty dangerous place, <name>.\n\nThose strange beasts there, I don't trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that's what I think they were called...\n\nAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there's no way I'm going back there. But here's where you come in -- if you clear some of them out, I just might think about going back. What do you think, <name>? Help me out?", objectives = "Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.", completion = "They're that big? I might have to rethink my plan...\n\nBut you did hold up your end of the bargain, so here's what I promised." }
WordHunterWoW_QuestEN[3363] = { title = "Corrupted Songflower", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[3364] = { title = "Scalding Mornbrew Delivery", description = "Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I'll never make it to Anvilmar before the brew runs cold!\n\nYou look fast.  Maybe you can make it.  This cup will only stay hot for five more minutes, and Durnan didn't order \"chilly\" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.\n\nThanks, <name>, and don't forget to bring me back my mug!", objectives = "Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!", progress = "Aye, I'm Durnan Furcutter.  You have something for me?", completion = "Ah good, now this will hit the spot.  Allow me to take a small break while I enjoy this scalding mornbrew!" }
WordHunterWoW_QuestEN[3365] = { title = "Bring Back the Mug", description = "Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go <name> - be a pal and take this empty mug back to Nori for me, would ya now.", objectives = "Return Nori's Mug to Nori Pridedrift in Coldridge Valley.", progress = "I trust the scalding mornbrew got to Durnan on time!  Did you remember to bring me back my mug?", completion = "Excellent, <name>!  You'd be surprised how many couriers I meet who forget to do something as simple as bring back the mug.  Mugs don't grow on trees, or so they tell me!\n\nHere's a little something for the effort.  Thanks again for your help." }
WordHunterWoW_QuestEN[3366] = { title = "The Glowing Shard", description = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.Upon completion of this quest you will gain:", objectives = "Travel to Ratchet to find the meaning behind the Nightmare Shard." }
WordHunterWoW_QuestEN[3367] = { title = "Suntara Stones", description = "<Dorius groans.>\n\nI'm badly injured, <race>. Feel... light headed... World spinning... Bleeding... internally.\n\nI must get back to Ironforge. Help me, <name>.", objectives = "Help Dorius get back to Ironforge.", completion = "This letter was dropped by Dorius when he was shot." }
WordHunterWoW_QuestEN[3368] = { title = "Suntara Stones", description = "Brother,\n\nIf you are reading this letter, I am no more. How it got to you, I do not know, but thank and reward the ones responsible.\n\nAbout the stones: They exist and the Dark Irons have them in their possession. Their leader, Lathoric the Black, is using the power of the stones to enslave my excavation team. They were taken to the cauldron. Their minds are twisted, working night and day to complete something called Obsidion.\n\nHelp them, brother. It is the final wish of a dead man.\n\n-Dorius", objectives = "Take the Singed Letter to Thorius in Ironforge. He is in the Hall of Explorers.", progress = "<Thorius sobs.>", completion = "<Thorius wipes his face dry.>\n\nIn the name of the Light, he will have his wish. This I vow." }
WordHunterWoW_QuestEN[3369] = { title = "In Nightmares", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, <name>, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.\n\nHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more.", objectives = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.", progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n<Hamuul peers into the shard>\n\nOh... I didn't... Well.\n\n<name>, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that you should not concern yourself with.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again." }
WordHunterWoW_QuestEN[3370] = { title = "In Nightmares", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, <name>, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... \n\nMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.", objectives = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.", progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n<Mathrengyl peers into the shard>\n\nOh... I didn't... Well.\n\n<name>, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that the Cenarion druids alone must attend to.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again." }
WordHunterWoW_QuestEN[3371] = { title = "Dwarven Justice", description = "There is an empty, vacuous hole, where my heart used to be, <name>. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.\n\nReturn to the Searing Gorge and fulfill his last request: Free his men. The Dark Iron dwarves force their slaves to work in a sweltering mine called the Slag Pits. Search there for Dorius' men.", objectives = "Return to the Searing Gorge and find Dorius's archaeology unit.There is an empty, vacuous hole, where my heart used to be, <name>. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.\n\nReturn to the Searing Gorge and fulfill his last request: Free his men. The Dark Iron dwarves force their slaves to work in a sweltering mine called the Slag Pits. Search there for Dorius' men.", completion = "Forget about me, help the others." }
WordHunterWoW_QuestEN[3372] = { title = "Release Them", description = "Release them, <race>. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.\n\nThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight's Hammer guard a relic. Retrieve it and place it on the altar of Suntara.\n\n<The dying archaeologist collapses.>", objectives = "Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge and bring it to the Altar of Suntara in the Slag Pit.", progress = "The altar is empty.", completion = "You place the mysterious artifact on the altar of Suntara." }
WordHunterWoW_QuestEN[3373] = { title = "The Essence of Eranikus", description = "As you touch the gem, a deep voice resonates in your mind.\n\n\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"", objectives = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", progress = "As you near the essence font that Eranikus told you of, his voice once again touches your mind.\n\n\"Yes mortal, this essence font will redeem what untainted element of my psyche remains imbued in this gem.  Place the gem inside the font, and let the magic of the Green Dragonflight cleanse the corruption and taint from my being.  Only then will I find true release, and only then will the Dragonflight be able to reassert their stewardship over the Atal'ai.\"", completion = "You place the gem inside the essence font.\n\n\"Thank you mortal, you have - no... this, this cannot be! No!  The corruption of this accursed god even taints the sanctity of a Green Dragonflight essence font!  No please, I feel my essence ripping from me!  THE PAIN!  I feel the grip of an eternal nightmare taking hold on me...\"\n\n\"Mortal, I implore you!  Find one of the Green Dragonflight to stop this... help me... I am chained in darkness... forever in agony... please do not torture...\"" }
WordHunterWoW_QuestEN[3374] = { title = "The Essence of Eranikus", description = "You engage the Oathstone, and Itharius speaks directly to your mind through the stone.\n\n\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"\n\n\"Do this <name>, and we will work together to redeem a soul worthy of redemption.\"", objectives = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows. It is there that you will make your choice to aid Ysera's Dragonflight or not.", progress = "Here we are <name>, at yet another crossroads.  The time has come to make another choice.  What choice do you make, mortal?", completion = "You have made your choice, and so it begins.  Your choices have been, to date, what I would consider to be the correct ones; your actions and deeds henceforth will determine whether this is to continue." }
WordHunterWoW_QuestEN[3375] = { title = "Replacement Phial", description = "Um... you need another phial of scrying?  You're kidding, right?  What did you do with the first one?!  We have a lot of work ahead of us here, <race>.  Those phials don't grow on trees!  Actually, I wish they did, because I'd go there and pick one off since I don't have another one!!\n\nin order to make you one, I need the following: a mana potion, a piece of coal, and some sweet nectar.  Don't ask why, just bring me what I ask and I'll make you a new one.", objectives = "Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying.", progress = "To make another phial I need a mana potion, a piece of coal, and some sweet nectar.\n\nThat, and a whole lotta patience apparently.", completion = "The mighty adventurer delivers.  Hooray for me.  By the way, I lied - I had another phial.  Ungh, take it.\n\nWell, what did you expect?!  \"Oh, here, have another one!  I'm just some goofball who has nothing better to do than hand out magical communication devices to adventurers!\"  Rest assured though, what you have given to me will be enough make you another phial when you lose that too.\n\nPlease prove me wrong and don't lose the new one, okay?" }
WordHunterWoW_QuestEN[3376] = { title = "Break Sharptusk!", description = "<name> - I have heard of you, newcomer.  Perhaps it is you that will help us, where others have failed.\n\nWe tauren have carved a home out of this land, but not without a cost.  The Bristleback quilboars of Brambleblade Ravine, led by Chief Sharptusk Thornmantle, have made our lives difficult with their continued war against us.  I charge you to bring me the chief's head!\n\nHe will be found in the ravine to the east in their makeshift village.", objectives = "Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.", progress = "Sharptusk will trouble us no more once you have brought me proof of his death.  It is his head that I seek, <name>.\n\nWe <race> live for the hunt, and there is no greater hunt than against one that is cunning enough to perhaps hunt us back.  If you are successful in this task, young one, you will start to learn what I mean.", completion = "Justice has been served on this day by your swift actions, <name>.  Let this deed serve as a warning to all who would threaten our home.\n\nYou have earned this reward to help you on your sojourn, young <class>." }
WordHunterWoW_QuestEN[3377] = { title = "Prayer to Elune", description = "Will you assist me, mortal? Hear my tale.", objectives = "Hear Zamael tell his tale.", completion = "I have accepted my fate here in this cage, but the prayer must be found." }
WordHunterWoW_QuestEN[3378] = { title = "Prayer to Elune", description = "Will you assist me, mortal? Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person.\n\nIf you do recover my prayer, take it to Astarii Starseeker in Darnassus. It matters little that my faith has been rekindled after the countless malevolent actions that I have taken against this world and its inhabitants, but my prayer must be heard. Absolution is the last thing I expect.", objectives = "Find the Prayer to Elune and take it to Astarii Starseeker in Darnassus.", progress = "What brings you to the Temple of the Moon, <name>?", completion = "Elune smiles upon you this eve, <name>. You have returned a lost soul to her. Please accept this as a token of our gratitude." }
WordHunterWoW_QuestEN[3379] = { title = "Shadoweaver", description = "The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade.\n\nRecently, a group of poachers has encroached upon these lands, carelessly slaying spiders en masse without so much as a thought as to the long term effect of their actions. The first task I ask of you, then, is a simple one: Find them... and end them.\n\nBegin your search to the north.\n\nIf you require assistance, speak with Raze.", objectives = "Kill the group of Shadow Silk Poachers that wander the Searing Gorge. Nilith has reason to believe that there are five of them that need to be exterminated. Return to Nilith in the Searing Gorge when this task is complete.", completion = "Excellent work, <name>.\n\nI am sure that this is a piece of shadoweave that you have not yet seen." }
WordHunterWoW_QuestEN[3380] = { title = "The Sunken Temple", description = "There are restless spirits in this world, <name>. There are spirits that have been tainted by their isolation, bound to an ancient evil...\n\nI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris.", objectives = "Find Marvon Rivetseeker in Tanaris.", completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you..." }
WordHunterWoW_QuestEN[3381] = { title = "A Meeting with the Master", description = "Ah, a young <race> come to speak to Sanath. What a wonderful day! I am so honored to have you grace me with your presence. Thank you!\n\nPlease... do not be so arrogant to assume my sarcasm was a compliment. Let us get one thing straight: I don't like you. But this little conversation doesn't have anything to do with us--it has to do with my master.\n\nBring me a couple hippogryph feathers for my arrows and I'll give you leave to see him. He's asked that I send adventurers to him if they proved worthy enough.Upon completion of this quest you will gain:", objectives = "Bring 2 Undamaged Hippogryph Feathers to Sanath Lim-yo in Azshara if you wish to speak to his master." }
WordHunterWoW_QuestEN[3382] = { title = "A Crew Under Fire", description = "We were just off the coast looking for a safe haven to make anchor. The sun hadn't been down for more than an hour when they attacked... those damned naga!\n\nI'm not sure what they were looking for, but it's clear they didn't find it--they've already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.\n\nI'm sorry you've come along now, <name>, but it's out of my hands.\n\nAre you ready for the fight of your life?", objectives = "Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive.", completion = "You've done it! Thank you! Surely this was one of the most brutal battles I've ever taken part in. I can't thank you enough.\n\nI only wish more of my crew could have lived through this trial.\n\nI would ask you to speak to any surviving passengers from the Horizon Scout. Some of them had business in the area, and may have a request or two of you if you're willing. Again, thank you for all your help." }
WordHunterWoW_QuestEN[3385] = { title = "The Undermarket", description = "They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price.\n\nIt gets worse, <name>. They have set up a base of operations here in the Searing Gorge. Trade Master Kovic is heading up the operation and has close ties with the Dark Iron dwarves of the region.\n\nWe must strike hard and send a message to their leadership. Slay Trade Master Kovic and his minion Clunk. Bring back his trader's satchel when the job is done.\n\nTo the Cauldron!You will receive:", objectives = "Slay Trade Master Kovic and his minion Clunk. Retrieve the Trader's Satchel from his corpse and return it to Nilith." }
WordHunterWoW_QuestEN[3402] = { title = "The Undermarket", description = "I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.", objectives = "Speak with Vizzklick in Gadgetzan.I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.", completion = "Kovic slain??! This is a glorious day, <name>! For years that scoundrel has been running shady undermarket trades, undercutting honest, hard working traders all over the world.\n\nYou deserve a fine reward for this accomplishment! And a fine reward you shall have!" }
WordHunterWoW_QuestEN[3421] = { title = "Return Trip", description = "", objectives = "I will return you to Sanath's camp now.\n\nDo not mind his bad manners--he is rude to everyone save for the master. Perhaps he shall learn his lesson one day." }
WordHunterWoW_QuestEN[3441] = { title = "Divine Retribution", description = "Hear my tale, adventurer.", objectives = "Listen as Kalaran Windblade tells his story.", completion = "Have you heard enough? Are you prepared to act?" }
WordHunterWoW_QuestEN[3442] = { title = "The Flawless Flame", description = "You have made the right decision, <name>.\n\nWe must strike where we will do the most damage: the four sentry towers.\n\nWith the four towers in flames, we can initiate an offensive before they have time to react.\n\nYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.\n\nBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.\n\nThe golems and elementals in these lands should be your first target.", objectives = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", progress = "Have you collected the materials?", completion = "Well done, <name>. We are almost ready." }
WordHunterWoW_QuestEN[3443] = { title = "Forging the Shaft", description = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.\n\nThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft.", objectives = "Bring 8 Thorium Plated Daggers to Kalaran Windblade.", progress = "Eight, <name>. I need eight!", completion = "You're an exceptional laborer, <name>. Have you ever considered a change of vocation? Perhaps a detective? Junk collector? Oh, I know, one of those silly gnomes that crawl across the beaches of Azeroth with their metal detecting contraptions, looking for lost treasure. Yes, that would be an ideal position for you." }
WordHunterWoW_QuestEN[3444] = { title = "The Stone Circle", description = "I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...\n\nRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more.", objectives = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", progress = "Ratchet is not far from here, <name>. The journey shouldn't take long.", completion = "Yes... This is the stone.\n\nIt's all coming back to me now, <name>..." }
WordHunterWoW_QuestEN[3445] = { title = "The Sunken Temple", description = "I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.\n\nGood luck finding him; he hasn't been heard from in some time.", objectives = "Find Marvon Rivetseeker in Tanaris.I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.\n\nGood luck finding him; he hasn't been heard from in some time.", completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you..." }
WordHunterWoW_QuestEN[3446] = { title = "Into the Depths", description = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple.", objectives = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", progress = "Upon examining the statue, you notice a depression in its side, just the size of the token that Marvon gave you...", completion = "You push the stone circle into the opening, and you hear it lock into place.\n\nNow that the stone is in place, you may continue... but what should you do next?\n\nPerhaps you should examine this altar further..." }
WordHunterWoW_QuestEN[3447] = { title = "Secret of the Circle", description = "My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, <name>. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...", objectives = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, <name>. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...", completion = "The eye of the idol glitters brightly even in the half-darkness of the temple. Its transparency reveals something shiny behind it. Sliding it to the side, you reach in and grasp what lies inside the statue.\n\nThe Atal'ai treasure is now yours." }
WordHunterWoW_QuestEN[3448] = { title = "Passing the Burden", description = "I've recently been handed the responsibility of investigating Azshara--a once beautiful area the elves called home. This would be back when they practiced magic. It's now a more dangerous place than it is beautiful, but that doesn't stop us from turning over every stone for answers to our past.\n\nA companion of mine named Tymor offered to help me investigate the area since he takes a particular interest in such things.\n\nHe owns a small place to the right of the Hall of Mysteries here in the city.", objectives = "Speak to Tymor in Ironforge.I've recently been handed the responsibility of investigating Azshara--a once beautiful area the elves called home. This would be back when they practiced magic. It's now a more dangerous place than it is beautiful, but that doesn't stop us from turning over every stone for answers to our past.\n\nA companion of mine named Tymor offered to help me investigate the area since he takes a particular interest in such things.\n\nHe owns a small place to the right of the Hall of Mysteries here in the city.", completion = "Ah, Karnik sent you, did he? I expected to hear from him soon. I've discovered such wonderful things about Azshara.. I know night elves have incredible life spans, but everyone forgets some of the more... unfortunate events in their lives sometimes. That's not meant as a criticism, just an observation.\n\nLong ago, there were cities created by the elves filled with knowledge about magic and other lost arts. Being a student of such things, I started my investigation. What I found was quite thrilling." }
WordHunterWoW_QuestEN[3449] = { title = "Arcane Runes", description = "Magic was once as revered as Elune herself to some elves. Some of their most powerful mages created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places.\n\nI would very much like rubbings of these runes from the Ruins of Eldarath. I have a kit for you to make the rubbings with, but it will be up to you to find them. Be careful though, the Explorer's League isn't the only one interested in Eldarath.", objectives = "Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up.", progress = "Well, well, well, glad to see you made it out here, <name>. Did you get the rubbings for Tymor?\n\nAs dangerous as this place is, there hasn't been too much action along the coast. That might be on account of the naga swimming underwater, but that's not my problem... I patrol the skies.", completion = "Good to see you safe and sound, <name>. I hope things weren't too tough for you.\n\nI'll get these to Tymor right away. He'll be thrilled to take a look at these things.\n\nGo ahead and toss the flare gun... probably won't be any good to you anymore anyway, and I already got a new one." }
WordHunterWoW_QuestEN[3450] = { title = "An Easy Pickup", description = "I want the rubbings delivered to my tower, but there's no need to have you go all the way there. I'll just have them air-lifted out of Azshara.\n\nXiggs Fuselighter owes me a favor or two and will be in the area soon--he's signed on to patrol the coast. Speak to him before you leave. He can give you a flare gun to signal him with. When you have the rubbings, just head to wherever he tells you and then give them to him so he can get them to my tower safely. He should be in the hangar in the Military Ward.", objectives = "Speak to Xiggs Fuselighter in Ironforge.I want the rubbings delivered to my tower, but there's no need to have you go all the way there. I'll just have them air-lifted out of Azshara.\n\nXiggs Fuselighter owes me a favor or two and will be in the area soon--he's signed on to patrol the coast. Speak to him before you leave. He can give you a flare gun to signal him with. When you have the rubbings, just head to wherever he tells you and then give them to him so he can get them to my tower safely. He should be in the hangar in the Military Ward.", completion = "What can I do for you, <name>? Kinda busy at the moment preparing my ship for a long trip. I just came over to see some of the tank pilots--I need some wendigo manes to line my cockpit and they usually have extra.\n\nI can give you a minute if you're brief... one of the boys just took off to Steelgrill's Depot to see if the pilots down there have extra manes for me." }
WordHunterWoW_QuestEN[3451] = { title = "Signal for Pickup", description = "Ah, so Tymor sent you, huh? Yeah, I owe him a favor or two. What's that? Why, that little devil. Yeah, I can help him out with that. So you'll need a flare gun and a location... easy enough.\n\nThere's a small island off the southern peninsula of Azshara that we've made a landing pad on. You take this flare gun, and use it there. I'll see your signal and come by to pick up this... whatever it is he wants.", objectives = "Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge.Ah, so Tymor sent you, huh? Yeah, I owe him a favor or two. What's that? Why, that little devil. Yeah, I can help him out with that. So you'll need a flare gun and a location... easy enough.\n\nThere's a small island off the southern peninsula of Azshara that we've made a landing pad on. You take this flare gun, and use it there. I'll see your signal and come by to pick up this... whatever it is he wants.", completion = "Here's my standard issue flare gun, and be patient after you fire off the gun--there are only a couple charges in one of these, and it might take me a minute to get to you depending on how far out to sea I am. Just look out to sea after you fire off the flare." }
WordHunterWoW_QuestEN[3452] = { title = "The Flame's Casing", description = "We need one final piece to form the torch.\n\nIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing.", objectives = "Find and return a Symbol of Ragnaros to Kalaran Windblade.", progress = "Without a suitable source of arcane energy, the torch of retribution cannot be completed.", completion = "The symbol radiates foul magic; perfectly suited for our task." }
WordHunterWoW_QuestEN[3453] = { title = "The Torch of Retribution", description = "Give me a moment to combine the pieces and apply the necessary enchantments.", objectives = "Wait for Kalaran Windblade to complete the Torch of Retribution.", completion = "There is one final task that you must complete." }
WordHunterWoW_QuestEN[3454] = { title = "The Torch of Retribution", description = "The torch must now be bound to its owner. Pick up the torch, <name>.", objectives = "Take the Torch of Retribution.The torch must now be bound to its owner. Pick up the torch, <name>.", completion = "You grab the torch with both hands; waves of hatred and anger pulse through your being." }
WordHunterWoW_QuestEN[3461] = { title = "Return to Tymor", description = "Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward. Just go knockin' and make sure he pays you good. This place ain't no picnic... that's for sure.\n\nThanks again for helping him out though, and good luck.\n\nOh, and I don't need the drawing kit. Why don't you just bring it back to Tymor when you go to see him?", objectives = "Return Tymor's Drawing Kit to him in Ironforge.", progress = "You're back! Excellent. Do you have my drawing kit also?", completion = "Wonderful! I'm so glad to hear it.\n\nI'm really excited to get to my tower and go over those rubbings. I'm so envious of you... going to a place like Azshara. That's any student of the arcane's dream, I would guess.\n\nWell, we never spoke about any kind of reward since you were just working for the Explorer's League, but you deserve something." }
WordHunterWoW_QuestEN[3462] = { title = "Squire Maltrake", description = "Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution.", objectives = "Speak with Squire Maltrake.Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution.", completion = "Are you prepared to make your strike?" }
WordHunterWoW_QuestEN[3463] = { title = "Set Them Ablaze!", description = "Listen well, <name>. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.\n\nWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.\n\nYou must enter each tower and use the torch of retribution within their fortifications. Beware the lookouts posted by the Dark Irons, <name>.", objectives = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.", completion = "It is glorious! Is it not glorious master?" }
WordHunterWoW_QuestEN[3481] = { title = "Trinkets...", description = "The chest appears locked.", objectives = "Open the chest.The chest appears locked.", completion = "The chest opens at your touch. How much cheese could possibly be in here? There is only one way to find out." }
WordHunterWoW_QuestEN[3483] = { title = "Signal for Pickup", description = "", objectives = "Ah, another flare gun, huh? That I can do.\n\nAnd don't forget, southern tip of Azshara. It's a small little island that's been turned into a landing pad. You can't miss it if you're in the right spot.You will receive:" }
WordHunterWoW_QuestEN[3501] = { title = "Everything Counts In Large Amounts", description = "Although you may never find a flawless sphere of draenethyst, you will undoubtedly uncover various imperfect fragments of the draenethyst in your exploration of these lands.\n\nWhile it is doubtful that Kum'isha will be able to use the flawed fragments to return home, the pieces may serve other, useful purposes for the draenei.\n\nReturn any piece of flawed draenethyst fragments that you may find and I shall reward you.", objectives = "Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in.", progress = "Have you had any luck in your exploration?", completion = "You truly disgust me, <race>. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight." }
WordHunterWoW_QuestEN[3502] = { title = "One Draenei's Junk...", description = "Well, after that display of voracious greed, I feel nauseous.\n\nRegardless, I shall not dwell too long on your material addiction.\n\nFor each imperfect draenethyst fragment you turn in, I shall reward you with more junk. My junk heap gets smaller while your junk heap gets larger. On Draenor we call this a 'win-win' situation.", objectives = "Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment.", progress = "Well? Draenethyst? Remember?\n\n<Kum'isha clenches his fist and knocks on your head.>\n\nIs anybody home?", completion = "You truly disgust me, <race>. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.\n\nSounds familiar? It should, because I say it a thousand times per day.\n\nOh how I loathe this world." }
WordHunterWoW_QuestEN[3503] = { title = "Meeting with the Master", description = "", objectives = "There was a time when I could ask whatever I wished from those who sought out my master.  But now, you need only ask and I will send you to him.\n\nIt is upsetting to me, but I do not question his orders.  I can only take enjoyment in making fun of the ridiculous clothes you wear or the pathetic look on your face.  Even that bores me...\n\nEven this rambling bores me!  Do you wish to see my master or not?" }
WordHunterWoW_QuestEN[3504] = { title = "Betrayed", description = "Betraying, thieving woman! That's what I call her--that's all she'll ever be!\n\nI may have made a grave mistake, <name>. I trusted a blood elf. What's worse, I trusted a woman!\n\nShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who's the fool--she's killed them all.\n\nI want vengeance, <name>, but I can't afford to send anyone else. Find Ag'tor at Valormok, north of the Haldarr Encampment. He'll tell you more.", objectives = "Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara.", progress = "Ah, Belgrom wizened up and finally sent someone not in his ranks to aid us, did he?\n\nThis camp used to be a dozen warriors strong, <name>, but now they're all dead. That mage, Rimtori, has slain them all. She played Belgrom like a lute... seduced him even. It's none of my business, but between you and I, she is quite the temptress. That's probably why I'm still out here helping Belgrom--I probably would have done the same thing.", completion = "We've sent everything we had at her and her workers, but they are strong in battle. None have bothered to return. I'm assuming some have died, but I'm sure others simply ran... cowards.\n\nBut now that reinforcements have arrived, perhaps there's still something we can do. Perhaps we can still punish her for lying and betraying Belgrom.\n\nWhat do you say, are you in?" }
WordHunterWoW_QuestEN[3506] = { title = "Betrayed", description = "A few more moments of thought brings a few ideas to mind, one of which brings a smile to your face: perhaps destroying the crystals would upset the blood elf responsible for the slaughter of so many orcs and the betrayal of Belgrom?\n\nYou continue to decipher more of the script and pictures and realize that one of the crystals is tied to the creator of the circle--the others are tied to something far more sinister.\n\nYou close the book and begin to decide which crystal to destroy.", objectives = "Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara.", progress = "How goes your slaughter of the blood elf traitors, <name>? Have you made any progress?\n\nI hope you are the one strong enough to bring that dog to her knees! She deserves nothing but a painful death for all that she has done!", completion = "RAR!! Incredible!\n\nYou've done it! Belgrom will be pleased! Finally the spirits of dozens of our warriors can be at peace. Thank you, <name>." }
WordHunterWoW_QuestEN[3508] = { title = "Breaking the Ward", description = "You are foolhardy, <name>. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.\n\nTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.\n\nBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power.", objectives = "Wait for Loramus to complete the enlightenment spell.", completion = "The name of the beast must be found." }
WordHunterWoW_QuestEN[3509] = { title = "The Name of the Beast", description = "There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.\n\nWhen such a weapon is forged, the demon and all under his command are vulnerable.\n\nA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.\n\nUndoubtedly, you will have to pay a price for such information.", objectives = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.\n\nWhen such a weapon is forged, the demon and all under his command are vulnerable.\n\nA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.\n\nUndoubtedly, you will have to pay a price for such information.", completion = "A demon lord?\n\n<Lord Arkkoroc laughs.>\n\nPerhaps the one can assist you with this information; but first, you must assist the one." }
WordHunterWoW_QuestEN[3510] = { title = "The Name of the Beast", description = "She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.\n\nFor that, you will be given the name that you seek and something else of equal importance.\n\nShe roams the clutch... Hetaera she is called.\n\n<Lord Arkkoroc points to the southwest.>\n\nGo!", objectives = "Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc.", progress = "<Lord Arkkoroc bends down to inspect you.>\n\nWhere are they?", completion = "Finally, one worthy of the wisdom of Arkkoroc!" }
WordHunterWoW_QuestEN[3511] = { title = "The Name of the Beast", description = "As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.\n\nThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.\n\n<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>\n\nTake the temper back to Loramus along with the name of the beast: Rakh'likh.", objectives = "Take the temper back to Loramus Thalipedes.", progress = "You return! Astounding, <race>. Did you discover the true name?", completion = "The temper will add the necessary vitriol we require for the forging of the weapons. There is but one more step in their creation." }
WordHunterWoW_QuestEN[3512] = { title = "In Eranikus' Own Words", description = "<name>, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us still.", objectives = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.<name>, our first step will be to devise a method to speak with Eranikus through the gem. He lies in a precarious state between sleep and death now, twisted within a weave of nightmares. Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker. He is a human medium who speaks for the dead. Though Eranikus is not truly dead, he may be of aid to us still.", completion = "Itharius was wise to send you to me.  While he is not dead as you understand death, Eranikus will soon give us advice in his own words.  For now though, I cannot directly help you... at least not yet.\n\nI will lend my skill at death-speaking to you, but first I need the help of one who - unlike me - is not limited by the frailties of old age.  My most potent augury device has been taken from me against my will, and unless I have it back we will be at a loss to help Eranikus." }
WordHunterWoW_QuestEN[3513] = { title = "The Runed Scroll", description = "The official-looking scroll is wrapped tightly with a silvery ribbon. You're sure someone would be interested in seeing this, but who?\n\nThere is an outpost close to the Ashenvale border to the north, and if the information on this scroll involves the night elves, this would be the place to take it.", objectives = "Take the Runed Scroll to the northern guard tower in the Barrens.", progress = "Whaddya got?", completion = "Well now... Where did you find this?" }
WordHunterWoW_QuestEN[3514] = { title = "Horde Presence", description = "This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak.\n\nShe'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here. The Horde will not tolerate her outrunners here.\n\n<name>, travel to the Talon Den. Kill Rynthariel, and then put up a symbol for all to see. Take this Horde flag, <name>. Put it up in the Talon Den so that they will not be so rash as to send another messenger through our territory again.", objectives = "Kill the leader of the Talon Den, Rynthariel the Keymaster.", completion = "You're a tough one! Ridding the Den of Rynthariel is a major step, <name>. They will be slow to regroup, and so we can count on less Alliance runners in the Barrens. They will think again before sending another this way.\n\nThank you." }
WordHunterWoW_QuestEN[3517] = { title = "Stealing Knowledge", description = "I admit, <name>, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.\n\nBefore I left, I did some research and you would be surprised how many valuable items are lying around.\n\nI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.\n\nThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more.", objectives = "Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara.", progress = "The tablets I'm having you gather should bring in a pretty copper or two to the right parties. I'll tell you who we need to deliver them to after you've found them. But I'm no fool... you'll get your share after I have proof that they've been delivered.\n\nSo get to it--we don't have all day. I might have to find someone else to help me.", completion = "Perfect, <name>, and in good condition also. These should get us a good price from all the parties concerned.\n\nLet's not dawdle around here any longer than we have to. We have some money to make." }
WordHunterWoW_QuestEN[3518] = { title = "Delivery to Magatha", description = "The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.\n\nBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims.", objectives = "Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff.", progress = "Yes, <name>. What can I do for you? I have many matters I must attend to, so please, be quick.", completion = "Ah, at long last, the Tablet of Beth'Amara. I was wondering if my partnership with Jediga had failed or if the poor orc had found her death in Azshara. I am glad she was successful.\n\nBeth'Amara was one of the Highborne's most influential alchemists. The wizard alone was said to have mastered transmuting metals among other things." }
WordHunterWoW_QuestEN[3519] = { title = "A Friend in Need", description = "Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.\n\nPlease tell Dirania Silvershine. She will be able to help me.\n\nHurry... I'm so dizzy...", objectives = "Speak to Dirania Silvershine in Shadowglen.Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.\n\nPlease tell Dirania Silvershine. She will be able to help me.\n\nHurry... I'm so dizzy...", completion = "Oh dear; I was wondering why I hadn't seen Iverron yet today. And I've always warned him about those spiders..." }
WordHunterWoW_QuestEN[3520] = { title = "Screecher Spirits", description = "I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.\n\nTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.\n\nReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.", objectives = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", progress = "Have you collected the essence of the screecher spirits, <name>?", completion = "You have done well, <name>.  Perhaps now it is time to reveal more...\n\nThere is an ancient prophecy among the trolls, where the dead god Hakkar, the Soulflayer, will one day return to this earth.  Some say the coming of Hakkar will bring joy and glory to trollkind, while others believe his resurrection marks the end of all things.\n\nI do not believe this myth, but I do know the essence of Hakkar holds great power, and this power should be kept from those who would abuse it..." }
WordHunterWoW_QuestEN[3521] = { title = "Iverron's Antidote", description = "I'm really worried about my friend Iverron. He's  been gone for nearly a day and I fear he may have been poisoned... or worse.\n\nI want you to gather the materials to make an antidote just in case. Gather hyacinth mushrooms from the base of the nearby trees, moonpetal lilies from around the water, and a webwood ichor from one of the spiders to the north.\n\nMixing it all together is simple enough, even if he's poisoned. He was heading north to Shadowthread Cave, hopefully you can find him near there.", objectives = "Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor.", progress = "Please, collect the ingredients, <name>. Iverron needs our help.", completion = "Thank Elune that you have gathered these ingredients so quickly!\n\nIn just a moment, I will have the antidote prepared." }
WordHunterWoW_QuestEN[3522] = { title = "Iverron's Antidote", description = "The antidote is ready, <name>. Please see that Iverron drinks it.\n\nThere is something that you should know -- the antidote -- it will only remain viable for 5 minutes. You must get it to him in time.\n\nSpeed be with you, <name>.", objectives = "Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north.", progress = "Oh... <name>, I'm so glad you have returned.", completion = "What is this, <name>?\n\nOh, I knew Dirania would be able to help me!\n\n\n\nI'm always getting into trouble and Dirania, well, she always manages to help me out of it.\n\nI am feeling much better, but I think I will sit here for a while longer, until I feel completely better. Well, that, and I was hoping you'd clear a path for me through those vicious Webwood spiders..." }
WordHunterWoW_QuestEN[3523] = { title = "Scourge of the Downs", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too much.", objectives = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us <name>, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.\n\nNow, let me bring you up to speed on what's been going on..." }
WordHunterWoW_QuestEN[3524] = { title = "Washed Ashore", description = "Majestic sea creatures are known to launch themselves at the Darkshore coastline, beached there until they die. Lately, these beasts have been washing ashore in ever-increasing numbers.  I've been sent here by the Temple of the Moon to investigate, but the presence of murlocs along the water has made my research difficult.\n\nThere is a giant creature washed ashore just south of Auberdine that is ringed by the foul Greymist murlocs.  Could you go there and retrieve bones from the creature for our study?", objectives = "Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine.", progress = "It is only recently that these creatures started landing on the coast of Darkshore in such alarming numbers.  I can't help but think that this is an ill omen of some sort.  Recovering a sample of that creature's bones to the south would help us in Darnassus assess this situation!", completion = "I hope the murloc did not give you much trouble in collecting this for us!  I will be sure to get this on the next hippogryph to Darnassus.  The Temple of the Moon has given me some funds to hand out for assistance; please have some with our thanks.\n\nYour success here emboldens me to offer you a chance to aid the Temple of the Moon further, if you are interested..." }
WordHunterWoW_QuestEN[3525] = { title = "Extinguishing the Idol", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.\n\nAre you with me?!", objectives = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.\n\nProtect Belnistrasz while he performs the ritual to shut down the idol.", completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in mortals such as yourself has been once more renewed.  Take this as a reward befitting of a hero.\"" }
WordHunterWoW_QuestEN[3526] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n<name>, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well <name>, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked <name>, and you might learn something." }
WordHunterWoW_QuestEN[3527] = { title = "The Prophecy of Mosh'aru", description = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.\n\nBring me the Mosh'aru tablets!\n\nThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\n\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\n\nWhen you have the tablets, bring them to me.", objectives = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", progress = "Do you have the tablets of the Prophecy of Mosh'aru, <name>?\n\nWhen I gain the tablets, I will study them, and learn how to contain the essence of Hakkar!", completion = "Ah, this is good.  I can fuse these ancient tablets together, and then study their hidden secrets.\n\nMy debt to you grows, <name>.  And it will grow further still." }
WordHunterWoW_QuestEN[3528] = { title = "The God Hakkar", description = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the Egg of Hakkar.", objectives = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", progress = "Have you defeated the avatar of Hakkar, <name>?  Has his essence yet empowered the egg I gave you?", completion = "The essence of Hakkar has been collected!  Even now the Egg stirs with life!  Could the myths of Hakkar be true?\n\nThat must not be true, for it is then I fear what Hakkar may do if birthed again.  I will keep this egg safe and be sure it does not fall into evil hands.\n\nYour labors with me are finished, <name>.  You have touched a legend, and your actions may one day change the face of our world." }
WordHunterWoW_QuestEN[3541] = { title = "Delivery to Jes'rimon", description = "I have a fence in Orgrimmar. He resides in The Drag. He's difficult to nail down if you don't know where to look, but if you go looking in one of the highest buildings there you should have no problem finding him.\n\nDo me a favor though, don't go shouting to all of Kalimdor that he's there and what his business is--it'd be bad for both of us.\n\nHe'll give us more than a fair price for the Tablet of Jin'yael. I'm not sure why, but you should have seen how excited he was to hear about its whereabouts.", objectives = "Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar.", progress = "Yes, what you be needin', mon? I got many tings to be takin' care of today, and you not be on me agenda as one of them. Pester me, and I make sure that changes.", completion = "Ahhh, Jediga be sendin' her package all the way from Azshara. Good. I be waitin' on this.\n\nJediga, now that be a fine woman... deadly too. What could be better?\n\nLook at this... the tablet be in perfect condition. You make a good messenger, <name>." }
WordHunterWoW_QuestEN[3542] = { title = "Delivery to Andron Gant", description = "Andron Gant is my next contact. He usually holds himself up in the Undercity... right near the Apothecarium.\n\nHe was a little more loose-lipped when it came to speaking about what he wanted the Tablet for. Apparently some of the mages of Undercity are looking to study some of the arcane spells the highborne used. They think this tablet will help them. Markri was adept at summoning creatures; especially elementals.\n\nTake the Tablet of Markri and return to me for your part of the reward.", objectives = "Bring the Tablet of Markri to Andron Gant in Undercity.", progress = "Well... <hic>... isn't this a surprise? An adventurererere... <hic>!\n\nWhat c'n I do for you... <hic>?", completion = "Here, take some coin... get yerself... <hic>... some new armor or something....\n\nThis'll bring a shiny gold or two to the right... <hic> people." }
WordHunterWoW_QuestEN[3561] = { title = "Delivery to Archmage Xylem", description = "This final tablet goes to someone very dangerous, <name>. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.\n\nArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.\n\nHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath.", objectives = "Bring the Tablet of Sael'hai to Archmage Xylem in Azshara.", progress = "What can I help you with, <name>?", completion = "Ah, the Tablet of Sael'hai... how long I've longed to study it.\n\nThank you, <name>. You may tell Jediga that she has done well. This will definitely be worth the payment she asked for." }
WordHunterWoW_QuestEN[3562] = { title = "Magatha's Payment to Jediga", description = "Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.\n\nGo swiftly, <name>. Tell your master I will be awaiting her here.", objectives = "Deliver Magatha's Note to Jediga in Azshara.", progress = "Well, what did Magatha say? The old crone... I bet she was less than polite.", completion = "Ah, good. She was much more reasonable than I expected... at least towards you. I half expected her to have you punished for my insolence in sending someone in my place. She must really want that tablet. Interesting.\n\nSomething to ponder another time." }
WordHunterWoW_QuestEN[3563] = { title = "Jes'rimon's Payment to Jediga", description = "Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.\n\nYou tell her she come back to Orgrimmar fast and Jes'rimon make sure he take good care of her.\n\nTell her that, and maybe in the future I have need of your services again, <name>.", objectives = "Deliver Jes'rimon's Note to Jediga in Azshara.", progress = "Have you spoken to Jes'rimon yet?\n\nHe's a boar among trolls, but his information is usually accurate and his jobs well paying.\n\nIf you can stand his attitude then you stand to make some good coin from his business endeavors.", completion = "I can see he was more than pleased by the looks of his note.... a little too pleased.\n\nPerhaps some day I'll take time to make sure he knows how much I appreciate his advances also. Well, at least there's one reason to look forward to spending more time in Azshara.\n\nHere's your share of our payment." }
WordHunterWoW_QuestEN[3564] = { title = "Andron's Payment to Jediga", description = "Here... take... <hic> this to Jediga. Good luck to ya!", objectives = "Deliver Andron's Note to Jediga in Azshara.", progress = "Have you met with Andron yet? He rarely leaves Undercity, so I don't think it'd be too hard to find him.", completion = "Perfect... wait a minute.\n\nHaha! What'd you tell him when you delivered the tablet, <name>? He overpaid us way too much! Not that I'm complaining. Did you tell him the deal changed? Or was he drunk again?\n\nDoesn't matter... here, take an extra share also." }
WordHunterWoW_QuestEN[3565] = { title = "Xylem's Payment to Jediga", description = "What is it? Oh yes, your payment. Of course.\n\nTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return.", objectives = "Deliver Xylem's Note to Jediga in Azshara.", progress = "Well, what did Xylem have to say? He didn't do anything to you, did he? Cast a spell on you? Con you into doing work for him?", completion = "No problems? None at all? Well, that's something to be said... I expected him to show some sort of reluctance or to at least betray our deal. Hmm, maybe he can be trusted after all.\n\nWell, no need to dwell on it that much. Here's your share. Thank you for your help." }
WordHunterWoW_QuestEN[3566] = { title = "Rise, Obsidion!", description = "It... It... It was all a trap.\n\nForgive... me.\n\nKill the traitor... Kill him for us... for Thorius.", objectives = "Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion.", progress = "I don't believe you! Show me proof!", completion = "<Thorius' face turns white.>\n\nThis... this cannot be. My own brother? He set this all up?\n\n<Thorius' face contorts in anger.>\n\nHe betrayed me, he betrayed Ironforge! It seems as if the influence of the Old Gods is still strong in these lands. I fear that if my brother - a once noble and honorable man - was so easily turned to the will of Ragnaros, no one is safe." }
WordHunterWoW_QuestEN[3567] = { title = "To the Top", description = "", objectives = "Would you like to see the view atop one of the twin colossals? I can send you there, <race>.\n\nDo consider how you will get down, though. This is a one way trip only." }
WordHunterWoW_QuestEN[3568] = { title = "Seeping Corruption", description = "See that tauren behind me--the one who looks like she's going to be ill at any moment? She was in Azshara recently. She claims she was wounded by some naga while making her way through the Ruins of Eldarath.\n\nAfter fighting off a few of them, she took a break on the beach and drank from one of the tide pools. Now she's feeling nauseous... among other things.\n\nI'd like to find out what she drank. Take this box, in it are some empty vials I labeled. Fill each at different pools and come back.", objectives = "Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely.", progress = "You know where this is leading, don't you, <name>? There's no way she can survive... look at her. The best thing for her now is to aid us in finding a cure for the plague. This water she drank might have a clue that helps us figure out how. She's going to die anyway--she might as well die doing something noble for our people before she does. Don't you agree?", completion = "Wonderful. You're back before she died. Good, good.\n\nLet's get started on this then, shall we?\n\nI've been studying her symptoms for some time now, and it's quite ugly. I'm surprised she's still standing. She's vomited three or four times all over the place... quite a pleasant odor.\n\nGive me just a moment to put something together to test on our... friend." }
WordHunterWoW_QuestEN[3569] = { title = "Seeping Corruption", description = "Give this to Thersa. Perhaps it will cure her... perhaps not. We really won't know until after she drinks it.", objectives = "Give Cuely's Elixir to Thersa Windsong in Undercity.", progress = "I've come to Undercity because I heard their alchemists have been studying long and hard on how to find a cure for their own illness. It was suggested that perhaps they could help me too.\n\nAlthough this place makes me feel far from welcome, I had no choice--the sickness that found me is tearing me up inside and I needed their help immediately.", completion = "Chemist Cuely has been very accommodating... disturbingly so. But if he says this will help me, then I have no other choice. I don't have time to find any other solution. I've already spoken to priests and shamans, none of which could help me.\n\nLet us hope that the Earthmother watches over my spirit." }
WordHunterWoW_QuestEN[3570] = { title = "Seeping Corruption", description = "", objectives = "I never dreamed the elixir would take hold that quickly. Thank you, <name>. I will get to work on the rest of these samples right away. I'm sure they'll be usable by the Lady Sylvanas and the Forsaken soon enough.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[3601] = { title = "Kim'jael Indeed!", description = "Kim'jael indeed!! Do you know what Kim'jael means to the Blood elves, <name>? Little rat... or something like that. The big bullies!\n\nThey hired me to help them scout the area looking for some sort of lost treasures. Of course I jumped aboard the moment they said \"treasure\" and the amount they were willing to pay, but of course, they turned on me and tried to kill me... ME!\n\nGoes to show you, you can't trust a Blood elf.\n\nThe problem is, they still have my equipment and I can't get it back. Help me out?", objectives = "Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara.", progress = "Those stinkin' Blood elves. I tell ya, if I was as strong as you are, I'd go down there and teach them a thing or two myself! But I'll have to settle with payin' you to take care of 'em for me.", completion = "Haha! You got them good, didn't you?!\n\nThis is great! That'll teach those Blood elves to betray their partners... especially someone as loyal as a goblin merchant! Bah, Blood elves...!\n\nWell, the least I can do for you is pay you for your time... just like I said I would.\n\nHere you go... those should be useful." }
WordHunterWoW_QuestEN[3602] = { title = "Azsharite", description = "The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.\n\nThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.\n\nYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal.", objectives = "Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.\n\nReturn to Loramus when the task is complete.", progress = "Evil does not sleep, fool. You will have time for rest when you are finally dead. Now, bring me those crystals.", completion = "Your tasks in Azshara are complete, mortal. I must now forge the necessary components for the next step in your adventure." }
WordHunterWoW_QuestEN[3621] = { title = "The Formation of Felbane", description = "The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.\n\nIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.\n\nMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.", objectives = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.", progress = "Loramus, eh? It has been many years since I have heard that name.", completion = "My goodness, I can only imagine what you went through to get these materials. Few venture into Azshara and return alive, let alone those that face demi-gods and giants!" }
WordHunterWoW_QuestEN[3625] = { title = "Enchanted Azsharite Fel Weaponry", description = "<name>, the creation of each weapon will take some time.\n\nAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!\n\nNow give me a moment to craft your weapon, <name>.", objectives = "Wait for Galvan to finish forging the weaponry.", completion = "<Galvan wipes the sweat from his brow.>\n\nA finer demon slayer has never existed, <name>." }
WordHunterWoW_QuestEN[3626] = { title = "Return to the Blasted Lands", description = "The hour of redemption is near, <name>. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective.", objectives = "Return to the Fallen Hero of the Horde at Splinterspear Junction in Swamp of Sorrows.", completion = "You look battle hardened, <name>. Are you prepared to face Razelikh and his minions?" }
WordHunterWoW_QuestEN[3627] = { title = "Uniting the Shattered Amulet", description = "To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.\n\nGo <name>! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!", objectives = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.\n\nRemember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...", progress = "The three shall form the one, the one shall light the way.", completion = "The amulet of Razelikh the Defiler is once again complete but he senses the disruption in his chain of command. He knows you come for him..." }
WordHunterWoW_QuestEN[3628] = { title = "You Are Rakh'likh, Demon", description = "Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, <name>. Use it on the Altar of the Defiler.\n\nShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.", objectives = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.", progress = "There is nothing left to fear.", completion = "Today is a day that will be remembered for all eternity. The demonic overlord of the Blasted Lands has finally fallen!" }
WordHunterWoW_QuestEN[3629] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n<name>, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well <name>, you were wise to seek my tutelage! Any schlep can become an expert at the basics of 	engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked <name>, and you might learn something." }
WordHunterWoW_QuestEN[3630] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n<name>, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!" }
WordHunterWoW_QuestEN[3631] = { title = "Summon Felsteed", description = "Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.\n\nHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.\n\nDo not dawdle long.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Strahad Farsan in the Barrens.Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.\n\nHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.\n\nDo not dawdle long.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[3632] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n<name>, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark here in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!" }
WordHunterWoW_QuestEN[3633] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n<name>, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan in Tanaris.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well <name>, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked <name>, and you might learn something." }
WordHunterWoW_QuestEN[3634] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely often work.\n\n<name>, read this manual.  If you wish to learn how to make metal paper weights, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!Upon completion of this quest you will gain:", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge." }
WordHunterWoW_QuestEN[3635] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n<name>, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", progress = "Hello there! If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance. Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh? Well, you've come to the right gnome. While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today. If you're a capable student, I'll teach you what I know." }
WordHunterWoW_QuestEN[3636] = { title = "Bring the Light", description = "The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, <name>.\n\nIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.\n\nAlign yourself with the Light, <name>; put an end to this evil union.", objectives = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.", completion = "Thank you , <name>. The Scourge will now think twice before attempting to bolster its ranks again.\n\nMay you be blessed by the Light." }
WordHunterWoW_QuestEN[3637] = { title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n<name>, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", progress = "Hello there! If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance. Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh? Well, you've come to the right gnome. While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today. If you're a capable student, I'll teach you what I know." }
WordHunterWoW_QuestEN[3638] = { title = "The Pledge of Secrecy", description = "Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a goblin engineer, that's that.  There is no access to gnome engineering at all.\n\nIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, <name>.", objectives = "If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan.", progress = "If you've signed the document and are ready to hand it to me, then that is that.  You've been told that this is a one way trip.  If you're ready, then hop on board!", completion = "Welcome aboard, Goblin Engineer <name>!  You soon will have access to the most powerful engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your goblin-oriented engineering work.  From there, we'll help you build a plan to maximize your goblin engineering talents!" }
WordHunterWoW_QuestEN[3639] = { title = "Show Your Work", description = "The gleam in your eye tells me everything; you want to blow things up.  You have budding talent, <name>, but I'd like to get some samples of your work so I might examine it for ways to emphasize goblin-oriented techniques.  I'll need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!\n\nSubmit these items to me and you'll be an official goblin engineer!", objectives = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan.", progress = "Once I receive your crafted engineering items for my review, I will grant you the last bit of knowledge required to join our exclusive little club, the goblin engineers!", completion = "It appears you are indeed ready for proper training.  I dub you Goblin Engineer <name>!\n\nYou'll be able to access any Goblin Engineer for some diabolical creations.  Have fun and try not to blow your face off." }
WordHunterWoW_QuestEN[3640] = { title = "The Pledge of Secrecy", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, <name>.", objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge.", progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nThe secrets I will share with you are of such a magnitude that the signing of the Pledge of Secrecy is absolutely critical.  I signed one, as did my brother and sister gnome engineers.  You will be joining quite the auspicious fold, Engineer <name>!", completion = "Welcome aboard, <name>!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!" }
WordHunterWoW_QuestEN[3641] = { title = "Show Your Work", description = "If you're ready to make some truly fantastic devices, then you've come to the right place.  And I can see you're a skilled engineer, but I want some samples of your work.  What I hope to do though is to analyze your craftmanship for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and you'll be an official gnomish engineer with access to all the schematics!", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge.", progress = "Once I receive your crafted engineering items for my review, you can become a certified gnomish engineer, granting you unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Today is the day you become a real engineer, <name>.  Don't worry about all those messy bombs and explosives, because it's time to shine!" }
WordHunterWoW_QuestEN[3642] = { title = "The Pledge of Secrecy", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, <name>.", objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay.", progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nWhile I may vehemently disagree with Gnomeregan - especially that fool Tinkmaster Overspark - politically, the Pledge of Secrecy transcends everything else!  You must agree to commit a single path and stay true to that path throughout your life.", completion = "Welcome aboard, <name>!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!" }
WordHunterWoW_QuestEN[3643] = { title = "Show Your Work", description = "If you're ready to make some truly fantastic devices, then you've come to the right place.  And I can see you're a skilled engineer, but I want some samples of your work.  What I hope to do though is to analyze your craftmanship for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and you'll be an official gnomish engineer with access to all the schematics!", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay.", progress = "Once I receive your crafted engineering items for my review, you can become a certified gnomish engineer, granting you unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Today is the day you become a real engineer, <name>.  Don't worry about all those messy bombs and explosives, because it's time to shine!" }
WordHunterWoW_QuestEN[3644] = { title = "Membership Card Renewal", description = "", objectives = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to goblin engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
WordHunterWoW_QuestEN[3645] = { title = "Membership Card Renewal", description = "", objectives = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of gnome engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to gnome engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
WordHunterWoW_QuestEN[3646] = { title = "Membership Card Renewal", description = "", objectives = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to goblin engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
WordHunterWoW_QuestEN[3647] = { title = "Membership Card Renewal", description = "", objectives = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of gnome engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to gnome engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
WordHunterWoW_QuestEN[3661] = { title = "Favored of Elune?", description = "Wildkin are quite unpredictable creatures, <name>. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.\n\nThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.\n\nRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?", objectives = "Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.", progress = "Try to avoid them if you can, <name>. The Wildkin may misread your interest as an intent to do them harm...", completion = "Thank you for bringing these to me, <name>.\n\nWhat did you learn of the Wildkin?\n\nPerhaps these feathers will tell us more. Ferocious monsters, or simply misguided pets? One day I'd like to know the truth...\n\nI am going to continue my research -- please come back and talk to me again after some time has passed." }
WordHunterWoW_QuestEN[3681] = { title = "Tome of Divinity", description = "Sorry to interrupt your travels, <race>, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.\n\nIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.\n\nLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.Upon completion of this quest you will gain:", objectives = "Speak with Duthorian Rall in Stormwind.Sorry to interrupt your travels, <race>, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.\n\nIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.\n\nLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[3701] = { title = "The Smoldering Ruins of Thaurissan", description = "Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.\n\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, <name>. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.", objectives = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", completion = "Oh my! This information explains quite a lot about Thaurissan.\n\nThere is much more to learn!" }
WordHunterWoW_QuestEN[3702] = { title = "The Smoldering Ruins of Thaurissan", description = "Would you like to hear a brief history of the Dark Iron dwarves?", objectives = "Listen to Royal Historian Archesonus recant the history of Thaurissan.", completion = "Shall we proceed?" }
WordHunterWoW_QuestEN[3721] = { title = "An OOX of Your Own", description = "", objectives = "You've recovered three of my OOX homing robots!  You've gone above and beyond what you needed to, so I will give you something special for all your help.  It is a miniature version of the very same robot that you have come to know and love, the OOX!\n\nI normally wouldn't let anyone have such a potentially lethal device, but you've been a real help.  Besides - the combat mechanisms and the homing logic on this one have been disabled.\n\nOther than that, it's an OOX by golly!" }
WordHunterWoW_QuestEN[3741] = { title = "Hilary's Necklace", description = "My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", objectives = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.", progress = "Hi.  I miss my necklace.  My daddy got it for me.  Daddy says that there are monsters in the lake.  Did you beat up any monsters?", completion = "Thank you for finding my necklace mister <class>... you are very kind!  My kitty thanks you too - isn't that right Effsee?" }
WordHunterWoW_QuestEN[3761] = { title = "Un'Goro Soil", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  The Cenarion Circle wants to study this soil in large quantities; go into the wilds of Un'Goro and acquire enough of it for our continued research.\n\nThe rich soil will stick out in piles from time to time, and some of the beasts might have usable samples on their being.  Take them all outside to Ghede; just look for the piles of dirt and the tauren barking orders.  He means well, just don't get him riled up though!", objectives = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.", progress = "At ease, Private.  If you're here to unload soil from Un'Goro - outstanding then!  Otherwise, disappear.", completion = "Oh that's right Private <name>, don't make any effort to help me unload this soil up on to the piles!  If the Great Spirits had wanted it done they would have miracled it up there, now wouldn't they?!\n\nArch Druid Runetotem wants to speak with you again, but for his next task you find that a journeyman's understanding of Herbalism would be helpful.  If you don't know it though, he'll still find a use for you." }
WordHunterWoW_QuestEN[3762] = { title = "Assisting Arch Druid Runetotem", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", objectives = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", completion = "Greetings, <class>; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before." }
WordHunterWoW_QuestEN[3763] = { title = "Assisting Arch Druid Staghelm", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", completion = "Well now, <class>... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself." }
WordHunterWoW_QuestEN[3764] = { title = "Un'Goro Soil", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study.\n\nYou may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not I.", objectives = "Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.", progress = "Ah yes, the dirt.  The Arch Druid wants twenty loads per adventurer, and twenty loads he shall get.  Let those who conspire against us fall to the wayside!", completion = "Unload your precious cargo here, noble <class>.  It must have been quite the burden... not unlike the burden I carry being a visionary.  Here is an honorarium for your work, as dictated by the Arch Druid himself.\n\nArch Druid Staghelm wants to speak with you again <name>, but for his next task you will be aided if you have a journeyman's understanding of Herbalism.  If you don't know it though, you will still be able to aid the Circle!" }
WordHunterWoW_QuestEN[3765] = { title = "The Corruption Abroad", description = "Stormwind -- such a bustling hub of activity.\n\nI have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets.\n\nMy brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine.\n\nThe journey is a long and epic one. It is for this reason that I ask the help of a seasoned <class> such as yourself.", objectives = "Travel to Gershala Nightwhisper in Auberdine.", completion = "Ah, so my brother, Argos, sent you? I realize you must be weary from your travels. But we have much to talk about." }
WordHunterWoW_QuestEN[3781] = { title = "Morrowgrain Research", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds blossom into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I intend to unravel this mystery.\n\nTake this to Mathrengyl downstairs, and he will give you some seeds so you can get started.  If you run out, you will need to purchase more from him.", objectives = "Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.", progress = "Peace and serenity be yours, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out, we have more that can be provided.  Unfortunately though, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.\n\nThose who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost." }
WordHunterWoW_QuestEN[3782] = { title = "Morrowgrain Research", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds have blossomed into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I very much hope to unravel this mystery for the Circle.\n\nTake this voucher over to my daughter Bashana, and she will give you some seeds so you may assist us.  If you run out, you will need to purchase more from her.", objectives = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.", progress = "Peace unto you, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out of seeds, I do have more that I am able to sell to you.\n\nUnfortunately <name>, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.  Those who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost." }
WordHunterWoW_QuestEN[3783] = { title = "re We There, Yeti?", description = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.", objectives = "Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.", progress = "I've got lots to get started on here. Please get me those furs as soon as you can!", completion = "These furs are perfect, <name>. We're off to a great start here!" }
WordHunterWoW_QuestEN[3784] = { title = "Assisting Arch Druid Runetotem", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", objectives = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", completion = "Greetings, <class>; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before." }
WordHunterWoW_QuestEN[3785] = { title = "Morrowgrain Research", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them here to me in the enclave.  Please don't bother the Arch Druid; he's a very busy man, and he doesn't need to be disturbed every time someone returns with another batch of morrowgrain!You will receive:", objectives = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus." }
WordHunterWoW_QuestEN[3786] = { title = "Morrowgrain Research", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them to me here on Elder Rise.  Please don't bother the Arch Druid; he'll be very busy with the research, as well as the multitude of concerns he has!", objectives = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.", progress = "Yes <name>, have you grown some morrowgrain for the Arch Druid's important research?  The mysterious properties of Un'Goro Crater become clearer with each passing day, thanks to the help you are giving us.", completion = "Well done <name>, I will be sure to give these to the Arch Druid himself when he has need of them.  Meanwhile, please accept this as a token of the Cenarion Circle's appreciation.\n\nOur need for morrowgrain, for now, is constant; if you wish to continue aiding us, then please return when you have cultivated more of it." }
WordHunterWoW_QuestEN[3787] = { title = "Jonespyre's Request", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", objectives = "Speak with Quintis Jonespyre in Feathermoon Stronghold.Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle. He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas. He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed." }
WordHunterWoW_QuestEN[3788] = { title = "Jonespyre's Request", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", objectives = "Speak with Quintis Jonespyre in Feathermoon Stronghold.Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle. He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold. He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed." }
WordHunterWoW_QuestEN[3789] = { title = "Assisting Arch Druid Staghelm", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", completion = "Well now, <class>... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself." }
WordHunterWoW_QuestEN[3790] = { title = "Assisting Arch Druid Staghelm", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", completion = "Well now, <class>... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself." }
WordHunterWoW_QuestEN[3791] = { title = "The Mystery of Morrowgrain", description = "Let me to be frank with you, <name>.  I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain.  I'm a researcher - curses are my specialty.  I've heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.\n\nI want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you.", objectives = "Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.", progress = "I'm looking for ten morrowgrain - that should be enough to at least get my research started.  I'll no doubt burn through a lot of those going down wrong paths, but such is the nature of research.", completion = "Gah, these morrowgrain make me feel... weird.  What in the name of Elune is Staghelm up to with these things?\n\nAnyway, thank you again for your help.  Here's a little something... you know, for the effort.  My research on morrowgrain is going to take a while, and I no doubt am going to need more.  While I'm at it, I suppose I could take the time to see if morrowgrain have some pertinent alchemical uses.  Still, I feel uncomfortable even being around them." }
WordHunterWoW_QuestEN[3792] = { title = "Morrowgrain to Feathermoon Stronghold", description = "", objectives = "Hello again, <name>.  My research is progressing fairly well, but if you have five more Morrowgrain I'd be happy to take them off your hands.  Well... happy is a figurative term in this case; the more I am around them, the more uncomfortable I feel.  Still, my research demands I buckle down and get through this.", progress = "Hello again, <name>.  My research is progressing fairly well, but if you have five more Morrowgrain I'd be happy to take them off your hands.  Well... happy is a figurative term in this case; the more I am around them, the more uncomfortable I feel.  Still, my research demands I buckle down and get through this.", completion = "Thanks <name>; I'll just store these out of the way for the time being.  While I don't command the resources that Staghelm does, I am able to give you a little something for your trouble.  Anyway, who knows what will happen if Staghelm keeps getting Morrowgrain after Morrowgrain.  There's something fishy going on, mark my words.\n\nRemember that I'm always looking for more Morrowgrain.  I'll take them in quantities of five at a time." }
WordHunterWoW_QuestEN[3801] = { title = "Dark Iron Legacy", description = "Greetings, <name>. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.", objectives = "Speak with Franclorn Forgewright at Forgewright's Tomb in Blackrock Mountain if you are interested in obtaining a key to the city major.Greetings, <name>. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.", completion = "Whether it is greed which brought you here or an act of selfless devotion, what you are about to undertake is for the good of us all." }
WordHunterWoW_QuestEN[3802] = { title = "Dark Iron Legacy", description = "You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel.\n\nTake Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor.\n\nWhen this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever.", objectives = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", progress = "The statue looms ominously above you.", completion = "The hammer slides firmly into place, within the grasp of the massive Dark Iron monument. A tiny compartment opens at the base of the statue. Inside you find..." }
WordHunterWoW_QuestEN[3803] = { title = "Morrowgrain to Darnassus", description = "", objectives = "" }
WordHunterWoW_QuestEN[3804] = { title = "Morrowgrain to Thunder Bluff", description = "", objectives = "The Arch Druid is always looking for more morrowgrain for the Cenarion Circle's research project on Un'Goro Crater.  We take them in increments of ten, and award you with a cache of goods you should find useful.  When you have ten, let me know and I will award you accordingly.", progress = "The Arch Druid is always looking for more morrowgrain for the Cenarion Circle's research project on Un'Goro Crater.  We take them in increments of ten, and award you with a cache of goods you should find useful.  When you have ten, let me know and I will award you accordingly.", completion = "Excellent - this morrowgrain will no doubt help when the time comes.  We know that the night elves are conducting similar research into these herbs, though it isn't clear to what end they will use them for if they discover anything.  The Arch Druid thinks that the need for morrowgrain will remain until we've figured out the mysteries behind this herb.\n\nThis is for you, <name>.  The Cenarion Circle thanks you for your continued support." }
WordHunterWoW_QuestEN[3821] = { title = "Dreadmaul Rock", description = "Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.\n\nGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!\n\nI can't leave my post, <name>, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.", objectives = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.\n\nGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!\n\nI can't leave my post, <name>, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.", completion = "My poor Thal'trak.\n\nWe were planning on moving in with my mother and father in the Hinterlands after our tours were over. Now those plans are ruined!" }
WordHunterWoW_QuestEN[3822] = { title = "Krom'Grul", description = "My whole platoon was captured, <name>. All were slain - except me.\n\nTheir leader, Krom'Grul, wanted to save me for some sort of ritual.\n\nI was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery!\n\nFind Krom'Grul and kill him! Take my ring back to Thal'trak.\n\nAnd <name>, tell him that we will meet again... in another life.", objectives = "Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock.", progress = "Did you find Sha'ni? Is she ok?", completion = "<Thal'trak collapses.>\n\nWe were going to move to the Hinterlands. Did she tell you? This was going to be her last mission.\n\n<Thal'trak sobs.>\n\nI don't want it, <name>. Keep it, throw it away, I don't care! The ring means nothing to me now. Not without her..." }
WordHunterWoW_QuestEN[3823] = { title = "Extinguish the Firegut", description = "We must strike at our enemies before they strike at us!\n\nI'll make this brief, soldier.\n\nThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.\n\nLeave your mark, <name>. Cripple their forces and return to me when the job is done.\n\n<Oralius grabs at the air and makes a choking motion.>\n\nI WILL KILL YOU, WINKY!", objectives = "Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes.", completion = "Outstanding, soldier! The orcs and ogres will be reeling from this blow for minutes, maybe even hours!" }
WordHunterWoW_QuestEN[3824] = { title = "Gor'tesh the Brute Lord", description = "They're reeling I tell you! Our next strike must be decisive.\n\nThe brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres.\n\nBe warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock.\n\nYour orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done.\n\nSHUT UP, WINKY!", objectives = "Collect Gor'tesh's Lopped Off Head.", progress = "Oh glorious day! Have you returned with the head?", completion = "Just look at it, soldier. Disgusting! When the remaining Firegut ogres see this fat mug stuck on a pike sitting at the top of their mountain, mass hysteria will ensue!\n\n<Oralius cackles wildly.>" }
WordHunterWoW_QuestEN[3825] = { title = "Ogre Head On A Stick = Party", description = "Just one last thing you must do, soldier.\n\nI've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work.\n\n<Oralius seems to be losing touch with reality.>", objectives = "Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.", completion = "Outstanding work, soldier! Simply amazing! Oh I'll get the medal of bravery for this, er, I mean you'll be rewarded handsomely for this!" }
WordHunterWoW_QuestEN[3841] = { title = "An Orphan Looking For a Home", description = "Oh, hello, <name>. I'm so glad to see you again. How was your trip to Darnassus?\n\nWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.\n\nSay, would you want one for a pet? They look to hatch soon, so they'll need a good <father/mother>. What do you say?\n\nIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more.", objectives = "Speak to Quentin in Thousand Needles.", progress = "Why hello, <class>.\n\nDon't let my location fool you, I'm really not here for the races... as entertaining as they may be.\n\nI'm actually here in Thousand Needles investigating all I can to find out how salvageable the land is. It has become my crusade of sorts to revitalize and replenish the area with new, fertile soil. Perhaps I'll find there's a water source nearby.\n\nTell me you haven't noticed how odd the transition between Feralas and Thousand Needles is. Strange magic was afoot when that happened.", completion = "Ah, a sprite darter egg, and one near maturation, if I'm not mistaken. Remarkable you've found one, let alone in this good a condition. They're rarely seen in Feralas these days. I understand there were various poachers in the area trying to capture and kill them for many reasons. Too bad really... such beautiful creatures when they reach adulthood.\n\nHow did you come across such a find?" }
WordHunterWoW_QuestEN[3842] = { title = "A Short Incubation", description = "The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.\n\nSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.\n\nI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me.", objectives = "Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.", progress = "The longer I stay here, the more tempted I am to partake in these races, <name>. Truly boggling...\n\nHave you found the elixirs yet? Once I can tell if the egg is going to be healthy or not, I'll return it to you to hold onto until it's prepared to hatch.\n\nLet me know.", completion = "Wonderful. These will do nicely. Give me a moment to mix together my components and we shall see how well this egg is going to do." }
WordHunterWoW_QuestEN[3843] = { title = "The Newest Member of the Family", description = "A magnificent specimen, <name>. If this creature survives gestation, then it'll be a healthy pet indeed!\n\nThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.\n\nBut hurry, <name>, this egg is fragile and will not last long without proper care.", objectives = "Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.", progress = "Greetin's, <name>. How can I be of service to ya?", completion = "Well, well, well... I haven't seen one of these in a dragon's age. Faerie dragon, if I'm not mistaken... looks to be of the sprite darter variety. Excellent, excellent indeed.\n\nWell, if this little fella's gonna hatch and live to be strong and healthy, then we should get some food for it. Good ya got it to me in time." }
WordHunterWoW_QuestEN[3844] = { title = "It's a Secret to Everybody", description = "A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.\n\nPerhaps a little exploration in the area might uncover more clues...", objectives = "Look around in the pond for a clue about who this wrecked raft may belong to.A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.\n\nPerhaps a little exploration in the area might uncover more clues...", completion = "A water-logged pack rests at the bottom of the pond." }
WordHunterWoW_QuestEN[3845] = { title = "It's a Secret to Everybody", description = "Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.\n\nThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.", objectives = "Examine the items inside the pack and bring them to their owner.", progress = "Hi there. I've seen you before... Haven't I?", completion = "Oh... Yes, these things do look familiar... well, kind of..." }
WordHunterWoW_QuestEN[3861] = { title = "CLUCK!", description = "\"Cluck... cluck... cluck... BACAW!\n\nCluck... cluck... cluck.\"\n\nThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.", objectives = "Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.", progress = "The chicken stares at you with dark, cold eyes. It waits for you hungrily.\n\n\"BACAAAW!\n\nCluck...cluck...cluck.\"", completion = "\"BACAW!!!\"\n\nThe chicken starts to gobble up the feed you put down.\n\nAfter a moment, the chicken looks around, startled. It uncomfortably shuffles back and forth. Is this chicken pregnant? You think you better check underneath it." }
WordHunterWoW_QuestEN[3881] = { title = "Expedition Salvation", description = "I don't know how you made it here, but you're a sight for sore eyes!  I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Our latest and greatest endeavor has met with what seems like countless disasters, the most serious of which being that we underestimated the savagery of Un'Goro Crater!\n\nAs we fled our base camps in the southwestern and northeastern parts of the crater, we left behind vital supplies.  You look like you're capable enough - can you help us by getting them back?", objectives = "Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.", progress = "If we're going to have any chance of getting out of here alive, we'll need our big crate of foodstuffs.  Also, getting at least some of our research equipment back would be a blessing in a sea of misery.", completion = "You got both our foodstuff AND our research equipment back!  You've not only saved the expedition, you've also saved our lives.  I and the rest of my team can't thank you enough; we just might make it here for a while now thanks to you.\n\nWhile we don't have much, I'm certainly not going to leave you high and dry for the invaluable help you've given us.  Thank you, <name> - you've got a friend in Marshal Expeditions!" }
WordHunterWoW_QuestEN[3882] = { title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", objectives = "Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.", progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ones from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!" }
WordHunterWoW_QuestEN[3883] = { title = "Alien Ecology", description = "Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why.\n\nIn their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!", objectives = "Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater. Look for the chambers with the hanging larval spawns.\n\nBring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater.", progress = "Do you have the sample of the Gorishi hive for me to study, <name>?", completion = "Yes, this will do nicely.  You've been a great help... I wish I could give you more than this, but being virtually stranded in the middle of a savage land does limit what I can and cannot give.  Rest assured though - the research done here would not have been possible without your assistance!" }
WordHunterWoW_QuestEN[3884] = { title = "Williden's Journal", description = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.", objectives = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.", progress = "Hello there!  I and my companions are happy to see some living beings here other than overgrown savage beasts!  What brings you into the Un'Goro Crater?", completion = "Well look at this - my journal!  I thought it was lost, much like almost everything else we brought into Un'Goro.  I thank you kindly for returning this to me!" }
